INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88643, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "胜利就是比赛或打仗时,你赢了。", "primary_collocate": null, "pronunciation": "shèng lì", "ipa": "ʂɤŋ˥˩ li˥˩", "syllable_count": 2, "sentences": [{"text": "我们队在比赛中胜利了。", "target_word": "胜利", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这场比赛,红队胜利了。", "target_word": "胜利", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们打了三天,终于胜利了。", "target_word": "胜利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哪一队胜利了?", "target_word": "胜利", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们班在拔河比赛中胜利了。", "target_word": "胜利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经过一场大战,士兵们胜利了。", "target_word": "胜利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次比赛他胜利了,大家都很高兴。", "target_word": "胜利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛结束了,蓝队胜利了。", "target_word": "胜利", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们在足球赛里胜利过一次。", "target_word": "胜利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "虽然对手很强,我们还是胜利了。", "target_word": "胜利", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "胜利了", "label": "体标"}, {"form": "胜利过", "label": "体标"}, {"form": "勝利", "label": "繁体"}], "register": "中性", "sense_fingerprint": "比赛或战争中赢了对手", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5767602e-4fc3-4fe7-bca0-b5bea1fa5ab2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88643, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "胜利", "is_correct": true, "explanation": "胜利：在比赛或战斗中赢了对手。"}, {"text": "生理", "is_correct": false, "explanation": "shēng lǐ（第一、三声）与 shèng lì（第四声）声调不同，意思是人体的生理机能。"}, {"text": "省力", "is_correct": false, "explanation": "shěng lì（第三声）与 shèng lì 第一个音节声调不同，意思是节省力气。"}, {"text": "升力", "is_correct": false, "explanation": "shēng lì（第一声）与 shèng lì 第一个音节声调不同，意思是使物体上升的力。"}, {"text": "生梨", "is_correct": false, "explanation": "shēng lí（第一、二声）与 shèng lì 声调不同，意思是没有煮过的梨。"}], "explanations": {"胜利": "胜利：在比赛或战斗中赢了对手。", "生理": "shēng lǐ（第一、三声）与 shèng lì（第四声）声调不同，意思是人体的生理机能。", "省力": "shěng lì（第三声）与 shèng lì 第一个音节声调不同，意思是节省力气。", "升力": "shēng lì（第一声）与 shèng lì 第一个音节声调不同，意思是使物体上升的力。", "生梨": "shēng lí（第一、二声）与 shèng lì 声调不同，意思是没有煮过的梨。"}, "sentence_index": null, "correct_answer": "胜利"}, "level_3": {"options": [{"text": "胜利", "is_correct": true, "explanation": "正确：“胜利”指比赛中赢了对手，与“我们队在比赛中胜利了”相符。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：比赛中不会“睡觉”，句子说不通。"}, {"text": "散步", "is_correct": false, "explanation": "语义：比赛里不能“散步”，与句子的语境不符。"}, {"text": "驾崩", "is_correct": false, "explanation": "语域：“驾崩”是帝王去世的书面用语，用在比赛里语域完全不符。"}], "explanations": {"胜利": "正确：“胜利”指比赛中赢了对手，与“我们队在比赛中胜利了”相符。", "睡觉": "语义：比赛中不会“睡觉”，句子说不通。", "散步": "语义：比赛里不能“散步”，与句子的语境不符。", "驾崩": "语域：“驾崩”是帝王去世的书面用语，用在比赛里语域完全不符。"}, "sentence_index": 0, "correct_answer": "胜利"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这场比赛的观众胜利了。", "explanation": "这里应该用〈欢呼〉。“胜利”的主语应是参赛的一方，观众不参赛，观众应该“欢呼”。"}, {"text": "我们班的成绩胜利了。", "explanation": "这里应该用〈提高〉。“胜利”的主语应是参赛的一方，成绩不能“胜利”，应说“成绩提高了”。"}, {"text": "这场比赛的裁判胜利了。", "explanation": "这里应该用〈判定〉。“胜利”的主语应是参赛的一方，裁判不参赛，裁判应该“判定”胜负。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '302840f7-b73e-4a61-bf0e-cb4145bc9216') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88643, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "胜利", "is_correct": true, "explanation": "正确：“他胜利了”指在比赛中赢了，“大家都很高兴”与之相符。"}, {"text": "感冒", "is_correct": false, "explanation": "语义：他感冒了，大家不会因此都很高兴，句意不通。"}, {"text": "迟到", "is_correct": false, "explanation": "语义：迟到不会让大家都很高兴，与后半句的语境相反。"}, {"text": "殉职", "is_correct": false, "explanation": "语域：“殉职”是郑重的书面语，指为工作而牺牲，与比赛的轻松语境不合。"}], "explanations": {"胜利": "正确：“他胜利了”指在比赛中赢了，“大家都很高兴”与之相符。", "感冒": "语义：他感冒了，大家不会因此都很高兴，句意不通。", "迟到": "语义：迟到不会让大家都很高兴，与后半句的语境相反。", "殉职": "语域：“殉职”是郑重的书面语，指为工作而牺牲，与比赛的轻松语境不合。"}, "sentence_index": 6, "correct_answer": "胜利"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这场比赛的主持人胜利了。", "explanation": "这里应该用〈主持〉。“胜利”的主语应是参赛的一方，主持人不参赛，应说“主持人主持比赛”。"}, {"text": "他们的赛程胜利了。", "explanation": "这里应该用〈结束〉。“胜利”的主语应是参赛的一方，赛程不能赢，应说“赛程结束了”。"}, {"text": "这场比赛的解说员胜利了。", "explanation": "这里应该用〈解说〉。“胜利”的主语应是参赛的一方，解说员不参赛，应说“解说员解说比赛”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '302840f7-b73e-4a61-bf0e-cb4145bc9216') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88643, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们队在决赛中胜利了对手。", "corrected_sentence": "我们队在决赛中胜利了。", "error_description": "“胜利”是不及物动词，后面不能直接带宾语“对手”，应说“战胜对手”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '302840f7-b73e-4a61-bf0e-cb4145bc9216') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88643, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们在复赛中被胜利了。", "corrected_sentence": "他们在复赛中胜利了。", "error_description": "“胜利”是不及物动词，不能用“被”构成被动句。正确：应说“他们在复赛中胜利了”，去掉“被”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '302840f7-b73e-4a61-bf0e-cb4145bc9216') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88645, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "肉体", "is_correct": true, "explanation": "正确：「肉体」指人的身体，与能离开身体的「灵魂」相对。"}, {"text": "花园", "is_correct": false, "explanation": "与「灵魂」无反义关系，「花园」是种植花草的地方。"}, {"text": "书包", "is_correct": false, "explanation": "与「灵魂」无反义关系，「书包」是装东西的袋子。"}, {"text": "石头", "is_correct": false, "explanation": "与「灵魂」无反义关系，「石头」是一种矿物。"}], "correct_answer": "肉体", "explanations": {"肉体": "正确：「肉体」指人的身体，与能离开身体的「灵魂」相对。", "花园": "与「灵魂」无反义关系，「花园」是种植花草的地方。", "书包": "与「灵魂」无反义关系，「书包」是装东西的袋子。", "石头": "与「灵魂」无反义关系，「石头」是一种矿物。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff29ca3d-b11c-4277-8681-bb558e1e29c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
