INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88645, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "灵魂是人们说的，住在人身体里、人死了以后还会在的东西。", "primary_collocate": null, "pronunciation": "líng hún", "ipa": "liŋ˧˥ xwən˧˥", "syllable_count": 2, "sentences": [{"text": "人们说，人死了灵魂还在。", "target_word": "灵魂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人相信灵魂会回到家里。", "target_word": "灵魂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶说，灵魂住在人的身体里。", "target_word": "灵魂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "故事里的灵魂离开了身体，飞到天上。", "target_word": "灵魂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不信有灵魂，所以不怕黑夜。", "target_word": "灵魂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "传说中，好人的灵魂会上天。", "target_word": "灵魂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子问妈妈：人死后灵魂去哪里？", "target_word": "灵魂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影讲了一个灵魂回家的故事。", "target_word": "灵魂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多人觉得灵魂可以看见自己的家人。", "target_word": "灵魂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜里，他好像看见了一个白色的灵魂。", "target_word": "灵魂", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "传说中住在身体里、人死后仍存在的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3de3ff09-fd2d-4605-9abd-d17a76935391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88645, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "灵魂", "is_correct": true, "explanation": "正确：「灵魂」指人死后仍存在的东西，与「人死了……还在」搭配。"}, {"text": "脚步", "is_correct": false, "explanation": "语义：「脚步」是走路的动作或声音，不能在人死后还留下。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：「年龄」不能与「人死了……还在」的说法搭配。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：「颜色」是物体的属性，不是人死后仍存在的东西。"}], "explanations": {"灵魂": "正确：「灵魂」指人死后仍存在的东西，与「人死了……还在」搭配。", "脚步": "语义：「脚步」是走路的动作或声音，不能在人死后还留下。", "年龄": "搭配：「年龄」不能与「人死了……还在」的说法搭配。", "颜色": "语义：「颜色」是物体的属性，不是人死后仍存在的东西。"}, "sentence_index": 0, "correct_answer": "灵魂"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的灵魂很短暂。", "explanation": "这里应该用〈生命〉。「灵魂」指死后仍存在的东西，不会「短暂」，说寿命短要用「生命」。"}, {"text": "他的灵魂被埋在山上。", "explanation": "这里应该用〈尸体〉。能离开身体的灵魂不会被埋，被埋的是尸体。"}, {"text": "他的灵魂很重，抬不动。", "explanation": "这里应该用〈身体〉。「灵魂」不是有重量的实体，「抬不动」只能说身体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff29ca3d-b11c-4277-8681-bb558e1e29c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88645, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "灵魂", "is_correct": true, "explanation": "正确：「灵魂」指人死后仍存在的东西，与「去哪里」这一问相呼应。"}, {"text": "钱包", "is_correct": false, "explanation": "语义：「钱包」是装钱的东西，不是人死后会去的地方的主体。"}, {"text": "房子", "is_correct": false, "explanation": "语义：「房子」是建筑，不能说人死后「去哪里」，句子问的是灵魂。"}, {"text": "作业", "is_correct": false, "explanation": "搭配：「作业」不能与「人死后……去哪里」搭配。"}], "explanations": {"灵魂": "正确：「灵魂」指人死后仍存在的东西，与「去哪里」这一问相呼应。", "钱包": "语义：「钱包」是装钱的东西，不是人死后会去的地方的主体。", "房子": "语义：「房子」是建筑，不能说人死后「去哪里」，句子问的是灵魂。", "作业": "搭配：「作业」不能与「人死后……去哪里」搭配。"}, "sentence_index": 6, "correct_answer": "灵魂"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夜里，他好像看见了一把白色的灵魂。", "explanation": "这里应该用〈个〉。「灵魂」用量词「个」，「把」用于有柄的器具，不能用于灵魂。"}, {"text": "夜里，他好像看见了一块白色的灵魂。", "explanation": "这里应该用〈个〉。「块」用于块状的东西，不能用于灵魂。"}, {"text": "夜里，他好像看见了一座白色的灵魂。", "explanation": "这里应该用〈个〉。「座」用于山、桥、房屋等大型固定的东西，不能用于灵魂。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff29ca3d-b11c-4277-8681-bb558e1e29c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88645, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老人相信一本灵魂会回到家里。", "corrected_sentence": "老人相信一个灵魂会回到家里。", "error_description": "量词错误：「灵魂」用量词「个」。「本」用于书，不能用于灵魂。应说「一个灵魂」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff29ca3d-b11c-4277-8681-bb558e1e29c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88645, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老人讲，有一张白色的灵魂飞到了树上。", "corrected_sentence": "老人讲，有一个白色的灵魂飞到了树上。", "error_description": "量词错误：「灵魂」用量词「个」。「张」用于纸、桌子等平面物，不能用于灵魂。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff29ca3d-b11c-4277-8681-bb558e1e29c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
