INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88646, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "人的精神、思想；内心的世界。", "primary_collocate": null, "pronunciation": "líng hún", "ipa": "liŋ˧˥ xwən˧˥", "syllable_count": 2, "sentences": [{"text": "他的灵魂很自由。", "target_word": "灵魂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老师有一个美丽的灵魂。", "target_word": "灵魂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好书能让人的灵魂变得丰富。", "target_word": "灵魂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把整个灵魂都放进了画里。", "target_word": "灵魂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的灵魂深处一直很安静。", "target_word": "灵魂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子的灵魂像水一样干净。", "target_word": "灵魂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首歌让我的灵魂得到了安慰。", "target_word": "灵魂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人的身体会老，灵魂不会老。", "target_word": "灵魂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说，读书是在和别人的灵魂说话。", "target_word": "灵魂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是个有趣的灵魂。", "target_word": "灵魂", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "灵魂深处", "label": "复合"}], "register": "中性", "sense_fingerprint": "人的精神、思想，内心世界", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3de3ff09-fd2d-4605-9abd-d17a76935391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EX