INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88646, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "灵魂", "is_correct": true, "explanation": "正确：「灵魂」指人的精神、思想，与「很自由」搭配。"}, {"text": "房子", "is_correct": false, "explanation": "语义：「房子」是建筑，不能说「很自由」，句子说的是精神。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：「年龄」不能用「自由」来形容。"}, {"text": "价格", "is_correct": false, "explanation": "语义：「价格」指钱数，不能是「自由」的，句子说的是精神状态。"}], "explanations": {"灵魂": "正确：「灵魂」指人的精神、思想，与「很自由」搭配。", "房子": "语义：「房子」是建筑，不能说「很自由」，句子说的是精神。", "年龄": "搭配：「年龄」不能用「自由」来形容。", "价格": "语义：「价格」指钱数，不能是「自由」的，句子说的是精神状态。"}, "sentence_index": 0, "correct_answer": "灵魂"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他有一只纯洁的灵魂。", "explanation": "这里应该用〈个〉。「灵魂」用量词「个」，「只」用于动物等，不能用于灵魂。"}, {"text": "他的灵魂穿着一双新鞋。", "explanation": "这里应该用〈脚〉。「灵魂」不穿鞋，说穿鞋要用「脚」。"}, {"text": "他的灵魂很聪明。", "explanation": "这里应该用〈头脑〉。「灵魂」指精神、思想的整体，不用来说「聪明」，说智力要用「头脑」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff29ca3d-b11c-4277-8681-bb558e1e29c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88646, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "灵魂", "is_correct": true, "explanation": "正确：「灵魂」指人的精神，句子说的是歌曲安慰了心灵，与「得到了安慰」搭配。"}, {"text": "课本", "is_correct": false, "explanation": "语义：「课本」是书，没有感受，不能「得到安慰」。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：「桌子」是家具，不能「得到安慰」，句子说的是人的内心。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：「体重」不能与「得到了安慰」搭配。"}], "explanations": {"灵魂": "正确：「灵魂」指人的精神，句子说的是歌曲安慰了心灵，与「得到了安慰」搭配。", "课本": "语义：「课本」是书，没有感受，不能「得到安慰」。", "桌子": "语义：「桌子」是家具，不能「得到安慰」，句子说的是人的内心。", "体重": "搭配：「体重」不能与「得到了安慰」搭配。"}, "sentence_index": 6, "correct_answer": "灵魂"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的灵魂很英俊。", "explanation": "这里应该用〈外表〉。「灵魂」是内在的精神，不能用来描述外貌的「英俊」。"}, {"text": "他的灵魂有一米八。", "explanation": "这里应该用〈身高〉。「灵魂」不能用身高的数值来计量。"}, {"text": "她的灵魂很红。", "explanation": "这里应该用〈脸〉。「灵魂」不是有颜色的部位，说「红」要用「脸」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff29ca3d-b11c-4277-8681-bb558e1e29c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
