INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88647, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "州是一个国家里分出来的大地方,有的国家用这个名字。", "primary_collocate": null, "pronunciation": "zhōu", "ipa": "ʈʂou˥", "syllable_count": 1, "sentences": [{"text": "美国有五十个州。", "target_word": "州", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个州的人很多。", "target_word": "州", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我去过那个州的大城市。", "target_word": "州", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "澳大利亚有六个州。", "target_word": "州", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "哪个州最大?", "target_word": "州", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个州的冬天很冷。", "target_word": "州", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他家在南边的一个州。", "target_word": "州", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "美国的每个州都有自己的法律。", "target_word": "州", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两个州之间有一条大河。", "target_word": "州", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想去另一个州工作。", "target_word": "州", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "州长", "label": "复合"}, {"form": "州政府", "label": "复合"}], "register": "中性", "sense_fingerprint": "国家内部划分出来的大地区,如美国的州", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5767602e-4fc3-4fe7-bca0-b5bea1fa5ab2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88647, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "州", "is_correct": true, "explanation": "州（zhōu）：国家内划分出来的大地区，如美国的州。"}, {"text": "抽", "is_correct": false, "explanation": "chōu（第一声）与 zhōu 声母不同（ch 与 zh），意思是抽出、抽取。"}, {"text": "收", "is_correct": false, "explanation": "shōu 与 zhōu 声母不同（sh 与 zh），意思是收集、接收。"}, {"text": "轴", "is_correct": false, "explanation": "zhóu（第二声）与 zhōu（第一声）声调不同，意思是轴，如车轴。"}, {"text": "皱", "is_correct": false, "explanation": "zhòu（第四声）与 zhōu（第一声）声调不同，意思是皱纹、起皱。"}, {"text": "肘", "is_correct": false, "explanation": "zhǒu（第三声）与 zhōu（第一声）声调不同，意思是手肘。"}], "explanations": {"州": "州（zhōu）：国家内划分出来的大地区，如美国的州。", "抽": "chōu（第一声）与 zhōu 声母不同（ch 与 zh），意思是抽出、抽取。", "收": "shōu 与 zhōu 声母不同（sh 与 zh），意思是收集、接收。", "轴": "zhóu（第二声）与 zhōu（第一声）声调不同，意思是轴，如车轴。", "皱": "zhòu（第四声）与 zhōu（第一声）声调不同，意思是皱纹、起皱。", "肘": "zhǒu（第三声）与 zhōu（第一声）声调不同，意思是手肘。"}, "sentence_index": null, "correct_answer": "州"}, "level_3": {"options": [{"text": "州", "is_correct": true, "explanation": "正确：州是国家内划分出来的大地区，美国确实有五十个州。"}, {"text": "省", "is_correct": false, "explanation": "语义：美国没有“省”这一级行政区，说“美国有五十个省”与事实不符。"}, {"text": "国家", "is_correct": false, "explanation": "语义：美国本身就是一个国家，不能说它里面有五十个国家。"}, {"text": "人口", "is_correct": false, "explanation": "搭配：“人口”是数量概念，不能用“五十个”来计数，应说“人口很多”。"}], "explanations": {"州": "正确：州是国家内划分出来的大地区，美国确实有五十个州。", "省": "语义：美国没有“省”这一级行政区，说“美国有五十个省”与事实不符。", "国家": "语义：美国本身就是一个国家，不能说它里面有五十个国家。", "人口": "搭配：“人口”是数量概念，不能用“五十个”来计数，应说“人口很多”。"}, "sentence_index": 0, "correct_answer": "州"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "美国是一个州。", "explanation": "这里应该用〈国家〉。州是国家内部划分出来的大地区，美国本身是一个国家，不能说它是一个州。"}, {"text": "中国有三十一个州。", "explanation": "这里应该用〈省〉。中国的一级行政区叫“省”，州不用于中国的行政区划。"}, {"text": "法国有十三个州。", "explanation": "这里应该用〈大区〉。法国的一级行政区叫“大区”，州不用于法国的行政区划。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '302840f7-b73e-4a61-bf0e-cb4145bc9216') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88647, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "州", "is_correct": true, "explanation": "正确：“南边的一个州”指国家内的一个大地区，符合句意。"}, {"text": "老师", "is_correct": false, "explanation": "语义：“老师”指人，不是地方，“他家在南边的一个老师”说不通。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“天气”不能用来指家所在的地方，“一个天气”也不是地点的说法。"}, {"text": "作业", "is_correct": false, "explanation": "语义：“作业”不能作为家所在的地方，句意不通。"}], "explanations": {"州": "正确：“南边的一个州”指国家内的一个大地区，符合句意。", "老师": "语义：“老师”指人，不是地方，“他家在南边的一个老师”说不通。", "天气": "搭配：“天气”不能用来指家所在的地方，“一个天气”也不是地点的说法。", "作业": "语义：“作业”不能作为家所在的地方，句意不通。"}, "sentence_index": 6, "correct_answer": "州"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "上海是一个大州。", "explanation": "这里应该用〈城市〉。州是国家内的大地区，上海是城市，不能说是一个州。"}, {"text": "中东是一个重要的州。", "explanation": "这里应该用〈地区〉。州是一个国家之内的行政区，中东跨越多个国家，不能叫州。"}, {"text": "北京有十六个州。", "explanation": "这里应该用〈区〉。北京内部划分为“区”，中国的城市不用“州”来划分。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '302840f7-b73e-4a61-bf0e-cb4145bc9216') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88647, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条州有很多大城市。", "corrected_sentence": "这个州有很多大城市。", "error_description": "“州”前应用量词“个”，不能用“条”（“条”多用于细长的东西）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '302840f7-b73e-4a61-bf0e-cb4145bc9216') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
