INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88648, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "某些国家的一级行政区域;也指古代的行政区划。", "primary_collocate": null, "pronunciation": "zhōu", "ipa": "ʈʂoʊ˥", "syllable_count": 1, "sentences": [{"text": "古代的州比现在的县大得多。", "target_word": "州", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "德国有十六个州。", "target_word": "州", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "印度的每个州都有自己的政府。", "target_word": "州", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个州的首府在河边。", "target_word": "州", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "古时候,这里是一个州。", "target_word": "州", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他是这个州的最高长官。", "target_word": "州", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "巴西有二十六个州。", "target_word": "州", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个州的政府决定修一条新路。", "target_word": "州", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古代中国分成很多州。", "target_word": "州", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个国家分成了几个州。", "target_word": "州", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "州长", "label": "复合"}, {"form": "州政府", "label": "复合"}], "register": "中性", "sense_fingerprint": "一级行政区划,也指古代的行政区划", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5767602e-4fc3-4fe7-bca0-b5bea1fa5ab2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88648, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "州", "is_correct": true, "explanation": "州（zhōu）：某些国家的一级行政区域，也指古代的行政区划。"}, {"text": "抽", "is_correct": false, "explanation": "chōu（第一声）与 zhōu 声母不同（ch 与 zh），意思是抽出、抽取。"}, {"text": "收", "is_correct": false, "explanation": "shōu 与 zhōu 声母不同（sh 与 zh），意思是收集、接收。"}, {"text": "轴", "is_correct": false, "explanation": "zhóu（第二声）与 zhōu（第一声）声调不同，意思是轴，如车轴。"}, {"text": "皱", "is_correct": false, "explanation": "zhòu（第四声）与 zhōu（第一声）声调不同，意思是皱纹、起皱。"}, {"text": "肘", "is_correct": false, "explanation": "zhǒu（第三声）与 zhōu（第一声）声调不同，意思是手肘。"}], "explanations": {"州": "州（zhōu）：某些国家的一级行政区域，也指古代的行政区划。", "抽": "chōu（第一声）与 zhōu 声母不同（ch 与 zh），意思是抽出、抽取。", "收": "shōu 与 zhōu 声母不同（sh 与 zh），意思是收集、接收。", "轴": "zhóu（第二声）与 zhōu（第一声）声调不同，意思是轴，如车轴。", "皱": "zhòu（第四声）与 zhōu（第一声）声调不同，意思是皱纹、起皱。", "肘": "zhǒu（第三声）与 zhōu（第一声）声调不同，意思是手肘。"}, "sentence_index": null, "correct_answer": "州"}, "level_3": {"options": [{"text": "州", "is_correct": true, "explanation": "正确：古代的州是一级行政区，比现在的县大得多，符合句意。"}, {"text": "村", "is_correct": false, "explanation": "语义：村比县小得多，“古代的村比现在的县大得多”与事实相反。"}, {"text": "乡", "is_correct": false, "explanation": "语义：乡是比县更小的基层单位，这里说“乡比县大得多”与事实不符。"}, {"text": "人口", "is_correct": false, "explanation": "搭配：“大”形容面积或规模，人口的多少应说“多”，不说“大得多”。"}], "explanations": {"州": "正确：古代的州是一级行政区，比现在的县大得多，符合句意。", "村": "语义：村比县小得多，“古代的村比现在的县大得多”与事实相反。", "乡": "语义：乡是比县更小的基层单位，这里说“乡比县大得多”与事实不符。", "人口": "搭配：“大”形容面积或规模，人口的多少应说“多”，不说“大得多”。"}, "sentence_index": 0, "correct_answer": "州"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "日本有四十七个州。", "explanation": "这里应该用〈都道府县〉。日本的一级行政区叫“都道府县”，州不用于日本的行政区划。"}, {"text": "英国有四个州。", "explanation": "这里应该用〈国家〉。英国由英格兰、苏格兰、威尔士和北爱尔兰四个国家组成，州不用于英国内部的划分。"}, {"text": "中国有两千多个州。", "explanation": "这里应该用〈县〉。中国县一级的行政区有两千多个，叫“县”，不叫“州”；州是比县大的一级区域。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '302840f7-b73e-4a61-bf0e-cb4145bc9216') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88648, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "州", "is_correct": true, "explanation": "正确：巴西是联邦制国家，国内划分为二十六个州，符合句意。"}, {"text": "省", "is_correct": false, "explanation": "语义：巴西没有“省”这一级行政区，“巴西有二十六个省”与事实不符。"}, {"text": "国家", "is_correct": false, "explanation": "语义：巴西本身就是一个国家，不能说它里面有二十六个国家。"}, {"text": "大陆", "is_correct": false, "explanation": "语义：巴西是一个国家，不是大陆，“二十六个大陆”说不通。"}], "explanations": {"州": "正确：巴西是联邦制国家，国内划分为二十六个州，符合句意。", "省": "语义：巴西没有“省”这一级行政区，“巴西有二十六个省”与事实不符。", "国家": "语义：巴西本身就是一个国家，不能说它里面有二十六个国家。", "大陆": "语义：巴西是一个国家，不是大陆，“二十六个大陆”说不通。"}, "sentence_index": 6, "correct_answer": "州"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那个县分成了几个州。", "explanation": "这里应该用〈乡〉。县下分为乡或镇，州只用于一级行政区，不用来划分县。"}, {"text": "北京分成了十六个州。", "explanation": "这里应该用〈区〉。北京内部划分为“区”，不用“州”。"}, {"text": "上海分成了十六个州。", "explanation": "这里应该用〈区〉。上海是城市，内部划分为“区”，不用“州”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '302840f7-b73e-4a61-bf0e-cb4145bc9216') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88648, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那条州的面积很大。", "corrected_sentence": "那个州的面积很大。", "error_description": "“州”前应用量词“个”，不能用“条”（“条”多用于细长的东西）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '302840f7-b73e-4a61-bf0e-cb4145bc9216') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88648, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位州的州长很能干。", "corrected_sentence": "这个州的州长很能干。", "error_description": "“州”前应用量词“个”，不能用“位”（“位”用于人）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '302840f7-b73e-4a61-bf0e-cb4145bc9216') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
