INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88651, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "必要是说一定要有,少了不行。", "primary_collocate": null, "pronunciation": "bì yào", "ipa": "pi˥˩ jaʊ˥˩", "syllable_count": 2, "sentences": [{"text": "水对每个人都是必要的。", "target_word": "必要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我觉得这笔钱是必要的。", "target_word": "必要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次考试，复习是必要的。", "target_word": "必要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做蛋糕，鸡蛋是必要的。", "target_word": "必要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学外语，多听多说非常必要。", "target_word": "必要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人出门，带手机很必要。", "target_word": "必要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他买了做这道菜必要的调料。", "target_word": "必要", "complexity_tier": "T3", "furigana": "tā mǎi le zuò zhè dào cài bìyào de tiáoliào。", "sentence_source": "generated"}, {"text": "买房子前，看清合同是必要的。", "target_word": "必要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爬山时，水和食物都是必要的。", "target_word": "必要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请带好办事必要的证件。", "target_word": "必要", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不必要", "label": "否定"}, {"form": "必要性", "label": "名词派生"}], "register": "中性", "sense_fingerprint": "一定要有、少了不行", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34fd70d5-5710-4b08-aede-8a64d3f83331') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88651, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "必要", "is_correct": true, "explanation": "正确：“必要”表示一定要有、少了不行，用来说水的重要性，符合句意。"}, {"text": "热情", "is_correct": false, "explanation": "语义：“热情”形容人的态度，不能用来评价“水”。"}, {"text": "害羞", "is_correct": false, "explanation": "搭配：“害羞”描写人的性情，不能用于“水”。"}, {"text": "严肃", "is_correct": false, "explanation": "语义：“严肃”形容态度庄重，不能用来描述“水”。"}], "explanations": {"必要": "正确：“必要”表示一定要有、少了不行，用来说水的重要性，符合句意。", "热情": "语义：“热情”形容人的态度，不能用来评价“水”。", "害羞": "搭配：“害羞”描写人的性情，不能用于“水”。", "严肃": "语义：“严肃”形容态度庄重，不能用来描述“水”。"}, "sentence_index": 0, "correct_answer": "必要"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这瓶水很必要，我每天都把它倒掉。", "explanation": "这里应该用〈不必要〉。必要表示一定要有、少了不行，倒掉东西说明它没用，要用不必要。"}, {"text": "这个方法很必要，所以我们从没试过。", "explanation": "这里逻辑矛盾。必要表示一定要有，从没试过却说它必要，应该用〈不必要〉。"}, {"text": "这间房子很必要，所以我们把它拆了。", "explanation": "这里应该用〈不必要〉。必要表示一定要有、少了不行，拆掉房子说明它没用，要用不必要。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ebf6d0a-6a0d-49ed-ba1e-53a310e30a00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88651, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "必要", "is_correct": true, "explanation": "正确：“必要”表示一定要有，修饰“调料”，符合句意。"}, {"text": "生气", "is_correct": false, "explanation": "语义：“生气”形容人的情绪，不能修饰“调料”。"}, {"text": "高兴", "is_correct": false, "explanation": "语义：“高兴”形容人的心情，不能修饰“调料”。"}, {"text": "紧张", "is_correct": false, "explanation": "搭配：“紧张”形容心理状态，不能用来修饰“调料”。"}], "explanations": {"必要": "正确：“必要”表示一定要有，修饰“调料”，符合句意。", "生气": "语义：“生气”形容人的情绪，不能修饰“调料”。", "高兴": "语义：“高兴”形容人的心情，不能修饰“调料”。", "紧张": "搭配：“紧张”形容心理状态，不能用来修饰“调料”。"}, "sentence_index": 6, "correct_answer": "必要"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个工程很必要，但我们已经取消了它。", "explanation": "这里逻辑矛盾。必要表示一定要有，取消却说它必要，应该用〈不必要〉。"}, {"text": "这些蔬菜很必要，但我从来不吃。", "explanation": "这里逻辑矛盾。必要表示一定要有，从来不吃却说它必要，应该用〈不必要〉。"}, {"text": "这些书很必要，但我一本也没看。", "explanation": "这里逻辑矛盾。必要表示一定要有，一本也不看却说它必要，应该用〈不必要〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ebf6d0a-6a0d-49ed-ba1e-53a310e30a00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88651, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我觉得必要复习一下。", "corrected_sentence": "我觉得有必要复习一下。", "error_description": "错误：“必要”前缺少“有”，应为“有必要”，这是固定说法，表示值得或需要做某事。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ebf6d0a-6a0d-49ed-ba1e-53a310e30a00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88651, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他买了做饭必要米。", "corrected_sentence": "他买了做饭必要的米。", "error_description": "错误：“必要”作定语修饰具体名词时，一般要加“的”，应为“必要的米”，不能说“必要米”；“必要条件”等固定词语不在此列。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ebf6d0a-6a0d-49ed-ba1e-53a310e30a00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
