INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88652, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "不可缺少的;非做不可的。", "primary_collocate": null, "pronunciation": "bì yào", "ipa": "pi˥˩ jaʊ˥˩", "syllable_count": 2, "sentences": [{"text": "出门前，带伞是必要的。", "target_word": "必要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学好汉语，每天练习很必要。", "target_word": "必要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旅行时必要的东西不多。", "target_word": "必要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "睡觉前刷牙是必要的。", "target_word": "必要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨很大，穿雨衣是必要的。", "target_word": "必要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开车时系安全带非常必要。", "target_word": "必要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们先买一些必要的东西吧。", "target_word": "必要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做饭时，盐是必要的。", "target_word": "必要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他只带了必要的行李。", "target_word": "必要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了健康，必要的休息不能少。", "target_word": "必要", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不必要", "label": "否定"}, {"form": "必要性", "label": "名词派生"}], "register": "中性", "sense_fingerprint": "不可缺少、非做不可的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34fd70d5-5710-4b08-aede-8a64d3f83331') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88652, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "必要", "is_correct": true, "explanation": "正确：“必要”表示不可缺少，用来说带伞这件事的判断，符合句意。"}, {"text": "漂亮", "is_correct": false, "explanation": "体貌：“漂亮”描写外貌，不能用来评价“带伞”这件事。"}, {"text": "安静", "is_correct": false, "explanation": "语义：“安静”指没有声音，与带伞是否必要无关。"}, {"text": "有趣", "is_correct": false, "explanation": "语义：“有趣”指好玩，不能用来评价带伞是否必要。"}], "explanations": {"必要": "正确：“必要”表示不可缺少，用来说带伞这件事的判断，符合句意。", "漂亮": "体貌：“漂亮”描写外貌，不能用来评价“带伞”这件事。", "安静": "语义：“安静”指没有声音，与带伞是否必要无关。", "有趣": "语义：“有趣”指好玩，不能用来评价带伞是否必要。"}, "sentence_index": 0, "correct_answer": "必要"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这些书很必要，所以我们把它们扔掉了。", "explanation": "这里应该用〈不必要〉。必要表示不可缺少，扔掉东西说明它没用，要用不必要。"}, {"text": "这台电脑很必要，所以我把它卖掉了。", "explanation": "这里应该用〈不必要〉。必要表示不可缺少，卖掉东西说明它没用，要用不必要。"}, {"text": "他的作业很必要，所以他从来不写。", "explanation": "这里应该用〈不必要〉。必要表示不可缺少，从来不做说明它不重要，要用不必要。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ebf6d0a-6a0d-49ed-ba1e-53a310e30a00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88652, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "必要", "is_correct": true, "explanation": "正确：“必要”表示不可缺少，修饰“东西”，符合句意。"}, {"text": "生气", "is_correct": false, "explanation": "语义：“生气”形容人的情绪，不能修饰“东西”。"}, {"text": "高兴", "is_correct": false, "explanation": "语义：“高兴”形容人的心情，不能修饰“东西”。"}, {"text": "害羞", "is_correct": false, "explanation": "搭配：“害羞”描写人的性情，不能用来修饰“东西”。"}], "explanations": {"必要": "正确：“必要”表示不可缺少，修饰“东西”，符合句意。", "生气": "语义：“生气”形容人的情绪，不能修饰“东西”。", "高兴": "语义：“高兴”形容人的心情，不能修饰“东西”。", "害羞": "搭配：“害羞”描写人的性情，不能用来修饰“东西”。"}, "sentence_index": 6, "correct_answer": "必要"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这份报告很必要，我们昨天就把它删掉了。", "explanation": "这里逻辑矛盾。必要表示不可缺少，删掉说明它没用，应该用〈不必要〉。"}, {"text": "这次聚会很必要，所以我没有去。", "explanation": "这里逻辑矛盾。必要表示不可缺少，不去却说它必要，应该用〈不必要〉。"}, {"text": "老师的话很必要，所以我们都不听。", "explanation": "这里逻辑矛盾。必要表示不可缺少，不听却说它必要，应该用〈不必要〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ebf6d0a-6a0d-49ed-ba1e-53a310e30a00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88652, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我觉得必要提醒你。", "corrected_sentence": "我觉得有必要提醒你。", "error_description": "错误：“必要”前缺少“有”，应为“有必要”，这是固定说法，表示值得或需要做某事。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ebf6d0a-6a0d-49ed-ba1e-53a310e30a00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
