INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88653, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "题是考试或练习里要你回答的问题。", "primary_collocate": null, "pronunciation": "tí", "ipa": "ti˧˥", "syllable_count": 1, "sentences": [{"text": "考试有二十道题，时间只有一小时。", "target_word": "题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这道题我看不懂，能再说一遍吗？", "target_word": "题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一口气做完了所有的题。", "target_word": "题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，不会的题可以先跳过。", "target_word": "题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "第三道题的答案我写错了。", "target_word": "题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次练习的题不多。", "target_word": "题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天晚上做十道题。", "target_word": "题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这道题我们昨天做过。", "target_word": "题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哪道题你觉得最简单？", "target_word": "题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试时，我先做容易的题。", "target_word": "题", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "道", "label": "量词"}, {"form": "题目", "label": "复合"}, {"form": "題", "label": "繁体"}], "register": "中性", "sense_fingerprint": "题：考试或练习里需要回答的问题", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '731f2910-2ba7-4598-8f94-a05db7954603') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88653, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "题", "is_correct": true, "explanation": "“题”读 tí（第二声），指考试或练习里要回答的问题。"}, {"text": "体", "is_correct": false, "explanation": "tǐ（第三声）与 tí（第二声）声调不同，意思是身体。"}, {"text": "踢", "is_correct": false, "explanation": "tī（第一声）与 tí（第二声）声调不同，意思是用脚撞击。"}, {"text": "替", "is_correct": false, "explanation": "tì（第四声）与 tí（第二声）声调不同，意思是代替。"}], "explanations": {"题": "“题”读 tí（第二声），指考试或练习里要回答的问题。", "体": "tǐ（第三声）与 tí（第二声）声调不同，意思是身体。", "踢": "tī（第一声）与 tí（第二声）声调不同，意思是用脚撞击。", "替": "tì（第四声）与 tí（第二声）声调不同，意思是代替。"}, "sentence_index": null, "correct_answer": "题"}, "level_3": {"options": [{"text": "题", "is_correct": true, "explanation": "“题”是考试中要回答的问题，“考试有二十道题”说得通。"}, {"text": "门", "is_correct": false, "explanation": "语义：门不是考试要回答的内容，“考试有二十道门”说不通。"}, {"text": "光", "is_correct": false, "explanation": "语义：光不能作为考试的内容，句子不成立。"}, {"text": "菜", "is_correct": false, "explanation": "搭配：考试的内容是题，不说“考试有二十道菜”。"}], "explanations": {"题": "“题”是考试中要回答的问题，“考试有二十道题”说得通。", "门": "语义：门不是考试要回答的内容，“考试有二十道门”说不通。", "光": "语义：光不能作为考试的内容，句子不成立。", "菜": "搭配：考试的内容是题，不说“考试有二十道菜”。"}, "sentence_index": 0, "correct_answer": "题"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个题关系到每个人的健康。", "explanation": "这里应该用〈问题〉。题指练习、考试中要回答的题目，不能指关系到健康的社会问题。"}, {"text": "这件事让我心里充满题。", "explanation": "这里应该用〈疑问〉。题指练习、考试中要回答的问题，不能指心里的疑惑。"}, {"text": "这个题的研究经费很充足。", "explanation": "这里应该用〈课题〉。题指考试、练习中要回答的问题，不指研究项目。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eeb5d895-bc93-49e4-bd82-39a63cc9f029') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88653, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "题", "is_correct": true, "explanation": "“题”读 tí（第二声），指考试或练习里要回答的问题。"}, {"text": "梯", "is_correct": false, "explanation": "tī（第一声）与 tí（第二声）声调不同，意思是楼梯、梯子。"}, {"text": "剃", "is_correct": false, "explanation": "tì（第四声）与 tí（第二声）声调不同，意思是剃除毛发。"}, {"text": "皮", "is_correct": false, "explanation": "pí（第二声）与 tí（第二声）声母不同，意思是皮肤、皮革。"}], "explanations": {"题": "“题”读 tí（第二声），指考试或练习里要回答的问题。", "梯": "tī（第一声）与 tí（第二声）声调不同，意思是楼梯、梯子。", "剃": "tì（第四声）与 tí（第二声）声调不同，意思是剃除毛发。", "皮": "pí（第二声）与 tí（第二声）声母不同，意思是皮肤、皮革。"}, "sentence_index": null, "correct_answer": "题"}, "level_3": {"options": [{"text": "题", "is_correct": true, "explanation": "“题”是要回答的问题，“他每天晚上做十道题”说得通。"}, {"text": "云", "is_correct": false, "explanation": "语义：云不能被“做”，“做十道云”说不通。"}, {"text": "峡谷", "is_correct": false, "explanation": "语义：峡谷不是可以“做”出来的东西，句子说不通。"}, {"text": "河", "is_correct": false, "explanation": "搭配：“做”不搭配“河”，河不说“做”。"}], "explanations": {"题": "“题”是要回答的问题，“他每天晚上做十道题”说得通。", "云": "语义：云不能被“做”，“做十道云”说不通。", "峡谷": "语义：峡谷不是可以“做”出来的东西，句子说不通。", "河": "搭配：“做”不搭配“河”，河不说“做”。"}, "sentence_index": 6, "correct_answer": "题"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "考试时，我先做一本容易的题。", "explanation": "这里应该用〈道〉。题用“道”计量；〈本〉用于书册，不能计量题。"}, {"text": "考试时，我先做一首容易的题。", "explanation": "这里应该用〈道〉。〈首〉用于诗歌、歌曲，不能计量题。"}, {"text": "考试时，我先做一篇容易的题。", "explanation": "这里应该用〈道〉。〈篇〉用于文章，不能计量题。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eeb5d895-bc93-49e4-bd82-39a63cc9f029') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88653, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次考试我只做对了三本题。", "corrected_sentence": "这次考试我只做对了三道题。", "error_description": "错误形式：“三本题”；正确形式：“三道题”。“题”的量词是“道”，“本”用于书册。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eeb5d895-bc93-49e4-bd82-39a63cc9f029') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88653, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "期末前他要做完两百首题。", "corrected_sentence": "期末前他要做完两百道题。", "error_description": "错误形式：“两百首题”；正确形式：“两百道题”。“题”的量词是“道”，“首”用于诗歌、歌曲。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eeb5d895-bc93-49e4-bd82-39a63cc9f029') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
