INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88654, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "练习、考试时要求回答的问题。", "primary_collocate": null, "pronunciation": "tí", "ipa": "ti˧˥", "syllable_count": 1, "sentences": [{"text": "这道题很难，我想了半天。", "target_word": "题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们出了五道题。", "target_word": "题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天的数学题我都做完了。", "target_word": "题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这道题的答案是什么？", "target_word": "题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试时我有一道题没做出来。", "target_word": "题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他做题做得很快。", "target_word": "题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这几道题我不会，请你教教我。", "target_word": "题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你看，这道题我做对了。", "target_word": "题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "最后一道题最难。", "target_word": "题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做错的题，我会再做一遍。", "target_word": "题", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "道", "label": "量词"}, {"form": "题目", "label": "复合"}, {"form": "題", "label": "繁体"}], "register": "中性", "sense_fingerprint": "题：练习、考试中要求回答的问题，量词用“道”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '731f2910-2ba7-4598-8f94-a05db7954603') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88654, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "题", "is_correct": true, "explanation": "“题”读 tí（第二声），指练习、考试中要求回答的问题。"}, {"text": "体", "is_correct": false, "explanation": "tǐ（第三声）与 tí（第二声）声调不同，意思是身体。"}, {"text": "踢", "is_correct": false, "explanation": "tī（第一声）与 tí（第二声）声调不同，意思是用脚撞击。"}, {"text": "替", "is_correct": false, "explanation": "tì（第四声）与 tí（第二声）声调不同，意思是代替。"}], "explanations": {"题": "“题”读 tí（第二声），指练习、考试中要求回答的问题。", "体": "tǐ（第三声）与 tí（第二声）声调不同，意思是身体。", "踢": "tī（第一声）与 tí（第二声）声调不同，意思是用脚撞击。", "替": "tì（第四声）与 tí（第二声）声调不同，意思是代替。"}, "sentence_index": null, "correct_answer": "题"}, "level_3": {"options": [{"text": "题", "is_correct": true, "explanation": "“题”是要回答的问题，可以“这道题很难，我想了半天”。"}, {"text": "雨", "is_correct": false, "explanation": "语义：雨不是需要回答的问题，「这道雨很难，我想了半天」说不通。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不能「很难」地需要回答，「这道空气很难」说不通。"}, {"text": "光", "is_correct": false, "explanation": "语义：光不是可以被思考解答的对象，“这道光很难”说不通。"}], "explanations": {"题": "“题”是要回答的问题，可以“这道题很难，我想了半天”。", "雨": "语义：雨不是需要回答的问题，「这道雨很难，我想了半天」说不通。", "空气": "语义：空气不能「很难」地需要回答，「这道空气很难」说不通。", "光": "语义：光不是可以被思考解答的对象，“这道光很难”说不通。"}, "sentence_index": 0, "correct_answer": "题"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这本题我一直没做出来。", "explanation": "这里应该用〈道〉。题用“道”计量；〈本〉用于书册，“这本题”是量词用错。"}, {"text": "这首题我想了半天。", "explanation": "这里应该用〈道〉。〈首〉用于诗歌、歌曲，题不能用〈首〉计量。"}, {"text": "这篇题不太难。", "explanation": "这里应该用〈道〉。〈篇〉用于文章，题不能用〈篇〉计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eeb5d895-bc93-49e4-bd82-39a63cc9f029') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88654, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "题", "is_correct": true, "explanation": "“题”读 tí（第二声），指练习、考试中要求回答的问题。"}, {"text": "梯", "is_correct": false, "explanation": "tī（第一声）与 tí（第二声）声调不同，意思是楼梯、梯子。"}, {"text": "剃", "is_correct": false, "explanation": "tì（第四声）与 tí（第二声）声调不同，意思是剃除毛发。"}, {"text": "皮", "is_correct": false, "explanation": "pí（第二声）与 tí（第二声）声母不同，意思是皮肤、皮革。"}], "explanations": {"题": "“题”读 tí（第二声），指练习、考试中要求回答的问题。", "梯": "tī（第一声）与 tí（第二声）声调不同，意思是楼梯、梯子。", "剃": "tì（第四声）与 tí（第二声）声调不同，意思是剃除毛发。", "皮": "pí（第二声）与 tí（第二声）声母不同，意思是皮肤、皮革。"}, "sentence_index": null, "correct_answer": "题"}, "level_3": {"options": [{"text": "题", "is_correct": true, "explanation": "“题”是要回答的问题，“这几道题我不会”说得通。"}, {"text": "门", "is_correct": false, "explanation": "语义：门不是可以学会的内容，“这几道门我不会”说不通。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不是可以学会的内容，「这几道空气我不会」说不通。"}, {"text": "河", "is_correct": false, "explanation": "搭配：“这几道”后接“河”不合常规，不能这样计量河。"}], "explanations": {"题": "“题”是要回答的问题，“这几道题我不会”说得通。", "门": "语义：门不是可以学会的内容，“这几道门我不会”说不通。", "空气": "语义：空气不是可以学会的内容，「这几道空气我不会」说不通。", "河": "搭配：“这几道”后接“河”不合常规，不能这样计量河。"}, "sentence_index": 6, "correct_answer": "题"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个社会题亟待解决。", "explanation": "这里应该用〈问题〉。题只指练习、考试中要回答的问题，不指社会问题。"}, {"text": "他对这件事一直存有题。", "explanation": "这里应该用〈疑问〉。题指考试、练习中要回答的问题，不指心中的疑惑。"}, {"text": "这个科研题获得了国家奖项。", "explanation": "这里应该用〈课题〉。题指考试、练习中要回答的问题，不指研究课题。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eeb5d895-bc93-49e4-bd82-39a63cc9f029') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88654, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次数学考试有二十本题。", "corrected_sentence": "这次数学考试有二十道题。", "error_description": "错误形式：“二十本题”；正确形式：“二十道题”。“题”的量词是“道”，“本”用于书册。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eeb5d895-bc93-49e4-bd82-39a63cc9f029') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88654, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这本练习册有五十首题。", "corrected_sentence": "这本练习册有五十道题。", "error_description": "错误形式：“五十首题”；正确形式：“五十道题”。“题”的量词是“道”，“首”用于诗歌、歌曲。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eeb5d895-bc93-49e4-bd82-39a63cc9f029') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
