INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88657, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "为何是问原因,就是为什么。", "primary_collocate": null, "pronunciation": "wèi hé", "ipa": "weɪ˥˩ xɤ˧˥", "syllable_count": 2, "sentences": [{"text": "她为何一直看着窗外？", "target_word": "为何", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你为何要把门关上？", "target_word": "为何", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子问妈妈，月亮为何会跟着人走。", "target_word": "为何", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他为何不愿意跟我们去？", "target_word": "为何", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不懂，你为何这么做。", "target_word": "为何", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为何下雨天路上人这么少？", "target_word": "为何", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他为何换了工作？", "target_word": "为何", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你为何对我说谢谢？", "target_word": "为何", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书上没说这座桥为何建在这里。", "target_word": "为何", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事为何会这样，我想不明白。", "target_word": "为何", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "书面语疑问词，问原因，就是为什么", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67aa835c-524f-4aad-8e43-c58392166a3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88657, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "为何", "is_correct": true, "explanation": "为何是疑问代词，问原因，相当于“为什么”，此处问“一直看着窗外”的原因。"}, {"text": "何时", "is_correct": false, "explanation": "语义：“何时”问时间，句子问的是原因，不是时间。"}, {"text": "怎样", "is_correct": false, "explanation": "语义：“怎样”问方式，句子问的是原因，不是方式。"}, {"text": "多少", "is_correct": false, "explanation": "语义：“多少”问数量，句子问的是原因，且“她多少一直看着”不成句。"}], "explanations": {"为何": "为何是疑问代词，问原因，相当于“为什么”，此处问“一直看着窗外”的原因。", "何时": "语义：“何时”问时间，句子问的是原因，不是时间。", "怎样": "语义：“怎样”问方式，句子问的是原因，不是方式。", "多少": "语义：“多少”问数量，句子问的是原因，且“她多少一直看着”不成句。"}, "sentence_index": 0, "correct_answer": "为何"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她的歌唱得为何？", "explanation": "这里应该用〈怎么样〉：她的歌唱得怎么样？“为何”只问原因，不问状态。"}, {"text": "会议为何地点举行？", "explanation": "这里应该用〈在哪里〉：会议在哪里举行？「为何」只问原因，不能用来问地点。"}, {"text": "你家住在为何？", "explanation": "这里应该用〈哪里〉：你家住在哪里？「为何」只问原因，不能用来问地点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8331ff59-ca01-46b3-a95a-7fe76d3603d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88657, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "为何", "is_correct": true, "explanation": "为何是疑问代词，问原因，相当于“为什么”，此处问“换了工作”的原因。"}, {"text": "多少", "is_correct": false, "explanation": "语义：“多少”问数量，不问原因，“他多少换了工作”不成句。"}, {"text": "哪次", "is_correct": false, "explanation": "语义：“哪次”问次序，不问原因。"}, {"text": "哪样", "is_correct": false, "explanation": "搭配：“哪样”问样式，不能用来问“换了工作”的原因。"}], "explanations": {"为何": "为何是疑问代词，问原因，相当于“为什么”，此处问“换了工作”的原因。", "多少": "语义：“多少”问数量，不问原因，“他多少换了工作”不成句。", "哪次": "语义：“哪次”问次序，不问原因。", "哪样": "搭配：“哪样”问样式，不能用来问“换了工作”的原因。"}, "sentence_index": 6, "correct_answer": "为何"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他喜欢为何水果？", "explanation": "这里应该用〈什么〉：他喜欢什么水果？“为何”只问原因，不能问种类。"}, {"text": "书架上为何几本书？", "explanation": "这里应该用〈多少〉：书架上有多少本书？「为何」只问原因，不能用来问数量。"}, {"text": "这是为何的伞？", "explanation": "这里应该用〈谁〉：这是谁的伞？“为何”只问原因，不问所属。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8331ff59-ca01-46b3-a95a-7fe76d3603d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88657, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈为何什么这么早就出门了？", "corrected_sentence": "妈妈为何这么早就出门了？", "error_description": "错误形式：“妈妈为何什么这么早就出门了”。正确形式：“妈妈为何这么早就出门了”。“为何”已是疑问词，句中多加的“什么”造成两个疑问词叠用，应删去。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8331ff59-ca01-46b3-a95a-7fe76d3603d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88657, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "同事们为何了都离开了公司？", "corrected_sentence": "同事们为何都离开了公司？", "error_description": "错误形式：“同事们为何了都离开了公司”。正确形式：“同事们为何都离开了公司”。“为何”是疑问代词，不带“了”，后面直接接副词“都”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8331ff59-ca01-46b3-a95a-7fe76d3603d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
