INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88659, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "一级是第一个等级，是最高或最好的那一级。", "primary_collocate": null, "pronunciation": "yī jí", "ipa": "i˥ tɕi˧˥", "syllable_count": 2, "sentences": [{"text": "这种茶叶是一级的，价格很贵。", "target_word": "一级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们学校的老师都是一级教师。", "target_word": "一级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次地震的警报是一级。", "target_word": "一级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件衣服是一级，那件是二级。", "target_word": "一级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种大米是一级的，非常好吃。", "target_word": "一级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家工厂的产品都是一级。", "target_word": "一级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这批钢材是一级的，质量很好。", "target_word": "一级", "complexity_tier": "T3", "furigana": "yī jí", "sentence_source": "generated"}, {"text": "这次考试，他的成绩达到了一级。", "target_word": "一级", "complexity_tier": "T3", "furigana": "yī jí", "sentence_source": "generated"}, {"text": "这条河的水质是一级，可以喝。", "target_word": "一级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家酒店的服务是一级的，客人都很满意。", "target_word": "一级", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "第一个等级，最高或最好的一级", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a25abb85-5ccf-42fc-84cc-7d66d0607671') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88659, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "一级", "is_correct": true, "explanation": "“一级”读 yī jí，指第一个等级、最高或最好的那一级，与所听的音一致。"}, {"text": "亿级", "is_correct": false, "explanation": "“亿”（yì，第四声）与“一”（yī，第一声）声调不同，“亿级”指亿这个数量级。"}, {"text": "乙级", "is_correct": false, "explanation": "“乙”（yǐ，第三声）与“一”（yī，第一声）声调不同，“乙级”指第二等级。"}, {"text": "医技", "is_correct": false, "explanation": "“技”（jì，第四声）与“级”（jí，第二声）声调不同，“医技”指医疗技术。"}, {"text": "一局", "is_correct": false, "explanation": "“局”（jú）与“级”（jí）韵母不同，“一局”指一盘或一场。"}], "explanations": {"一级": "“一级”读 yī jí，指第一个等级、最高或最好的那一级，与所听的音一致。", "亿级": "“亿”（yì，第四声）与“一”（yī，第一声）声调不同，“亿级”指亿这个数量级。", "乙级": "“乙”（yǐ，第三声）与“一”（yī，第一声）声调不同，“乙级”指第二等级。", "医技": "“技”（jì，第四声）与“级”（jí，第二声）声调不同，“医技”指医疗技术。", "一局": "“局”（jú）与“级”（jí）韵母不同，“一局”指一盘或一场。"}, "sentence_index": null, "correct_answer": "一级"}, "level_3": {"options": [{"text": "便宜", "is_correct": false, "explanation": "语义：“便宜”与后面的“价格很贵”自相矛盾。"}, {"text": "轻便", "is_correct": false, "explanation": "搭配：“轻便”多用于形容鞋、包等物件，不用来形容茶叶。"}, {"text": "一级", "is_correct": true, "explanation": "正确：“一级”表示最高等级，可以说“是一级的”。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容人或物的形体，不用来形容茶叶的品质。"}], "explanations": {"便宜": "语义：“便宜”与后面的“价格很贵”自相矛盾。", "轻便": "搭配：“轻便”多用于形容鞋、包等物件，不用来形容茶叶。", "一级": "正确：“一级”表示最高等级，可以说“是一级的”。", "高大": "体貌：“高大”形容人或物的形体，不用来形容茶叶的品质。"}, "sentence_index": 0, "correct_answer": "一级"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件事是一级大事，大家都很重视。", "explanation": "这里应该用〈头等〉。“头等大事”指最重要的事，“一级大事”不这样说。"}, {"text": "她是我们年级的一级生。", "explanation": "这里应该用〈优等〉。成绩优秀的学生说“优等生”，“一级生”不这样说。"}, {"text": "他的答案是一级的，老师给了满分。", "explanation": "这里应该用〈正确〉。答案的对错要说“正确”，“一级”用于等级划分，不能用来评价答案对错。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b39abac4-41a8-471c-9f79-f136dc0d8927') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88659, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "一级", "is_correct": true, "explanation": "“一级”读 yī jí，指第一个等级、最高或最好的那一级，与所听的音一致。"}, {"text": "一季", "is_correct": false, "explanation": "“季”（jì，第四声）与“级”（jí，第二声）声调不同，“一季”指一个季度或季节。"}, {"text": "一击", "is_correct": false, "explanation": "“击”（jī，第一声）与“级”（jí，第二声）声调不同，“一击”指一次攻击。"}, {"text": "一剂", "is_correct": false, "explanation": "“剂”（jì，第四声）与“级”（jí，第二声）声调不同，“一剂”指一服药。"}, {"text": "音级", "is_correct": false, "explanation": "“音”（yīn）比“一”（yī）多了鼻音韵尾 n，“音级”指音阶上的一个音级。"}], "explanations": {"一级": "“一级”读 yī jí，指第一个等级、最高或最好的那一级，与所听的音一致。", "一季": "“季”（jì，第四声）与“级”（jí，第二声）声调不同，“一季”指一个季度或季节。", "一击": "“击”（jī，第一声）与“级”（jí，第二声）声调不同，“一击”指一次攻击。", "一剂": "“剂”（jì，第四声）与“级”（jí，第二声）声调不同，“一剂”指一服药。", "音级": "“音”（yīn）比“一”（yī）多了鼻音韵尾 n，“音级”指音阶上的一个音级。"}, "sentence_index": null, "correct_answer": "一级"}, "level_3": {"options": [{"text": "劣质", "is_correct": false, "explanation": "语义：“劣质”与后面的“质量很好”自相矛盾。"}, {"text": "透明", "is_correct": false, "explanation": "搭配：“透明”不用来形容钢材。"}, {"text": "一级", "is_correct": true, "explanation": "正确：“一级”表示最高等级，可以说“是一级的”。"}, {"text": "甜", "is_correct": false, "explanation": "搭配：“甜”是味觉词，不能用来形容钢材。"}], "explanations": {"劣质": "语义：“劣质”与后面的“质量很好”自相矛盾。", "透明": "搭配：“透明”不用来形容钢材。", "一级": "正确：“一级”表示最高等级，可以说“是一级的”。", "甜": "搭配：“甜”是味觉词，不能用来形容钢材。"}, "sentence_index": 6, "correct_answer": "一级"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她在演讲比赛中拿了一级奖。", "explanation": "这里应该用〈一等〉。比赛名次说“一等奖”，“一级奖”不这样说。"}, {"text": "这栋大楼是一级写字楼。", "explanation": "这里应该用〈甲级〉。写字楼的等级一般说“甲级”，不说“一级写字楼”。"}, {"text": "他一级跑完了全程。", "explanation": "这里应该用〈一口气〉。“一级”不能作动量词，一次完成全程不说“一级”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b39abac4-41a8-471c-9f79-f136dc0d8927') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88659, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台机器的安全等级很一级。", "corrected_sentence": "这台机器的安全等级是一级。", "error_description": "错误形式：“很一级”；正确形式：“是一级”。“一级”表示等级，不能受程度副词“很”修饰，说明等级要用“是一级”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b39abac4-41a8-471c-9f79-f136dc0d8927') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88659, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这栋楼的耐火等级是的一级。", "corrected_sentence": "这栋楼的耐火等级是一级。", "error_description": "错误形式：“是的一级”；正确形式：“是一级”。“的”不能插在“是”和“一级”之间，多出的“的”使句子不通顺，应删去。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b39abac4-41a8-471c-9f79-f136dc0d8927') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88660, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b39abac4-41a8-471c-9f79-f136dc0d8927') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
