INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88660, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "第一个等级；最高等级。", "primary_collocate": null, "pronunciation": "yī jí", "ipa": "i˥ tɕi˧˥", "syllable_count": 2, "sentences": [{"text": "这家饭店的卫生评定是一级。", "target_word": "一级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种茶叶是一级的，价格最高。", "target_word": "一级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些苹果质量最好，都是一级。", "target_word": "一级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市的空气质量达到了一级。", "target_word": "一级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的厨艺是一级的，大家都爱吃。", "target_word": "一级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座大楼的抗震能力达到了一级。", "target_word": "一级", "complexity_tier": "T3", "furigana": "yī jí", "sentence_source": "generated"}, {"text": "这座古桥是国家一级保护文物。", "target_word": "一级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试成绩分三级，他得了一级。", "target_word": "一级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个景区是一级景区，很有名。", "target_word": "一级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的书法是一级的，没人比得过。", "target_word": "一级", "complexity_tier": "T3", "furigana": "yī jí", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "第一个等级，最高等级", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a25abb85-5ccf-42fc-84cc-7d66d0607671') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88660, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "一级", "is_correct": true, "explanation": "“一级”读 yī jí，指第一个等级、最高等级，与所听的音一致。"}, {"text": "亿级", "is_correct": false, "explanation": "“亿”（yì，第四声）与“一”（yī，第一声）声调不同，“亿级”指亿这个数量级，如亿级用户。"}, {"text": "乙级", "is_correct": false, "explanation": "“乙”（yǐ，第三声）与“一”（yī，第一声）声调不同，“乙级”指第二等级。"}, {"text": "医技", "is_correct": false, "explanation": "“技”（jì，第四声）与“级”（jí，第二声）声调不同，“医技”指医疗技术。"}, {"text": "一击", "is_correct": false, "explanation": "“击”（jī，第一声）与“级”（jí，第二声）声调不同，“一击”指一次攻击。"}, {"text": "一局", "is_correct": false, "explanation": "“局”（jú）与“级”（jí）韵母不同，“一局”指一盘或一场。"}], "explanations": {"一级": "“一级”读 yī jí，指第一个等级、最高等级，与所听的音一致。", "亿级": "“亿”（yì，第四声）与“一”（yī，第一声）声调不同，“亿级”指亿这个数量级，如亿级用户。", "乙级": "“乙”（yǐ，第三声）与“一”（yī，第一声）声调不同，“乙级”指第二等级。", "医技": "“技”（jì，第四声）与“级”（jí，第二声）声调不同，“医技”指医疗技术。", "一击": "“击”（jī，第一声）与“级”（jí，第二声）声调不同，“一击”指一次攻击。", "一局": "“局”（jú）与“级”（jí）韵母不同，“一局”指一盘或一场。"}, "sentence_index": null, "correct_answer": "一级"}, "level_3": {"options": [{"text": "热闹", "is_correct": false, "explanation": "搭配：“热闹”形容场面，不能作为卫生评定的结果。"}, {"text": "一级", "is_correct": true, "explanation": "正确：“一级”表示最高等级，卫生评定可以说“是一级”。"}, {"text": "好吃", "is_correct": false, "explanation": "搭配：“好吃”形容食物味道，不是评定等级。"}, {"text": "便宜", "is_correct": false, "explanation": "语义：“便宜”说的是价格，不是卫生评定的等级。"}], "explanations": {"热闹": "搭配：“热闹”形容场面，不能作为卫生评定的结果。", "一级": "正确：“一级”表示最高等级，卫生评定可以说“是一级”。", "好吃": "搭配：“好吃”形容食物味道，不是评定等级。", "便宜": "语义：“便宜”说的是价格，不是卫生评定的等级。"}, "sentence_index": 0, "correct_answer": "一级"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在比赛中拿了一级奖。", "explanation": "这里应该用〈一等〉。比赛名次要说“一等奖”，“一级”用于等级划分，如医院、文物，不说“一级奖”。"}, {"text": "他的身高是一级的。", "explanation": "这里应该用〈一米八〉。身高按数值描述，不按等级划分，“一级”不适用。"}, {"text": "他跑步的速度是一级的，拿了冠军。", "explanation": "这里应该用〈很快〉。速度用快慢描述，不按等级划分，“一级”不适用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b39abac4-41a8-471c-9f79-f136dc0d8927') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88660, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "一级", "is_correct": true, "explanation": "“一级”读 yī jí，指第一个等级、最高等级，与所听的音一致。"}, {"text": "一季", "is_correct": false, "explanation": "“季”（jì，第四声）与“级”（jí，第二声）声调不同，“一季”指一个季度或季节。"}, {"text": "一记", "is_correct": false, "explanation": "“记”（jì，第四声）与“级”（jí，第二声）声调不同，“一记”是一下的量词用法，如一记耳光。"}, {"text": "一剂", "is_correct": false, "explanation": "“剂”（jì，第四声）与“级”（jí，第二声）声调不同，“一剂”指一服药。"}, {"text": "音级", "is_correct": false, "explanation": "“音”（yīn）比“一”（yī）多了鼻音韵尾 n，“音级”指音阶上的一个音级。"}], "explanations": {"一级": "“一级”读 yī jí，指第一个等级、最高等级，与所听的音一致。", "一季": "“季”（jì，第四声）与“级”（jí，第二声）声调不同，“一季”指一个季度或季节。", "一记": "“记”（jì，第四声）与“级”（jí，第二声）声调不同，“一记”是一下的量词用法，如一记耳光。", "一剂": "“剂”（jì，第四声）与“级”（jí，第二声）声调不同，“一剂”指一服药。", "音级": "“音”（yīn）比“一”（yī）多了鼻音韵尾 n，“音级”指音阶上的一个音级。"}, "sentence_index": null, "correct_answer": "一级"}, "level_3": {"options": [{"text": "省级", "is_correct": false, "explanation": "语义：“省级”指省一级，与“国家”的范围冲突。"}, {"text": "一级", "is_correct": true, "explanation": "正确：“一级”表示最高等级，可用于文物保护等级，符合“国家一级”的说法。"}, {"text": "脆弱", "is_correct": false, "explanation": "搭配：“脆弱”形容事物不耐用，不能用来说文物的保护等级。"}, {"text": "县级", "is_correct": false, "explanation": "语义：“县级”指县一级，与“国家”的范围冲突。"}], "explanations": {"省级": "语义：“省级”指省一级，与“国家”的范围冲突。", "一级": "正确：“一级”表示最高等级，可用于文物保护等级，符合“国家一级”的说法。", "脆弱": "搭配：“脆弱”形容事物不耐用，不能用来说文物的保护等级。", "县级": "语义：“县级”指县一级，与“国家”的范围冲突。"}, "sentence_index": 6, "correct_answer": "一级"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这栋写字楼的等级是一级的。", "explanation": "这里应该用〈甲级〉。写字楼的等级通常说“甲级”“乙级”，不说“一级”。"}, {"text": "她是班里的一级生。", "explanation": "这里应该用〈优等〉。学习成绩好的学生说“优等生”，“一级生”不这样说。"}, {"text": "我们买的是一级舱的机票。", "explanation": "这里应该用〈头等〉。舱位的等级说“头等舱”，“一级舱”不这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b39abac4-41a8-471c-9f79-f136dc0d8927') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88660, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家饭店的卫生检查结果很一级。", "corrected_sentence": "这家饭店的卫生检查结果是一级。", "error_description": "错误形式：“很一级”；正确形式：“是一级”。“一级”表示等级，不能受程度副词“很”修饰，说明等级要用“是一级”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b39abac4-41a8-471c-9f79-f136dc0d8927') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88660, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座水库的大坝是一级地，很安全。", "corrected_sentence": "这座水库的大坝是一级的，很安全。", "error_description": "错误形式：“是一级地”；正确形式：“是一级的”。“是……的”句中要用结构助词“的”，不能用“地”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b39abac4-41a8-471c-9f79-f136dc0d8927') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88661, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "跟随", "is_correct": true, "explanation": "跟随：走在别人后面，与“引领”相对。"}, {"text": "躲避", "is_correct": false, "explanation": "躲避：指避开，与引领没有反义关系。"}, {"text": "依靠", "is_correct": false, "explanation": "依靠：指倚赖他人，与引领没有反义关系。"}, {"text": "挖掘", "is_correct": false, "explanation": "挖掘：指向下掘取，与引领没有反义关系。"}], "correct_answer": "跟随", "explanations": {"跟随": "跟随：走在别人后面，与“引领”相对。", "躲避": "躲避：指避开，与引领没有反义关系。", "依靠": "依靠：指倚赖他人，与引领没有反义关系。", "挖掘": "挖掘：指向下掘取，与引领没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cca996fa-89f2-4b62-b054-8f3d42d0e953') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
