INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88661, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "引领是走在前面，带大家往前走。", "primary_collocate": null, "pronunciation": "yǐn lǐng", "ipa": "in˨˩˦ liŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "爬山时，小李走在最前面引领大家。", "target_word": "引领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "队长引领着队伍向前走。", "target_word": "引领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "导游举着小旗引领游客过马路。", "target_word": "引领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗引领着我们走进树林。", "target_word": "引领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他引领大家一步一步走上山顶。", "target_word": "引领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师引领同学们排好队走出教室。", "target_word": "引领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我愿意在前面引领你们。", "target_word": "引领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村长引领村民走过小桥。", "target_word": "引领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "灯光引领我们走出了黑暗的山洞。", "target_word": "引领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他引领着十个人的小队穿过森林。", "target_word": "引领", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "引领着", "label": "体标"}, {"form": "引领了", "label": "体标"}, {"form": "引领过", "label": "体标"}], "register": "书面", "sense_fingerprint": "引领：走在前面，带大家往前走", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1265afb-6555-40ef-9957-6070abf5a913') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88661, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "引领", "is_correct": true, "explanation": "引领：走在前面带路，与句中“走在最前面”相符。"}, {"text": "修补", "is_correct": false, "explanation": "语义：“修补”指把破损的东西补好，不能用于带领大家。"}, {"text": "煎", "is_correct": false, "explanation": "搭配：“煎”的对象是食物，不能用于大家。"}, {"text": "擦拭", "is_correct": false, "explanation": "搭配：“擦拭”的对象是物体表面，不能用于大家。"}], "explanations": {"引领": "引领：走在前面带路，与句中“走在最前面”相符。", "修补": "语义：“修补”指把破损的东西补好，不能用于带领大家。", "煎": "搭配：“煎”的对象是食物，不能用于大家。", "擦拭": "搭配：“擦拭”的对象是物体表面，不能用于大家。"}, "sentence_index": 0, "correct_answer": "引领"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他引领着一桶水走过马路。", "explanation": "这里应该用〈提〉。引领的对象是人或队伍，提水桶要用「提」。"}, {"text": "小李走在最后面引领大家。", "explanation": "这里应该用〈殿后〉。引领是走在前面带路，走在最后面的人要说殿后，不说引领。"}, {"text": "他引领着箱子走进房间。", "explanation": "这里应该用〈拖〉。引领带的是人，拖箱子要用“拖”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cca996fa-89f2-4b62-b054-8f3d42d0e953') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88661, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "引领", "is_correct": true, "explanation": "引领：在前面带路，与“在前面”相符。"}, {"text": "烧毁", "is_correct": false, "explanation": "语义：“烧毁”是毁坏的意思，不能用于带领你们。"}, {"text": "播种", "is_correct": false, "explanation": "语义：“播种”指撒种子，不能用于你们。"}, {"text": "擦拭", "is_correct": false, "explanation": "搭配：“擦拭”的对象是物体表面，不能用于人。"}], "explanations": {"引领": "引领：在前面带路，与“在前面”相符。", "烧毁": "语义：“烧毁”是毁坏的意思，不能用于带领你们。", "播种": "语义：“播种”指撒种子，不能用于你们。", "擦拭": "搭配：“擦拭”的对象是物体表面，不能用于人。"}, "sentence_index": 6, "correct_answer": "引领"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他引领着行李穿过森林。", "explanation": "这里应该用〈扛〉。引领带的是人或队伍，扛行李要用“扛”。"}, {"text": "他落在队伍最后面，却引领着大家。", "explanation": "这里应该用〈殿后〉。引领是走在前面带路，落在队伍最后面的人不能说引领，应说殿后或压阵。"}, {"text": "他引领着自行车穿过森林。", "explanation": "这里应该用〈骑〉。引领带的是人，骑自行车要用“骑”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cca996fa-89f2-4b62-b054-8f3d42d0e953') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
