INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88662, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "带领；引导向前。", "primary_collocate": null, "pronunciation": "yǐn lǐng", "ipa": "in˨˩˦ liŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "老师引领我们走进博物馆。", "target_word": "引领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他引领大家参观了新工厂。", "target_word": "引领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位导游引领着客人走过老街。", "target_word": "引领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "队长引领大家走出了茂密的森林。", "target_word": "引领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "校长引领全校学生唱校歌。", "target_word": "引领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王引领着我们找到了会议室。", "target_word": "引领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老人曾经引领过许多年轻人。", "target_word": "引领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小红引领我们走进了一条幽静的小巷。", "target_word": "引领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她引领孩子们走进了花园。", "target_word": "引领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的老师应该引领学生努力学习。", "target_word": "引领", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "引领着", "label": "体标"}, {"form": "引领了", "label": "体标"}, {"form": "引领过", "label": "体标"}], "register": "书面", "sense_fingerprint": "引领：带领、引导别人向前", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1265afb-6555-40ef-9957-6070abf5a913') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, va