INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88662, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "引领", "is_correct": true, "explanation": "引领：带领人向前走，与“我们走进博物馆”相符。"}, {"text": "驾驶", "is_correct": false, "explanation": "搭配：“驾驶”的对象是车辆，不能用来带领人。"}, {"text": "烧毁", "is_correct": false, "explanation": "语义：“烧毁”是毁坏的意思，与带领人走进博物馆的意思不符。"}, {"text": "翻译", "is_correct": false, "explanation": "语义：“翻译”指转换语言，不能用来指带领人走进博物馆。"}], "explanations": {"引领": "引领：带领人向前走，与“我们走进博物馆”相符。", "驾驶": "搭配：“驾驶”的对象是车辆，不能用来带领人。", "烧毁": "语义：“烧毁”是毁坏的意思，与带领人走进博物馆的意思不符。", "翻译": "语义：“翻译”指转换语言，不能用来指带领人走进博物馆。"}, "sentence_index": 0, "correct_answer": "引领"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "公司引领了新设备。", "explanation": "这里应该用〈引进〉。引领指带领人或潮流向前，不能用来说把设备引入公司。"}, {"text": "这件事引领了大家的注意。", "explanation": "这里应该用〈引起〉。引领指带领向前，不能用于“注意”。"}, {"text": "这次事故引领了人们的警惕。", "explanation": "这里应该用〈唤起〉。引领指带领人或潮流向前，不能用于“警惕”这类心理状态；唤起人们的警惕要用“唤起”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cca996fa-89f2-4b62-b054-8f3d42d0e953') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88662, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "引领", "is_correct": true, "explanation": "引领：带领人向前走，符合“曾经……许多年轻人”的句意。"}, {"text": "煎", "is_correct": false, "explanation": "搭配：“煎”的对象是食物，不能用于年轻人。"}, {"text": "播种", "is_correct": false, "explanation": "语义：“播种”指撒种子，不能用于带领年轻人。"}, {"text": "熄灭", "is_correct": false, "explanation": "语义：“熄灭”指火或光不再燃烧，不能用于年轻人。"}], "explanations": {"引领": "引领：带领人向前走，符合“曾经……许多年轻人”的句意。", "煎": "搭配：“煎”的对象是食物，不能用于年轻人。", "播种": "语义：“播种”指撒种子，不能用于带领年轻人。", "熄灭": "语义：“熄灭”指火或光不再燃烧，不能用于年轻人。"}, "sentence_index": 6, "correct_answer": "引领"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校应该引领学生的能力。", "explanation": "这里应该用〈培养〉。引领指带领人向前走，不能用来说培养能力。"}, {"text": "这把钥匙引领了门。", "explanation": "这里应该用〈打开〉。引领的对象是人或队伍，不能用于门。"}, {"text": "这家工厂引领了货物。", "explanation": "这里应该用〈输送〉。引领带领的对象是人，不能用于货物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cca996fa-89f2-4b62-b054-8f3d42d0e953') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88662, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们将在前面引领了游客走过草地。", "corrected_sentence": "他们将在前面引领游客走过草地。", "error_description": "错误形式是“引领了游客”，正确形式是“引领游客”。“将”表示将来，句中“引领”后不应加“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cca996fa-89f2-4b62-b054-8f3d42d0e953') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88662, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老板引领员工着走进新工厂。", "corrected_sentence": "老板引领员工走进新工厂。", "error_description": "错误形式是“引领员工着”，正确形式是“引领员工”。“着”不能放在宾语“员工”后面，这句话不需要体标，直接说“引领员工走进新工厂”即可。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cca996fa-89f2-4b62-b054-8f3d42d0e953') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
