INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88663, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "雇主是给钱请别人来帮忙做事的人。", "primary_collocate": null, "pronunciation": "gù zhǔ", "ipa": "ku˥˩ ʈʂu˨˩˦", "syllable_count": 2, "sentences": [{"text": "我的雇主是一位老太太。", "target_word": "雇主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雇主每个月给我两千块钱。", "target_word": "雇主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雇主请他来家里修水管。", "target_word": "雇主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位雇主对人很客气。", "target_word": "雇主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想找一个好雇主。", "target_word": "雇主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雇主说明天不用来了。", "target_word": "雇主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她给雇主做了三年饭。", "target_word": "雇主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雇主对我的工作很满意。", "target_word": "雇主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的雇主住在国外。", "target_word": "雇主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雇主要给工人发工钱。", "target_word": "雇主", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "个", "label": "量词"}, {"form": "僱主", "label": "繁体"}], "register": "中性", "sense_fingerprint": "给钱请别人来帮忙做事的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9bc0fff-f698-48aa-a31e-eceacc41eba5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88663, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "雇主", "is_correct": true, "explanation": "雇主 gù zhǔ，指出钱请别人来做事的人。"}, {"text": "户主", "is_correct": false, "explanation": "hù（h）与 gù（g）声母不同，意思是一家之主。"}, {"text": "物主", "is_correct": false, "explanation": "wù（w）与 gù（g）声母不同，意思是东西的所有者。"}, {"text": "苦主", "is_correct": false, "explanation": "kǔ（送气 k）与 gù（不送气 g）声母和声调都不同，意思是案件中的受害人一方。"}], "explanations": {"雇主": "雇主 gù zhǔ，指出钱请别人来做事的人。", "户主": "hù（h）与 gù（g）声母不同，意思是一家之主。", "物主": "wù（w）与 gù（g）声母不同，意思是东西的所有者。", "苦主": "kǔ（送气 k）与 gù（不送气 g）声母和声调都不同，意思是案件中的受害人一方。"}, "sentence_index": null, "correct_answer": "雇主"}, "level_3": {"options": [{"text": "孩子", "is_correct": false, "explanation": "语义：“孩子”与“是一位老太太”冲突，年龄和身份对不上。"}, {"text": "雇主", "is_correct": true, "explanation": "正确：“雇主”指出钱请人做事的人，可以是一位老太太。"}, {"text": "房子", "is_correct": false, "explanation": "搭配：“一位”只能修饰人，“房子”不能与“是一位老太太”搭配。"}, {"text": "婴儿", "is_correct": false, "explanation": "语义：“婴儿”年纪太小，不可能是一位老太太。"}], "explanations": {"孩子": "语义：“孩子”与“是一位老太太”冲突，年龄和身份对不上。", "雇主": "正确：“雇主”指出钱请人做事的人，可以是一位老太太。", "房子": "搭配：“一位”只能修饰人，“房子”不能与“是一位老太太”搭配。", "婴儿": "语义：“婴儿”年纪太小，不可能是一位老太太。"}, "sentence_index": 0, "correct_answer": "雇主"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "雇主每个月都从我手里领工资。", "explanation": "这里应该用〈工人〉。领工资的是被雇用干活的一方，“雇主”是付工资、请人干活的一方，这里角色正好相反。"}, {"text": "我每天在这家公司打工，每月从老板那里领工资，却是这里的雇主。", "explanation": "这里应该用〈雇员〉。我为公司打工，是被雇用的人；“雇主”是出钱雇人的一方。"}, {"text": "我每天凌晨骑车送餐，靠配送费赚钱，却是平台的雇主。", "explanation": "这里应该用〈外卖员〉。骑车送餐、靠配送费赚钱的是被雇用干活的人；“雇主”指出钱请人的一方，不能用于此。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b7ebae2-2f65-4161-84f1-edbb55d44851') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88663, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "电脑", "is_correct": false, "explanation": "语义：“电脑”不吃饭，不能做饭给它。"}, {"text": "雇主", "is_correct": true, "explanation": "正确：“雇主”是她做饭的对象，“做了三年饭”与之搭配。"}, {"text": "锅", "is_correct": false, "explanation": "搭配：“做饭”要给能吃饭的人，“锅”不能吃饭，不能说“给锅做饭”。"}, {"text": "石头", "is_correct": false, "explanation": "语义：“石头”不吃饭，句意不通。"}], "explanations": {"电脑": "语义：“电脑”不吃饭，不能做饭给它。", "雇主": "正确：“雇主”是她做饭的对象，“做了三年饭”与之搭配。", "锅": "搭配：“做饭”要给能吃饭的人，“锅”不能吃饭，不能说“给锅做饭”。", "石头": "语义：“石头”不吃饭，句意不通。"}, "sentence_index": 6, "correct_answer": "雇主"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这只猫的雇主每天给它喂鱼。", "explanation": "这里应该用〈主人〉。养宠物的人称“主人”，“雇主”指雇用他人劳动的人。"}, {"text": "我每个月按时把房租交给雇主。", "explanation": "这里应该用〈房东〉。付房租的对象是出租房屋的人，“雇主”是出钱请人做事的一方。"}, {"text": "小区的雇主每月都要交物业费。", "explanation": "这里应该用〈业主〉。交物业费的是房屋所有人，“雇主”不用于指房屋所有者。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b7ebae2-2f65-4161-84f1-edbb55d44851') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88663, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我遇到过一只雇主，他对我很客气。", "corrected_sentence": "我遇到过一位雇主，他对我很客气。", "error_description": "量词错误：“雇主”指人，量词应用“位”，不能用“只”。正确形式是“一位雇主”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b7ebae2-2f65-4161-84f1-edbb55d44851') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88663, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我找到过一个雇主们。", "corrected_sentence": "我找到过一个雇主。", "error_description": "复数错误：“一个”表示单数，前面有“一个”时不能再加“们”，应说“一个雇主”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b7ebae2-2f65-4161-84f1-edbb55d44851') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
