INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88664, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "出钱雇用他人劳动的人或单位。", "primary_collocate": null, "pronunciation": "gù zhǔ", "ipa": "ku˥˩ ʈʂu˨˩˦", "syllable_count": 2, "sentences": [{"text": "这家公司是他的雇主。", "target_word": "雇主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雇主要按时给工人发工资。", "target_word": "雇主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂是三百名工人的雇主。", "target_word": "雇主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "找工作时，要先看雇主的名声。", "target_word": "雇主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的雇主是一家大银行。", "target_word": "雇主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雇主和工人签了一份合同。", "target_word": "雇主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他换了雇主，工资高了不少。", "target_word": "雇主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校是很多老师的雇主。", "target_word": "雇主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好雇主会关心工人的生活。", "target_word": "雇主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雇主不能不给工人工资。", "target_word": "雇主", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "个", "label": "量词"}, {"form": "僱主", "label": "繁体"}], "register": "中性", "sense_fingerprint": "出钱雇用他人劳动的人或单位", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9bc0fff-f698-48aa-a31e-eceacc41eba5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88664, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "雇主", "is_correct": true, "explanation": "雇主 gù zhǔ，指出钱雇用他人劳动的人或单位。"}, {"text": "户主", "is_correct": false, "explanation": "hù（h）与 gù（g）声母不同，意思是一家之主。"}, {"text": "物主", "is_correct": false, "explanation": "wù（w）与 gù（g）声母不同，意思是东西的所有者。"}, {"text": "苦主", "is_correct": false, "explanation": "kǔ（送气 k）与 gù（不送气 g）声母和声调都不同，意思是案件中的受害人一方。"}], "explanations": {"雇主": "雇主 gù zhǔ，指出钱雇用他人劳动的人或单位。", "户主": "hù（h）与 gù（g）声母不同，意思是一家之主。", "物主": "wù（w）与 gù（g）声母不同，意思是东西的所有者。", "苦主": "kǔ（送气 k）与 gù（不送气 g）声母和声调都不同，意思是案件中的受害人一方。"}, "sentence_index": null, "correct_answer": "雇主"}, "level_3": {"options": [{"text": "同学", "is_correct": false, "explanation": "语义：公司不能是“同学”，与“这家公司是他的”矛盾。"}, {"text": "房子", "is_correct": false, "explanation": "搭配：“房子”指住所，不能与“这家公司是他的”搭配。"}, {"text": "雇主", "is_correct": true, "explanation": "正确：“雇主”指出钱雇人的一方，公司可以是雇主。"}, {"text": "妻子", "is_correct": false, "explanation": "语义：“妻子”是人，公司不能是他的妻子。"}], "explanations": {"同学": "语义：公司不能是“同学”，与“这家公司是他的”矛盾。", "房子": "搭配：“房子”指住所，不能与“这家公司是他的”搭配。", "雇主": "正确：“雇主”指出钱雇人的一方，公司可以是雇主。", "妻子": "语义：“妻子”是人，公司不能是他的妻子。"}, "sentence_index": 0, "correct_answer": "雇主"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "雇主每天在流水线上组装手机，每月从老板那里领工资。", "explanation": "这里应该用〈工人〉。在流水线上干活、领工资的是被雇用的一方；“雇主”是出钱请人的一方，角色正好相反。"}, {"text": "雇主每个月都来收一次房租。", "explanation": "这里应该用〈房东〉。收房租的是出租房屋的一方，“雇主”是出钱请人干活的一方，不用于此。"}, {"text": "我在这家工厂干了十年，每月从老板那里领工资，却是这里的雇主。", "explanation": "这里应该用〈雇员〉。在工厂打工的人是雇员，“雇主”是出钱请人的一方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b7ebae2-2f65-4161-84f1-edbb55d44851') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88664, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "朋友", "is_correct": false, "explanation": "语义：“朋友”不发工资，与“工资高了”没有关系。"}, {"text": "雇主", "is_correct": true, "explanation": "正确：“雇主”可以换，换了雇主后工资能提高，句意通顺。"}, {"text": "名字", "is_correct": false, "explanation": "搭配：“换名字”虽可说，但“名字”与“工资高了”无法搭配成因果关系。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”不是给人发工资的一方，句意不通。"}], "explanations": {"朋友": "语义：“朋友”不发工资，与“工资高了”没有关系。", "雇主": "正确：“雇主”可以换，换了雇主后工资能提高，句意通顺。", "名字": "搭配：“换名字”虽可说，但“名字”与“工资高了”无法搭配成因果关系。", "天气": "语义：“天气”不是给人发工资的一方，句意不通。"}, "sentence_index": 6, "correct_answer": "雇主"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这辆车的雇主每年都要去年检。", "explanation": "这里应该用〈车主〉。车的所有人称“车主”，“雇主”指雇用他人劳动的人。"}, {"text": "这栋楼的雇主要按时交物业费。", "explanation": "这里应该用〈业主〉。交物业费的是房屋所有人，“雇主”不用于指房屋所有者。"}, {"text": "这家公司的雇主每月都从工人那里领工资。", "explanation": "这里应该用〈工人〉。领工资的是被雇用干活的一方；“雇主”是付工资的一方，这里角色正好相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b7ebae2-2f65-4161-84f1-edbb55d44851') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88664, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只雇主每个月都按时发工资。", "corrected_sentence": "这位雇主每个月都按时发工资。", "error_description": "量词错误：“雇主”指人，应用“位”或“个”，不能用“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b7ebae2-2f65-4161-84f1-edbb55d44851') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88664, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我终于找到了一个雇主们。", "corrected_sentence": "我终于找到了一个雇主。", "error_description": "复数错误：“一个”表示单数，前面有“一个”时不能再加“们”，应说“一个雇主”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b7ebae2-2f65-4161-84f1-edbb55d44851') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
