INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88665, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "看中就是看了以后,觉得很好,想要。", "primary_collocate": null, "pronunciation": "kàn zhòng", "ipa": "kʰan˥˩ ʈʂʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "我看中了这双运动鞋，可是太贵。", "target_word": "看中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟看中了一个新玩具。", "target_word": "看中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她看中这张桌子，想放在书房。", "target_word": "看中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在市场看中了几个苹果。", "target_word": "看中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师看中了他的画，想放在教室里。", "target_word": "看中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件外套我看中很久了。", "target_word": "看中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你看中什么，就告诉我。", "target_word": "看中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看中了那台电脑，想存钱买。", "target_word": "看中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她看中了路边的一盆花。", "target_word": "看中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们都看中了这个公园旁边的房子。", "target_word": "看中", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "看中", "label": "原形"}, {"form": "看中了", "label": "体标"}, {"form": "看不中", "label": "可能补语否定式"}], "register": "口语", "sense_fingerprint": "看了以后觉得很好而想要", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7650858-8e73-466d-9c43-9b60207a9353') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88665, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "看中", "is_correct": true, "explanation": "正确。看中表示看了以后觉得很好而想要。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”的对象是食物，运动鞋不能被吃。"}, {"text": "发愁", "is_correct": false, "explanation": "配价：发愁是不及物动词，不能带“这双运动鞋”作宾语。"}, {"text": "跳", "is_correct": false, "explanation": "搭配：“跳”不能与“运动鞋”搭配作宾语。"}], "explanations": {"看中": "正确。看中表示看了以后觉得很好而想要。", "吃": "语义：“吃”的对象是食物，运动鞋不能被吃。", "发愁": "配价：发愁是不及物动词，不能带“这双运动鞋”作宾语。", "跳": "搭配：“跳”不能与“运动鞋”搭配作宾语。"}, "sentence_index": 0, "correct_answer": "看中"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们正在看中这个方案的可行性。", "explanation": "这里应该用〈考虑〉。看中是看后想要某物，不用于评估方案的可行性。"}, {"text": "我在窗外看中了一只飞过的鸟。", "explanation": "这里应该用〈看见〉。看中是看后觉得好而想要，一闪飞过的鸟只是被看到，应说看见。"}, {"text": "老师看中了他的错误。", "explanation": "这里应该用〈批评〉。批评是指出错误，看中是想要某物，不能用于错误。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5e1f9d6-9cae-4794-b652-01952c2d0684') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88665, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "看中", "is_correct": true, "explanation": "正确。看中表示看了以后觉得很好而想要，句中指选定想要的东西。"}, {"text": "醒", "is_correct": false, "explanation": "配价：醒是不及物动词，不能带“什么”作宾语。"}, {"text": "睡", "is_correct": false, "explanation": "配价：睡是不及物动词，不能带“什么”作宾语。"}, {"text": "眨", "is_correct": false, "explanation": "搭配：“眨”不能与“什么”构成动作宾语，不能说“眨什么”。"}], "explanations": {"看中": "正确。看中表示看了以后觉得很好而想要，句中指选定想要的东西。", "醒": "配价：醒是不及物动词，不能带“什么”作宾语。", "睡": "配价：睡是不及物动词，不能带“什么”作宾语。", "眨": "搭配：“眨”不能与“什么”构成动作宾语，不能说“眨什么”。"}, "sentence_index": 6, "correct_answer": "看中"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我看中了那场大雨。", "explanation": "这里应该用〈看见〉。看中是看后选定想要的东西，大雨不能被选定，只能说看见。"}, {"text": "他看中了这个错误。", "explanation": "这里应该用〈承认〉。承认是认下错误，看中是选定想要的东西，不能用于错误。"}, {"text": "他看中了这场比赛的胜负。", "explanation": "这里应该用〈关心〉。看中是选定想要的东西，胜负不能被选定，应说关心。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5e1f9d6-9cae-4794-b652-01952c2d0684') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88665, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我看中着这双舒服的鞋。", "corrected_sentence": "我看中了这双舒服的鞋。", "error_description": "错误：“看中着”；正确：“看中了”。“着”表示持续状态，与“看中”这种一次性的动作不符，应用“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5e1f9d6-9cae-4794-b652-01952c2d0684') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88665, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我看中着这件衣服，可是没买。", "corrected_sentence": "我看中了这件衣服，可是没买。", "error_description": "错误：“看中着”；正确：“看中了”。“着”表示持续状态，与“看中”这种一次性的动作不符，应用“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5e1f9d6-9cae-4794-b652-01952c2d0684') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
