INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88666, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5e1f9d6-9cae-4794-b652-01952c2d0684') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88666, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "看后觉得合意,选定。", "primary_collocate": null, "pronunciation": "kàn zhòng", "ipa": "kʰan˥˩ ʈʂʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "她在商店里看中了一条裙子。", "target_word": "看中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我看中了这家店的蛋糕。", "target_word": "看中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看中那套房子的位置。", "target_word": "看中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥看中了一辆红色的自行车。", "target_word": "看中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈看中这块布做窗帘。", "target_word": "看中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你看中哪一个，我就买哪一个。", "target_word": "看中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们看中了一间离公司近的房子。", "target_word": "看中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她一眼就看中了橱窗里的包。", "target_word": "看中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看中了一只白色的小狗。", "target_word": "看中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友看中我的手表，想买下来。", "target_word": "看中", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "看中", "label": "原形"}, {"form": "看中了", "label": "体标"}, {"form": "看不中", "label": "可能补语否定式"}], "register": "口语", "sense_fingerprint": "看后觉得合意而选定", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7650858-8e73-466d-9c43-9b60207a9353') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88666, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "看中", "is_correct": true, "explanation": "正确。看中是动词，表示看后觉得合意而选定。"}, {"text": "喝", "is_correct": false, "explanation": "语义：“喝”的对象是饮品，裙子不能被“喝”。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”不能带“裙子”作宾语。"}, {"text": "生气", "is_correct": false, "explanation": "配价：生气是不及物动词，不能带“一条裙子”作宾语。"}], "explanations": {"看中": "正确。看中是动词，表示看后觉得合意而选定。", "喝": "语义：“喝”的对象是饮品，裙子不能被“喝”。", "唱": "搭配：“唱”不能带“裙子”作宾语。", "生气": "配价：生气是不及物动词，不能带“一条裙子”作宾语。"}, "sentence_index": 0, "correct_answer": "看中"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们都看中这家公司的倒闭。", "explanation": "这里应该用〈担心〉。看中是看后选定想要的东西，倒闭不能被选定，应说〈担心〉。"}, {"text": "她看中了这次考试的失败。", "explanation": "这里应该用〈接受〉。看中是看后选定想要的东西，失败不能被选定，应说接受。"}, {"text": "他看中了昨天的那场感冒。", "explanation": "这里应该用〈得了〉。看中是看后选定想要的东西，感冒不是挑选的对象，应说得了感冒。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5e1f9d6-9cae-4794-b652-01952c2d0684') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88666, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "看中", "is_correct": true, "explanation": "正确。看中表示看后选定，与“房子”搭配自然。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”的对象是食物，房子不能被吃。"}, {"text": "跑", "is_correct": false, "explanation": "配价：跑是不及物动词，不能带“一间房子”作宾语。"}, {"text": "写", "is_correct": false, "explanation": "语义：“写”的对象是文字，房子不能被写。"}], "explanations": {"看中": "正确。看中表示看后选定，与“房子”搭配自然。", "吃": "语义：“吃”的对象是食物，房子不能被吃。", "跑": "配价：跑是不及物动词，不能带“一间房子”作宾语。", "写": "语义：“写”的对象是文字，房子不能被写。"}, "sentence_index": 6, "correct_answer": "看中"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我看中了这场雨的节奏。", "explanation": "这里应该用〈欣赏〉。看中是看后选定想要的东西，雨的节奏不能被选定，应说欣赏。"}, {"text": "他终于看中了问题的原因。", "explanation": "这里应该用〈发现〉。发现是找出，看中是选定，原因不能被选定。"}, {"text": "他终于看中了自己的失误。", "explanation": "这里应该用〈承认〉。承认是认下错误，看中是选定，不能用于失误。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5e1f9d6-9cae-4794-b652-01952c2d0684') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88666, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天在商店看中着那件外套。", "corrected_sentence": "我昨天在商店看中了那件外套。", "error_description": "错误：“看中着”；正确：“看中了”。看中是一次完成的选定动作，不表示持续状态，“着”应换成“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5e1f9d6-9cae-4794-b652-01952c2d0684') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88666, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他没看中了这条裙子。", "corrected_sentence": "他没看中这条裙子。", "error_description": "错误：“没看中了”；正确：“没看中”。“没”表示未完成的否定，与“了”不能同用，应去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5e1f9d6-9cae-4794-b652-01952c2d0684') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
