INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88667, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一面是一个东西的一边。", "primary_collocate": null, "pronunciation": "yí miàn", "ipa": "i˧˥ mjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "这张纸的一面是白的。", "target_word": "一面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子的一面靠着墙。", "target_word": "一面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你把书的这一面朝上。", "target_word": "一面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房子的一面有一个小花园。", "target_word": "一面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块布的一面很光滑。", "target_word": "一面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "盒子的一面写着我的名字。", "target_word": "一面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河的一面是山，另一面是田。", "target_word": "一面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你看，这个杯子的一面有一只小猫。", "target_word": "一面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门的一面贴着一张红纸。", "target_word": "一面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他坐在桌子的一面，我坐在另一面。", "target_word": "一面", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "另一面", "label": "复合"}], "register": "中性", "sense_fingerprint": "东西的一边、一侧", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3de3ff09-fd2d-4605-9abd-d17a76935391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88667, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "一面", "is_correct": true, "explanation": "正确：「一面」指纸的一侧，与「是白的」搭配，句子描述的是这一侧的颜色。"}, {"text": "重量", "is_correct": false, "explanation": "语义：「重量」指轻重，不能是白的，句子描述的是颜色。"}, {"text": "味道", "is_correct": false, "explanation": "语义：「味道」指口感或气味，不能用「白的」来形容。"}, {"text": "时间", "is_correct": false, "explanation": "搭配：「时间」不能与「是白的」搭配，颜色只能用于有形的物体。"}], "explanations": {"一面": "正确：「一面」指纸的一侧，与「是白的」搭配，句子描述的是这一侧的颜色。", "重量": "语义：「重量」指轻重，不能是白的，句子描述的是颜色。", "味道": "语义：「味道」指口感或气味，不能用「白的」来形容。", "时间": "搭配：「时间」不能与「是白的」搭配，颜色只能用于有形的物体。"}, "sentence_index": 0, "correct_answer": "一面"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她的一面很红。", "explanation": "这里应该用〈一边脸〉。「一面」指物体的一侧，说脸红要指明是哪一边，「她的一面很红」不成立。"}, {"text": "她唱了一面歌。", "explanation": "这里应该用〈一首〉。「面」用于墙、镜子、旗等平面物，歌要用「首」，不能用「面」。"}, {"text": "我买了一面书。", "explanation": "这里应该用〈一本〉。「面」用于墙、镜子、旗等平面物，书要用「本」，不能用「面」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff29ca3d-b11c-4277-8681-bb558e1e29c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88667, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "一面", "is_correct": true, "explanation": "正确：「一面」指河的一侧，与后面的「另一面」形成对照。"}, {"text": "时间", "is_correct": false, "explanation": "语义：「时间」不能是山，句子描述的是河岸的地貌。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：「年龄」是人或事物存在的年数，不能说是山。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：「价格」不能与「是山」搭配，句子说的是河的一侧。"}], "explanations": {"一面": "正确：「一面」指河的一侧，与后面的「另一面」形成对照。", "时间": "语义：「时间」不能是山，句子描述的是河岸的地貌。", "年龄": "语义：「年龄」是人或事物存在的年数，不能说是山。", "价格": "搭配：「价格」不能与「是山」搭配，句子说的是河的一侧。"}, "sentence_index": 6, "correct_answer": "一面"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这根绳子的一面系在树上。", "explanation": "这里应该用〈一端〉。「一面」指物体的一侧，绳子的一头要用「一端」，系在树上说的是一端。"}, {"text": "一面树叶落在水上。", "explanation": "这里应该用〈一片〉。「一面」指物体的一侧，不指薄片状的树叶，树叶要用「一片」。"}, {"text": "河边有一面石头。", "explanation": "这里应该用〈一块〉。「一面」多用于有平面的东西，石头要用「一块」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff29ca3d-b11c-4277-8681-bb558e1e29c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88667, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这本书地一面是红色的。", "corrected_sentence": "这本书的一面是红色的。", "error_description": "结构错误：「书」修饰「一面」时要用「的」。「地」用于修饰动词，不能放在名词前。应说「这本书的一面是红色的」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff29ca3d-b11c-4277-8681-bb558e1e29c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88667, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这块石头地一面长满了青苔。", "corrected_sentence": "这块石头的一面长满了青苔。", "error_description": "结构错误：「一面」修饰「石头」时要用「的」，「地」用于修饰动词，不能放在名词前。应说「这块石头的一面长满了青苔」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff29ca3d-b11c-4277-8681-bb558e1e29c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
