INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88668, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "物体的一个方面或一侧。", "primary_collocate": null, "pronunciation": "yí miàn", "ipa": "i˧˥ mjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "山的一面有很多树。", "target_word": "一面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "月亮总是用它的一面对着地球。", "target_word": "一面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书的一面印着图片。", "target_word": "一面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把盘子翻到另一面。", "target_word": "一面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家楼的一面朝南。", "target_word": "一面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子的一面坏了，不能用了。", "target_word": "一面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路的一面有一排树。", "target_word": "一面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把卡片的一面涂成红色。", "target_word": "一面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "湖的一面很安静，人很少。", "target_word": "一面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "窗户只开在房子的一面。", "target_word": "一面", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "另一面", "label": "复合"}], "register": "中性", "sense_fingerprint": "物体的某一侧、某一个面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3de3ff09-fd2d-4605-9abd-d17a76935391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88668, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "一面", "is_correct": true, "explanation": "正确：「一面」指山的一侧，与「有很多树」搭配，句子描述的是这一侧的景象。"}, {"text": "时间", "is_correct": false, "explanation": "语义：「时间」不是山的部分，不能说山的一侧有树。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：「年龄」指存在的年数，不是山的一个部分，无法放在这里。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：「价格」不能与「有很多树」搭配，句子说的是山的一侧。"}], "explanations": {"一面": "正确：「一面」指山的一侧，与「有很多树」搭配，句子描述的是这一侧的景象。", "时间": "语义：「时间」不是山的部分，不能说山的一侧有树。", "年龄": "语义：「年龄」指存在的年数，不是山的一个部分，无法放在这里。", "价格": "搭配：「价格」不能与「有很多树」搭配，句子说的是山的一侧。"}, "sentence_index": 0, "correct_answer": "一面"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他买了一面笔。", "explanation": "这里应该用〈支〉。「面」用于墙、镜子、旗等平面物，笔要用「支」，不能用「面」。"}, {"text": "他很讲一面，不肯认错。", "explanation": "这里应该用〈面子〉。「一面」指物体的一侧或方面，「讲面子」是固定说法，不能说「讲一面」。"}, {"text": "老师的一面很红。", "explanation": "这里应该用〈一边脸〉。「一面」指物体的一侧，说脸红要指明是哪一边，「老师的一面很红」不成立。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff29ca3d-b11c-4277-8681-bb558e1e29c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88668, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "一面", "is_correct": true, "explanation": "正确：「一面」指路的一侧，与「有一排树」搭配，句子描述的是路旁的景象。"}, {"text": "课本", "is_correct": false, "explanation": "语义：「课本」是书，不是路的一部分，无法放在这里。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：「桌子」是家具，不是路的一侧，句子说的是路边的树。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：「体重」不能与「有一排树」搭配，句子说的是路的一侧。"}], "explanations": {"一面": "正确：「一面」指路的一侧，与「有一排树」搭配，句子描述的是路旁的景象。", "课本": "语义：「课本」是书，不是路的一部分，无法放在这里。", "桌子": "语义：「桌子」是家具，不是路的一侧，句子说的是路边的树。", "体重": "搭配：「体重」不能与「有一排树」搭配，句子说的是路的一侧。"}, "sentence_index": 6, "correct_answer": "一面"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他来过我家一面。", "explanation": "这里应该用〈一次〉。「面」作量词多用于「见一面」，「来过…一面」不自然，要用「来过一次」。"}, {"text": "一面苹果被他吃了。", "explanation": "这里应该用〈一个〉。「面」用于墙、镜子、旗等平面物。苹果用量词「个」，不能用「面」。"}, {"text": "他把一面盘子翻过来。", "explanation": "这里应该用〈个〉。「面」用于墙、镜子、旗等平面物，盘子用「个」，不能用「面」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff29ca3d-b11c-4277-8681-bb558e1e29c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88668, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这本书地一面画着小猫。", "corrected_sentence": "这本书的一面画着小猫。", "error_description": "结构错误：「书」修饰「一面」时要用「的」。「地」用于修饰动词，不能放在名词前。应说「这本书的一面画着小猫」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff29ca3d-b11c-4277-8681-bb558e1e29c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88668, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这块蛋糕地一面烤焦了。", "corrected_sentence": "这块蛋糕的一面烤焦了。", "error_description": "结构错误：「一面」修饰「蛋糕」时要用「的」，「地」用于修饰动词，不能放在名词前。应说「这块蛋糕的一面烤焦了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff29ca3d-b11c-4277-8681-bb558e1e29c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88669, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不如", "is_correct": true, "explanation": "反义：“不如”表示比不上，与“强如”表示胜过正好相对。"}, {"text": "放弃", "is_correct": false, "explanation": "“放弃”与比较优劣无关，不构成反义关系。"}, {"text": "保护", "is_correct": false, "explanation": "“保护”与比较优劣无关，不构成反义关系。"}, {"text": "参加", "is_correct": false, "explanation": "“参加”与比较优劣无关，不构成反义关系。"}], "correct_answer": "不如", "explanations": {"不如": "反义：“不如”表示比不上，与“强如”表示胜过正好相对。", "放弃": "“放弃”与比较优劣无关，不构成反义关系。", "保护": "“保护”与比较优劣无关，不构成反义关系。", "参加": "“参加”与比较优劣无关，不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe85e85b-b923-4d72-872e-bb5531d5b0aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
