INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88669, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "property", "definition": "强如是比别的更好、更厉害。", "primary_collocate": null, "pronunciation": "qiáng rú", "ipa": "tɕʰjɑŋ˧˥ ɻu˧˥", "syllable_count": 2, "sentences": [{"text": "一个好朋友强如十个坏朋友。", "target_word": "强如", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "靠自己努力，强如等别人帮忙。", "target_word": "强如", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有一个好办法，强如想很多天。", "target_word": "强如", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "自己动手做，强如在旁边看着。", "target_word": "强如", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "早点儿准备，强如晚了着急。", "target_word": "强如", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个好老师强如一堆书。", "target_word": "强如", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在就做，强如明天再说。", "target_word": "强如", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说一句真话，强如别人说十句好话。", "target_word": "强如", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多读书强如多看电视。", "target_word": "强如", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "少说多做，强如只说不做。", "target_word": "强如", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "強如", "label": "繁体"}], "register": "书面", "sense_fingerprint": "这样做比那样做更好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcc8d081-6bea-4594-9ad4-67f2274bb8ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88669, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "强如", "is_correct": true, "explanation": "强如：表示比较优劣，句意是好朋友胜过十个坏朋友。"}, {"text": "需要", "is_correct": false, "explanation": "配价：“需要”后接所需之物，不能表示“一个顶十个”的比较。"}, {"text": "乘坐", "is_correct": false, "explanation": "配价：“乘坐”的宾语是交通工具，不能接“坏朋友”，句意不通。"}, {"text": "翻译", "is_correct": false, "explanation": "配价：“翻译”的对象是语言文字，不能接“坏朋友”，句意不通。"}], "explanations": {"强如": "强如：表示比较优劣，句意是好朋友胜过十个坏朋友。", "需要": "配价：“需要”后接所需之物，不能表示“一个顶十个”的比较。", "乘坐": "配价：“乘坐”的宾语是交通工具，不能接“坏朋友”，句意不通。", "翻译": "配价：“翻译”的对象是语言文字，不能接“坏朋友”，句意不通。"}, "sentence_index": 0, "correct_answer": "强如"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个方法强如那个好用。", "explanation": "这里应该用〈比〉。“强如”后面不能直接接“好用”这类谓语，直接比较用“比”。"}, {"text": "学校强如学生穿校服。", "explanation": "这里应该用〈强制〉。“强如”表示比较优劣，不能表示用权力要求学生做某事，要说“强制”。"}, {"text": "他完全强如这个工作。", "explanation": "这里应该用〈胜任〉。“强如”表示比较优劣，不能表示能够承担某项工作，要说“胜任”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe85e85b-b923-4d72-872e-bb5531d5b0aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88669, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "强如", "is_correct": true, "explanation": "强如：表示现在做比明天说更好，句意正确。"}, {"text": "忘记", "is_correct": false, "explanation": "语义：“忘记明天再说”与“现在就做”的意思矛盾。"}, {"text": "乘坐", "is_correct": false, "explanation": "配价：“乘坐”的宾语是交通工具，不能接“明天再说”。"}, {"text": "劝", "is_correct": false, "explanation": "配价：“劝”要带劝说的对象，不能直接接“明天再说”。"}], "explanations": {"强如": "强如：表示现在做比明天说更好，句意正确。", "忘记": "语义：“忘记明天再说”与“现在就做”的意思矛盾。", "乘坐": "配价：“乘坐”的宾语是交通工具，不能接“明天再说”。", "劝": "配价：“劝”要带劝说的对象，不能直接接“明天再说”。"}, "sentence_index": 6, "correct_answer": "强如"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "多锻炼能强如体质。", "explanation": "这里应该用〈增强〉。“强如”表示比较优劣，不能表示使体质变强。"}, {"text": "我们要强如练习。", "explanation": "这里应该用〈加强〉。“强如”不表示加大力度，要说“加强”。"}, {"text": "他把自己的想法强如给别人。", "explanation": "这里应该用〈强加〉。“强如”表示胜过，这里是硬把想法加给别人，要说“强加”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe85e85b-b923-4d72-872e-bb5531d5b0aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88669, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个办法很强如那个办法。", "corrected_sentence": "这个办法强如那个办法。", "error_description": "程度副词错误：“强如”是比较动词，前面不能加“很”。错误形式是「很强如」，正确形式是「强如」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe85e85b-b923-4d72-872e-bb5531d5b0aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88669, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的成绩强如。", "corrected_sentence": "他的成绩强如我的成绩。", "error_description": "缺少比较对象：“强如”后面必须带被比较的对象。错误形式是「强如」后直接结束，正确形式是「强如我的成绩」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe85e85b-b923-4d72-872e-bb5531d5b0aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88671, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "舒服", "is_correct": true, "explanation": "舒服与“难受”意思相反，指身体或心里舒适。"}, {"text": "安静", "is_correct": false, "explanation": "安静与“吵闹”相对，不是“难受”的反义词。"}, {"text": "聪明", "is_correct": false, "explanation": "聪明与“笨”相对，与“难受”的意思无关。"}, {"text": "漂亮", "is_correct": false, "explanation": "漂亮与“丑”相对，与“难受”的意思无关。"}], "correct_answer": "舒服", "explanations": {"舒服": "舒服与“难受”意思相反，指身体或心里舒适。", "安静": "安静与“吵闹”相对，不是“难受”的反义词。", "聪明": "聪明与“笨”相对，与“难受”的意思无关。", "漂亮": "漂亮与“丑”相对，与“难受”的意思无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b7ebae2-2f65-4161-84f1-edbb55d44851') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88671, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "舒服", "is_correct": true, "explanation": "舒服与“难受”意思相反，指身体舒适。"}, {"text": "干净", "is_correct": false, "explanation": "干净与“脏”相对，与“难受”的意思无关。"}, {"text": "快", "is_correct": false, "explanation": "快与“慢”相对，与“难受”的意思无关。"}, {"text": "亮", "is_correct": false, "explanation": "亮与“暗”相对，与“难受”的意思无关。"}], "correct_answer": "舒服", "explanations": {"舒服": "舒服与“难受”意思相反，指身体舒适。", "干净": "干净与“脏”相对，与“难受”的意思无关。", "快": "快与“慢”相对，与“难受”的意思无关。", "亮": "亮与“暗”相对，与“难受”的意思无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b7ebae2-2f65-4161-84f1-edbb55d44851') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88671, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "难受是身体或心里很不舒服。", "primary_collocate": null, "pronunciation": "nán shòu", "ipa": "nan˧˥ ʂou˥˩", "syllable_count": 2, "sentences": [{"text": "我感冒了，头疼，嗓子也很难受。", "target_word": "难受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃得太多，肚子难受极了。", "target_word": "难受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友要搬走了，我心里很难受。", "target_word": "难受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车里太闷，他坐了一会儿就难受了。", "target_word": "难受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到妈妈哭，我难受得说不出话。", "target_word": "难受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "发烧的时候，全身都难受。", "target_word": "难受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试没考好，我心里特别难受。", "target_word": "难受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喝了很多酒，现在胃里难受。", "target_word": "难受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶生病了，我看着她，心里难受。", "target_word": "难受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "屋里太热，我难受得睡不着。", "target_word": "难受", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "難受", "label": "繁体"}, {"form": "难受了", "label": "体标"}], "register": "中性", "sense_fingerprint": "身体不适或心里不好受，常与肚子、嗓子、心里搭配", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9bc0fff-f698-48aa-a31e-eceacc41eba5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88671, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "高兴", "is_correct": false, "explanation": "语义：嗓子不会高兴，且与“感冒、头疼”的不适语境矛盾。"}, {"text": "难受", "is_correct": true, "explanation": "正确：“难受”指身体不舒服，与感冒、头疼的语境一致。"}, {"text": "清楚", "is_correct": false, "explanation": "搭配：“清楚”多用于声音、说明，不说“嗓子很清楚”。"}, {"text": "聪明", "is_correct": false, "explanation": "语义：“聪明”形容人的头脑，不能用来形容嗓子。"}], "explanations": {"高兴": "语义：嗓子不会高兴，且与“感冒、头疼”的不适语境矛盾。", "难受": "正确：“难受”指身体不舒服，与感冒、头疼的语境一致。", "清楚": "搭配：“清楚”多用于声音、说明，不说“嗓子很清楚”。", "聪明": "语义：“聪明”形容人的头脑，不能用来形容嗓子。"}, "sentence_index": 0, "correct_answer": "难受"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这道数学题很难受，我做了一个小时也没做出来。", "explanation": "这里应该用〈困难〉。形容题目不容易做要用“困难”之类，“难受”表示身体或心里不舒服，不能用来形容题目。"}, {"text": "听到这个好消息，他觉得很难受。", "explanation": "这里应该用〈高兴〉。听到好消息应该高兴，“难受”表示不舒服，与语境相反。"}, {"text": "我们赢了比赛，大家都很难受。", "explanation": "这里应该用〈兴奋〉。赢了比赛应该兴奋，“难受”与这种欢快的语境相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b7ebae2-2f65-4161-84f1-edbb55d44851') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88671, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "开心", "is_correct": false, "explanation": "语义：考试没考好，心里不可能特别开心。"}, {"text": "难受", "is_correct": true, "explanation": "正确：“难受”表示心里痛苦，与考试没考好的语境一致。"}, {"text": "精神", "is_correct": false, "explanation": "搭配：“精神”多形容人的状态或面貌，不说“心里很精神”。"}, {"text": "得意", "is_correct": false, "explanation": "语义：考试没考好，心里不会得意。"}], "explanations": {"开心": "语义：考试没考好，心里不可能特别开心。", "难受": "正确：“难受”表示心里痛苦，与考试没考好的语境一致。", "精神": "搭配：“精神”多形容人的状态或面貌，不说“心里很精神”。", "得意": "语义：考试没考好，心里不会得意。"}, "sentence_index": 6, "correct_answer": "难受"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他睡了一整夜，醒来后精神饱满，觉得很难受。", "explanation": "这里应该用〈舒服〉。睡醒后精神饱满，身体感觉舒服，“难受”表示身体或心里不舒服，与这种状态相反。"}, {"text": "考完最后一门，我心里很难受，一身轻松。", "explanation": "这里应该用〈舒畅〉。考完试后心情舒畅，“难受”表示心里不舒服，与此处的心情不符。"}, {"text": "痛痛快快洗了个热水澡，我觉得很难受。", "explanation": "这里应该用〈舒服〉。洗完热水澡后身体舒服，“难受”表示身体或心里不适，与这种感觉相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b7ebae2-2f65-4161-84f1-edbb55d44851') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88671, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他吃坏了东西，难受厉害。", "corrected_sentence": "他吃坏了东西，难受得厉害。", "error_description": "补语错误：“难受”后表示程度时要用“得”引出补语，应说“难受得厉害”，省略“得”不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b7ebae2-2f65-4161-84f1-edbb55d44851') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88671, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他一个人在家，心里难受很。", "corrected_sentence": "他一个人在家，心里难受得很。", "error_description": "补语错误：表示程度的补语要用“得”引出，应说“难受得很”；省略“得”写成“难受很”不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b7ebae2-2f65-4161-84f1-edbb55d44851') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
