INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88672, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "舒服", "is_correct": true, "explanation": "舒服与“难受”意思相反，指身体舒适。"}, {"text": "安静", "is_correct": false, "explanation": "安静与“吵闹”相对，与“难受”的意思无关。"}, {"text": "聪明", "is_correct": false, "explanation": "聪明与“笨”相对，与“难受”的意思无关。"}, {"text": "漂亮", "is_correct": false, "explanation": "漂亮与“丑”相对，与“难受”的意思无关。"}], "correct_answer": "舒服", "explanations": {"舒服": "舒服与“难受”意思相反，指身体舒适。", "安静": "安静与“吵闹”相对，与“难受”的意思无关。", "聪明": "聪明与“笨”相对，与“难受”的意思无关。", "漂亮": "漂亮与“丑”相对，与“难受”的意思无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b7ebae2-2f65-4161-84f1-edbb55d44851') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88672, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "身体不舒服；心里痛苦。", "primary_collocate": null, "pronunciation": "nán shòu", "ipa": "nan˧˥ ʂou˥˩", "syllable_count": 2, "sentences": [{"text": "他晕车了，一路上都很难受。", "target_word": "难受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到坏消息，她难受地哭了。", "target_word": "难受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "牙疼的时候，吃什么都难受。", "target_word": "难受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好朋友不理我，我心里难受。", "target_word": "难受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "嗓子干得难受，快给我一杯水。", "target_word": "难受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你哪里难受？我带你去医院。", "target_word": "难受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不说话，看起来很难受。", "target_word": "难受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们都走了，只有我一个人留下，难受极了。", "target_word": "难受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一想到要离开家，我就难受。", "target_word": "难受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "肚子饿得难受，我先去买点吃的。", "target_word": "难受", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "難受", "label": "繁体"}, {"form": "难受了", "label": "体标"}], "register": "中性", "sense_fingerprint": "身体不舒服，或因难过、失落而心里痛苦", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9bc0fff-f698-48aa-a31e-eceacc41eba5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88672, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "精神", "is_correct": false, "explanation": "语义：晕车的人不会精神饱满，与句意矛盾。"}, {"text": "难受", "is_correct": true, "explanation": "正确：“难受”表示身体不舒服，与晕车的语境一致。"}, {"text": "轻松", "is_correct": false, "explanation": "语义：晕车时一路上不可能轻松。"}, {"text": "清楚", "is_correct": false, "explanation": "搭配：“清楚”多用于声音、说明，不用于描述一路上的身体状态。"}], "explanations": {"精神": "语义：晕车的人不会精神饱满，与句意矛盾。", "难受": "正确：“难受”表示身体不舒服，与晕车的语境一致。", "轻松": "语义：晕车时一路上不可能轻松。", "清楚": "搭配：“清楚”多用于声音、说明，不用于描述一路上的身体状态。"}, "sentence_index": 0, "correct_answer": "难受"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "考上了理想的大学，他心里很难受。", "explanation": "这里应该用〈高兴〉。考上大学应当高兴，“难受”表示不舒服，与语境相反。"}, {"text": "痛快地玩了一整天，我们都觉得很难受。", "explanation": "这里应该用〈尽兴〉。玩得尽兴要用“尽兴”之类，“难受”表示身体或心里痛苦，与这种愉快的语境相反。"}, {"text": "这门外语对我来说很难受，我学了三年也没学会。", "explanation": "这里应该用〈困难〉。形容学习不容易要用“困难”之类，“难受”表示身体或心里的不适，不能用来形容学习。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b7ebae2-2f65-4161-84f1-edbb55d44851') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88672, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "热闹", "is_correct": false, "explanation": "语义：“热闹”形容场面或气氛，与“他不说话”矛盾。"}, {"text": "难受", "is_correct": true, "explanation": "正确：“难受”表示不舒服，与他不说话、看起来不舒服的情形一致。"}, {"text": "香", "is_correct": false, "explanation": "搭配：“香”多用于气味或食物，不用于描述人的样子。"}, {"text": "健谈", "is_correct": false, "explanation": "语义：“健谈”指爱说话，与“他不说话”矛盾。"}], "explanations": {"热闹": "语义：“热闹”形容场面或气氛，与“他不说话”矛盾。", "难受": "正确：“难受”表示不舒服，与他不说话、看起来不舒服的情形一致。", "香": "搭配：“香”多用于气味或食物，不用于描述人的样子。", "健谈": "语义：“健谈”指爱说话，与“他不说话”矛盾。"}, "sentence_index": 6, "correct_answer": "难受"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "下班以后，我觉得很难受，浑身轻松。", "explanation": "这里应该用〈放松〉。下班后身心放松，要用“放松”之类，“难受”表示身体或心里不舒服，与此处的感觉相反。"}, {"text": "他得了第一名，得意地笑着，心里很难受。", "explanation": "这里应该用〈自豪〉。得了第一名应感到自豪，“难受”表示心里痛苦，与这种开心的心情不符。"}, {"text": "我很健康，身体一直很难受。", "explanation": "这里应该用〈舒服〉。身体状况良好时要说“舒服”，“难受”表示身体不适，与这里的描述矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b7ebae2-2f65-4161-84f1-edbb55d44851') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88672, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他晕车了，一路上难受直吐。", "corrected_sentence": "他晕车了，一路上难受得直吐。", "error_description": "补语错误：表示程度或结果的“难受”后要用“得”，应说“难受得直吐”，省略“得”不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b7ebae2-2f65-4161-84f1-edbb55d44851') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88672, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我肚子疼了一下午，难受很。", "corrected_sentence": "我肚子疼了一下午，难受得很。", "error_description": "补语错误：表示程度的补语要用“得”引出，应说“难受得很”；省略“得”写成“难受很”不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b7ebae2-2f65-4161-84f1-edbb55d44851') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
