INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88673, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "统治是有权力的人管着一个国家或很多人。", "primary_collocate": null, "pronunciation": "tǒng zhì", "ipa": "tʰʊŋ˨˩˦ ʈʂʐ̩˥˩", "syllable_count": 2, "sentences": [{"text": "国王用法律统治他的人民。", "target_word": "统治", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他有很大的权力，统治着很多人。", "target_word": "统治", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家由一个女王统治。", "target_word": "统治", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "以前这里由一个大家族统治。", "target_word": "统治", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他统治这个国家的时候，人们过得很苦。", "target_word": "统治", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国王统治人民，也要保护人民。", "target_word": "统治", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个人想统治这座城市。", "target_word": "统治", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "好国王不会只靠害怕来统治人们。", "target_word": "统治", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他统治了这个国家四十年。", "target_word": "统治", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一个人统治很多人，并不容易。", "target_word": "统治", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "统治着", "label": "体标"}, {"form": "统治了", "label": "体标"}, {"form": "統治", "label": "繁体"}], "register": "书面", "sense_fingerprint": "有权力的人管着国家或很多人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07e1ab4a-5687-4830-8ee0-0311191f4520') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88673, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "统治", "is_correct": true, "explanation": "“统治”指有权力的人管着一个国家或很多人，是本题的正确答案。"}, {"text": "同志", "is_correct": false, "explanation": "tóng zhì（第二声）与 tǒng zhì（第三声）只有第一个音节声调不同，“同志”指志同道合的人。"}, {"text": "通知", "is_correct": false, "explanation": "tōng zhī 与 tǒng zhì 两个音节的声调都不同，“通知”意思是告知。"}, {"text": "统计", "is_correct": false, "explanation": "zhì（zh 声母）与 jì（j 声母）不同，“统计”意思是对数据进行汇总计算。"}], "explanations": {"统治": "“统治”指有权力的人管着一个国家或很多人，是本题的正确答案。", "同志": "tóng zhì（第二声）与 tǒng zhì（第三声）只有第一个音节声调不同，“同志”指志同道合的人。", "通知": "tōng zhī 与 tǒng zhì 两个音节的声调都不同，“通知”意思是告知。", "统计": "zhì（zh 声母）与 jì（j 声母）不同，“统计”意思是对数据进行汇总计算。"}, "sentence_index": null, "correct_answer": "统治"}, "level_3": {"options": [{"text": "统治", "is_correct": true, "explanation": "“统治”指凭权力管理人民，与“用法律”搭配，句意通顺。"}, {"text": "逃避", "is_correct": false, "explanation": "语义：“逃避”与“用法律”管理人民的做法相矛盾，句意不通。"}, {"text": "打扮", "is_correct": false, "explanation": "搭配：“打扮”指修饰外表，不能与“他的人民”搭配表示管理。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”后面要接歌曲等对象，不能说“唱他的人民”。"}], "explanations": {"统治": "“统治”指凭权力管理人民，与“用法律”搭配，句意通顺。", "逃避": "语义：“逃避”与“用法律”管理人民的做法相矛盾，句意不通。", "打扮": "搭配：“打扮”指修饰外表，不能与“他的人民”搭配表示管理。", "唱": "搭配：“唱”后面要接歌曲等对象，不能说“唱他的人民”。"}, "sentence_index": 0, "correct_answer": "统治"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这首诗由他统治。", "explanation": "这里应该用〈创作〉。“统治”只用于国家、地区或人群，写诗要用“创作”。"}, {"text": "这只猫由她统治。", "explanation": "这里应该用〈照料〉。“统治”只用于国家、地区或人群，照顾小动物要用“照料”。"}, {"text": "他统治了这个问题一个下午。", "explanation": "这里应该用〈思考〉。“统治”不能用来形容思考问题，应说“思考”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc96276b-a330-4831-a2a4-3b52a87bc571') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88673, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "统治", "is_correct": true, "explanation": "“统治”指凭权力管理一座城市，与“那个人想”的意图相符。"}, {"text": "睡", "is_correct": false, "explanation": "配价：“睡”是不及物动词，不能带“这座城市”作宾语。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”的对象是衣物或身体等，不能与“这座城市”搭配，句意不通。"}, {"text": "哭", "is_correct": false, "explanation": "搭配：“哭”不能支配城市，不能说“哭这座城市”。"}], "explanations": {"统治": "“统治”指凭权力管理一座城市，与“那个人想”的意图相符。", "睡": "配价：“睡”是不及物动词，不能带“这座城市”作宾语。", "洗": "搭配：“洗”的对象是衣物或身体等，不能与“这座城市”搭配，句意不通。", "哭": "搭配：“哭”不能支配城市，不能说“哭这座城市”。"}, "sentence_index": 6, "correct_answer": "统治"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位医生统治着这里的病人。", "explanation": "这里应该用〈照顾〉。“统治”指凭权力管理人群，医生对病人要用“照顾”。"}, {"text": "他统治了这个文件夹里的每个文件。", "explanation": "这里应该用〈整理〉。“统治”只用于国家、地区或人群，整理文件要用“整理”。"}, {"text": "他统治了这个月的工资。", "explanation": "这里应该用〈花〉。“统治”只用于国家、地区或人群，花钱要用“花”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc96276b-a330-4831-a2a4-3b52a87bc571') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88673, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那位女王统治过了这个国家二十年。", "corrected_sentence": "那位女王统治了这个国家二十年。", "error_description": "“统治”后面只能用一个体标。这里说统治持续了二十年，用“了”就够了，“过了”连用是错的。应把“统治过了”改为“统治了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc96276b-a330-4831-a2a4-3b52a87bc571') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88673, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那个暴君是一个残酷的统治人。", "corrected_sentence": "那个暴君是一个残酷的统治者。", "error_description": "表示“掌权统治的人”要用“统治者”，“统治人”不是常用的词，应为“统治者”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc96276b-a330-4831-a2a4-3b52a87bc571') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
