INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88675, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指外表、样子不相同，有不同的地方。", "primary_collocate": null, "pronunciation": "bù yí yàng", "ipa": "pu˥˩ i˧˥ jɑŋ˥˩", "syllable_count": 3, "sentences": [{"text": "这两件衣服的颜色不一样。", "target_word": "不一样", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我和哥哥长得不一样。", "target_word": "不一样", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两个杯子的样子不一样。", "target_word": "不一样", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的鞋和我的鞋不一样大。", "target_word": "不一样", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两张照片看起来不一样。", "target_word": "不一样", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两个字的写法不一样。", "target_word": "不一样", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "姐姐的头发和我的不一样。", "target_word": "不一样", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "双胞胎的脸也有点不一样。", "target_word": "不一样", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他今天穿得和平时不一样。", "target_word": "不一样", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的手机和你的不一样，比较大。", "target_word": "不一样", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不一样的", "label": "定语形式"}, {"form": "不太一样", "label": "程度表达"}], "register": "口语", "sense_fingerprint": "外表、样子上不相同", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92d2e1a1-099e-41db-962b-ec5c14b7f3d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88675, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "安静", "is_correct": false, "explanation": "搭配：“安静”形容声音、环境或人的状态，不能用来形容衣服的颜色。"}, {"text": "不一样", "is_correct": true, "explanation": "“不一样”指颜色不同，符合“这两件衣服的颜色”这一语境。"}, {"text": "聪明", "is_correct": false, "explanation": "语义：“聪明”指头脑灵活，颜色不能是聪明的。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容身材或体型，不能用来形容衣服的颜色。"}], "explanations": {"安静": "搭配：“安静”形容声音、环境或人的状态，不能用来形容衣服的颜色。", "不一样": "“不一样”指颜色不同，符合“这两件衣服的颜色”这一语境。", "聪明": "语义：“聪明”指头脑灵活，颜色不能是聪明的。", "高大": "体貌：“高大”形容身材或体型，不能用来形容衣服的颜色。"}, "sentence_index": 0, "correct_answer": "不一样"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这两张照片一模一样，连细节都完全不一样。", "explanation": "“一模一样”表示完全相同，与“不一样”（有不同的地方）互相矛盾。这里应该用“一样”，不能说“不一样”。"}, {"text": "这两个杯子的颜色和样子完全相同，看起来却不一样。", "explanation": "“完全相同”说明两个杯子外表一样，而“看起来却不一样”用“不一样”表示有差别，前后矛盾，应说“看起来一样”。"}, {"text": "我的鞋和你的鞋一样大，但是它们不一样大。", "explanation": "“一样大”与“不一样大”互相矛盾；“不一样”表示有差别，这里应该用“一样”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b5e8e9e2-9a18-4d41-b561-6e310940faf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88675, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "勇敢", "is_correct": false, "explanation": "语义：“勇敢”形容人的胆量，不能用来拿头发作比较。"}, {"text": "慢", "is_correct": false, "explanation": "搭配：“慢”说速度或动作，不能用来形容头发。"}, {"text": "不一样", "is_correct": true, "explanation": "“不一样”表示头发的样子不同，符合“姐姐的头发和我的”这一比较语境。"}, {"text": "瘦", "is_correct": false, "explanation": "体貌：“瘦”形容人或物的体形，头发不能说瘦。"}], "explanations": {"勇敢": "语义：“勇敢”形容人的胆量，不能用来拿头发作比较。", "慢": "搭配：“慢”说速度或动作，不能用来形容头发。", "不一样": "“不一样”表示头发的样子不同，符合“姐姐的头发和我的”这一比较语境。", "瘦": "体貌：“瘦”形容人或物的体形，头发不能说瘦。"}, "sentence_index": 6, "correct_answer": "不一样"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他这几年一直没有变化，现在和以前的样子不一样了。", "explanation": "“一直没有变化”与“不一样了”互相矛盾。“不一样”表示有差别，这里应该用“一样”，表示样子没有改变。"}, {"text": "我和妹妹穿的裙子颜色、样子都一样，可是我们的裙子不一样。", "explanation": "“颜色、样子都一样”与“裙子不一样”互相矛盾；“不一样”表示外表有差别，这里应该用“一样”。"}, {"text": "这两张照片完全相同，连一点区别都没有，但是它们不一样。", "explanation": "“完全相同”“一点区别都没有”与“不一样”互相矛盾，应说“它们一样”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b5e8e9e2-9a18-4d41-b561-6e310940faf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88675, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她画了一朵不一样花。", "corrected_sentence": "她画了一朵不一样的花。", "error_description": "“不一样”作定语修饰名词时要加“的”，应说“不一样的花”，不能省略“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b5e8e9e2-9a18-4d41-b561-6e310940faf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88675, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这两条裙子的颜色比不一样。", "corrected_sentence": "这两条裙子的颜色不一样。", "error_description": "“比”不能直接放在“不一样”前面。比较两者的差别只用“……不一样”或“和……不一样”，应说“这两条裙子的颜色不一样”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b5e8e9e2-9a18-4d41-b561-6e310940faf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
