INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88676, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指想法、习惯、情况等方面不相同，有差别。", "primary_collocate": null, "pronunciation": "bù yí yàng", "ipa": "pu˥˩ i˧˥ jɑŋ˥˩", "syllable_count": 3, "sentences": [{"text": "我们的想法不一样。", "target_word": "不一样", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "北方和南方的天气不一样。", "target_word": "不一样", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个人的习惯都不一样。", "target_word": "不一样", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他今天说的和昨天说的不一样。", "target_word": "不一样", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的饭和我家的味道不一样。", "target_word": "不一样", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中国的春节和我们国家的新年不一样。", "target_word": "不一样", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师的看法跟学生不一样。", "target_word": "不一样", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个国家的文化不一样。", "target_word": "不一样", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的生活和我的不一样。", "target_word": "不一样", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个城市的生活节奏都不一样。", "target_word": "不一样", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不一样的", "label": "定语形式"}, {"form": "不太一样", "label": "程度表达"}], "register": "口语", "sense_fingerprint": "想法、习惯、情况等有差别", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92d2e1a1-099e-41db-962b-ec5c14b7f3d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88676, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "圆", "is_correct": false, "explanation": "语义：“圆”指形状，不能用来形容想法。"}, {"text": "硬", "is_correct": false, "explanation": "搭配：“硬”一般形容物体的质地，不能说想法很硬。"}, {"text": "不一样", "is_correct": true, "explanation": "“不一样”指想法有差别，符合“我们的想法”这一语境。"}, {"text": "方", "is_correct": false, "explanation": "语义：“方”指形状，与想法无关。"}], "explanations": {"圆": "语义：“圆”指形状，不能用来形容想法。", "硬": "搭配：“硬”一般形容物体的质地，不能说想法很硬。", "不一样": "“不一样”指想法有差别，符合“我们的想法”这一语境。", "方": "语义：“方”指形状，与想法无关。"}, "sentence_index": 0, "correct_answer": "不一样"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的习惯和我的完全一样，可是我们的习惯不一样。", "explanation": "“完全一样”与“习惯不一样”互相矛盾；“不一样”表示有差别，这里应该用“一样”。"}, {"text": "这两个班的人数都是三十人，人数却不一样。", "explanation": "“都是三十人”说明人数相同，而“人数却不一样”用“不一样”表示有差别，前后矛盾，应说“人数一样”。"}, {"text": "我们俩的看法完全相同，却又有很多地方不一样。", "explanation": "“完全相同”与“有很多地方不一样”互相矛盾；这里应该用“相同”或“一样”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b5e8e9e2-9a18-4d41-b561-6e310940faf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88676, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "甜", "is_correct": false, "explanation": "搭配：“甜”一般形容味道或言语，不能用来形容看法。"}, {"text": "瘦", "is_correct": false, "explanation": "体貌：“瘦”形容人或物的体形，看法不能说瘦。"}, {"text": "矮", "is_correct": false, "explanation": "体貌：“矮”形容身高或位置的低，不能用来形容看法。"}, {"text": "不一样", "is_correct": true, "explanation": "“不一样”指看法有差别，符合“老师的看法跟学生”这一语境。"}], "explanations": {"甜": "搭配：“甜”一般形容味道或言语，不能用来形容看法。", "瘦": "体貌：“瘦”形容人或物的体形，看法不能说瘦。", "矮": "体貌：“矮”形容身高或位置的低，不能用来形容看法。", "不一样": "“不一样”指看法有差别，符合“老师的看法跟学生”这一语境。"}, "sentence_index": 6, "correct_answer": "不一样"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们俩的习惯从小到大一直没有变，现在却不一样了。", "explanation": "“一直没有变”与“不一样了”互相矛盾；“不一样”表示有差别，这里应该用“一样”，表示习惯没有改变。"}, {"text": "我们俩的看法完全相同，没有一点差别，可是我们的看法不一样。", "explanation": "“完全相同，没有一点差别”与“看法不一样”互相矛盾；这里应该用“一样”。"}, {"text": "我和他的爱好完全一样，可是我们喜欢做的事情都不一样。", "explanation": "“爱好完全一样”与“喜欢做的事情都不一样”前后矛盾，应说“都一样”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b5e8e9e2-9a18-4d41-b561-6e310940faf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88676, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的习惯和我的不不一样。", "corrected_sentence": "他的习惯和我的不一样。", "error_description": "“不”重复使用，“不一样”本身已表示否定的差别，前面不能再加“不”。应说“他的习惯和我的不一样”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b5e8e9e2-9a18-4d41-b561-6e310940faf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88676, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "父母的教育方式和我们的比不一样。", "corrected_sentence": "父母的教育方式和我们的不一样。", "error_description": "“比”不能直接放在“不一样”前面。比较两者的差别只用“和……不一样”，应说“父母的教育方式和我们的不一样”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b5e8e9e2-9a18-4d41-b561-6e310940faf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88677, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2edd13e3-0dfc-4492-8163-e0f64239493b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88677, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2edd13e3-0dfc-4492-8163-e0f64239493b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88677, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "忠实是对人很好，一直不变，说话算数。", "primary_collocate": null, "pronunciation": "zhōng shí", "ipa": "ʈʂʊŋ˥˥ ʂʅ˧˥", "syllable_count": 2, "sentences": [{"text": "他是一个忠实的朋友。", "target_word": "忠实", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说话算数，为人很忠实。", "target_word": "忠实", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多年来，她对丈夫一直很忠实。", "target_word": "忠实", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老人是我们最忠实的朋友。", "target_word": "忠实", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他忠实地遵守着自己的诺言。", "target_word": "忠实", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李对朋友非常忠实。", "target_word": "忠实", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我需要一个忠实可靠的人帮忙。", "target_word": "忠实", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷一直忠实地照顾着奶奶。", "target_word": "忠实", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "忠实的朋友在困难时也不会离开你。", "target_word": "忠实", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老张为人忠实，说过的话一定做到。", "target_word": "忠实", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "忠實", "label": "繁体"}], "register": "中性", "sense_fingerprint": "对人真心，始终不变，守信用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cfb60cc5-2c9b-4622-a473-6ce24ef464ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88677, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "忠实", "is_correct": true, "explanation": "正确答案：忠实（zhōng shí），指对人真心、始终不变、守信用。"}, {"text": "充实", "is_correct": false, "explanation": "chōng（第一声）与 zhōng（第一声）声母不同，“充实”意思是内容丰富、饱满。"}, {"text": "中式", "is_correct": false, "explanation": "shì（第四声）与 shí（第二声）韵母相同，仅声调不同，“中式”意思是中国式的。"}, {"text": "重视", "is_correct": false, "explanation": "zhòng（第四声）与 zhōng（第一声）声调不同，shì（第四声）与 shí（第二声）声调不同，“重视”意思是认为重要、看重。"}], "explanations": {"忠实": "正确答案：忠实（zhōng shí），指对人真心、始终不变、守信用。", "充实": "chōng（第一声）与 zhōng（第一声）声母不同，“充实”意思是内容丰富、饱满。", "中式": "shì（第四声）与 shí（第二声）韵母相同，仅声调不同，“中式”意思是中国式的。", "重视": "zhòng（第四声）与 zhōng（第一声）声调不同，shì（第四声）与 shí（第二声）声调不同，“重视”意思是认为重要、看重。"}, "sentence_index": null, "correct_answer": "忠实"}, "level_3": {"options": [{"text": "忠实", "is_correct": true, "explanation": "“忠实的朋友”指真心、守信的朋友，符合句意。"}, {"text": "锋利", "is_correct": false, "explanation": "语义：“锋利”形容刀具，不形容朋友。"}, {"text": "辛辣", "is_correct": false, "explanation": "语义：“辛辣”形容味道，不能形容朋友。"}, {"text": "薄", "is_correct": false, "explanation": "搭配：“朋友”一般不与“薄”搭配。"}], "explanations": {"忠实": "“忠实的朋友”指真心、守信的朋友，符合句意。", "锋利": "语义：“锋利”形容刀具，不形容朋友。", "辛辣": "语义：“辛辣”形容味道，不能形容朋友。", "薄": "搭配：“朋友”一般不与“薄”搭配。"}, "sentence_index": 0, "correct_answer": "忠实"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位老人很忠实，经常骗我们的钱。", "explanation": "这里不能用〈忠实〉。忠实指守信、说话算数，“骗钱”与之相反，这句话应该用〈奸诈〉。"}, {"text": "她忠实地抱怨了一整天。", "explanation": "这里应该用〈不停地〉。忠实指对人守信、始终如一，不用来形容抱怨的样子。"}, {"text": "这把刀很忠实，切菜很快。", "explanation": "这里应该用〈锋利〉。忠实形容人对人对事真心守信，不能形容刀等物品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2edd13e3-0dfc-4492-8163-e0f64239493b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88677, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "忠实", "is_correct": true, "explanation": "“忠实可靠”形容人真心、守信，符合句意。"}, {"text": "愤怒", "is_correct": false, "explanation": "语义：“愤怒”形容情绪，不与“可靠”搭配来形容人的品质。"}, {"text": "透明", "is_correct": false, "explanation": "语义：“透明”形容物体，不用来形容人的品质。"}, {"text": "冰冷", "is_correct": false, "explanation": "搭配：“冰冷可靠”不搭配，“可靠”不与“冰冷”连用。"}], "explanations": {"忠实": "“忠实可靠”形容人真心、守信，符合句意。", "愤怒": "语义：“愤怒”形容情绪，不与“可靠”搭配来形容人的品质。", "透明": "语义：“透明”形容物体，不用来形容人的品质。", "冰冷": "搭配：“冰冷可靠”不搭配，“可靠”不与“冰冷”连用。"}, "sentence_index": 6, "correct_answer": "忠实"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他忠实地吃完了一整碗饭。", "explanation": "这里应该用〈认真〉。忠实指对人守信、始终如一，不用于形容吃饭的样子。"}, {"text": "他对朋友很忠实，经常在背后说坏话。", "explanation": "这里不能用〈忠实〉。忠实指守信、始终如一，与“背后说坏话”相反，这里应该用〈不忠〉。"}, {"text": "她向我们表达了忠实的感谢。", "explanation": "这里应该用〈诚挚〉。忠实指守信、始终如一，不用来修饰感谢。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2edd13e3-0dfc-4492-8163-e0f64239493b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88677, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他是一个忠实地老朋友了。", "corrected_sentence": "他是一个忠实的老朋友了。", "error_description": "结构助词错误：“忠实”修饰名词“老朋友”时应用“的”，不能用“地”。应改为“忠实的老朋友”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2edd13e3-0dfc-4492-8163-e0f64239493b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88677, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位邻居对我们一直被忠实。", "corrected_sentence": "这位邻居对我们一直很忠实。", "error_description": "用词错误：“忠实”是形容词，前面应用程度副词“很”，不能用“被”（“被”用于引出被动的动作）。应改为“一直很忠实”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2edd13e3-0dfc-4492-8163-e0f64239493b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
