INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88678, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "忠诚可靠，始终如一；也指真实、不歪曲。", "primary_collocate": null, "pronunciation": "zhōng shí", "ipa": "ʈʂʊŋ˥˥ ʂʅ˧˥", "syllable_count": 2, "sentences": [{"text": "这只狗是主人忠实的朋友。", "target_word": "忠实", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是一个忠实的球迷。", "target_word": "忠实", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书忠实地记录了那段历史。", "target_word": "忠实", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "翻译要忠实于原文。", "target_word": "忠实", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对祖国一直很忠实。", "target_word": "忠实", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老王是公司最忠实的员工。", "target_word": "忠实", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影忠实地反映了当时的生活。", "target_word": "忠实", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他忠实地完成了每一项任务。", "target_word": "忠实", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者应该忠实地写出事情的经过。", "target_word": "忠实", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多年来，他忠实地守着这家小店。", "target_word": "忠实", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "忠實", "label": "繁体"}], "register": "中性", "sense_fingerprint": "忠诚可靠，或真实不歪曲", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cfb60cc5-2c9b-4622-a473-6ce24ef464ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88678, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "忠实", "is_correct": true, "explanation": "正确答案：忠实（zhōng shí），指忠诚可靠，或真实、不歪曲。"}, {"text": "充实", "is_correct": false, "explanation": "chōng（第一声）与 zhōng（第一声）声母不同，“充实”意思是内容丰富、饱满。"}, {"text": "中式", "is_correct": false, "explanation": "shì（第四声）与 shí（第二声）韵母相同，仅声调不同，“中式”意思是中国式的。"}, {"text": "重视", "is_correct": false, "explanation": "zhòng（第四声）与 zhōng（第一声）声调不同，shì（第四声）与 shí（第二声）声调不同，“重视”意思是认为重要、看重。"}], "explanations": {"忠实": "正确答案：忠实（zhōng shí），指忠诚可靠，或真实、不歪曲。", "充实": "chōng（第一声）与 zhōng（第一声）声母不同，“充实”意思是内容丰富、饱满。", "中式": "shì（第四声）与 shí（第二声）韵母相同，仅声调不同，“中式”意思是中国式的。", "重视": "zhòng（第四声）与 zhōng（第一声）声调不同，shì（第四声）与 shí（第二声）声调不同，“重视”意思是认为重要、看重。"}, "sentence_index": null, "correct_answer": "忠实"}, "level_3": {"options": [{"text": "忠实", "is_correct": true, "explanation": "“忠实”修饰“朋友”，表示忠诚可靠，符合句意。"}, {"text": "锋利", "is_correct": false, "explanation": "语义：“锋利”形容刀具等物体，不形容朋友。"}, {"text": "辛辣", "is_correct": false, "explanation": "语义：“辛辣”形容味道，不能形容朋友。"}, {"text": "薄", "is_correct": false, "explanation": "搭配：“朋友”一般不与“薄”搭配。"}], "explanations": {"忠实": "“忠实”修饰“朋友”，表示忠诚可靠，符合句意。", "锋利": "语义：“锋利”形容刀具等物体，不形容朋友。", "辛辣": "语义：“辛辣”形容味道，不能形容朋友。", "薄": "搭配：“朋友”一般不与“薄”搭配。"}, "sentence_index": 0, "correct_answer": "忠实"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个数字计算得很忠实。", "explanation": "这里应该用〈准确〉。忠实用于翻译、记录等与原文对照的文字，不用于计算结果。"}, {"text": "这个孩子忠实地吃完了饭。", "explanation": "这里应该用〈认真〉。忠实指忠诚可靠或不歪曲，不用于形容吃饭的样子。"}, {"text": "我们受到了忠实的招待。", "explanation": "这里应该用〈热情〉。忠实指忠诚守信，不用于形容招待的态度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2edd13e3-0dfc-4492-8163-e0f64239493b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88678, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "忠实", "is_correct": true, "explanation": "“忠实地”修饰“反映”，表示真实、不歪曲，符合句意。"}, {"text": "愤怒", "is_correct": false, "explanation": "语义：“愤怒”形容人的情绪，不用来形容电影反映生活。"}, {"text": "冷冻", "is_correct": false, "explanation": "语义：“冷冻”指低温保存，不能修饰“反映”。"}, {"text": "潮湿", "is_correct": false, "explanation": "搭配：“反映”不与“潮湿”搭配。"}], "explanations": {"忠实": "“忠实地”修饰“反映”，表示真实、不歪曲，符合句意。", "愤怒": "语义：“愤怒”形容人的情绪，不用来形容电影反映生活。", "冷冻": "语义：“冷冻”指低温保存，不能修饰“反映”。", "潮湿": "搭配：“反映”不与“潮湿”搭配。"}, "sentence_index": 6, "correct_answer": "忠实"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她向我表达了忠实的谢意。", "explanation": "这里应该用〈诚挚〉。忠实指忠诚守信，不用于修饰谢意。"}, {"text": "他忠实地说了一句假话。", "explanation": "这里不能用〈忠实〉的“真实、不歪曲”义。忠实指真实，与“假话”矛盾。"}, {"text": "他忠实地看着书，一动不动。", "explanation": "这里应该用〈专注〉。忠实不用于形容看书的神态。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2edd13e3-0dfc-4492-8163-e0f64239493b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88678, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她是一个忠实地读者，每期都买。", "corrected_sentence": "她是一个忠实的读者，每期都买。", "error_description": "结构助词错误：“忠实”修饰名词“读者”时应用“的”，不能用“地”（“地”用于修饰动词）。应改为“忠实的读者”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2edd13e3-0dfc-4492-8163-e0f64239493b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88678, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这份报告忠实的记录了那次会议。", "corrected_sentence": "这份报告忠实地记录了那次会议。", "error_description": "结构助词错误：“忠实”修饰动词“记录”时应用“地”，不能用“的”。应改为“忠实地记录”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2edd13e3-0dfc-4492-8163-e0f64239493b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
