INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88679, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "电器是要用电才能工作的东西，像电视和冰箱。", "primary_collocate": null, "pronunciation": "diàn qì", "ipa": "tjɛn˥˩ tɕʰi˥˩", "syllable_count": 2, "sentences": [{"text": "我家的电器都是新买的。", "target_word": "电器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厨房里有冰箱和很多小电器。", "target_word": "电器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店专门卖电器，价钱很便宜。", "target_word": "电器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出门前，请关掉家里所有的电器。", "target_word": "电器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电器坏了，不要自己拆开修。", "target_word": "电器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洗衣机和电视都是常见的电器。", "target_word": "电器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买电器要看清楚能用几年。", "target_word": "电器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件电器太旧了，该换新的了。", "target_word": "电器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我哥哥的工作是修电器。", "target_word": "电器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电器用完后要关电源。", "target_word": "电器", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "件", "label": "量词"}, {"form": "台", "label": "量词"}, {"form": "家用电器", "label": "复合"}, {"form": "電器", "label": "繁体"}], "register": "中性", "sense_fingerprint": "家里用电才能工作的东西，如电视、冰箱", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5345ed11-06b2-4130-89ce-bb50ae77b3fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88679, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "电器", "is_correct": true, "explanation": "正确答案。电器指用电才能工作的器具。"}, {"text": "电力", "is_correct": false, "explanation": "lì（第四声）与 qì（第四声）声母不同，意思是电力。"}, {"text": "天气", "is_correct": false, "explanation": "tiān（第一声）与 diàn（第四声）声母、声调不同，第二字同音 qì，意思是天气。"}, {"text": "电机", "is_correct": false, "explanation": "jī（第一声）与 qì（第四声）送气与声调不同，意思是电动机。"}], "explanations": {"电器": "正确答案。电器指用电才能工作的器具。", "电力": "lì（第四声）与 qì（第四声）声母不同，意思是电力。", "天气": "tiān（第一声）与 diàn（第四声）声母、声调不同，第二字同音 qì，意思是天气。", "电机": "jī（第一声）与 qì（第四声）送气与声调不同，意思是电动机。"}, "sentence_index": null, "correct_answer": "电器"}, "level_3": {"options": [{"text": "电器", "is_correct": true, "explanation": "正确答案。家里的电器可以买，也可以是新的。"}, {"text": "空气", "is_correct": false, "explanation": "语义：“空气”不是可以买来的物品，“我家的空气都是新买的”说不通。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”描写人的体态，不是家里的物品，不能说“新买的”。"}, {"text": "人", "is_correct": false, "explanation": "语义：“人”不能用“买”来获得，“我家的人都是新买的”不成立。"}], "explanations": {"电器": "正确答案。家里的电器可以买，也可以是新的。", "空气": "语义：“空气”不是可以买来的物品，“我家的空气都是新买的”说不通。", "身高": "体貌：“身高”描写人的体态，不是家里的物品，不能说“新买的”。", "人": "语义：“人”不能用“买”来获得，“我家的人都是新买的”不成立。"}, "sentence_index": 0, "correct_answer": "电器"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "冰箱里放着鸡蛋和牛奶等电器。", "explanation": "这里应该用〈食物〉。鸡蛋和牛奶是吃的东西，不用电，不能称电器。"}, {"text": "厨房里有刀、锅等电器。", "explanation": "这里应该用〈厨具〉。电器指用电工作的器具，刀和锅不用电，不能称电器。"}, {"text": "卧室里有床和衣柜等电器。", "explanation": "这里应该用〈家具〉。床和衣柜不用电，不属于电器。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34fe6152-7971-4806-a660-cd4a4206742a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88679, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "电器", "is_correct": true, "explanation": "正确答案。电器是耐用的器具，买之前要看能用几年。"}, {"text": "房间", "is_correct": false, "explanation": "搭配：“买”一般说“买房子”，很少说“买房间”，“买房间要看能用几年”不通。"}, {"text": "笑容", "is_correct": false, "explanation": "搭配：“笑容”不能买，“买笑容”不搭配。"}, {"text": "阳光", "is_correct": false, "explanation": "配价：“买”的宾语必须是可买卖的物品，“阳光”不能被买。"}], "explanations": {"电器": "正确答案。电器是耐用的器具，买之前要看能用几年。", "房间": "搭配：“买”一般说“买房子”，很少说“买房间”，“买房间要看能用几年”不通。", "笑容": "搭配：“笑容”不能买，“买笑容”不搭配。", "阳光": "配价：“买”的宾语必须是可买卖的物品，“阳光”不能被买。"}, "sentence_index": 6, "correct_answer": "电器"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今天我穿了一件新电器。", "explanation": "这里应该用〈衣服〉。电器指用电工作的器具，衣服不用电，不能称电器。"}, {"text": "她每天练习的是毛笔这种电器。", "explanation": "这里应该用〈文具〉。毛笔不用电工作，属于文具，不属于电器。"}, {"text": "花园里种了很多电器。", "explanation": "这里应该用〈植物〉。电器是用电的器具，花草是植物，不能用电器指代。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34fe6152-7971-4806-a660-cd4a4206742a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88679, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我买了一台的新电器。", "corrected_sentence": "我买了一台新的电器。", "error_description": "定语位置错误：“的”不能紧跟量词“一台”，应放在修饰语“新”之后，应说“一台新的电器”，不能说“一台的新电器”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34fe6152-7971-4806-a660-cd4a4206742a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88679, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们家买了两只电器。", "corrected_sentence": "我们家买了两台电器。", "error_description": "量词错误：“电器”的量词应为〈台〉或〈件〉，〈只〉用于动物或成对物中的一个，不能用于电器，应说“两台电器”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34fe6152-7971-4806-a660-cd4a4206742a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
