INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88680, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "使用电力工作的器具或设备。", "primary_collocate": null, "pronunciation": "diàn qì", "ipa": "tjɛn˥˩ tɕʰi˥˩", "syllable_count": 2, "sentences": [{"text": "夏天用电器多，电费也变高了。", "target_word": "电器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩不能玩电器，会有危险。", "target_word": "电器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电器着火时，先把电源关掉。", "target_word": "电器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "搬家的时候，电器要小心放。", "target_word": "电器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些电器一年要用多少电？", "target_word": "电器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新房里的电器已经装好了。", "target_word": "电器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电器上有一个小小的红灯。", "target_word": "电器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把用不到的电器收起来。", "target_word": "电器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个牌子的电器很受欢迎。", "target_word": "电器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他去商场买电器，选了一台空调。", "target_word": "电器", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "件", "label": "量词"}, {"form": "台", "label": "量词"}, {"form": "家用电器", "label": "复合"}, {"form": "電器", "label": "繁体"}], "register": "中性", "sense_fingerprint": "使用电力工作的器具或设备", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5345ed11-06b2-4130-89ce-bb50ae77b3fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88680, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "电器", "is_correct": true, "explanation": "正确答案。电器指使用电力工作的器具或设备。"}, {"text": "电力", "is_correct": false, "explanation": "lì（第四声）与 qì（第四声）声母不同，意思是电力。"}, {"text": "天气", "is_correct": false, "explanation": "tiān（第一声）与 diàn（第四声）声母、声调不同，第二字同音 qì，意思是天气。"}, {"text": "电机", "is_correct": false, "explanation": "jī（第一声）与 qì（第四声）送气与声调不同，意思是电动机。"}], "explanations": {"电器": "正确答案。电器指使用电力工作的器具或设备。", "电力": "lì（第四声）与 qì（第四声）声母不同，意思是电力。", "天气": "tiān（第一声）与 diàn（第四声）声母、声调不同，第二字同音 qì，意思是天气。", "电机": "jī（第一声）与 qì（第四声）送气与声调不同，意思是电动机。"}, "sentence_index": null, "correct_answer": "电器"}, "level_3": {"options": [{"text": "电器", "is_correct": true, "explanation": "正确答案。夏天用的电器多，所以电费变高。"}, {"text": "口气", "is_correct": false, "explanation": "搭配：“用”后面要接可以使用的物品，不说“用口气”。"}, {"text": "空气", "is_correct": false, "explanation": "语义：“空气”不耗电，“夏天用空气多，电费变高”与句意不符。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”不能被使用，也不会让电费变高。"}], "explanations": {"电器": "正确答案。夏天用的电器多，所以电费变高。", "口气": "搭配：“用”后面要接可以使用的物品，不说“用口气”。", "空气": "语义：“空气”不耗电，“夏天用空气多，电费变高”与句意不符。", "颜色": "语义：“颜色”不能被使用，也不会让电费变高。"}, "sentence_index": 0, "correct_answer": "电器"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "孩子们在操场上踢电器。", "explanation": "这里应该用〈足球〉。电器指用电工作的器具，足球是运动器材，不能用“踢”来指电器。"}, {"text": "吃饭前要摆好碗筷等电器。", "explanation": "这里应该用〈餐具〉。碗筷不用电，属于餐具，不能称电器。"}, {"text": "书包里装着笔和本子等电器。", "explanation": "这里应该用〈文具〉。笔和本子不用电，属于文具，不能称电器。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34fe6152-7971-4806-a660-cd4a4206742a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88680, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "电器", "is_correct": true, "explanation": "正确答案。电器上可以装指示灯，所以会有小小的红灯。"}, {"text": "脸", "is_correct": false, "explanation": "体貌：“脸”描写人的外貌，脸上不会装指示灯，“脸上有一个红灯”不合语境。"}, {"text": "手", "is_correct": false, "explanation": "体貌：“手”是人的身体部位，不会有指示灯。"}, {"text": "花", "is_correct": false, "explanation": "配价：“上有红灯”要求主体是能装灯的器物，“花”不能带红灯。"}], "explanations": {"电器": "正确答案。电器上可以装指示灯，所以会有小小的红灯。", "脸": "体貌：“脸”描写人的外貌，脸上不会装指示灯，“脸上有一个红灯”不合语境。", "手": "体貌：“手”是人的身体部位，不会有指示灯。", "花": "配价：“上有红灯”要求主体是能装灯的器物，“花”不能带红灯。"}, "sentence_index": 6, "correct_answer": "电器"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他开着电器去上班。", "explanation": "这里应该用〈汽车〉。电器指用电工作的器具，汽车是交通工具，不能用“开”来指电器。"}, {"text": "他在音乐课上学习弹电器。", "explanation": "这里应该用〈乐器〉。“弹”的对象是乐器，“电器”是用电工作的器具的统称，不能作为“弹”的对象。"}, {"text": "他在花园里种了很多电器。", "explanation": "这里应该用〈植物〉。电器是用电的器具，花草是植物，不能用电器指代。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34fe6152-7971-4806-a660-cd4a4206742a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88680, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "家里买了一套的新电器。", "corrected_sentence": "家里买了一套新的电器。", "error_description": "定语位置错误：“的”不能紧跟量词“一套”，应放在修饰语“新”之后，应说“一套新的电器”，不能说“一套的新电器”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34fe6152-7971-4806-a660-cd4a4206742a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
