INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88681, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "撤除", "is_correct": true, "explanation": "正确。撤除是把已安放的东西搬走，与「设置」的安放义相反。"}, {"text": "观察", "is_correct": false, "explanation": "「观察」指仔细看，与「设置」的任何义项都无反义关系。"}, {"text": "推广", "is_correct": false, "explanation": "「推广」指扩大普及，与「设置」的任何义项都无反义关系。"}, {"text": "清洁", "is_correct": false, "explanation": "「清洁」指把脏东西弄干净，与「设置」的安放义无反义关系。"}], "correct_answer": "撤除", "explanations": {"撤除": "正确。撤除是把已安放的东西搬走，与「设置」的安放义相反。", "观察": "「观察」指仔细看，与「设置」的任何义项都无反义关系。", "推广": "「推广」指扩大普及，与「设置」的任何义项都无反义关系。", "清洁": "「清洁」指把脏东西弄干净，与「设置」的安放义无反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0be81865-5a6b-41b7-b7c7-e3a4302724c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
