INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88681, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "设置是把东西安放在一个地方,让它能用。", "primary_collocate": null, "pronunciation": "shè zhì", "ipa": "ʂɤ˥˩ ʈʂɨ˥˩", "syllable_count": 2, "sentences": [{"text": "路口设置了一个红绿灯。", "target_word": "设置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园里设置了很多长椅。", "target_word": "设置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车站设置着一台自动售票机。", "target_word": "设置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校在门口设置了一面大镜子。", "target_word": "设置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图书馆门口设置了一台饮水机。", "target_word": "设置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "马路两边设置了很多路灯。", "target_word": "设置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院在走廊里设置了几把椅子。", "target_word": "设置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路上设置过摄像头。", "target_word": "设置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店在门口设置了一个雨伞架。", "target_word": "设置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上设置了几个垃圾桶。", "target_word": "设置", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "设置了", "label": "体标"}, {"form": "设置着", "label": "体标"}, {"form": "设置过", "label": "体标"}], "register": "中性", "sense_fingerprint": "把设备、物品安放在某处供人使用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28512d04-a44a-481e-98dc-fa698edcda0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88681, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "设置", "is_correct": true, "explanation": "正确答案：设置 shè zhì，表示把物品安放在某处供人使用。"}, {"text": "设计", "is_correct": false, "explanation": "jì（第四声）与 zhì（第四声）声母不同（j 与 zh），意思是设计。"}, {"text": "社址", "is_correct": false, "explanation": "zhǐ（第三声）与 zhì（第四声）声调不同，意思是机构的地址。"}, {"text": "试制", "is_correct": false, "explanation": "shì 与 shè 韵母不同（i 与 e），意思是试验性地制造。"}, {"text": "市制", "is_correct": false, "explanation": "shì（第四声）与 shè 韵母不同（i 与 e），意思是旧时的度量衡制度。"}], "explanations": {"设置": "正确答案：设置 shè zhì，表示把物品安放在某处供人使用。", "设计": "jì（第四声）与 zhì（第四声）声母不同（j 与 zh），意思是设计。", "社址": "zhǐ（第三声）与 zhì（第四声）声调不同，意思是机构的地址。", "试制": "shì 与 shè 韵母不同（i 与 e），意思是试验性地制造。", "市制": "shì（第四声）与 shè 韵母不同（i 与 e），意思是旧时的度量衡制度。"}, "sentence_index": null, "correct_answer": "设置"}, "level_3": {"options": [{"text": "设置", "is_correct": true, "explanation": "正确。设置表示在路口安放红绿灯，供人使用。"}, {"text": "种", "is_correct": false, "explanation": "搭配：「种」多用于植物，不能说「路口种了一个红绿灯」。"}, {"text": "写", "is_correct": false, "explanation": "语义：「写」是书写，与红绿灯的安放无关。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：「喝」的对象是饮品，不能说「路口喝了一个红绿灯」。"}], "explanations": {"设置": "正确。设置表示在路口安放红绿灯，供人使用。", "种": "搭配：「种」多用于植物，不能说「路口种了一个红绿灯」。", "写": "语义：「写」是书写，与红绿灯的安放无关。", "喝": "搭配：「喝」的对象是饮品，不能说「路口喝了一个红绿灯」。"}, "sentence_index": 0, "correct_answer": "设置"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他设置了一段旋律。", "explanation": "这里应该用〈谱写〉。设置指安放设备、物品，创作旋律要用「谱写」。"}, {"text": "工人设置了一座新桥。", "explanation": "这里应该用〈建造〉。设置指安放物品或设备，建造桥梁要用「建造」。"}, {"text": "我把书设置在桌子上。", "explanation": "这里应该用〈放〉。设置指安放设施、设备，单独的一本书放在桌上要用「放」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0be81865-5a6b-41b7-b7c7-e3a4302724c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88681, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "设置", "is_correct": true, "explanation": "正确。设置表示医院在走廊里安放椅子，供人使用。"}, {"text": "唱", "is_correct": false, "explanation": "语义：「唱」是唱歌，不能说「唱了几把椅子」。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：「喝」的对象是饮品，不能说「喝了几把椅子」。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：「吃」的对象是食物，不能说「吃了几把椅子」。"}], "explanations": {"设置": "正确。设置表示医院在走廊里安放椅子，供人使用。", "唱": "语义：「唱」是唱歌，不能说「唱了几把椅子」。", "喝": "搭配：「喝」的对象是饮品，不能说「喝了几把椅子」。", "吃": "搭配：「吃」的对象是食物，不能说「吃了几把椅子」。"}, "sentence_index": 6, "correct_answer": "设置"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人设置了一条新路。", "explanation": "这里应该用〈修建〉。设置指安放设备、物品，修路要用「修建」。"}, {"text": "他在院子里设置了一棵树。", "explanation": "这里应该用〈栽〉。设置不用于栽种植物，种树要用「栽」。"}, {"text": "厨房设置了一锅水。", "explanation": "这里应该用〈烧〉。设置指安放设备、物品，烧水要用「烧」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0be81865-5a6b-41b7-b7c7-e3a4302724c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
