INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88682, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "设置是建立机构、专业，或为软件、设备设定选项。", "primary_collocate": null, "pronunciation": "shè zhì", "ipa": "ʂɤ˥˩ ʈʂɨ˥˩", "syllable_count": 2, "sentences": [{"text": "学校今年设置了新的专业。", "target_word": "设置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你在手机里设置一个闹钟。", "target_word": "设置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我给电脑设置了新的密码。", "target_word": "设置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司设置了一个客服部门。", "target_word": "设置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把手机的声音设置得很小。", "target_word": "设置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个游戏可以自己设置难度。", "target_word": "设置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院新设置了一个儿童科。", "target_word": "设置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你可以把文字设置成大一点。", "target_word": "设置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市里设置了新的公交线路。", "target_word": "设置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这所大学去年设置了新的奖学金。", "target_word": "设置", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "设置了", "label": "体标"}, {"form": "设置过", "label": "体标"}], "register": "中性", "sense_fingerprint": "建立机构、专业，或配置软件、设备的选项", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28512d04-a44a-481e-98dc-fa698edcda0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88682, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "设置", "is_correct": true, "explanation": "正确答案：设置 shè zhì，表示建立机构、专业，或配置设备的选项。"}, {"text": "设计", "is_correct": false, "explanation": "jì（第四声）与 zhì（第四声）声母不同（j 与 zh），意思是设计。"}, {"text": "社址", "is_correct": false, "explanation": "zhǐ（第三声）与 zhì（第四声）声调不同，意思是机构的地址。"}, {"text": "试制", "is_correct": false, "explanation": "shì 与 shè 韵母不同（i 与 e），意思是试验性地制造。"}, {"text": "市制", "is_correct": false, "explanation": "shì（第四声）与 shè 韵母不同（i 与 e），意思是旧时的度量衡制度。"}], "explanations": {"设置": "正确答案：设置 shè zhì，表示建立机构、专业，或配置设备的选项。", "设计": "jì（第四声）与 zhì（第四声）声母不同（j 与 zh），意思是设计。", "社址": "zhǐ（第三声）与 zhì（第四声）声调不同，意思是机构的地址。", "试制": "shì 与 shè 韵母不同（i 与 e），意思是试验性地制造。", "市制": "shì（第四声）与 shè 韵母不同（i 与 e），意思是旧时的度量衡制度。"}, "sentence_index": null, "correct_answer": "设置"}, "level_3": {"options": [{"text": "设置", "is_correct": true, "explanation": "正确。设置表示学校今年建立了新的专业。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：「吃」的对象是食物，不能说「吃了新的专业」。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：「穿」的对象是衣物，与「专业」不搭配。"}, {"text": "唱", "is_correct": false, "explanation": "语义：「唱」是唱歌，与「新的专业」的建立无关。"}], "explanations": {"设置": "正确。设置表示学校今年建立了新的专业。", "吃": "搭配：「吃」的对象是食物，不能说「吃了新的专业」。", "穿": "搭配：「穿」的对象是衣物，与「专业」不搭配。", "唱": "语义：「唱」是唱歌，与「新的专业」的建立无关。"}, "sentence_index": 0, "correct_answer": "设置"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他设置了一首歌。", "explanation": "这里应该用〈唱〉。设置指建立机构或配置选项，唱歌不用「设置」。"}, {"text": "他设置了一件新衣服。", "explanation": "这里应该用〈挑选〉。设置指建立或配置，选衣服要用「挑选」。"}, {"text": "他设置了一封信。", "explanation": "这里应该用〈写〉。设置不用于书写文字，写信要用「写」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0be81865-5a6b-41b7-b7c7-e3a4302724c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88682, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "设置", "is_correct": true, "explanation": "正确。设置表示医院建立了一个新的科室。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：「煮」的对象是食物，不能说「煮了一个儿童科」。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：「穿」的对象是衣物，不能说「穿了一个儿童科」。"}, {"text": "砍", "is_correct": false, "explanation": "语义：「砍」是用刀斩断，与建立科室无关。"}], "explanations": {"设置": "正确。设置表示医院建立了一个新的科室。", "煮": "搭配：「煮」的对象是食物，不能说「煮了一个儿童科」。", "穿": "搭配：「穿」的对象是衣物，不能说「穿了一个儿童科」。", "砍": "语义：「砍」是用刀斩断，与建立科室无关。"}, "sentence_index": 6, "correct_answer": "设置"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他设置了一个笑话。", "explanation": "这里应该用〈讲〉。设置指建立机构或配置选项，讲笑话不用「设置」。"}, {"text": "他设置了一段路。", "explanation": "这里应该用〈修〉。设置不用于修建道路，修路要用「修」。"}, {"text": "作家设置了一篇文章。", "explanation": "这里应该用〈发表〉。设置不用于发表文章。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0be81865-5a6b-41b7-b7c7-e3a4302724c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88682, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这所学校去年设置了过一个新专业。", "corrected_sentence": "这所学校去年设置过一个新专业。", "error_description": "「了」与「过」叠用错误：表示曾经建立过要用「设置过」，不能在中间加「了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0be81865-5a6b-41b7-b7c7-e3a4302724c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88682, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我给这台旧电脑设置了过一个开机密码。", "corrected_sentence": "我给这台旧电脑设置过一个开机密码。", "error_description": "「了」与「过」叠用：表示曾经做过要用「设置过」，不能在中间加「了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0be81865-5a6b-41b7-b7c7-e3a4302724c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
