INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88683, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "property", "definition": "不如是比另一个差一点，没有它好。", "primary_collocate": null, "pronunciation": "bù rú", "ipa": "pu˥˩ ɻu˧˥", "syllable_count": 2, "sentences": [{"text": "我的汉语不如他好。", "target_word": "不如", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天不如昨天热。", "target_word": "不如", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坐车不如骑车快。", "target_word": "不如", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟跑得不如哥哥快。", "target_word": "不如", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的菜不如那家好吃。", "target_word": "不如", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的字不如姐姐写得漂亮。", "target_word": "不如", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件衣服不如那件便宜。", "target_word": "不如", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的成绩不如以前好。", "target_word": "不如", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "住在城里不如住在乡下安静。", "target_word": "不如", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种面料不如那种柔软。", "target_word": "不如", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "动词：A不如B，A比B稍差", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '525423d5-7b31-4df5-a976-f002812aab26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88683, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "不如", "is_correct": true, "explanation": "正确：不如（bù rú），意思是比不上，没有它好。"}, {"text": "哺乳", "is_correct": false, "explanation": "bǔ（第三声）与 bù（第四声）、rǔ（第三声）与 rú（第二声）声调都不同，意思是给婴儿喂奶。"}, {"text": "步入", "is_correct": false, "explanation": "rù（第四声）与 rú（第二声）声调不同，意思是走进。"}, {"text": "补入", "is_correct": false, "explanation": "bǔ（第三声）与 bù（第四声）、rù（第四声）与 rú（第二声）声调都不同，意思是补充加入。"}], "explanations": {"不如": "正确：不如（bù rú），意思是比不上，没有它好。", "哺乳": "bǔ（第三声）与 bù（第四声）、rǔ（第三声）与 rú（第二声）声调都不同，意思是给婴儿喂奶。", "步入": "rù（第四声）与 rú（第二声）声调不同，意思是走进。", "补入": "bǔ（第三声）与 bù（第四声）、rù（第四声）与 rú（第二声）声调都不同，意思是补充加入。"}, "sentence_index": null, "correct_answer": "不如"}, "level_3": {"options": [{"text": "不如", "is_correct": true, "explanation": "正确：“不如”表示比不上，与“他好”的比较相符。"}, {"text": "超过", "is_correct": false, "explanation": "配价：“超过”后已直接带比较对象，不能再接形容词“好”作补语。"}, {"text": "赶上", "is_correct": false, "explanation": "语义：“赶上”指追上，不表示比较优劣的结果，与“他好”不符。"}, {"text": "胜过", "is_correct": false, "explanation": "搭配：“胜过”本身已表示比较，后面不能再接“好”，应说“胜过他”。"}], "explanations": {"不如": "正确：“不如”表示比不上，与“他好”的比较相符。", "超过": "配价：“超过”后已直接带比较对象，不能再接形容词“好”作补语。", "赶上": "语义：“赶上”指追上，不表示比较优劣的结果，与“他好”不符。", "胜过": "搭配：“胜过”本身已表示比较，后面不能再接“好”，应说“胜过他”。"}, "sentence_index": 0, "correct_answer": "不如"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家店的菜不如那家，所以这家的菜更好吃。", "explanation": "这里应该用〈强于〉。“不如那家”说这家较差，后半句却说这家更好吃，前后矛盾。"}, {"text": "这台电脑比那台快，所以不如那台。", "explanation": "这里应该用〈胜过〉。前半句说明更快，“不如”说明更差，前后矛盾。"}, {"text": "我不如他高，所以我比他高。", "explanation": "这里应该用〈高于〉。“不如”说明比不上，与后半句“我比他高”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b01eabee-5f23-40fb-bd13-a6b2189c2450') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88683, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不如", "is_correct": true, "explanation": "正确：“不如”表示比不上，与“那件便宜”的比较相符。"}, {"text": "挑选", "is_correct": false, "explanation": "语义：“挑选”是选择的动作，不能用来比较价格高低。"}, {"text": "试穿", "is_correct": false, "explanation": "语义：“试穿”是试衣服的动作，与“那件便宜”的比较无关。"}, {"text": "打折", "is_correct": false, "explanation": "配价：“打折”要接金额或比例，不能以“那件”作为比较对象。"}], "explanations": {"不如": "正确：“不如”表示比不上，与“那件便宜”的比较相符。", "挑选": "语义：“挑选”是选择的动作，不能用来比较价格高低。", "试穿": "语义：“试穿”是试衣服的动作，与“那件便宜”的比较无关。", "打折": "配价：“打折”要接金额或比例，不能以“那件”作为比较对象。"}, "sentence_index": 6, "correct_answer": "不如"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他这次比赛不如我，所以我输了。", "explanation": "这里前后矛盾：“不如”说他较差，我应当领先，后半句却说我输了，应改用〈领先〉。"}, {"text": "姐姐唱歌不如妹妹，所以妹妹唱得比姐姐差。", "explanation": "这里前后矛盾：“不如”说明前者比后者差，后半句却说后者比前者差，应改用〈超过〉。"}, {"text": "这条路不如那条路长，所以这条路比那条路还长。", "explanation": "这里应该用〈比…短〉。“不如”说前者不及后者，后半句却说更长，前后矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b01eabee-5f23-40fb-bd13-a6b2189c2450') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88683, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妹妹跑不如姐姐快。", "corrected_sentence": "妹妹跑得不如姐姐快。", "error_description": "“跑”后漏了补语标记“得”。应说“跑得不如姐姐快”，“得”引出“不如”的比较短语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b01eabee-5f23-40fb-bd13-a6b2189c2450') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88683, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条裙子很不如那条便宜。", "corrected_sentence": "这条裙子不如那条便宜。", "error_description": "“不如”比较结构前不能加程度副词“很”，应去掉“很”，说“不如那条便宜”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b01eabee-5f23-40fb-bd13-a6b2189c2450') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
