INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88685, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "念头是脑子里忽然想到的一个想法。", "primary_collocate": null, "pronunciation": "niàn tou", "ipa": "njɛn˥˩ tʰoʊ", "syllable_count": 2, "sentences": [{"text": "他脑子里忽然冒出一个念头。", "target_word": "念头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我突然有了一个奇怪的念头。", "target_word": "念头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看着窗外的雪，她忽然有个念头。", "target_word": "念头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个念头在我脑子里一闪就过去了。", "target_word": "念头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "走到门口，他又冒出一个新念头。", "target_word": "念头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我刚有这个念头，电话就响了。", "target_word": "念头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想把这个念头马上告诉妈妈。", "target_word": "念头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到那首歌，我忽然有了回家的念头。", "target_word": "念头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她脑子里闪过一个可笑的念头。", "target_word": "念头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个念头太突然，连我自己都吓了一跳。", "target_word": "念头", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "念頭", "label": "繁体"}, {"form": "个念头", "label": "量词"}], "register": "口语", "sense_fingerprint": "脑子里忽然闪现的一个想法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c11a758-978a-45e2-9505-b243bd2bcd26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88685, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "石头", "is_correct": false, "explanation": "语义：冒出的是念头、声音这类无形的东西，石头是实物，脑子里不会冒出石头。"}, {"text": "念头", "is_correct": true, "explanation": "念头指脑子里忽然闪现的想法，与“忽然冒出”搭配自然。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是家具，不是脑子里能冒出的东西。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：“冒出”多与念头、声音、火苗等搭配，不能和“窗户”搭配。"}], "explanations": {"石头": "语义：冒出的是念头、声音这类无形的东西，石头是实物，脑子里不会冒出石头。", "念头": "念头指脑子里忽然闪现的想法，与“忽然冒出”搭配自然。", "桌子": "语义：桌子是家具，不是脑子里能冒出的东西。", "窗户": "搭配：“冒出”多与念头、声音、火苗等搭配，不能和“窗户”搭配。"}, "sentence_index": 0, "correct_answer": "念头"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我脑子里闪过一条念头。", "explanation": "这里应该用〈个〉。“念头”的量词用“个”或“种”，“条”多用于细长的东西，不能用于念头。"}, {"text": "他把这个念头放进冰箱里了。", "explanation": "这里应该用〈牛奶〉。“放进冰箱”的对象是食物等实物，念头是脑子里闪过的想法，不能放进冰箱。"}, {"text": "他饿得厉害，一口气把这个念头吃完了。", "explanation": "这里应该用〈饭〉。“吃完”的对象是食物，念头是脑子里的想法，不能吃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '326e01e2-45d0-4634-b61d-c9accebcc226') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88685, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "钥匙", "is_correct": false, "explanation": "配价：“告诉”要接消息或事情作宾语，“钥匙”不能作为告诉的内容。"}, {"text": "手套", "is_correct": false, "explanation": "语义：手套是实物，不是可以告诉别人的想法或事情。"}, {"text": "念头", "is_correct": true, "explanation": "念头指脑子里产生的想法，可以告诉别人，与“马上告诉妈妈”搭配自然。"}, {"text": "房子", "is_correct": false, "explanation": "配价：“告诉”要接消息或事情，“房子”不能作为告诉的内容。"}], "explanations": {"钥匙": "配价：“告诉”要接消息或事情作宾语，“钥匙”不能作为告诉的内容。", "手套": "语义：手套是实物，不是可以告诉别人的想法或事情。", "念头": "念头指脑子里产生的想法，可以告诉别人，与“马上告诉妈妈”搭配自然。", "房子": "配价：“告诉”要接消息或事情，“房子”不能作为告诉的内容。"}, "sentence_index": 6, "correct_answer": "念头"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他饿了一整天，狠狠咬了一口念头。", "explanation": "这里应该用〈馒头〉。“咬”的对象是食物，念头是脑子里的想法，不能咬。"}, {"text": "经过讨论，我们得出了一个念头。", "explanation": "这里应该用〈结论〉。“得出”搭配“结论”，念头不能作为讨论得出的结果。"}, {"text": "他下定了念头，每天早起跑步。", "explanation": "这里应该用〈决心〉。“下定”搭配“决心”，念头是闪现的想法，不能下定。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '326e01e2-45d0-4634-b61d-c9accebcc226') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88685, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她心里闪过一本念头。", "corrected_sentence": "她心里闪过一个念头。", "error_description": "量词错误：“念头”应该用量词“个”，说“一个念头”；“本”用于书籍等，不能用于念头。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '326e01e2-45d0-4634-b61d-c9accebcc226') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88685, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我洗澡时突然冒出一本新念头。", "corrected_sentence": "我洗澡时突然冒出一个新念头。", "error_description": "量词错误：“念头”应该用量词“个”，说“一个新念头”；“本”用于书籍等，不能用于念头。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '326e01e2-45d0-4634-b61d-c9accebcc226') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88686, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '326e01e2-45d0-4634-b61d-c9accebcc226') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88686, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '326e01e2-45d0-4634-b61d-c9accebcc226') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88686, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "心里产生的想法或打算。", "primary_collocate": null, "pronunciation": "niàn tou", "ipa": "njɛn˥˩ tʰoʊ", "syllable_count": 2, "sentences": [{"text": "他早就有了出国读书的念头。", "target_word": "念头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈劝了很久，他才打消了辞职的念头。", "target_word": "念头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她心里一直有开一家小店的念头。", "target_word": "念头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你怎么会有这种念头？", "target_word": "念头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我从没有过放弃的念头。", "target_word": "念头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到别人都成功了，他动了学画画的念头。", "target_word": "念头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他这几年一直有搬到海边住的念头。", "target_word": "念头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个念头在我心里放了很多年。", "target_word": "念头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看了那本书以后，他有了写小说的念头。", "target_word": "念头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她想把这个念头变成现实。", "target_word": "念头", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "念頭", "label": "繁体"}, {"form": "种念头", "label": "量词"}], "register": "口语", "sense_fingerprint": "心里产生的、带有打算意味的想法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c11a758-978a-45e2-9505-b243bd2bcd26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88686, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "眼镜", "is_correct": false, "explanation": "语义：眼镜是戴在脸上的物品，不是想法或打算。"}, {"text": "念头", "is_correct": true, "explanation": "念头指心里产生的想法或打算，与“出国读书的”搭配自然。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：“出国读书的”修饰的应是计划、打算一类，不能修饰脾气。"}, {"text": "石子", "is_correct": false, "explanation": "语义：石子是实物，不是心里的想法或打算。"}], "explanations": {"眼镜": "语义：眼镜是戴在脸上的物品，不是想法或打算。", "念头": "念头指心里产生的想法或打算，与“出国读书的”搭配自然。", "脾气": "搭配：“出国读书的”修饰的应是计划、打算一类，不能修饰脾气。", "石子": "语义：石子是实物，不是心里的想法或打算。"}, "sentence_index": 0, "correct_answer": "念头"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他这几年有一条搬家的念头。", "explanation": "这里应该用〈个〉。“念头”的量词用“个”或“种”，“条”多用于细长的东西，不能用于念头。"}, {"text": "他下定了念头要减肥。", "explanation": "这里应该用〈决心〉。“下定”搭配“决心”，念头指心里的打算，不能说“下定”。"}, {"text": "会议结束后，大家得出了一个念头。", "explanation": "这里应该用〈结论〉。“得出”搭配“结论”，念头不能作为会议得出的结果。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '326e01e2-45d0-4634-b61d-c9accebcc226') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88686, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "雨伞", "is_correct": false, "explanation": "语义：雨伞是日用品，不是搬家的打算或想法。"}, {"text": "念头", "is_correct": true, "explanation": "念头指心里产生的想法或打算，“搬到海边住的”修饰它很自然。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”指人的体型，不能指“搬到海边住”这样的想法或打算。"}, {"text": "水杯", "is_correct": false, "explanation": "语义：水杯是器皿，不是心里的打算，与“搬到海边住”无关。"}], "explanations": {"雨伞": "语义：雨伞是日用品，不是搬家的打算或想法。", "念头": "念头指心里产生的想法或打算，“搬到海边住的”修饰它很自然。", "身材": "体貌：“身材”指人的体型，不能指“搬到海边住”这样的想法或打算。", "水杯": "语义：水杯是器皿，不是心里的打算，与“搬到海边住”无关。"}, "sentence_index": 6, "correct_answer": "念头"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她饿坏了，一口气吃掉了这个念头。", "explanation": "这里应该用〈馒头〉。“吃掉”的对象是食物，念头是心里的打算，不能吃。"}, {"text": "公司把这个念头印成了宣传册，发给大家。", "explanation": "这里应该用〈方案〉。能印成宣传册的是具体的方案，念头只是心里的打算，不能印刷。"}, {"text": "他在会上发表了自己的念头。", "explanation": "这里应该用〈观点〉。“发表”搭配“观点”，念头不能拿到会上发表。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '326e01e2-45d0-4634-b61d-c9accebcc226') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88686, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她这几年心里一直有一头搬去乡下住的念头。", "corrected_sentence": "她这几年心里一直有一个搬去乡下住的念头。", "error_description": "量词错误：“念头”应该用“个”，说“一个念头”；“头”是牛、猪等牲畜的量词，不能用于念头。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '326e01e2-45d0-4634-b61d-c9accebcc226') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88686, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她心里一直有一个开咖啡馆念头。", "corrected_sentence": "她心里一直有一个开咖啡馆的念头。", "error_description": "结构助词错误：定语“开咖啡馆”和“念头”之间要用“的”，应说“开咖啡馆的念头”，不能省略“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '326e01e2-45d0-4634-b61d-c9accebcc226') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
