INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88689, 1, 'prompt1_core', '{"pos": "介词", "semantic_class": "function", "definition": "随着是前面的事变了,后面的事也跟着变。", "primary_collocate": null, "pronunciation": "suí zhe", "ipa": "sweɪ˧˥ ʈʂɤ˙", "syllable_count": 2, "sentences": [{"text": "随着天气变冷,人们都穿上厚衣服。", "target_word": "随着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "随着年龄变大,他越来越爱安静。", "target_word": "随着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "随着时间过去,她慢慢忘了这件事。", "target_word": "随着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "随着城市变大,路也越来越多。", "target_word": "随着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "随着天色变黑,街上的人少了。", "target_word": "随着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "随着作业增多,他睡得越来越晚。", "target_word": "随着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "随着价格上涨,买东西的人少了。", "target_word": "随着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "随着春天到来,花都开了。", "target_word": "随着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "随着孩子长大,父母也慢慢变老了。", "target_word": "随着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "随着天气变热,吃冰的人多了。", "target_word": "随着", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "随着:介词:前面的事变化,后面的事跟着变化", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bbc60e8-a9d1-4985-8b02-39b76cfdb0b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88689, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "随着", "is_correct": true, "explanation": "随着：表示后一件事跟着前一件事的变化而变化，符合“天气变冷，人们穿厚衣服”的句意。"}, {"text": "朝", "is_correct": false, "explanation": "语义：朝表示方向，不能表示天气变化引起后续变化。"}, {"text": "沿着", "is_correct": false, "explanation": "语义：沿着表示沿路线行走，不能说“沿着天气变冷”。"}, {"text": "向", "is_correct": false, "explanation": "搭配：向后面接方向或对象，不能接“天气变冷”这样的事件。"}], "explanations": {"随着": "随着：表示后一件事跟着前一件事的变化而变化，符合“天气变冷，人们穿厚衣服”的句意。", "朝": "语义：朝表示方向，不能表示天气变化引起后续变化。", "沿着": "语义：沿着表示沿路线行走，不能说“沿着天气变冷”。", "向": "搭配：向后面接方向或对象，不能接“天气变冷”这样的事件。"}, "sentence_index": 0, "correct_answer": "随着"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们随着河边散步。", "explanation": "这里应该用〈沿着〉。随着表示一件事变化时另一件事跟着变化，不表示沿路线行走。"}, {"text": "随着有你，我才没迟到。", "explanation": "这里应该用〈幸亏〉。随着表示伴随变化，不能表示幸亏这种原因。"}, {"text": "随着他是班长，大家都很听话。", "explanation": "这里应该用〈因为〉。随着表示后一事物跟着前一事物的变化而变化，“是班长”是固定状态，不会变化，表示原因要用因为。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ded55dbc-1397-42e7-98c6-9921558a174b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88689, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "随着", "is_correct": true, "explanation": "随着：表示后一件事跟着前一件事的变化而变化，符合“价格上涨，买东西的人少了”的句意。"}, {"text": "凭", "is_correct": false, "explanation": "语义：凭表示凭借的依据，不能说“凭价格上涨”。"}, {"text": "按照", "is_correct": false, "explanation": "语义：按照表示依据某种标准，不能说“按照价格上涨”。"}, {"text": "比", "is_correct": false, "explanation": "搭配：比用于比较两个事物，不能接“价格上涨”这样的事件。"}], "explanations": {"随着": "随着：表示后一件事跟着前一件事的变化而变化，符合“价格上涨，买东西的人少了”的句意。", "凭": "语义：凭表示凭借的依据，不能说“凭价格上涨”。", "按照": "语义：按照表示依据某种标准，不能说“按照价格上涨”。", "比": "搭配：比用于比较两个事物，不能接“价格上涨”这样的事件。"}, "sentence_index": 6, "correct_answer": "随着"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件事随着老师负责。", "explanation": "这里应该用〈由〉。随着表示伴随变化，不能用来引出负责的人。"}, {"text": "我随着老师问好。", "explanation": "这里应该用〈向〉。随着表示后一事物跟着前一事物变化，不能引出问好的对象，应说“向老师问好”。"}, {"text": "我们随着大家的力量完成了任务。", "explanation": "这里应该用〈依靠〉。随着表示伴随变化，不能表示凭借或依赖。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ded55dbc-1397-42e7-98c6-9921558a174b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88689, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "随着了收入增加，人们买的东西越来越多了。", "corrected_sentence": "随着收入增加，人们买的东西越来越多了。", "error_description": "“了”不能放在“随着”后面。正确形式是“随着收入增加”，“随着了收入增加”是错误的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ded55dbc-1397-42e7-98c6-9921558a174b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88689, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "随着的年龄增长，他越来越喜欢运动。", "corrected_sentence": "随着年龄增长，他越来越喜欢运动。", "error_description": "“随着”后面不能直接加“的”。正确形式是“随着年龄增长”，“随着的年龄增长”是错误的。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ded55dbc-1397-42e7-98c6-9921558a174b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
