INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88691, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "不必是不用做，没有一定要做的需要。", "primary_collocate": null, "pronunciation": "bú bì", "ipa": "pu˧˥ pi˥˩", "syllable_count": 2, "sentences": [{"text": "你不必担心，我会照顾好自己。", "target_word": "不必", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "明天放假，你不必早起。", "target_word": "不必", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这件事很小，不必告诉老师。", "target_word": "不必", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他已经知道了，你不必再说一遍。", "target_word": "不必", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "钱我已经付了，你不必给我。", "target_word": "不必", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "路不远，我们不必坐车。", "target_word": "不必", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这里有人帮忙，你不必留下来。", "target_word": "不必", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "衣服还很新，不必买新的。", "target_word": "不必", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "孩子已经长大了，您不必每天打电话。", "target_word": "不必", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我自己能回家，你不必送我。", "target_word": "不必", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "表示没有必要去做某事，多用来劝人不用做", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e55811ed-4f23-4d28-8c01-de6b3a9ee27b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88691, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "必须", "is_correct": false, "explanation": "语义：“必须”表示一定要做，与“不必”（没有必要）意思相反，和“别担心”的劝慰语气不合。"}, {"text": "不必", "is_correct": true, "explanation": "不必：表示没有必要，与“我会照顾好自己”配合，劝对方不用担心。"}, {"text": "马上", "is_correct": false, "explanation": "搭配：“马上”表示立刻，不能修饰“担心”这种持续的心理状态。"}, {"text": "千万", "is_correct": false, "explanation": "搭配：“千万”多与“别”“不要”连用表示叮嘱，不能直接修饰“担心”。"}], "explanations": {"必须": "语义：“必须”表示一定要做，与“不必”（没有必要）意思相反，和“别担心”的劝慰语气不合。", "不必": "不必：表示没有必要，与“我会照顾好自己”配合，劝对方不用担心。", "马上": "搭配：“马上”表示立刻，不能修饰“担心”这种持续的心理状态。", "千万": "搭配：“千万”多与“别”“不要”连用表示叮嘱，不能直接修饰“担心”。"}, "sentence_index": 0, "correct_answer": "不必"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "不必碰那个开关！里面有高压电，很危险！", "explanation": "这里应该用〈别〉。“别”表示劝阻或禁止，“不必”只表示没有必要，不能用来警告别人不要碰危险的东西。"}, {"text": "他的腿断了，不必能走路。", "explanation": "这里应该用〈不能〉。“不能”表示做不到，“不必”只表示没有必要，不能用来说明能力上做不到。"}, {"text": "上课时不必玩手机，这是学校的规定。", "explanation": "这里应该用〈不许〉。“不许”表示禁止，“不必”只表示没有必要，不能用来说明校规的禁令。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '841391c4-6f01-4abc-9538-5b5083aeb62e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88691, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "很", "is_correct": false, "explanation": "语法：“很”是程度副词，不能直接修饰动词“留下来”，“你很留下来”不成句。"}, {"text": "不必", "is_correct": true, "explanation": "不必：表示没有必要，与“这里有人帮忙”配合，说明对方不用留下来。"}, {"text": "只好", "is_correct": false, "explanation": "语义：“只好”表示无奈之下不得不做，与“有人帮忙”的情况不合，句子语义不通。"}, {"text": "非常", "is_correct": false, "explanation": "语法：“非常”是程度副词，不能直接修饰动词“留下来”，“你非常留下来”不成句。"}], "explanations": {"很": "语法：“很”是程度副词，不能直接修饰动词“留下来”，“你很留下来”不成句。", "不必": "不必：表示没有必要，与“这里有人帮忙”配合，说明对方不用留下来。", "只好": "语义：“只好”表示无奈之下不得不做，与“有人帮忙”的情况不合，句子语义不通。", "非常": "语法：“非常”是程度副词，不能直接修饰动词“留下来”，“你非常留下来”不成句。"}, "sentence_index": 6, "correct_answer": "不必"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "明天的比赛不必能赢。", "explanation": "这里应该用〈不一定〉。“不一定”表示结果不确定，“不必”只表示没有必要，不能用来说比赛的结果。"}, {"text": "这里不必讲话，老师说要安静。", "explanation": "这里应该用〈不许〉。“不许”表示禁止，“不必”只表示没有必要，与“老师说要安静”的禁令相冲突。"}, {"text": "孩子刚做完手术，不必跑步，这对身体不好。", "explanation": "这里应该用〈不宜〉。“不宜”表示不适合做，“不必”只表示没有必要，不能用来表示对身体有害的劝阻。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '841391c4-6f01-4abc-9538-5b5083aeb62e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88691, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条路好走，我们没不必绕路。", "corrected_sentence": "这条路好走，我们不必绕路。", "error_description": "“不必”本身已经表示否定，前面不能再加“没”。应说“我们不必绕路”，“没不必”是双重否定，不成话。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '841391c4-6f01-4abc-9538-5b5083aeb62e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88691, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "谢谢，但你很不必送我。", "corrected_sentence": "谢谢，但你不必送我。", "error_description": "错误：“不必”是副词，不能被程度副词“很”修饰，应去掉“很”，说“你不必送我”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '841391c4-6f01-4abc-9538-5b5083aeb62e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
