INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88692, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词，表示不需要；用不着。", "primary_collocate": null, "pronunciation": "bú bì", "ipa": "pu˧˥ pi˥˩", "syllable_count": 2, "sentences": [{"text": "大家不必紧张，这只是一个小考试。", "target_word": "不必", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你不必客气，就当是自己的家。", "target_word": "不必", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "时间还早，我们不必着急。", "target_word": "不必", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这点小事，你不必放在心上。", "target_word": "不必", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "饭我来做，你不必动手。", "target_word": "不必", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "门票是免费的，不必买票。", "target_word": "不必", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我记得路，你不必带我去。", "target_word": "不必", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "天气很好，不必带伞。", "target_word": "不必", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他不会生气，你不必怕他。", "target_word": "不必", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "明天在家上网课，学生不必来学校。", "target_word": "不必", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "表示不需要、用不着，常用于安慰或客气的话", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e55811ed-4f23-4d28-8c01-de6b3a9ee27b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88692, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "必须", "is_correct": false, "explanation": "语义：“必须”表示一定要紧张，与“只是一个小考试”的安慰语气相反。"}, {"text": "不必", "is_correct": true, "explanation": "不必：表示没有必要，符合安慰对方不用紧张的语气。"}, {"text": "千万", "is_correct": false, "explanation": "搭配：“千万”多与“别”“不要”连用表示叮嘱，不能直接说“千万紧张”。"}, {"text": "赶紧", "is_correct": false, "explanation": "语义：“赶紧”是催促快做某事，与“只是一个小考试”的安慰语境不合。"}], "explanations": {"必须": "语义：“必须”表示一定要紧张，与“只是一个小考试”的安慰语气相反。", "不必": "不必：表示没有必要，符合安慰对方不用紧张的语气。", "千万": "搭配：“千万”多与“别”“不要”连用表示叮嘱，不能直接说“千万紧张”。", "赶紧": "语义：“赶紧”是催促快做某事，与“只是一个小考试”的安慰语境不合。"}, "sentence_index": 0, "correct_answer": "不必"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "不必动这把剪刀！它很锋利，会割伤手！", "explanation": "这里应该用〈别〉。“别”表示劝阻或禁止，“不必”只表示没有必要，不能用来警告别人不要动危险的东西。"}, {"text": "他的眼睛看不见，不必能认路。", "explanation": "这里应该用〈不能〉。“不能”表示做不到，“不必”只表示没有必要，不能用来说明看不见时的能力。"}, {"text": "课堂上不必玩游戏，这是纪律。", "explanation": "这里应该用〈不许〉。“不许”表示禁止，“不必”只表示没有必要，不能用来说明纪律的禁令。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '841391c4-6f01-4abc-9538-5b5083aeb62e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88692, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "很", "is_correct": false, "explanation": "语法：“很”是程度副词，不能直接修饰动词“带”，“你很带我去”不成句。"}, {"text": "不必", "is_correct": true, "explanation": "不必：表示没有必要，与“我记得路”配合，说明对方不用带路。"}, {"text": "只好", "is_correct": false, "explanation": "语义：“只好”表示无奈之下不得不做，与“我记得路”的情况不合。"}, {"text": "非常", "is_correct": false, "explanation": "语法：“非常”是程度副词，不能直接修饰动词“带”，“你非常带我去”不成句。"}], "explanations": {"很": "语法：“很”是程度副词，不能直接修饰动词“带”，“你很带我去”不成句。", "不必": "不必：表示没有必要，与“我记得路”配合，说明对方不用带路。", "只好": "语义：“只好”表示无奈之下不得不做，与“我记得路”的情况不合。", "非常": "语法：“非常”是程度副词，不能直接修饰动词“带”，“你非常带我去”不成句。"}, "sentence_index": 6, "correct_answer": "不必"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "明天不必下雨，我们照常上课。", "explanation": "这里应该用〈不一定〉。“不一定”表示可能不会，“不必”只表示没有必要，不能用来说天气是否下雨。"}, {"text": "孩子刚发烧，不必出门，这样对身体不好。", "explanation": "这里应该用〈不宜〉。“不宜”表示不适合做，“不必”只表示没有必要，不能用来表示对身体有害的劝阻。"}, {"text": "我的手受伤了，不必能拿笔。", "explanation": "这里应该用〈不能〉。“不能”表示做不到，“不必”只表示没有必要，不能用来说明手受伤时的能力。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '841391c4-6f01-4abc-9538-5b5083aeb62e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88692, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这事不急，咱们很不必着急。", "corrected_sentence": "这事不急，咱们不必着急。", "error_description": "错误：“不必”是副词，不能被“很”修饰，应去掉“很”，说“咱们不必着急”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '841391c4-6f01-4abc-9538-5b5083aeb62e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88692, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我的伞还能用，你没不必担心。", "corrected_sentence": "我的伞还能用，你不必担心。", "error_description": "“不必”本身已经表示否定，前面不能再加“没”。应说“你不必担心”，“没不必”是双重否定，不成话。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '841391c4-6f01-4abc-9538-5b5083aeb62e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
