INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88694, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "研究人类性行为、性心理及相关问题的学科。", "primary_collocate": null, "pronunciation": "xìng xué", "ipa": "ɕiŋ˥˩ ɕɥe˧˥", "syllable_count": 2, "sentences": [{"text": "性学是研究人类性行为和性心理的学科。", "target_word": "性学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学了性学以后，她更懂人类的性行为了。", "target_word": "性学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "性学研究人的性行为，需要科学的方法。", "target_word": "性学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位教授多年来一直研究性行为，所以很懂性学。", "target_word": "性学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "研究性行为时，性学常常用到心理学和社会学。", "target_word": "性学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书介绍了性学的历史，也谈到性心理。", "target_word": "性学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "研究性行为的性学是一门年轻的学科，很多人还不了解。", "target_word": "性学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要研究人的性心理，就要先学一点性学。", "target_word": "性学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这门选修课讲人的性行为和性心理，叫性学。", "target_word": "性学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她对性行为的研究很有兴趣，所以选了性学。", "target_word": "性学", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一门性学", "label": "量词（门）"}, {"form": "性学家", "label": "复合"}, {"form": "性學", "label": "繁体"}], "register": "书面", "sense_fingerprint": "性学：研究人类性行为和性心理的学科", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ddf0a86-9417-4ade-a111-6e198f133eb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88694, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "性学", "is_correct": true, "explanation": "性学：研究人类性行为和性心理的学科，符合语境。"}, {"text": "哲学", "is_correct": false, "explanation": "语义：哲学研究世界本原与认识，不研究性行为。"}, {"text": "性别", "is_correct": false, "explanation": "语义：性别是人的类别，不是研究性行为的学科。"}, {"text": "生物", "is_correct": false, "explanation": "搭配：「生物」指生命现象，作学科名应说「生物学」。"}], "explanations": {"性学": "性学：研究人类性行为和性心理的学科，符合语境。", "哲学": "语义：哲学研究世界本原与认识，不研究性行为。", "性别": "语义：性别是人的类别，不是研究性行为的学科。", "生物": "搭配：「生物」指生命现象，作学科名应说「生物学」。"}, "sentence_index": 0, "correct_answer": "性学"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "父母应该对孩子进行性学，帮助他们保护自己。", "explanation": "这里应该用〈性教育〉。性教育是对人进行的知识教育，「进行」指对孩子施行的教育活动；性学是研究性行为的学科，不能作为教育活动施行。"}, {"text": "她和丈夫的性学很和谐。", "explanation": "这里应该用〈性生活〉。性生活指夫妻间的性行为状况，性学是研究性行为的学科，不能用来指两人的性生活。"}, {"text": "这位学者研究人的大脑和记忆，他的专业是性学。", "explanation": "这里应该用〈神经科学〉。神经科学研究大脑和神经系统，性学研究性行为和性心理，二者不能互换。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd55f774-744e-4867-8748-d72ae34848bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88694, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "性学", "is_correct": true, "explanation": "性学：研究性行为的学科，符合语境。"}, {"text": "天文学", "is_correct": false, "explanation": "语义：天文学研究天体，与性行为无关。"}, {"text": "地质学", "is_correct": false, "explanation": "语义：地质学研究地球的构造，与性行为无关。"}, {"text": "生理", "is_correct": false, "explanation": "搭配：「生理」指身体功能，作学科名应说「生理学」。"}], "explanations": {"性学": "性学：研究性行为的学科，符合语境。", "天文学": "语义：天文学研究天体，与性行为无关。", "地质学": "语义：地质学研究地球的构造，与性行为无关。", "生理": "搭配：「生理」指身体功能，作学科名应说「生理学」。"}, "sentence_index": 6, "correct_answer": "性学"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位学者研究社会结构，他主修的是性学。", "explanation": "这里应该用〈社会学〉。社会学研究社会结构，性学研究性行为和性心理，二者不能互换。"}, {"text": "她研究汉字的演变，专业是性学。", "explanation": "这里应该用〈语言学〉。语言学研究语言的结构和演变规律，性学研究性行为和性心理，不能用来指汉字研究。"}, {"text": "这位厨师每天研究菜谱，他的专业是性学。", "explanation": "这里应该用〈烹饪〉。烹饪研究做菜的方法，性学研究性行为和性心理，二者毫无关系。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd55f774-744e-4867-8748-d72ae34848bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88694, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我想学一位性学。", "corrected_sentence": "我想学一门性学。", "error_description": "量词错误：性学作学科用「门」，「位」只用于人。正确说法是「一门性学」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd55f774-744e-4867-8748-d72ae34848bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88694, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她选了过性学，所以很懂这门课。", "corrected_sentence": "她选过性学，所以很懂这门课。", "error_description": "「了」和「过」不能同时用。「过」已表示经历，「了」多余，应说「选过性学」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd55f774-744e-4867-8748-d72ae34848bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
