INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88697, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "一再是一次又一次，做了很多遍。", "primary_collocate": null, "pronunciation": "yī zài", "ipa": "i˥ tsaɪ˥˩", "syllable_count": 2, "sentences": [{"text": "他一再说对不起。", "target_word": "一再", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈一再告诉我要早点睡。", "target_word": "一再", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师一再提醒我们别迟到。", "target_word": "一再", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我一再看表，他还是没来。", "target_word": "一再", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她一再拒绝了他的帮助。", "target_word": "一再", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生一再说，不要吃太多盐。", "target_word": "一再", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友一再请我去他家玩。", "target_word": "一再", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一再问我路怎么走。", "target_word": "一再", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们一再商量，最后选了这个。", "target_word": "一再", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸一再要我小心开车。", "target_word": "一再", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "同一个动作一次又一次地做", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5345ed11-06b2-4130-89ce-bb50ae77b3fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88697, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "非常", "is_correct": false, "explanation": "搭配：“非常”一般修饰形容词或心理动词，不与“说对不起”这样的言语动作搭配，句子不通。"}, {"text": "格外", "is_correct": false, "explanation": "搭配：“格外”表示超出一般的程度，用来修饰“说对不起”不通，且不表示反复。"}, {"text": "亲手", "is_correct": false, "explanation": "语义：“亲手”强调亲自动手，不能用来修饰“说对不起”。"}, {"text": "一再", "is_correct": true, "explanation": "表示同一动作一次又一次地做，与“说对不起”相符。"}], "explanations": {"非常": "搭配：“非常”一般修饰形容词或心理动词，不与“说对不起”这样的言语动作搭配，句子不通。", "格外": "搭配：“格外”表示超出一般的程度，用来修饰“说对不起”不通，且不表示反复。", "亲手": "语义：“亲手”强调亲自动手，不能用来修饰“说对不起”。", "一再": "表示同一动作一次又一次地做，与“说对不起”相符。"}, "sentence_index": 0, "correct_answer": "一再"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我一再高兴，笑个不停。", "explanation": "这里应该用〈非常〉。一再修饰动作，不修饰形容词“高兴”。"}, {"text": "我一再看了一次表，他还是没来。", "explanation": "这里应该用〈只〉。一再表示反复多次，与“看了一次”矛盾。"}, {"text": "我一再在家待了一整天，哪儿也没去。", "explanation": "这里应该用〈一直〉。一再强调动作反复，描述持续的状态要用一直。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34fe6152-7971-4806-a660-cd4a4206742a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88697, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "根本", "is_correct": false, "explanation": "语义：“根本”多用于否定，与“请我去他家玩”的语义不通。"}, {"text": "十分", "is_correct": false, "explanation": "搭配：“十分”是程度副词，一般修饰形容词，不能修饰“请我去他家玩”这样的动作，句子不通。"}, {"text": "极其", "is_correct": false, "explanation": "搭配：“极其”表示程度极高，多修饰形容词，不能修饰“请”这一邀请动作，也不表示反复。"}, {"text": "一再", "is_correct": true, "explanation": "表示反复，与朋友多次邀请相符。"}], "explanations": {"根本": "语义：“根本”多用于否定，与“请我去他家玩”的语义不通。", "十分": "搭配：“十分”是程度副词，一般修饰形容词，不能修饰“请我去他家玩”这样的动作，句子不通。", "极其": "搭配：“极其”表示程度极高，多修饰形容词，不能修饰“请”这一邀请动作，也不表示反复。", "一再": "表示反复，与朋友多次邀请相符。"}, "sentence_index": 6, "correct_answer": "一再"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一再是个好学生。", "explanation": "这里应该用〈一向〉。一再强调动作反复，描述长期的状态要用一向。"}, {"text": "他一再拿到了博士学位。", "explanation": "这里应该用〈终于〉。一再表示反复多次，拿到博士学位只能发生一次。"}, {"text": "哥哥一再大学毕业了。", "explanation": "这里应该用〈已经〉。一再表示反复，大学毕业只发生一次。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34fe6152-7971-4806-a660-cd4a4206742a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88697, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我一再的提醒他别忘了。", "corrected_sentence": "我一再提醒他别忘了。", "error_description": "助词错误：“一再”修饰动词作状语，后面直接接动词，不用“的”。“一再的提醒他”把“提醒”误当成名词，结构不通，应说“一再提醒他”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34fe6152-7971-4806-a660-cd4a4206742a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88697, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他一再的提醒我带好钥匙。", "corrected_sentence": "他一再提醒我带好钥匙。", "error_description": "助词错误：“一再”修饰动词作状语，后面直接接动词，不用“的”。“一再的提醒我”把“提醒”误当成名词，结构不通，应说“一再提醒我”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34fe6152-7971-4806-a660-cd4a4206742a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
