INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88698, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "表示动作多次重复。", "primary_collocate": null, "pronunciation": "yī zài", "ipa": "i˥ tsaɪ˥˩", "syllable_count": 2, "sentences": [{"text": "小王一再迟到，经理很生气。", "target_word": "一再", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司一再改变计划，大家很累。", "target_word": "一再", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一再犯同样的错误。", "target_word": "一再", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子一再问：“我们到了吗？”", "target_word": "一再", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察一再劝他，他还是不听。", "target_word": "一再", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一再努力，终于成功了。", "target_word": "一再", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题一再出现，要认真想办法。", "target_word": "一再", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛一再推迟，大家都等急了。", "target_word": "一再", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她一再看手机，在等一个电话。", "target_word": "一再", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人一再感谢我们的帮助。", "target_word": "一再", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "表示动作或情况多次重复出现", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5345ed11-06b2-4130-89ce-bb50ae77b3fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88698, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "从不", "is_correct": false, "explanation": "语义：“从不”表示从来没有，与“经理很生气”的前后逻辑不通。"}, {"text": "亲自", "is_correct": false, "explanation": "语义：“亲自”指本人动手去做，“迟到”不能由人“亲自”完成，句子不通。"}, {"text": "亲手", "is_correct": false, "explanation": "语义：“亲手”强调亲自动手，不能修饰“迟到”，句子不通。"}, {"text": "一再", "is_correct": true, "explanation": "表示动作多次重复，与“迟到”的反复情况相符。"}], "explanations": {"从不": "语义：“从不”表示从来没有，与“经理很生气”的前后逻辑不通。", "亲自": "语义：“亲自”指本人动手去做，“迟到”不能由人“亲自”完成，句子不通。", "亲手": "语义：“亲手”强调亲自动手，不能修饰“迟到”，句子不通。", "一再": "表示动作多次重复，与“迟到”的反复情况相符。"}, "sentence_index": 0, "correct_answer": "一再"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "孩子一再开心，蹦个不停。", "explanation": "这里应该用〈非常〉。一再修饰动作，不修饰形容词“开心”。"}, {"text": "孩子一再问了一次：“我们到了吗？”", "explanation": "这里应该用〈只〉。一再表示反复，与“问了一次”矛盾。"}, {"text": "孩子一再在院子里玩了一整天，不肯进屋。", "explanation": "这里应该用〈一直〉。“玩了一整天”是持续的时段，应用“一直”；“一再”强调反复出现。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34fe6152-7971-4806-a660-cd4a4206742a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88698, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "亲自", "is_correct": false, "explanation": "语义：“亲自”需要有人执行，“问题”不能亲自出现。"}, {"text": "大声", "is_correct": false, "explanation": "语义：“大声”修饰声音，不能修饰“出现”。"}, {"text": "特别", "is_correct": false, "explanation": "搭配：“特别”多修饰形容词或“喜欢”“关心”等，不能修饰“出现”，句子不通。"}, {"text": "一再", "is_correct": true, "explanation": "表示问题反复出现，与句中“要认真想办法”相符。"}], "explanations": {"亲自": "语义：“亲自”需要有人执行，“问题”不能亲自出现。", "大声": "语义：“大声”修饰声音，不能修饰“出现”。", "特别": "搭配：“特别”多修饰形容词或“喜欢”“关心”等，不能修饰“出现”，句子不通。", "一再": "表示问题反复出现，与句中“要认真想办法”相符。"}, "sentence_index": 6, "correct_answer": "一再"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老人一再去世了。", "explanation": "这里应该用〈已经〉。一再表示反复，去世只发生一次。"}, {"text": "老人一再是个好人。", "explanation": "这里应该用〈一向〉。一再强调动作反复，描述长期的状态要用一向。"}, {"text": "这座桥一再建成了。", "explanation": "这里应该用〈终于〉。一再表示反复多次，桥建成只能发生一次。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34fe6152-7971-4806-a660-cd4a4206742a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88698, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈一再的提醒我注意身体。", "corrected_sentence": "妈妈一再提醒我注意身体。", "error_description": "助词错误：“一再”修饰动词作状语，后面直接接动词，不用“的”。“一再的提醒我”把“提醒”误当成名词，结构不通，应说“一再提醒我”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34fe6152-7971-4806-a660-cd4a4206742a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88698, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师一再的叮嘱我们早点回家。", "corrected_sentence": "老师一再叮嘱我们早点回家。", "error_description": "助词错误：“一再”修饰动词作状语，后面直接接动词，不用“的”。“一再的叮嘱我们”把“叮嘱”误当成名词，结构不通，应说“一再叮嘱我们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34fe6152-7971-4806-a660-cd4a4206742a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
