INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88701, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "恐龙是很久很久以前的大动物，现在已经没有了。", "primary_collocate": null, "pronunciation": "kǒng lóng", "ipa": "kʰʊŋ˨˩˦ lʊŋ˧˥", "syllable_count": 2, "sentences": [{"text": "我儿子最喜欢的动物是恐龙。", "target_word": "恐龙", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "恐龙很大，可是现在已经没有了。", "target_word": "恐龙", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们在公园里一起讲恐龙的故事。", "target_word": "恐龙", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她给弟弟买了一本恐龙的书。", "target_word": "恐龙", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电影里的恐龙跑得很快，吓了我一跳。", "target_word": "恐龙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他画了一只绿色的恐龙。", "target_word": "恐龙", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "商场门口有一只会动的大恐龙。", "target_word": "恐龙", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小朋友们跟着老师去看恐龙。", "target_word": "恐龙", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "周末我带女儿去博物馆，她最想看的是恐龙。", "target_word": "恐龙", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子问爸爸：“恐龙吃什么？”", "target_word": "恐龙", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "只", "label": "量词"}, {"form": "恐龙玩具", "label": "复合词"}, {"form": "恐龙展览", "label": "复合词"}, {"form": "恐龍", "label": "繁体"}], "register": "中性", "sense_fingerprint": "很久以前的大动物，现在没有了（日常义）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9f9ac96-b38b-4ebd-b1f9-bb290722a815') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88701, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "恐龙", "is_correct": true, "explanation": "正确：恐龙是很久以前的大动物，现在没有了，可以作为“最喜欢的动物”。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：电脑不是动物，不能作为“动物”的答案。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车不是动物，不能作为“动物”的答案。"}, {"text": "水果", "is_correct": false, "explanation": "语义：水果不是动物，与“动物”的类别不符。"}], "explanations": {"恐龙": "正确：恐龙是很久以前的大动物，现在没有了，可以作为“最喜欢的动物”。", "电脑": "语义：电脑不是动物，不能作为“动物”的答案。", "汽车": "语义：汽车不是动物，不能作为“动物”的答案。", "水果": "语义：水果不是动物，与“动物”的类别不符。"}, "sentence_index": 0, "correct_answer": "恐龙"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "窗台上摆着一盏恐龙。", "explanation": "这里应该用〈只〉。“盏”用于灯、茶杯等，恐龙是动物，应说“一只恐龙”。"}, {"text": "桌上放着一把恐龙。", "explanation": "这里应该用〈只〉。“把”用于有把手的器具，恐龙是动物，应说“一只恐龙”。"}, {"text": "他看见了一辆恐龙。", "explanation": "这里应该用〈只〉。“辆”用于车，恐龙是动物，应说“一只恐龙”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54251e93-d74e-4fa7-93dc-f81bfb7fcd91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88701, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "恐龙", "is_correct": true, "explanation": "正确：恐龙是会动的大动物，“商场门口有一只会动的大恐龙”符合语境。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不会动，与“会动的”矛盾。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：量词“只”一般不用于“桌子”，应说“张”。"}, {"text": "房子", "is_correct": false, "explanation": "语义：房子不会动，与“会动的”矛盾。"}], "explanations": {"恐龙": "正确：恐龙是会动的大动物，“商场门口有一只会动的大恐龙”符合语境。", "石头": "语义：石头不会动，与“会动的”矛盾。", "桌子": "搭配：量词“只”一般不用于“桌子”，应说“张”。", "房子": "语义：房子不会动，与“会动的”矛盾。"}, "sentence_index": 6, "correct_answer": "恐龙"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "爸爸说，恐龙是古代生物留下的痕迹。", "explanation": "这里应该用〈化石〉。化石是古代生物留下的痕迹，恐龙是生物本身，二者不能互换。"}, {"text": "港口停着一艘恐龙。", "explanation": "这里应该用〈只〉。“艘”用于船只，恐龙是动物，应说“一只恐龙”。"}, {"text": "客厅里放着一张恐龙。", "explanation": "这里应该用〈只〉。“张”用于平面的东西，恐龙是动物，应说“一只恐龙”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54251e93-d74e-4fa7-93dc-f81bfb7fcd91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88701, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是一只很大恐龙。", "corrected_sentence": "这是一只很大的恐龙。", "error_description": "错误：“很大恐龙”。修饰语“很大”与中心语“恐龙”之间漏了“的”，正确为“很大的恐龙”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54251e93-d74e-4fa7-93dc-f81bfb7fcd91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88701, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子指着一辆恐龙问：“它是什么？”", "corrected_sentence": "孩子指着一只恐龙问：“它是什么？”", "error_description": "错误：“一辆恐龙”。“辆”用于车，恐龙是动物，应用“只”，正确为“一只恐龙”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54251e93-d74e-4fa7-93dc-f81bfb7fcd91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
