INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88702, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "中生代时期生存的一类大型爬行动物，现已灭绝。", "primary_collocate": null, "pronunciation": "kǒng lóng", "ipa": "kʰʊŋ˨˩˦ lʊŋ˧˥", "syllable_count": 2, "sentences": [{"text": "恐龙生活在很久以前，现在已经没有了。", "target_word": "恐龙", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "博物馆里展出了一只很大的恐龙。", "target_word": "恐龙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家说，恐龙是六千多万年前灭绝的。", "target_word": "恐龙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地下埋着很多恐龙的骨头。", "target_word": "恐龙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有的恐龙吃草，有的恐龙吃肉。", "target_word": "恐龙", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这只恐龙的脖子特别长。", "target_word": "恐龙", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小明在书上看到了一只恐龙的照片。", "target_word": "恐龙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家在山里找到了恐龙的蛋。", "target_word": "恐龙", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "恐龙为什么会灭绝，人们还在研究。", "target_word": "恐龙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中生代的恐龙有的很大，有的很小。", "target_word": "恐龙", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "只", "label": "量词"}, {"form": "恐龙化石", "label": "复合词"}, {"form": "恐龙蛋", "label": "复合词"}, {"form": "恐龍", "label": "繁体"}], "register": "中性", "sense_fingerprint": "中生代的大型爬行动物，已灭绝（科学义）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9f9ac96-b38b-4ebd-b1f9-bb290722a815') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88702, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "恐龙", "is_correct": true, "explanation": "正确：恐龙是中生代的爬行动物，只在很久以前生存，与“现在已经没有了”相符。"}, {"text": "人类", "is_correct": false, "explanation": "语义：人类至今仍然存在，与“现在已经没有了”矛盾。"}, {"text": "电脑", "is_correct": false, "explanation": "搭配：“生活”的主语须是生物，“电脑”不能说“生活”。"}, {"text": "大象", "is_correct": false, "explanation": "语义：大象至今仍然活着，与“现在已经没有了”矛盾。"}], "explanations": {"恐龙": "正确：恐龙是中生代的爬行动物，只在很久以前生存，与“现在已经没有了”相符。", "人类": "语义：人类至今仍然存在，与“现在已经没有了”矛盾。", "电脑": "搭配：“生活”的主语须是生物，“电脑”不能说“生活”。", "大象": "语义：大象至今仍然活着，与“现在已经没有了”矛盾。"}, "sentence_index": 0, "correct_answer": "恐龙"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "花园里有一朵恐龙。", "explanation": "这里应该用〈只〉。“朵”用于花、云等，恐龙是动物，应说“一只恐龙”。"}, {"text": "路边停着一辆恐龙。", "explanation": "这里应该用〈只〉。“辆”用于车，恐龙是动物，应说“一只恐龙”。"}, {"text": "公园里有一棵恐龙。", "explanation": "这里应该用〈只〉。“棵”用于树木和植物，恐龙是动物，应说“一只恐龙”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54251e93-d74e-4fa7-93dc-f81bfb7fcd91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88702, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "恐龙", "is_correct": true, "explanation": "正确：“一只恐龙的照片”符合语境，“只”用于动物，书上可以有恐龙的图片。"}, {"text": "梦", "is_correct": false, "explanation": "语义：梦无法被拍成照片，与“照片”的语义不符。"}, {"text": "电脑", "is_correct": false, "explanation": "搭配：量词“只”一般用于动物，不说“一只电脑”。"}, {"text": "吉他", "is_correct": false, "explanation": "搭配：乐器的量词用“把”，不说“一只吉他”。"}], "explanations": {"恐龙": "正确：“一只恐龙的照片”符合语境，“只”用于动物，书上可以有恐龙的图片。", "梦": "语义：梦无法被拍成照片，与“照片”的语义不符。", "电脑": "搭配：量词“只”一般用于动物，不说“一只电脑”。", "吉他": "搭配：乐器的量词用“把”，不说“一只吉他”。"}, "sentence_index": 6, "correct_answer": "恐龙"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "恐龙是古代生物留下的痕迹。", "explanation": "这里应该用〈化石〉。化石是古代生物留下的痕迹，恐龙是生物本身，二者不能互换。"}, {"text": "天上挂着一颗恐龙。", "explanation": "这里应该用〈只〉。“颗”用于星星、珠子等圆粒状的东西，恐龙是动物，应说“一只恐龙”。"}, {"text": "客厅里放着一张恐龙。", "explanation": "这里应该用〈只〉。“张”用于平面的东西，恐龙是动物，应说“一只恐龙”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54251e93-d74e-4fa7-93dc-f81bfb7fcd91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88702, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "书上画着一恐龙，它的脖子很长。", "corrected_sentence": "书上画着一只恐龙，它的脖子很长。", "error_description": "错误：“一恐龙”。数词与名词之间漏了量词，动物用“只”，正确为“一只恐龙”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54251e93-d74e-4fa7-93dc-f81bfb7fcd91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88702, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我在博物馆看见了一恐龙。", "corrected_sentence": "我在博物馆看见了一只恐龙。", "error_description": "错误：“一恐龙”。数词和名词之间少了量词，动物用“只”，正确为“一只恐龙”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54251e93-d74e-4fa7-93dc-f81bfb7fcd91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
