INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88703, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一部分是整个东西里的一小块。", "primary_collocate": null, "pronunciation": "yí bù fèn", "ipa": "i˧˥ pu˥˩ fən˥˩", "syllable_count": 3, "sentences": [{"text": "我把蛋糕的一部分给了弟弟。", "target_word": "一部分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他只吃了一部分饭。", "target_word": "一部分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书我只看了一部分。", "target_word": "一部分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教室里一部分灯坏了。", "target_word": "一部分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一部分学生已经回家了。", "target_word": "一部分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我花了一部分钱买书。", "target_word": "一部分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "院子的一部分种了花。", "target_word": "一部分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把工资的一部分存起来了。", "target_word": "一部分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天的作业，我做完了一部分。", "target_word": "一部分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一部分人喜欢喝咖啡。", "target_word": "一部分", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一小部分", "label": "复合"}, {"form": "大部分", "label": "复合"}], "register": "中性", "sense_fingerprint": "整个东西里的一小块", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34fd70d5-5710-4b08-aede-8a64d3f83331') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88703, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "一部分", "is_correct": true, "explanation": "正确：“一部分”指蛋糕中的一块，可以分给弟弟。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不是蛋糕的一部分，无法分给弟弟。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“给”要求可以转让的具体东西，“颜色”不能说“给了弟弟”。"}, {"text": "身体", "is_correct": false, "explanation": "语义：身体是人或动物的躯体，蛋糕没有身体，不能分给弟弟。"}], "explanations": {"一部分": "正确：“一部分”指蛋糕中的一块，可以分给弟弟。", "桌子": "语义：桌子不是蛋糕的一部分，无法分给弟弟。", "颜色": "搭配：“给”要求可以转让的具体东西，“颜色”不能说“给了弟弟”。", "身体": "语义：身体是人或动物的躯体，蛋糕没有身体，不能分给弟弟。"}, "sentence_index": 0, "correct_answer": "一部分"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的一部分父亲在北京工作。", "explanation": "这里应该用〈一位〉。“一部分”指整体中的一小块，父亲是一个人，不能分成部分，所以不能说“一部分父亲”。"}, {"text": "我坐车一部分就到了学校。", "explanation": "这里应该用〈几分钟〉。“一部分”不能单独作为时间量（须说“一部分时间”），“坐车一部分就到了学校”也不自然。"}, {"text": "这间房子的一部分就是它的全体。", "explanation": "这里应删去“一部分”。“一部分”指整体中的一块，与“它的全体”矛盾，不能等同于整体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ebf6d0a-6a0d-49ed-ba1e-53a310e30a00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88703, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "一部分", "is_correct": true, "explanation": "正确：“一部分”指院子的一块，可以用来种花。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不能被种植，“院子的石头种了花”语义不通。"}, {"text": "狗", "is_correct": false, "explanation": "语义：狗是动物，不能被种花，句子语义不通。"}, {"text": "大门", "is_correct": false, "explanation": "搭配：“种”后要接植物或可种植的地方，“大门”不能用来种花。"}], "explanations": {"一部分": "正确：“一部分”指院子的一块，可以用来种花。", "石头": "语义：石头不能被种植，“院子的石头种了花”语义不通。", "狗": "语义：狗是动物，不能被种花，句子语义不通。", "大门": "搭配：“种”后要接植物或可种植的地方，“大门”不能用来种花。"}, "sentence_index": 6, "correct_answer": "一部分"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我等了一部分就走了。", "explanation": "这里应该用〈一会儿〉。“一部分”不能单独作为等待的时间量（须说“等了一部分时间”），句子不自然。"}, {"text": "我的一部分妈妈是老师。", "explanation": "这里应该用〈妈妈〉（删去“一部分”）。“一部分”指整体中的一块，妈妈只有一个人，不能分成部分。"}, {"text": "我一部分就吃光了这碗饭。", "explanation": "这里应删去“一部分”。“一部分”指整体中的一块，与“吃光”（整碗吃完）矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ebf6d0a-6a0d-49ed-ba1e-53a310e30a00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88703, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把工资的一部分个寄回了老家。", "corrected_sentence": "他把工资的一部分寄回了老家。", "error_description": "错误：“部分”是名词，“一部分”后不能直接加量词“个”。正确应删去“个”，即“他把工资的一部分寄回了老家”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ebf6d0a-6a0d-49ed-ba1e-53a310e30a00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88703, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一部分个学生喜欢打篮球。", "corrected_sentence": "一部分学生喜欢打篮球。", "error_description": "错误：“一部分”后面不能直接加量词“个”。正确应为“一部分学生”。“一部分”本身已表示整体中的一块，后面的名词不需要量词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ebf6d0a-6a0d-49ed-ba1e-53a310e30a00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88704, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "整体", "is_correct": true, "explanation": "正确：“整体”与“组成部分”相对，是“一部分”的反义词。"}, {"text": "窗帘", "is_correct": false, "explanation": "窗帘与“一部分”没有反义关系。"}, {"text": "课本", "is_correct": false, "explanation": "课本与“一部分”没有反义关系。"}, {"text": "池塘", "is_correct": false, "explanation": "池塘与“一部分”没有反义关系。"}], "correct_answer": "整体", "explanations": {"整体": "正确：“整体”与“组成部分”相对，是“一部分”的反义词。", "窗帘": "窗帘与“一部分”没有反义关系。", "课本": "课本与“一部分”没有反义关系。", "池塘": "池塘与“一部分”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ebf6d0a-6a0d-49ed-ba1e-53a310e30a00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88704, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "整体", "is_correct": true, "explanation": "正确：“整体”与“组成部分”相对，是“一部分”的反义词。"}, {"text": "书架", "is_correct": false, "explanation": "书架与“一部分”没有反义关系。"}, {"text": "雨伞", "is_correct": false, "explanation": "雨伞与“一部分”没有反义关系。"}, {"text": "河流", "is_correct": false, "explanation": "河流与“一部分”没有反义关系。"}], "correct_answer": "整体", "explanations": {"整体": "正确：“整体”与“组成部分”相对，是“一部分”的反义词。", "书架": "书架与“一部分”没有反义关系。", "雨伞": "雨伞与“一部分”没有反义关系。", "河流": "河流与“一部分”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ebf6d0a-6a0d-49ed-ba1e-53a310e30a00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88704, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "整体中的某一个组成部分。", "primary_collocate": null, "pronunciation": "yí bù fèn", "ipa": "i˧˥ pu˥˩ fən˥˩", "syllable_count": 3, "sentences": [{"text": "音乐是我生活的一部分。", "target_word": "一部分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长城是中国历史的一部分。", "target_word": "一部分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只是工作的一部分。", "target_word": "一部分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "运动已经成了他生活的一部分。", "target_word": "一部分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个故事是电影的一部分。", "target_word": "一部分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手臂是身体的一部分。", "target_word": "一部分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市是我们国家的一部分。", "target_word": "一部分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友是我生活中重要的一部分。", "target_word": "一部分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这道题是考试的一部分。", "target_word": "一部分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "猫早就成了我们家的一部分。", "target_word": "一部分", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一小部分", "label": "复合"}, {"form": "大部分", "label": "复合"}], "register": "中性", "sense_fingerprint": "整体中的某个组成部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34fd70d5-5710-4b08-aede-8a64d3f83331') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88704, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "一部分", "is_correct": true, "explanation": "正确：“一部分”指生活中的一部分，音乐正是其中之一。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：音乐不是桌子，“音乐是我生活的桌子”语义不通。"}, {"text": "数字", "is_correct": false, "explanation": "语义：数字不是音乐所属的组成部分，“音乐是我生活的数字”语义不通。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车是交通工具，不能作为音乐所属的组成部分。"}], "explanations": {"一部分": "正确：“一部分”指生活中的一部分，音乐正是其中之一。", "桌子": "语义：音乐不是桌子，“音乐是我生活的桌子”语义不通。", "数字": "语义：数字不是音乐所属的组成部分，“音乐是我生活的数字”语义不通。", "汽车": "语义：汽车是交通工具，不能作为音乐所属的组成部分。"}, "sentence_index": 0, "correct_answer": "一部分"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的一部分姐姐在北京工作。", "explanation": "这里应该用〈一位〉。“一部分”指整体中的一块，姐姐是一个人，不能分成部分，不能说“一部分姐姐”。"}, {"text": "这座山的一部分就是整座山。", "explanation": "这里应该用〈全部〉。“一部分”只指整体中的一块，不能等于整座山。"}, {"text": "一部分生活是音乐，所以音乐就是我的全部生活。", "explanation": "“一部分”只指整体中的一个组成部分，不能由此推出它就是“全部”，前后矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ebf6d0a-6a0d-49ed-ba1e-53a310e30a00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88704, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "一部分", "is_correct": true, "explanation": "正确：“一部分”指国家中的一部分，城市是其中之一。"}, {"text": "鱼", "is_correct": false, "explanation": "语义：鱼不能是城市，“这个城市是我们国家的鱼”语义不通。"}, {"text": "钢笔", "is_correct": false, "explanation": "语义：钢笔不是城市的组成部分，句子语义不通。"}, {"text": "人", "is_correct": false, "explanation": "搭配：“是……的一部分”后面要接地区或区域，“人”不能用来指城市的组成。"}], "explanations": {"一部分": "正确：“一部分”指国家中的一部分，城市是其中之一。", "鱼": "语义：鱼不能是城市，“这个城市是我们国家的鱼”语义不通。", "钢笔": "语义：钢笔不是城市的组成部分，句子语义不通。", "人": "搭配：“是……的一部分”后面要接地区或区域，“人”不能用来指城市的组成。"}, "sentence_index": 6, "correct_answer": "一部分"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "猫早就成了我们家的一部分，也就是整个家。", "explanation": "这里应该用〈全部〉。“一部分”指整体中的一块，与“也就是整个家”矛盾。"}, {"text": "猫早就成了我们家的一部分时间。", "explanation": "“一部分时间”指时间的一段，猫不是时间，不能这样说。"}, {"text": "猫早就成了我们家的一部分钱。", "explanation": "“一部分钱”指钱款的一部分，猫不是钱，不能这样说。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ebf6d0a-6a0d-49ed-ba1e-53a310e30a00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88704, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次旅行是我人生的一部分个。", "corrected_sentence": "这次旅行是我人生的一部分。", "error_description": "错误：“一部分”后不能再加量词“个”。正确应删去“个”，即“这次旅行是我人生的一部分”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ebf6d0a-6a0d-49ed-ba1e-53a310e30a00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88704, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们班一部分个同学喜欢踢足球。", "corrected_sentence": "我们班一部分同学喜欢踢足球。", "error_description": "错误：“一部分”后面不能直接加量词“个”。正确应为“我们班一部分同学”。“一部分”已表示整体中的一块，后面的名词不需要量词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ebf6d0a-6a0d-49ed-ba1e-53a310e30a00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
