INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88705, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一身是从头到脚的整个身体，也可以是一套衣服。", "primary_collocate": null, "pronunciation": "yī shēn", "ipa": "i˥ ʂən˥", "syllable_count": 2, "sentences": [{"text": "跑完步，他一身都是汗。", "target_word": "一身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从河里爬上来，一身是水。", "target_word": "一身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "刚干完活，我一身都是泥，先去洗澡。", "target_word": "一身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天他穿了一身黑色的西装。", "target_word": "一身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她买了一身新衣服，准备过年穿。", "target_word": "一身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "摔了一跤，他一身都疼。", "target_word": "一身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一身白衣，站在门口。", "target_word": "一身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨太大了，我回家时一身都湿了。", "target_word": "一身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子玩了一天，一身脏兮兮的。", "target_word": "一身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雪了，他一身雪花走进屋来。", "target_word": "一身", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "从头到脚的整个身体；也指一套衣服", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9bc0fff-f698-48aa-a31e-eceacc41eba5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88705, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "一身", "is_correct": true, "explanation": "一身：全身，或一套衣服，是正确答案。"}, {"text": "医生", "is_correct": false, "explanation": "shēng（后鼻音 -ng）与 shēn（-n）韵母不同，意思是医生。"}, {"text": "一审", "is_correct": false, "explanation": "shěn（第三声）与 shēn（第一声）声调不同，意思是第一次审判。"}, {"text": "衣衫", "is_correct": false, "explanation": "shān（-an）与 shēn（-en）韵母不同，意思是衣服。"}], "explanations": {"一身": "一身：全身，或一套衣服，是正确答案。", "医生": "shēng（后鼻音 -ng）与 shēn（-n）韵母不同，意思是医生。", "一审": "shěn（第三声）与 shēn（第一声）声调不同，意思是第一次审判。", "衣衫": "shān（-an）与 shēn（-en）韵母不同，意思是衣服。"}, "sentence_index": null, "correct_answer": "一身"}, "level_3": {"options": [{"text": "一身", "is_correct": true, "explanation": "正确：“一身”指全身，“他一身都是汗”。"}, {"text": "教室", "is_correct": false, "explanation": "语义：汗只能附着在人或衣物上，教室不会出汗。"}, {"text": "黑板", "is_correct": false, "explanation": "语义：黑板是物体，不会出汗。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包不会出汗，汗不能附着于书包。"}], "explanations": {"一身": "正确：“一身”指全身，“他一身都是汗”。", "教室": "语义：汗只能附着在人或衣物上，教室不会出汗。", "黑板": "语义：黑板是物体，不会出汗。", "书包": "语义：书包不会出汗，汗不能附着于书包。"}, "sentence_index": 0, "correct_answer": "一身"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我昨天在书店买了一身书。", "explanation": "这里不能用〈一身〉量书。“一身”只用于一整套衣服或全身，书应该用〈本〉。"}, {"text": "他提出了一身理论，很受大家欢迎。", "explanation": "这里应该用〈一套〉。“一身”只能量衣服或全身，理论要说〈一套〉。"}, {"text": "她买了一身新鞋，准备明天穿。", "explanation": "这里应该用〈一双〉。“一身”指一整套衣服或全身，鞋要成双计算，不能用来量鞋。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b7ebae2-2f65-4161-84f1-edbb55d44851') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88705, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "一身", "is_correct": true, "explanation": "一身：全身，或一套衣服，是正确答案。"}, {"text": "一生", "is_correct": false, "explanation": "shēng（-ng）与 shēn（-n）韵母不同，意思是一辈子。"}, {"text": "以身", "is_correct": false, "explanation": "yǐ（第三声）与 yī（第一声）声调不同，意思是用自己的身体，如“以身作则”。"}, {"text": "一神", "is_correct": false, "explanation": "shén（第二声）与 shēn（第一声）声调不同，意思是一个神，如“一神教”。"}], "explanations": {"一身": "一身：全身，或一套衣服，是正确答案。", "一生": "shēng（-ng）与 shēn（-n）韵母不同，意思是一辈子。", "以身": "yǐ（第三声）与 yī（第一声）声调不同，意思是用自己的身体，如“以身作则”。", "一神": "shén（第二声）与 shēn（第一声）声调不同，意思是一个神，如“一神教”。"}, "sentence_index": null, "correct_answer": "一身"}, "level_3": {"options": [{"text": "一身", "is_correct": true, "explanation": "正确：“一身”指全身，“一身白衣”是穿着一身白色衣服。"}, {"text": "一脸", "is_correct": false, "explanation": "搭配：“一脸”多用于表情或脸上的东西，不能修饰白衣。"}, {"text": "操场", "is_correct": false, "explanation": "语义：白衣是衣服，操场不能被穿在身上。"}, {"text": "课本", "is_correct": false, "explanation": "语义：课本不是衣物，不能与“白衣”搭配。"}], "explanations": {"一身": "正确：“一身”指全身，“一身白衣”是穿着一身白色衣服。", "一脸": "搭配：“一脸”多用于表情或脸上的东西，不能修饰白衣。", "操场": "语义：白衣是衣服，操场不能被穿在身上。", "课本": "语义：课本不是衣物，不能与“白衣”搭配。"}, "sentence_index": 6, "correct_answer": "一身"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他买了一身电脑，放在桌子上。", "explanation": "这里应该用〈一台〉。电脑用〈台〉，“一身”只量衣服或全身。"}, {"text": "他们昨天开了一身会议，讨论了很久。", "explanation": "这里应该用〈一场〉。“一身”指一整套衣服或全身，会议要用〈场〉计算，不能用来量会议。"}, {"text": "我写了一身信给朋友。", "explanation": "这里应该用〈一封〉。“一身”指一整套衣服或全身，信要用〈封〉计算，不能用来量信。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b7ebae2-2f65-4161-84f1-edbb55d44851') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88705, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在泥地里踢球，一身都泥。", "corrected_sentence": "他在泥地里踢球，一身都是泥。", "error_description": "错误：“一身都是泥”中的“是”被省略，写成“一身都泥”不成立，应说“一身都是泥”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b7ebae2-2f65-4161-84f1-edbb55d44851') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88705, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他穿了过一身白衣，站在门口。", "corrected_sentence": "他穿着一身白衣，站在门口。", "error_description": "体标错误：“了”与“过”不能同时使用，“穿了过”不成立；描述“站在门口”的持续状态要用“着”，应说“穿着一身白衣”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b7ebae2-2f65-4161-84f1-edbb55d44851') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
