INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88706, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "全身；也指一套衣服。", "primary_collocate": null, "pronunciation": "yī shēn", "ipa": "i˥ ʂən˥", "syllable_count": 2, "sentences": [{"text": "他换上一身干净的衣服。", "target_word": "一身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "参加面试，她穿了一身正式的套装。", "target_word": "一身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天到了，妈妈给我做了一身棉衣。", "target_word": "一身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸一身酒气地回到家。", "target_word": "一身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他骑了一天车，一身都是灰。", "target_word": "一身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "演员穿着一身红衣服，站在台上。", "target_word": "一身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到这个消息，我吓出了一身冷汗。", "target_word": "一身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这一身衣服是新买的，你觉得怎么样？", "target_word": "一身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他练了很久，一身肌肉很结实。", "target_word": "一身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厨师一身白色工作服，站在厨房里。", "target_word": "一身", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "全身上下；也指一整套衣服", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9bc0fff-f698-48aa-a31e-eceacc41eba5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88706, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "一身", "is_correct": true, "explanation": "一身：全身，或一套衣服，是正确答案。"}, {"text": "一生", "is_correct": false, "explanation": "shēng（-ng）与 shēn（-n）韵母不同，意思是一辈子。"}, {"text": "以身", "is_correct": false, "explanation": "yǐ（第三声）与 yī（第一声）声调不同，意思是用自己的身体，如“以身作则”。"}, {"text": "一神", "is_correct": false, "explanation": "shén（第二声）与 shēn（第一声）声调不同，意思是一个神，如“一神教”。"}, {"text": "一山", "is_correct": false, "explanation": "shān（-an）与 shēn（-en）韵母不同，意思是一座山。"}], "explanations": {"一身": "一身：全身，或一套衣服，是正确答案。", "一生": "shēng（-ng）与 shēn（-n）韵母不同，意思是一辈子。", "以身": "yǐ（第三声）与 yī（第一声）声调不同，意思是用自己的身体，如“以身作则”。", "一神": "shén（第二声）与 shēn（第一声）声调不同，意思是一个神，如“一神教”。", "一山": "shān（-an）与 shēn（-en）韵母不同，意思是一座山。"}, "sentence_index": null, "correct_answer": "一身"}, "level_3": {"options": [{"text": "一身", "is_correct": true, "explanation": "正确：“一身”指一整套衣服，“他换上一身干净的衣服”。"}, {"text": "一双", "is_correct": false, "explanation": "搭配：“双”只用于成对的东西，不能用来量衣服。"}, {"text": "一颗", "is_correct": false, "explanation": "搭配：“颗”用于粒状的东西，不能用来量衣服。"}, {"text": "一滴", "is_correct": false, "explanation": "语义：“滴”指液体的量，衣服不是液体。"}], "explanations": {"一身": "正确：“一身”指一整套衣服，“他换上一身干净的衣服”。", "一双": "搭配：“双”只用于成对的东西，不能用来量衣服。", "一颗": "搭配：“颗”用于粒状的东西，不能用来量衣服。", "一滴": "语义：“滴”指液体的量，衣服不是液体。"}, "sentence_index": 0, "correct_answer": "一身"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我昨天买了一身苹果。", "explanation": "这里不能用〈一身〉量苹果。苹果应该用〈个〉，“一身”只用于衣服或全身。"}, {"text": "他们买了一身家具，搬进了新家。", "explanation": "这里应该用〈一套〉。家具按套计算，“一身”只用于衣服或全身。"}, {"text": "他吃了一身饭，就去上班了。", "explanation": "这里应该用〈一顿〉。“一身”指一整套衣服或全身，饭要按餐数计算，不能用来量饭。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b7ebae2-2f65-4161-84f1-edbb55d44851') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88706, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "一身", "is_correct": true, "explanation": "一身：全身，或一套衣服，是正确答案。"}, {"text": "医生", "is_correct": false, "explanation": "shēng（-ng）与 shēn（-n）韵母不同，意思是医生。"}, {"text": "一审", "is_correct": false, "explanation": "shěn（第三声）与 shēn（第一声）声调不同，意思是第一次审判。"}, {"text": "衣衫", "is_correct": false, "explanation": "shān（-an）与 shēn（-en）韵母不同，意思是衣服。"}], "explanations": {"一身": "一身：全身，或一套衣服，是正确答案。", "医生": "shēng（-ng）与 shēn（-n）韵母不同，意思是医生。", "一审": "shěn（第三声）与 shēn（第一声）声调不同，意思是第一次审判。", "衣衫": "shān（-an）与 shēn（-en）韵母不同，意思是衣服。"}, "sentence_index": null, "correct_answer": "一身"}, "level_3": {"options": [{"text": "一身", "is_correct": true, "explanation": "正确：“一身冷汗”指全身出了很多冷汗。"}, {"text": "一本", "is_correct": false, "explanation": "搭配：“本”用于书册，不能用来量汗。"}, {"text": "一封", "is_correct": false, "explanation": "搭配：“封”用于信件，不能用来量汗。"}, {"text": "一座", "is_correct": false, "explanation": "语义：“座”指山、楼等大型固定之物，汗不属于这类事物。"}], "explanations": {"一身": "正确：“一身冷汗”指全身出了很多冷汗。", "一本": "搭配：“本”用于书册，不能用来量汗。", "一封": "搭配：“封”用于信件，不能用来量汗。", "一座": "语义：“座”指山、楼等大型固定之物，汗不属于这类事物。"}, "sentence_index": 6, "correct_answer": "一身"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们在草原上看到一身草地。", "explanation": "这里应该用〈一片〉。“一身”指一整套衣服或全身，草地要用〈片〉计算，不能用来量草地。"}, {"text": "他吃了一身蛋糕，很开心。", "explanation": "这里应该用〈一块〉。“一身”指一整套衣服或全身，蛋糕要按块计算，不能用来量蛋糕。"}, {"text": "路边停着一身汽车。", "explanation": "这里应该用〈一辆〉。“一身”指一整套衣服或全身，汽车要用〈辆〉计算，不能用来量汽车。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b7ebae2-2f65-4161-84f1-edbb55d44851') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88706, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他修完屋顶下来，一身都灰。", "corrected_sentence": "他修完屋顶下来，一身都是灰。", "error_description": "错误：“一身都是灰”中的“是”被省略，写成“一身都灰”不成立，应说“一身都是灰”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b7ebae2-2f65-4161-84f1-edbb55d44851') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88706, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他刚洗完澡，一身都香皂味。", "corrected_sentence": "他刚洗完澡，一身都是香皂味。", "error_description": "错误：“一身都”后缺少判断词“是”，应说“一身都是香皂味”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b7ebae2-2f65-4161-84f1-edbb55d44851') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
