INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88707, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "印象是见过、听过的事物留在脑子里的样子。", "primary_collocate": null, "pronunciation": "yìn xiàng", "ipa": "in˥˩ ɕiɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这座城市给我留下了很好的印象。", "target_word": "印象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我对他的第一印象不错。", "target_word": "印象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小时候的很多事，我已经没有印象了。", "target_word": "印象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭店给客人的印象很干净。", "target_word": "印象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你对这个人还有印象吗？", "target_word": "印象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她给老师留下了好印象。", "target_word": "印象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "第一次来北京，我对长城印象最深。", "target_word": "印象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我对这个名字没有一点印象。", "target_word": "印象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的话给我的印象很深。", "target_word": "印象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影给大家留下了深刻的印象。", "target_word": "印象", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "名词：见过听过的事物留在脑中的样子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '525423d5-7b31-4df5-a976-f002812aab26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88707, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "印象", "is_correct": true, "explanation": "印象 yìn xiàng，指见过、听过的事物留在脑子里的样子。"}, {"text": "音像", "is_correct": false, "explanation": "yīn（第一声）与 yìn（第四声）声调不同，“音像”指声音和图像，意思不同。"}, {"text": "引向", "is_correct": false, "explanation": "yǐn（第三声）与 yìn（第四声）声调不同，“引向”指把人或事物引到某个方向。"}, {"text": "映像", "is_correct": false, "explanation": "yìng（第四声）与 yìn（第四声）韵母不同（ing 与 in），“映像”指映在屏幕或水面上的像。"}], "explanations": {"印象": "印象 yìn xiàng，指见过、听过的事物留在脑子里的样子。", "音像": "yīn（第一声）与 yìn（第四声）声调不同，“音像”指声音和图像，意思不同。", "引向": "yǐn（第三声）与 yìn（第四声）声调不同，“引向”指把人或事物引到某个方向。", "映像": "yìng（第四声）与 yìn（第四声）韵母不同（ing 与 in），“映像”指映在屏幕或水面上的像。"}, "sentence_index": null, "correct_answer": "印象"}, "level_3": {"options": [{"text": "印象", "is_correct": true, "explanation": "印象：与“留下”搭配，指给人留下的印象。"}, {"text": "体重", "is_correct": false, "explanation": "语义：“体重”指身体的重量，不能说“留下了很好的体重”。"}, {"text": "价格", "is_correct": false, "explanation": "语义：“价格”指商品的钱数，不能说“留下了很好的价格”。"}, {"text": "温度", "is_correct": false, "explanation": "语义：“温度”指冷热的程度，不能说“留下了很好的温度”。"}], "explanations": {"印象": "印象：与“留下”搭配，指给人留下的印象。", "体重": "语义：“体重”指身体的重量，不能说“留下了很好的体重”。", "价格": "语义：“价格”指商品的钱数，不能说“留下了很好的价格”。", "温度": "语义：“温度”指冷热的程度，不能说“留下了很好的温度”。"}, "sentence_index": 0, "correct_answer": "印象"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的头印象很疼。", "explanation": "这里应该用〈感觉〉。印象指留在脑中的样子，不能用来说身体的疼痛，身体的感受要用“感觉”。"}, {"text": "这块地毯上留下了一个深深的印象。", "explanation": "这里应该用〈印记〉。印象只指留在脑中的样子，不能指物体上留下的痕迹，表示痕迹要用“印记”。"}, {"text": "这个印象很好听。", "explanation": "这里应该用〈声音〉。印象指留在脑中的样子，不能说好听，好听用于声音。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b01eabee-5f23-40fb-bd13-a6b2189c2450') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88707, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "印象", "is_correct": true, "explanation": "印象 yìn xiàng，指见过、听过的事物留在脑子里的样子。"}, {"text": "进项", "is_correct": false, "explanation": "jìn 与 yìn 只差声母（j 与零声母），声调相同（第四声），“进项”指收入、进账。"}, {"text": "影像", "is_correct": false, "explanation": "yǐng（第三声）与 yìn（第四声）声调、韵母都不同，“影像”指图像、画面。"}, {"text": "音响", "is_correct": false, "explanation": "yīn 与 yìn 声调不同，xiǎng 与 xiàng 声调也不同，“音响”指声音设备或声音效果。"}], "explanations": {"印象": "印象 yìn xiàng，指见过、听过的事物留在脑子里的样子。", "进项": "jìn 与 yìn 只差声母（j 与零声母），声调相同（第四声），“进项”指收入、进账。", "影像": "yǐng（第三声）与 yìn（第四声）声调、韵母都不同，“影像”指图像、画面。", "音响": "yīn 与 yìn 声调不同，xiǎng 与 xiàng 声调也不同，“音响”指声音设备或声音效果。"}, "sentence_index": null, "correct_answer": "印象"}, "level_3": {"options": [{"text": "印象", "is_correct": true, "explanation": "印象：与“对……最深”搭配，指对某事物的印象很深。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：“对长城”后面不能接“脾气”，脾气只用于人。"}, {"text": "价格", "is_correct": false, "explanation": "语义：“价格”指钱数，不能说“我对长城价格最深”。"}, {"text": "身材", "is_correct": false, "explanation": "语义：“身材”指人的体形，不能用来说长城的身材。"}], "explanations": {"印象": "印象：与“对……最深”搭配，指对某事物的印象很深。", "脾气": "搭配：“对长城”后面不能接“脾气”，脾气只用于人。", "价格": "语义：“价格”指钱数，不能说“我对长城价格最深”。", "身材": "语义：“身材”指人的体形，不能用来说长城的身材。"}, "sentence_index": 6, "correct_answer": "印象"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台电脑的印象很硬。", "explanation": "这里应该用〈硬度〉。印象指留在脑中的样子，不能说软硬，表示软硬要用“硬度”。"}, {"text": "这辆车的印象很快。", "explanation": "这里应该用〈速度〉。印象没有快慢，表示快慢要用“速度”。"}, {"text": "这条路的印象很远。", "explanation": "这里应该用〈距离〉。印象没有远近，表示远近要用“距离”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b01eabee-5f23-40fb-bd13-a6b2189c2450') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88707, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那位老师给我留下了一张好印象。", "corrected_sentence": "那位老师给我留下了一个好印象。", "error_description": "量词错误：“印象”应该用量词“个”，不能用“张”（“张”多用于纸、桌子等平面的东西）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b01eabee-5f23-40fb-bd13-a6b2189c2450') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88707, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他给我留下了一台很深的印象。", "corrected_sentence": "他给我留下了一个很深的印象。", "error_description": "量词错误：“印象”应该用量词“个”，“台”用于机器、电器，不能用于印象。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b01eabee-5f23-40fb-bd13-a6b2189c2450') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
