INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88709, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "感冒是人生了病，会流鼻涕、咳嗽。", "primary_collocate": null, "pronunciation": "gǎn mào", "ipa": "kan˨˩ mɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "我昨天感冒了，今天没上班。", "target_word": "感冒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他感冒了，一直咳嗽。", "target_word": "感冒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气太冷，小心感冒。", "target_word": "感冒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子感冒了，妈妈很着急。", "target_word": "感冒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我感冒过一次，很难受。", "target_word": "感冒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她感冒了，所以不想吃饭。", "target_word": "感冒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们都感冒了，教室里很安静。", "target_word": "感冒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他穿得太少，才感冒的。", "target_word": "感冒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我最近常常感冒，要多运动。", "target_word": "感冒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟感冒了，鼻子不通气。", "target_word": "感冒", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "感冒了", "label": "体标"}, {"form": "感冒过", "label": "体标"}], "register": "中性", "sense_fingerprint": "人得了感冒，流鼻涕咳嗽", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3763d68d-fe1a-4cec-95df-e92983c5cf23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88709, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "下雨", "is_correct": false, "explanation": "语义：“下雨”的主语只能是天气，不能说“我昨天下雨了”。"}, {"text": "感冒", "is_correct": true, "explanation": "感冒：生病，与“今天没上班”的原因相符。"}, {"text": "罹患", "is_correct": false, "explanation": "配价：“罹患”后面必须带疾病作宾语，“我昨天罹患了”说不完整。"}, {"text": "感激", "is_correct": false, "explanation": "配价：“感激”需要带对象，如“感激某人”，单独说“感激了”不完整。"}], "explanations": {"下雨": "语义：“下雨”的主语只能是天气，不能说“我昨天下雨了”。", "感冒": "感冒：生病，与“今天没上班”的原因相符。", "罹患": "配价：“罹患”后面必须带疾病作宾语，“我昨天罹患了”说不完整。", "感激": "配价：“感激”需要带对象，如“感激某人”，单独说“感激了”不完整。"}, "sentence_index": 0, "correct_answer": "感冒"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "伤口感冒了，要去医院。", "explanation": "这里应该用〈感染〉。感冒指人得了呼吸道的病，伤口发炎要说感染。"}, {"text": "这棵树感冒了，叶子都黄了。", "explanation": "这里应该用〈生病〉。感冒只用于人得病，树生病不说感冒。"}, {"text": "他吃了海鲜，皮肤感冒，起了红疹。", "explanation": "这里应该用〈过敏〉。起红疹是过敏反应，感冒不会让皮肤起疹子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be51c686-fcf4-468c-b04e-498f8f788a98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88709, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "唱歌", "is_correct": false, "explanation": "语义：“唱歌”会让教室吵闹，与“教室里很安静”矛盾。"}, {"text": "感冒", "is_correct": true, "explanation": "感冒：同学们生病没来，所以教室安静，句意合理。"}, {"text": "举行", "is_correct": false, "explanation": "配价：“举行”后面要带活动作宾语，如“举行比赛”，“同学们都举行了”说不完整。"}, {"text": "吵架", "is_correct": false, "explanation": "语义：“吵架”会发出声音，与“教室里很安静”相反。"}], "explanations": {"唱歌": "语义：“唱歌”会让教室吵闹，与“教室里很安静”矛盾。", "感冒": "感冒：同学们生病没来，所以教室安静，句意合理。", "举行": "配价：“举行”后面要带活动作宾语，如“举行比赛”，“同学们都举行了”说不完整。", "吵架": "语义：“吵架”会发出声音，与“教室里很安静”相反。"}, "sentence_index": 6, "correct_answer": "感冒"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他吃坏了东西，感冒了，一直跑厕所。", "explanation": "这里应该用〈拉肚子〉。吃坏东西、一直跑厕所是拉肚子，感冒是呼吸道的病。"}, {"text": "他摔了一跤，腿感冒了，要住院打石膏。", "explanation": "这里应该用〈骨折〉。感冒不会发生在腿上，骨头断了要说骨折。"}, {"text": "孩子感冒到三十九度，很难受。", "explanation": "这里应该用〈发烧〉。感冒不说体温达到多少度，体温高要说发烧。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be51c686-fcf4-468c-b04e-498f8f788a98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88709, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他昨天感冒地很厉害，只能在家躺着。", "corrected_sentence": "他昨天感冒得很厉害，只能在家躺着。", "error_description": "“感冒”后面的程度补语要用“得”，不能用“地”。“地”用在动词前作状语，应改为「感冒得很厉害」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be51c686-fcf4-468c-b04e-498f8f788a98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88709, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我去年感冒了过三次，很麻烦。", "corrected_sentence": "我去年感冒过三次，很麻烦。", "error_description": "“感冒”后面的“了”和“过”不能同时用。表示经历过几次只用“过”，应改为「感冒过三次」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be51c686-fcf4-468c-b04e-498f8f788a98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
