INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88710, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "病毒引起的呼吸道疾病，症状为鼻塞、流涕、咳嗽、发热等。", "primary_collocate": null, "pronunciation": "gǎn mào", "ipa": "kan˨˩ mɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "感冒是一种常见的病。", "target_word": "感冒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次感冒让我难受了三天。", "target_word": "感冒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "感冒会传染给别人。", "target_word": "感冒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天是感冒最多的时候。", "target_word": "感冒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他得了重感冒，要去医院。", "target_word": "感冒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "感冒的症状有咳嗽和发热。", "target_word": "感冒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小感冒不用吃太多药。", "target_word": "感冒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "感冒好了以后，我就去跑步。", "target_word": "感冒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说这个感冒很快会好。", "target_word": "感冒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "喝热水对感冒有帮助。", "target_word": "感冒", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "场", "label": "量词"}, {"form": "次", "label": "量词"}], "register": "中性", "sense_fingerprint": "病毒引起的呼吸道疾病", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3763d68d-fe1a-4cec-95df-e92983c5cf23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88710, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "咖啡", "is_correct": false, "explanation": "语义：咖啡是饮料，不是病，不能说「咖啡是一种常见的病」。"}, {"text": "感冒", "is_correct": true, "explanation": "感冒：病毒引起的常见病，与句中定义相符。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”不是病，不能说“天气是一种常见的病”。"}, {"text": "手机", "is_correct": false, "explanation": "语义：“手机”是电子产品，不是疾病。"}], "explanations": {"咖啡": "语义：咖啡是饮料，不是病，不能说「咖啡是一种常见的病」。", "感冒": "感冒：病毒引起的常见病，与句中定义相符。", "天气": "语义：“天气”不是病，不能说“天气是一种常见的病”。", "手机": "语义：“手机”是电子产品，不是疾病。"}, "sentence_index": 0, "correct_answer": "感冒"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的手机感冒了，打不出电话。", "explanation": "这里应该用〈坏〉。感冒只用于人得病，手机出了问题要说坏了。"}, {"text": "他吃了不干净的东西，得了食物感冒。", "explanation": "这里应该用〈食物中毒〉。感冒是呼吸道的病，不是吃坏东西引起的。"}, {"text": "电脑感冒了，开不了机。", "explanation": "这里应该用〈中毒〉。感冒只用于人得病，电脑被病毒攻击要说中毒。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be51c686-fcf4-468c-b04e-498f8f788a98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88710, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "小费", "is_correct": false, "explanation": "搭配：“吃”不能搭配“小费”，“小费”不是药，也不能吃。"}, {"text": "感冒", "is_correct": true, "explanation": "感冒：轻微的病，不用吃太多药，符合句意。"}, {"text": "小说", "is_correct": false, "explanation": "搭配：“吃”只搭配药和食物，不说吃“小说”。"}, {"text": "小事", "is_correct": false, "explanation": "语义：“小事”不是病，说它不用吃药没有意义。"}], "explanations": {"小费": "搭配：“吃”不能搭配“小费”，“小费”不是药，也不能吃。", "感冒": "感冒：轻微的病，不用吃太多药，符合句意。", "小说": "搭配：“吃”只搭配药和食物，不说吃“小说”。", "小事": "语义：“小事”不是病，说它不用吃药没有意义。"}, "sentence_index": 6, "correct_answer": "感冒"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的腿感冒了，要住院打石膏。", "explanation": "这里应该用〈骨折〉。感冒不会发生在腿上，骨头断了要说骨折。"}, {"text": "天气感冒了，下起了大雨。", "explanation": "这里应该用〈降温〉。感冒只用于人，天气变冷要说降温。"}, {"text": "他的眼睛感冒了，又红又疼。", "explanation": "这里应该用〈发炎〉。感冒指人整体生病，眼睛发炎要说发炎。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be51c686-fcf4-468c-b04e-498f8f788a98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88710, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我得了一只严重的感冒，要休息两天。", "corrected_sentence": "我得了一场严重的感冒，要休息两天。", "error_description": "错误：量词用错。“感冒”应用量词“场”，不能用“只”（“只”用于动物）。应说“得了一场严重的感冒”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be51c686-fcf4-468c-b04e-498f8f788a98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88710, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他得了一个很重感冒，在家休息。", "corrected_sentence": "他得了一个很重的感冒，在家休息。", "error_description": "“很重”修饰名词“感冒”时要加“的”。“重感冒”可以直接说，但加了“很”就要说「很重的感冒」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be51c686-fcf4-468c-b04e-498f8f788a98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88711, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "渺小", "is_correct": true, "explanation": "正确。“渺小”与“伟大”在“特别了不起”这一义上相对，指微小、不值一提。"}, {"text": "清楚", "is_correct": false, "explanation": "“清楚”指明白、分明，与“伟大”在这一义上没有反义关系。"}, {"text": "坚硬", "is_correct": false, "explanation": "“坚硬”指质地硬，与“伟大”没有反义关系。"}, {"text": "寒冷", "is_correct": false, "explanation": "“寒冷”指温度低，与“伟大”没有反义关系。"}], "correct_answer": "渺小", "explanations": {"渺小": "正确。“渺小”与“伟大”在“特别了不起”这一义上相对，指微小、不值一提。", "清楚": "“清楚”指明白、分明，与“伟大”在这一义上没有反义关系。", "坚硬": "“坚硬”指质地硬，与“伟大”没有反义关系。", "寒冷": "“寒冷”指温度低，与“伟大”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e6934fd-af88-42ee-8f05-f584150832bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88711, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "渺小", "is_correct": true, "explanation": "正确。“渺小”与“伟大”在“特别了不起”这一义上相对，指微小、不值一提。"}, {"text": "迟钝", "is_correct": false, "explanation": "“迟钝”指反应慢，与“伟大”没有反义关系。"}, {"text": "潮湿", "is_correct": false, "explanation": "“潮湿”指含水分多，与“伟大”没有反义关系。"}, {"text": "懒惰", "is_correct": false, "explanation": "“懒惰”指不愿劳动，与“伟大”在这一义上没有反义关系。"}], "correct_answer": "渺小", "explanations": {"渺小": "正确。“渺小”与“伟大”在“特别了不起”这一义上相对，指微小、不值一提。", "迟钝": "“迟钝”指反应慢，与“伟大”没有反义关系。", "潮湿": "“潮湿”指含水分多，与“伟大”没有反义关系。", "懒惰": "“懒惰”指不愿劳动，与“伟大”在这一义上没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e6934fd-af88-42ee-8f05-f584150832bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88711, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "伟大是特别了不起,让人佩服。", "primary_collocate": null, "pronunciation": "wěi dà", "ipa": "weɪ˨˩ ta˥˩", "syllable_count": 2, "sentences": [{"text": "妈妈是一个很伟大的人。", "target_word": "伟大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她为了孩子放弃了自己的工作，真伟大。", "target_word": "伟大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老师一辈子帮助穷孩子，他很伟大。", "target_word": "伟大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "母亲的爱是世界上最伟大的爱。", "target_word": "伟大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他救了落水的小孩，大家都说他伟大。", "target_word": "伟大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把钱都给了穷人，这种爱心很伟大。", "target_word": "伟大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每天照顾生病的老人，这种行为很伟大。", "target_word": "伟大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在我心里，爷爷是个伟大的英雄。", "target_word": "伟大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生冒着危险去帮助病人，真伟大！", "target_word": "伟大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你为朋友做了这么多，你太伟大了。", "target_word": "伟大", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "更伟大", "label": "比较形式"}, {"form": "最伟大", "label": "最高级形式"}], "register": "中性", "sense_fingerprint": "人的品行或做法特别了不起，让人佩服", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07800451-dd71-4009-8d4c-1927c61a756d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88711, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "伟大", "is_correct": true, "explanation": "正确。“伟大”形容妈妈的品格，句子是在赞美她。"}, {"text": "渺小", "is_correct": false, "explanation": "语义：“渺小”与句中赞美妈妈的语气相反，不能说妈妈渺小。"}, {"text": "陌生", "is_correct": false, "explanation": "语义：“陌生”与“妈妈”的亲近关系相矛盾，不能说妈妈是陌生的人。"}, {"text": "巨大", "is_correct": false, "explanation": "搭配：“巨大”多修饰体积、数量或影响，直接修饰“人”这一身份不自然。"}], "explanations": {"伟大": "正确。“伟大”形容妈妈的品格，句子是在赞美她。", "渺小": "语义：“渺小”与句中赞美妈妈的语气相反，不能说妈妈渺小。", "陌生": "语义：“陌生”与“妈妈”的亲近关系相矛盾，不能说妈妈是陌生的人。", "巨大": "搭配：“巨大”多修饰体积、数量或影响，直接修饰“人”这一身份不自然。"}, "sentence_index": 0, "correct_answer": "伟大"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次事故造成的损失非常伟大。", "explanation": "这里应该用〈巨大〉。“伟大”形容人的品格、事业的崇高，不用来形容损失这类程度。"}, {"text": "这家公司的规模非常伟大。", "explanation": "这里应该用〈庞大〉。规模的大小用“庞大”，“伟大”只用于人的品格或成就，不说公司的规模。"}, {"text": "那朵花非常伟大。", "explanation": "这里应该用〈美丽〉。形容景物的外观用“美丽”，“伟大”用于人的品格和成就，不形容花。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e6934fd-af88-42ee-8f05-f584150832bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88711, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "伟大", "is_correct": true, "explanation": "正确。“伟大”形容照顾病人这种行为的崇高，与句意一致。"}, {"text": "残忍", "is_correct": false, "explanation": "语义：照顾生病的老人是关爱的表现，“残忍”与句意相反。"}, {"text": "可耻", "is_correct": false, "explanation": "语义：“可耻”是负面评价，照顾生病的老人是善行，与句意相反。"}, {"text": "冷淡", "is_correct": false, "explanation": "语义：“冷淡”与“每天照顾生病的老人”的关心态度矛盾。"}], "explanations": {"伟大": "正确。“伟大”形容照顾病人这种行为的崇高，与句意一致。", "残忍": "语义：照顾生病的老人是关爱的表现，“残忍”与句意相反。", "可耻": "语义：“可耻”是负面评价，照顾生病的老人是善行，与句意相反。", "冷淡": "语义：“冷淡”与“每天照顾生病的老人”的关心态度矛盾。"}, "sentence_index": 6, "correct_answer": "伟大"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这种药的效果非常伟大。", "explanation": "这里应该用〈显著〉。效果、变化的明显程度用“显著”，“伟大”只用于人的品格、事业等。"}, {"text": "他这次考试考得很伟大。", "explanation": "这里应该用〈优秀〉。考试成绩和表现用“优秀”，“伟大”不用来评价成绩。"}, {"text": "这间房间很伟大。", "explanation": "这里应该用〈干净〉。房间的整洁用“干净”，“伟大”不用来形容房间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e6934fd-af88-42ee-8f05-f584150832bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88711, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他是我见过的最伟大得老师。", "corrected_sentence": "他是我见过的最伟大的老师。", "error_description": "错误：“伟大得老师”；正确：“伟大的老师”。修饰名词要用结构助词“的”，“得”用于动词或形容词后连接补语，这里不能用“得”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e6934fd-af88-42ee-8f05-f584150832bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88711, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他对家乡的贡献很的伟大。", "corrected_sentence": "他对家乡的贡献很伟大。", "error_description": "错误：“很的伟大”；正确：“很伟大”。程度副词“很”与形容词之间不能加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e6934fd-af88-42ee-8f05-f584150832bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
