INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88712, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "品格、才能、成就等崇高而不平凡。", "primary_collocate": null, "pronunciation": "wěi dà", "ipa": "weɪ˨˩ ta˥˩", "syllable_count": 2, "sentences": [{"text": "爱因斯坦是一位伟大的科学家。", "target_word": "伟大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是一项伟大的发明。", "target_word": "伟大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鲁迅是中国伟大的文学家。", "target_word": "伟大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部伟大的作品影响了很多人。", "target_word": "伟大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们完成了一件伟大的工程。", "target_word": "伟大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长城是古代人民创造的伟大奇迹。", "target_word": "伟大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一生取得了伟大的成就。", "target_word": "伟大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "伟大的音乐家贝多芬耳朵听不见，还写出了好音乐。", "target_word": "伟大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们伟大的祖国有五千年的历史。", "target_word": "伟大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位伟大的诗人写了很多名诗。", "target_word": "伟大", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "更伟大", "label": "比较形式"}, {"form": "最伟大", "label": "最高级形式"}], "register": "书面", "sense_fingerprint": "人物、成就、作品等崇高而不平凡", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07800451-dd71-4009-8d4c-1927c61a756d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_erro