INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88712, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "伟大", "is_correct": true, "explanation": "正确。“伟大”形容爱因斯坦的成就和品格，与句意一致。"}, {"text": "渺小", "is_correct": false, "explanation": "语义：爱因斯坦是著名科学家，“渺小”与句中的敬佩语气相反。"}, {"text": "陌生", "is_correct": false, "explanation": "语义：爱因斯坦是家喻户晓的人物，“陌生”与句意矛盾。"}, {"text": "巨大", "is_correct": false, "explanation": "搭配：“巨大”多修饰体积、数量或影响，直接修饰“科学家”这类人物身份不自然。"}], "explanations": {"伟大": "正确。“伟大”形容爱因斯坦的成就和品格，与句意一致。", "渺小": "语义：爱因斯坦是著名科学家，“渺小”与句中的敬佩语气相反。", "陌生": "语义：爱因斯坦是家喻户晓的人物，“陌生”与句意矛盾。", "巨大": "搭配：“巨大”多修饰体积、数量或影响，直接修饰“科学家”这类人物身份不自然。"}, "sentence_index": 0, "correct_answer": "伟大"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座城市的人口非常伟大。", "explanation": "这里应该用〈庞大〉。人口的多少用“庞大”，“伟大”不用来形容人口。"}, {"text": "她这学期的成绩很伟大。", "explanation": "这里应该用〈优秀〉。成绩和表现用“优秀”，“伟大”用于人的品格或事业，不评价成绩。"}, {"text": "这碗汤的味道非常伟大。", "explanation": "这里应该用〈鲜美〉。味道用“鲜美”或“好喝”，“伟大”不用来评价味道。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e6934fd-af88-42ee-8f05-f584150832bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88712, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "伟大", "is_correct": true, "explanation": "正确。“伟大”形容成就的崇高，与“取得”搭配自然。"}, {"text": "残忍", "is_correct": false, "explanation": "语义：“残忍”是负面评价，与句中肯定成就的语气相矛盾。"}, {"text": "幼稚", "is_correct": false, "explanation": "语义：“幼稚”指不成熟，与“成就”的褒义不符。"}, {"text": "笨重", "is_correct": false, "explanation": "搭配：“笨重”形容物体，不能修饰成就。"}], "explanations": {"伟大": "正确。“伟大”形容成就的崇高，与“取得”搭配自然。", "残忍": "语义：“残忍”是负面评价，与句中肯定成就的语气相矛盾。", "幼稚": "语义：“幼稚”指不成熟，与“成就”的褒义不符。", "笨重": "搭配：“笨重”形容物体，不能修饰成就。"}, "sentence_index": 6, "correct_answer": "伟大"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家餐厅的菜非常伟大。", "explanation": "这里应该用〈美味〉。菜肴的味道用“美味”，“伟大”用于人的品格和成就，不用来评价菜。"}, {"text": "这面旗子的颜色非常伟大。", "explanation": "这里应该用〈鲜艳〉。颜色的鲜明用“鲜艳”，“伟大”不用来形容颜色。"}, {"text": "这张桌子擦得很伟大。", "explanation": "这里应该用〈干净〉。桌面的整洁用“干净”，“伟大”不用来形容擦桌子的结果。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e6934fd-af88-42ee-8f05-f584150832bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88712, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他是中国最伟大得作家之一。", "corrected_sentence": "他是中国最伟大的作家之一。", "error_description": "错误：“伟大得作家”；正确：“伟大的作家”。修饰名词要用结构助词“的”，“得”用于补语，这里不能用“得”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e6934fd-af88-42ee-8f05-f584150832bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88712, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位画家的作品很的伟大。", "corrected_sentence": "这位画家的作品很伟大。", "error_description": "错误：“很的伟大”；正确：“很伟大”。程度副词“很”与形容词之间不能加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e6934fd-af88-42ee-8f05-f584150832bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
