INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88713, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "上算是花的钱少，得到的多，很划得来。", "primary_collocate": null, "pronunciation": "shàng suàn", "ipa": "ʂɑŋ˥˩ swan˥˩", "syllable_count": 2, "sentences": [{"text": "买一送一，真上算。", "target_word": "上算", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "大瓶的比小瓶的上算。", "target_word": "上算", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "打折的时候买，更上算。", "target_word": "上算", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这家店的东西便宜，买多了很上算。", "target_word": "上算", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "坐地铁比打车上算多了。", "target_word": "上算", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件衣服又好又便宜，买了真上算。", "target_word": "上算", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我在网上买菜，又快又上算。", "target_word": "上算", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一次买十个，每个只要两块，很上算。", "target_word": "上算", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这张卡能打八折，办一张挺上算的。", "target_word": "上算", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他算了算，觉得买这个不上算。", "target_word": "上算", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "不上算", "label": "否定式"}], "register": "口语", "sense_fingerprint": "买东西花钱少、得到多，很划得来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cda74fbf-1808-476c-b0e7-6f1b5b85d218') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88713, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "上算", "is_correct": true, "explanation": "“上算”指花钱少、得到多，与“买一送一”的优惠相符。"}, {"text": "贵", "is_correct": false, "explanation": "语义：“贵”指价格高，与买一送一的优惠相反。"}, {"text": "厚", "is_correct": false, "explanation": "搭配：“厚”形容物体的厚度，不能用来形容买卖是否划算。"}, {"text": "辣", "is_correct": false, "explanation": "语义：“辣”指味道刺激，与买卖的好处无关。"}], "explanations": {"上算": "“上算”指花钱少、得到多，与“买一送一”的优惠相符。", "贵": "语义：“贵”指价格高，与买一送一的优惠相反。", "厚": "搭配：“厚”形容物体的厚度，不能用来形容买卖是否划算。", "辣": "语义：“辣”指味道刺激，与买卖的好处无关。"}, "sentence_index": 0, "correct_answer": "上算"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次买贵了，我很上算。", "explanation": "这里应该用〈吃亏〉。上算指花钱少、得到多，买贵了不能说上算。"}, {"text": "他每天早起跑步，身体变得很上算。", "explanation": "这里应该用〈健康〉。上算只用于买卖和花费的得失，不能形容身体状况。"}, {"text": "这张票太贵了，我觉得很上算。", "explanation": "这里应该用〈不值得〉。上算指划算，票价太贵时应说〈不值得〉买。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '081d27b6-2776-49a0-9ed9-3975b461f9a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88713, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "上算", "is_correct": true, "explanation": "“上算”指花钱少、得到多，与“又快又……”买菜的划算情况相符。"}, {"text": "结实", "is_correct": false, "explanation": "语义：“结实”形容物品牢固，不能用来形容购物是否划算。"}, {"text": "聪明", "is_correct": false, "explanation": "搭配：“聪明”形容人的头脑，不能用来形容买菜的方式。"}, {"text": "胖", "is_correct": false, "explanation": "体貌：“胖”形容人或动物的体型，与购物无关。"}], "explanations": {"上算": "“上算”指花钱少、得到多，与“又快又……”买菜的划算情况相符。", "结实": "语义：“结实”形容物品牢固，不能用来形容购物是否划算。", "聪明": "搭配：“聪明”形容人的头脑，不能用来形容买菜的方式。", "胖": "体貌：“胖”形容人或动物的体型，与购物无关。"}, "sentence_index": 6, "correct_answer": "上算"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我买到假货，觉得很上算。", "explanation": "这里应该用〈被骗〉。上算指划算，买到假货应说〈被骗〉，不能说上算。"}, {"text": "他把朋友的秘密告诉了别人，还觉得很上算。", "explanation": "这里应该用〈后悔〉。上算指划算，泄露朋友秘密后应说〈后悔〉，不能说上算。"}, {"text": "这次考试我考了零分，觉得很上算。", "explanation": "这里应该用〈失败〉。上算指花钱少、得到多，考砸了应说〈失败〉，不能说上算。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '081d27b6-2776-49a0-9ed9-3975b461f9a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88713, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "网购比去店里买很上算。", "corrected_sentence": "网购比去店里买上算。", "error_description": "比字句中不能再用“很”修饰形容词，“网购比去店里买很上算”应删去「很」，即“网购比去店里买上算”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '081d27b6-2776-49a0-9ed9-3975b461f9a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88713, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家超市的菜上算很。", "corrected_sentence": "这家超市的菜上算得很。", "error_description": "“上算”作谓语带程度补语时，补语前要用“得”，应说“上算得很”，不能省略“得”说“上算很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '081d27b6-2776-49a0-9ed9-3975b461f9a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
