INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88714, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "合算；所得大于所付。", "primary_collocate": null, "pronunciation": "shàng suàn", "ipa": "ʂɑŋ˥˩ swan˥˩", "syllable_count": 2, "sentences": [{"text": "租房子比买房子上算。", "target_word": "上算", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "自己做饭比天天下馆子上算。", "target_word": "上算", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这笔生意做下来，很上算。", "target_word": "上算", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "坐高铁又快又不贵，上算得很。", "target_word": "上算", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他觉得多花一点钱买好的更上算。", "target_word": "上算", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "买年票比每次买票上算多了。", "target_word": "上算", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "修旧的不如买新的上算。", "target_word": "上算", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "合伙买车，大家分钱，上算多了。", "target_word": "上算", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "算上折扣，这个价格最上算。", "target_word": "上算", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "套餐比单点上算多了。", "target_word": "上算", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "不上算", "label": "否定式"}], "register": "口语", "sense_fingerprint": "比较两种做法后，所得大于所付，更合算", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cda74fbf-1808-476c-b0e7-6f1b5b85d218') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88714, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "上算", "is_correct": true, "explanation": "“上算”指比较之下所得大于所付，与“租房子比买房子”的比较相符。"}, {"text": "礼貌", "is_correct": false, "explanation": "搭配：“礼貌”形容人的言行，不能用来比较租房和买房。"}, {"text": "甜", "is_correct": false, "explanation": "语义：“甜”指味道，与租房和买房的经济比较无关。"}, {"text": "辛辣", "is_correct": false, "explanation": "语义：“辛辣”指味道刺激，与此句的比较无关。"}], "explanations": {"上算": "“上算”指比较之下所得大于所付，与“租房子比买房子”的比较相符。", "礼貌": "搭配：“礼貌”形容人的言行，不能用来比较租房和买房。", "甜": "语义：“甜”指味道，与租房和买房的经济比较无关。", "辛辣": "语义：“辛辣”指味道刺激，与此句的比较无关。"}, "sentence_index": 0, "correct_answer": "上算"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这双鞋大小很上算，我穿着舒服。", "explanation": "这里应该用〈合适〉。上算指所得大于所付，不能用来形容大小。"}, {"text": "他是个很上算的朋友，有事都会帮忙。", "explanation": "这里应该用〈可靠〉。上算只用于事情或买卖的合算，不能形容人。"}, {"text": "这个设计很上算，大家都夸好。", "explanation": "这里应该用〈美观〉。上算指合算，不能用来形容外观。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '081d27b6-2776-49a0-9ed9-3975b461f9a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88714, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "上算", "is_correct": true, "explanation": "“上算”指比较之下更合算，与“修旧的不如买新的”相符。"}, {"text": "悲伤", "is_correct": false, "explanation": "语义：“悲伤”形容心情，与比较经济的合算无关。"}, {"text": "老实", "is_correct": false, "explanation": "搭配：“老实”形容人的言行，不能用来形容修理和购买的划算程度。"}, {"text": "冷清", "is_correct": false, "explanation": "语义：“冷清”形容场所或场面，与此句的比较无关。"}], "explanations": {"上算": "“上算”指比较之下更合算，与“修旧的不如买新的”相符。", "悲伤": "语义：“悲伤”形容心情，与比较经济的合算无关。", "老实": "搭配：“老实”形容人的言行，不能用来形容修理和购买的划算程度。", "冷清": "语义：“冷清”形容场所或场面，与此句的比较无关。"}, "sentence_index": 6, "correct_answer": "上算"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个观点很上算，大家都同意。", "explanation": "这里应该用〈正确〉。上算指合算，不能用来评价观点对不对。"}, {"text": "图书馆里很吵，我们觉得很上算。", "explanation": "这里应该用〈安静〉。上算指合算，不能用来形容环境的吵闹；图书馆应说〈安静〉。"}, {"text": "厨房很上算，每天都有人打扫。", "explanation": "这里应该用〈干净〉。上算不能用来形容厨房的卫生状况。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '081d27b6-2776-49a0-9ed9-3975b461f9a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88714, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "早点订票比临时买票很上算。", "corrected_sentence": "早点订票比临时买票上算。", "error_description": "比字句中不能再用“很”修饰形容词，“早点订票比临时买票很上算”应删去「很」，即“早点订票比临时买票上算”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '081d27b6-2776-49a0-9ed9-3975b461f9a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88714, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种套餐上算很。", "corrected_sentence": "这种套餐上算得很。", "error_description": "“上算”作谓语带程度补语“很”时，中间要用“得”，“上算很”漏掉了“得”，应说“上算得很”（或说“很上算”）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '081d27b6-2776-49a0-9ed9-3975b461f9a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88715, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "可喜", "is_correct": true, "explanation": "正确：“可喜”指值得高兴，与“可惜”的遗憾相对。"}, {"text": "清楚", "is_correct": false, "explanation": "与“可惜”没有反义关系，“清楚”形容明白、分明，意思不相对。"}, {"text": "结实", "is_correct": false, "explanation": "与“可惜”没有反义关系，“结实”形容物体牢固。"}, {"text": "安静", "is_correct": false, "explanation": "与“可惜”没有反义关系，“安静”形容声音或环境平静。"}], "correct_answer": "可喜", "explanations": {"可喜": "正确：“可喜”指值得高兴，与“可惜”的遗憾相对。", "清楚": "与“可惜”没有反义关系，“清楚”形容明白、分明，意思不相对。", "结实": "与“可惜”没有反义关系，“结实”形容物体牢固。", "安静": "与“可惜”没有反义关系，“安静”形容声音或环境平静。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b01eabee-5f23-40fb-bd13-a6b2189c2450') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
