INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88715, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "可惜是事情没有做成，心里觉得有点难过。", "primary_collocate": null, "pronunciation": "kě xī", "ipa": "kʰɤ˨˩˦ ɕi˥", "syllable_count": 2, "sentences": [{"text": "真可惜，我们差一分就赢了。", "target_word": "可惜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天的电影票卖完了，真可惜。", "target_word": "可惜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没考上大学，大家都觉得可惜。", "target_word": "可惜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你没来看比赛，太可惜了。", "target_word": "可惜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨太大了，我们没去成公园，真可惜。", "target_word": "可惜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次机会没抓住，他觉得很可惜。", "target_word": "可惜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "差五分钟没赶上火车，真可惜！", "target_word": "可惜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她没能参加朋友的婚礼，觉得很可惜。", "target_word": "可惜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛下雨取消了，多可惜啊。", "target_word": "可惜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "事情没办成，我也觉得有点可惜。", "target_word": "可惜", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "形容词，事情没有做成或错过机会，心里觉得遗憾难过", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '525423d5-7b31-4df5-a976-f002812aab26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88715, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "可惜", "is_correct": true, "explanation": "正确：听到的是“可惜”（kě xī），指事情没做成而心里遗憾。"}, {"text": "可喜", "is_correct": false, "explanation": "xǐ（第三声）与 xī（第一声）声调不同，“可喜”意思是值得高兴。"}, {"text": "可心", "is_correct": false, "explanation": "xīn 比 xī 多一个鼻音韵尾 -n，“可心”意思是称心如意。"}, {"text": "可期", "is_correct": false, "explanation": "qī 与 xī 声母不同（q / x），“可期”意思是值得期待，如“前途可期”。"}], "explanations": {"可惜": "正确：听到的是“可惜”（kě xī），指事情没做成而心里遗憾。", "可喜": "xǐ（第三声）与 xī（第一声）声调不同，“可喜”意思是值得高兴。", "可心": "xīn 比 xī 多一个鼻音韵尾 -n，“可心”意思是称心如意。", "可期": "qī 与 xī 声母不同（q / x），“可期”意思是值得期待，如“前途可期”。"}, "sentence_index": null, "correct_answer": "可惜"}, "level_3": {"options": [{"text": "可惜", "is_correct": true, "explanation": "正确：“真可惜”表示事情没做成而遗憾，与“差一分就赢了”相符。"}, {"text": "可爱", "is_correct": false, "explanation": "搭配：“可爱”多用于人或小动物，不能评价比赛的失利结果。"}, {"text": "快乐", "is_correct": false, "explanation": "语义：“快乐”表示高兴，与“差一分就赢了”的失利语境相反。"}, {"text": "丰富", "is_correct": false, "explanation": "搭配：“丰富”修饰经验、内容等，不能用来评价比赛结果。"}], "explanations": {"可惜": "正确：“真可惜”表示事情没做成而遗憾，与“差一分就赢了”相符。", "可爱": "搭配：“可爱”多用于人或小动物，不能评价比赛的失利结果。", "快乐": "语义：“快乐”表示高兴，与“差一分就赢了”的失利语境相反。", "丰富": "搭配：“丰富”修饰经验、内容等，不能用来评价比赛结果。"}, "sentence_index": 0, "correct_answer": "可惜"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "那只流浪狗饿得站不起来，真可惜。", "explanation": "这里应该用〈可怜〉。“可惜”表示事情没做成或好东西被浪费的遗憾；形容动物处境悲惨、令人同情时要用“可怜”。"}, {"text": "他这次考试进步很大，真是可惜。", "explanation": "这里应该用〈可喜〉。进步是值得高兴的事，“可惜”表达遗憾，与语境的感情相反，应该用“可喜”。"}, {"text": "这个宝宝真可惜，大家都喜欢逗她。", "explanation": "这里应该用〈可爱〉。“可惜”表示遗憾惋惜，形容讨人喜欢的小孩要用“可爱”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b01eabee-5f23-40fb-bd13-a6b2189c2450') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88715, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "可惜", "is_correct": true, "explanation": "正确：“真可惜”表示遗憾，与“差五分钟没赶上火车”相符。"}, {"text": "热闹", "is_correct": false, "explanation": "语义：“热闹”形容场面喧闹，与没赶上车的遗憾语境不符。"}, {"text": "便宜", "is_correct": false, "explanation": "搭配：“便宜”说价格，不能用来评价没赶上车这件事。"}, {"text": "整齐", "is_correct": false, "explanation": "体貌：“整齐”形容排列或外貌，不能用于描述没赶上火车的情况。"}], "explanations": {"可惜": "正确：“真可惜”表示遗憾，与“差五分钟没赶上火车”相符。", "热闹": "语义：“热闹”形容场面喧闹，与没赶上车的遗憾语境不符。", "便宜": "搭配：“便宜”说价格，不能用来评价没赶上车这件事。", "整齐": "体貌：“整齐”形容排列或外貌，不能用于描述没赶上火车的情况。"}, "sentence_index": 6, "correct_answer": "可惜"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个朋友很可惜，什么事都愿意帮你。", "explanation": "这里应该用〈可靠〉。“可惜”表示事情没做成而遗憾，不能用来形容人值得信赖；说人靠得住要用“可靠”。"}, {"text": "他的态度很可惜，我们要小心。", "explanation": "这里应该用〈可疑〉。“可惜”表示惋惜，不能用来形容令人起疑的态度。"}, {"text": "这次演出结束后，我的心情很可惜。", "explanation": "这里应该用〈平静〉。“可惜”是惋惜的感情，不能描述心情平和的状态。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b01eabee-5f23-40fb-bd13-a6b2189c2450') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88715, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次没去成，太可惜的。", "corrected_sentence": "这次没去成，太可惜了。", "error_description": "错误：句末用“的”，“太可惜的”不能单独作谓语，表示感叹要用“了”。正确：“太可惜了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b01eabee-5f23-40fb-bd13-a6b2189c2450') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88715, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他没能参加决赛，我觉得太很可惜。", "corrected_sentence": "他没能参加决赛，我觉得很可惜。", "error_description": "错误：“太”和“很”同时修饰“可惜”，程度副词不能重叠。正确：去掉“太”，说“很可惜”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b01eabee-5f23-40fb-bd13-a6b2189c2450') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
