INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88716, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "令人惋惜，觉得不应该失去。", "primary_collocate": null, "pronunciation": "kě xī", "ipa": "kʰɤ˨˩˦ ɕi˥", "syllable_count": 2, "sentences": [{"text": "这么新的衣服扔了，太可惜了。", "target_word": "可惜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好看的花这么快就谢了，真可惜。", "target_word": "可惜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "剩下的饭倒掉太可惜了。", "target_word": "可惜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他那么聪明，不读书太可惜了。", "target_word": "可惜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书这么好，没人看，很可惜。", "target_word": "可惜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件毛衣还很新，不穿太可惜了。", "target_word": "可惜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "让这么好的人才离开公司，真可惜。", "target_word": "可惜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把这些好水果放坏了，多可惜啊。", "target_word": "可惜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里风景这么美，没人来，太可惜了。", "target_word": "可惜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他唱得那么好，不当歌手太可惜了。", "target_word": "可惜", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "形容词，好东西、好人才被浪费或失去，让人觉得惋惜", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '525423d5-7b31-4df5-a976-f002812aab26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88716, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "可惜", "is_correct": true, "explanation": "正确：听到的是“可惜”（kě xī），指好东西被失去或浪费而令人惋惜。"}, {"text": "可喜", "is_correct": false, "explanation": "xǐ（第三声）与 xī（第一声）声调不同，“可喜”意思是值得高兴。"}, {"text": "可心", "is_correct": false, "explanation": "xīn 比 xī 多一个鼻音韵尾 -n，“可心”意思是称心如意。"}, {"text": "可期", "is_correct": false, "explanation": "qī 与 xī 声母不同（q / x），“可期”意思是值得期待，如“前途可期”。"}], "explanations": {"可惜": "正确：听到的是“可惜”（kě xī），指好东西被失去或浪费而令人惋惜。", "可喜": "xǐ（第三声）与 xī（第一声）声调不同，“可喜”意思是值得高兴。", "可心": "xīn 比 xī 多一个鼻音韵尾 -n，“可心”意思是称心如意。", "可期": "qī 与 xī 声母不同（q / x），“可期”意思是值得期待，如“前途可期”。"}, "sentence_index": null, "correct_answer": "可惜"}, "level_3": {"options": [{"text": "可惜", "is_correct": true, "explanation": "正确：“太可惜了”表示好东西被扔掉而惋惜，与“衣服扔了”相符。"}, {"text": "凉快", "is_correct": false, "explanation": "语义：“凉快”形容温度舒适，与把新衣服扔掉的惋惜语境不符。"}, {"text": "整齐", "is_correct": false, "explanation": "搭配：“整齐”形容排列或外观，不能用来评价扔掉衣服这件事。"}, {"text": "热闹", "is_correct": false, "explanation": "语义：“热闹”形容场面喧闹，与扔掉新衣服的语境无关。"}], "explanations": {"可惜": "正确：“太可惜了”表示好东西被扔掉而惋惜，与“衣服扔了”相符。", "凉快": "语义：“凉快”形容温度舒适，与把新衣服扔掉的惋惜语境不符。", "整齐": "搭配：“整齐”形容排列或外观，不能用来评价扔掉衣服这件事。", "热闹": "语义：“热闹”形容场面喧闹，与扔掉新衣服的语境无关。"}, "sentence_index": 0, "correct_answer": "可惜"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这份心意很可惜，我要好好收下。", "explanation": "这里应该用〈可贵〉。“可惜”表示令人惋惜、不应失去；形容心意珍贵要用“可贵”。"}, {"text": "那只流浪猫很可惜，没人给它吃的。", "explanation": "这里应该用〈可怜〉。“可惜”用于好东西被浪费，形容处境悲惨、令人同情的动物要用“可怜”。"}, {"text": "这个笑话很可惜，大家都笑了。", "explanation": "这里应该用〈可笑〉。“可惜”表示令人惋惜，笑话引人发笑要用“可笑”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b01eabee-5f23-40fb-bd13-a6b2189c2450') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88716, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "可惜", "is_correct": true, "explanation": "正确：“真可惜”表示好人才离开而惋惜，与语境相符。"}, {"text": "安静", "is_correct": false, "explanation": "语义：“安静”形容环境无声，与人才离开公司的惋惜语境不符。"}, {"text": "清楚", "is_correct": false, "explanation": "搭配：“清楚”多修饰说明、想法，不能用来形容人才离职这件事。"}, {"text": "结实", "is_correct": false, "explanation": "体貌：“结实”形容身体强壮或物品牢固，不能评价人才离开。"}], "explanations": {"可惜": "正确：“真可惜”表示好人才离开而惋惜，与语境相符。", "安静": "语义：“安静”形容环境无声，与人才离开公司的惋惜语境不符。", "清楚": "搭配：“清楚”多修饰说明、想法，不能用来形容人才离职这件事。", "结实": "体貌：“结实”形容身体强壮或物品牢固，不能评价人才离开。"}, "sentence_index": 6, "correct_answer": "可惜"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这笔收入很可惜，比去年多了很多。", "explanation": "这里应该用〈可观〉。“可惜”表示惋惜、不应失去，形容数量多、收入丰厚要用“可观”。"}, {"text": "他说话的语气很可惜，我们都不想听。", "explanation": "这里应该用〈讨厌〉。“可惜”表示惋惜，不能用来形容令人反感的语气；说语气让人不愿听要用“讨厌”。"}, {"text": "这间屋子很可惜，又干净又明亮。", "explanation": "这里应该用〈漂亮〉。“可惜”表示惋惜，不能用来形容屋子的外观；夸赞屋子好看要用“漂亮”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b01eabee-5f23-40fb-bd13-a6b2189c2450') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88716, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这么好的书扔了，太可惜的。", "corrected_sentence": "这么好的书扔了，太可惜了。", "error_description": "错误：句末用“的”，“太可惜的”不能单独作谓语，感叹要用“了”。正确：“太可惜了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b01eabee-5f23-40fb-bd13-a6b2189c2450') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88716, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台电脑还能用，扔掉太很可惜。", "corrected_sentence": "这台电脑还能用，扔掉很可惜。", "error_description": "错误：“太”和“很”同时修饰“可惜”，程度副词不能重叠。正确：去掉“太”，说“扔掉很可惜”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b01eabee-5f23-40fb-bd13-a6b2189c2450') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
