INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88717, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "所有主是东西属于他的那个人。", "primary_collocate": null, "pronunciation": "suó yǒu zhǔ", "ipa": "suɔ˧˥ joʊ˨˩ ʈʂu˨˩", "syllable_count": 3, "sentences": [{"text": "谁是这辆自行车的所有主？", "target_word": "所有主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书的所有主把名字写在了第一页。", "target_word": "所有主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我捡到一把钥匙，想找它的所有主。", "target_word": "所有主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "所有主来了，他把自行车骑走了。", "target_word": "所有主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件外套的所有主是谁？请过来拿。", "target_word": "所有主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部手机的所有主是个年轻女孩。", "target_word": "所有主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只钱包的所有主一直在找它。", "target_word": "所有主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "照片里那辆车的所有主就是我爸爸。", "target_word": "所有主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师问：这支笔的所有主在哪儿？", "target_word": "所有主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "所有主不在家，我们不能进去。", "target_word": "所有主", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "某样东西属于的那个人,常用于寻找失物或确认归属", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34fd70d5-5710-4b08-aede-8a64d3f83331') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88717, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "所有主", "is_correct": true, "explanation": "正确：“所有主”指自行车属于的那个人，可以用“谁”来提问。"}, {"text": "轮胎", "is_correct": false, "explanation": "语义：轮胎是车的部件，不是人，不能回答“谁”。"}, {"text": "车铃", "is_correct": false, "explanation": "语义：车铃是物品，不能回答“谁”的提问。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不是人，“谁是……的颜色”不通。"}], "explanations": {"所有主": "正确：“所有主”指自行车属于的那个人，可以用“谁”来提问。", "轮胎": "语义：轮胎是车的部件，不是人，不能回答“谁”。", "车铃": "语义：车铃是物品，不能回答“谁”的提问。", "颜色": "语义：颜色不是人，“谁是……的颜色”不通。"}, "sentence_index": 0, "correct_answer": "所有主"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "一只所有主来了，他把自行车骑走了。", "explanation": "这里应该用〈位〉。“只”不用于指人，“所有主”指人时应说“一位所有主”。"}, {"text": "我是你的所有主，你要听我的。", "explanation": "“所有主”指财产或物品的所有者，不用于指人与人之间的关系。"}, {"text": "天空的所有主是太阳。", "explanation": "“所有主”指财产或物品的所有者，天空不是财产，不能说它有所有主。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ebf6d0a-6a0d-49ed-ba1e-53a310e30a00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88717, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "所有主", "is_correct": true, "explanation": "正确：“所有主”是钱包的所有者，会一直在找它。"}, {"text": "钞票", "is_correct": false, "explanation": "语义：钞票不会主动去找钱包。"}, {"text": "拉链", "is_correct": false, "explanation": "语义：拉链是钱包的部件，不能“找它”。"}, {"text": "口袋", "is_correct": false, "explanation": "语义：口袋没有主动行为，不能“一直在找”。"}], "explanations": {"所有主": "正确：“所有主”是钱包的所有者，会一直在找它。", "钞票": "语义：钞票不会主动去找钱包。", "拉链": "语义：拉链是钱包的部件，不能“找它”。", "口袋": "语义：口袋没有主动行为，不能“一直在找”。"}, "sentence_index": 6, "correct_answer": "所有主"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块地的一只所有主是老王。", "explanation": "这里应该用〈位〉。“只”用于动物或成对物品，不用来数人；指人时应说“一位所有主”。"}, {"text": "这栋房子的所有主是一只狗。", "explanation": "这里应该用〈人〉。“所有主”指拥有财产的人，狗不能拥有房子，所以不能这样说。"}, {"text": "这本书的所有主写了这本书。", "explanation": "这里应该用〈作者〉。“所有主”指拥有这本书的人，不是写书的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ebf6d0a-6a0d-49ed-ba1e-53a310e30a00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88717, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这把钥匙所有主是谁？", "corrected_sentence": "这把钥匙的所有主是谁？", "error_description": "错误：“钥匙”与“所有主”之间漏了“的”。正确应为“这把钥匙的所有主是谁？”。“的”连接定语与中心词，不能省略。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ebf6d0a-6a0d-49ed-ba1e-53a310e30a00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88717, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "谁是这把雨伞的一只所有主？", "corrected_sentence": "谁是这把雨伞的所有主？", "error_description": "错误：“所有主”指人，量词不能用“只”（“只”多用于动物或成对的物品）。应删去“一只”，为“谁是这把雨伞的所有主？”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ebf6d0a-6a0d-49ed-ba1e-53a310e30a00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
