INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88718, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "财产或物品的所有者。", "primary_collocate": null, "pronunciation": "suó yǒu zhǔ", "ipa": "suɔ˧˥ joʊ˨˩ ʈʂu˨˩", "syllable_count": 3, "sentences": [{"text": "这辆车的所有主是我的邻居。", "target_word": "所有主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房子的所有主必须在合同上签字。", "target_word": "所有主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察找到了这只钱包的所有主。", "target_word": "所有主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块地的所有主已经搬到国外了。", "target_word": "所有主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "失物招领处在找这把伞的所有主。", "target_word": "所有主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "所有主可以决定是否卖掉这套房子。", "target_word": "所有主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这幅画的所有主愿意借给博物馆展览。", "target_word": "所有主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车子坏了，修车前要先问所有主。", "target_word": "所有主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司想联系这栋楼的所有主。", "target_word": "所有主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老房子的所有主是一位老先生。", "target_word": "所有主", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "财产、物品的所有者,多用于房产、车辆、土地等", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34fd70d5-5710-4b08-aede-8a64d3f83331') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88718, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "所有主", "is_correct": true, "explanation": "正确：“所有主”指车的所有者，可以是我的邻居。"}, {"text": "车轮", "is_correct": false, "explanation": "语义：车轮是车的一部分，不是人，不能成为邻居。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“颜色”不能作“是我的邻居”的主语，不能指人。"}, {"text": "汽油", "is_correct": false, "explanation": "语义：汽油是燃料，不是人，不能成为邻居。"}], "explanations": {"所有主": "正确：“所有主”指车的所有者，可以是我的邻居。", "车轮": "语义：车轮是车的一部分，不是人，不能成为邻居。", "颜色": "搭配：“颜色”不能作“是我的邻居”的主语，不能指人。", "汽油": "语义：汽油是燃料，不是人，不能成为邻居。"}, "sentence_index": 0, "correct_answer": "所有主"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是我们家的所有主。", "explanation": "这里应该用〈主人〉。“所有主”专指财产或物品的所有者，不用于指一家之主。"}, {"text": "这个班级的所有主是老师。", "explanation": "“所有主”只用于财产或物品，班级不是财产，不能说它有所有主。"}, {"text": "他的所有主是父母。", "explanation": "“所有主”只用于财产或物品的所有者，人不是财产，不能说“他的所有主”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ebf6d0a-6a0d-49ed-ba1e-53a310e30a00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88718, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "所有主", "is_correct": true, "explanation": "正确：“所有主”是画的所有者，可以决定是否把画借出。"}, {"text": "颜料", "is_correct": false, "explanation": "语义：颜料没有意愿，不能“愿意借给博物馆展览”。"}, {"text": "墙壁", "is_correct": false, "explanation": "搭配：“借给博物馆展览”的对象应是可外借的物品，“墙壁”不能借出。"}, {"text": "边框", "is_correct": false, "explanation": "语义：边框是画的一部分，不能自己决定是否借出。"}], "explanations": {"所有主": "正确：“所有主”是画的所有者，可以决定是否把画借出。", "颜料": "语义：颜料没有意愿，不能“愿意借给博物馆展览”。", "墙壁": "搭配：“借给博物馆展览”的对象应是可外借的物品，“墙壁”不能借出。", "边框": "语义：边框是画的一部分，不能自己决定是否借出。"}, "sentence_index": 6, "correct_answer": "所有主"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这把伞的一只所有主是我的同学。", "explanation": "这里应该用〈个〉。“只”多用于动物或成对物品中的一个，不用来数人。"}, {"text": "这栋楼的所有主是在楼里打扫卫生的阿姨。", "explanation": "这里应该用〈清洁工〉。在楼里工作不等于拥有这栋楼，“所有主”指财产的拥有者。"}, {"text": "这幅画的所有主是画上的那朵花。", "explanation": "“所有主”指拥有财产的人或单位，画上的花不能拥有画。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ebf6d0a-6a0d-49ed-ba1e-53a310e30a00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88718, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这块表所有主是我的同学。", "corrected_sentence": "这块表的所有主是我的同学。", "error_description": "错误：“表”与“所有主”之间漏了“的”。正确应为“这块表的所有主是我的同学”。“的”连接定语“这块表”与中心词“所有主”，不能省略。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ebf6d0a-6a0d-49ed-ba1e-53a310e30a00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88718, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这栋楼的一只所有主是一家公司。", "corrected_sentence": "这栋楼的所有主是一家公司。", "error_description": "错误：“所有主”前多加了数量词“一只”。正确应为“这栋楼的所有主是一家公司”。“所有主”本身不需要数量词，“只”是动物量词，不能用来指人或单位。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ebf6d0a-6a0d-49ed-ba1e-53a310e30a00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
