INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88719, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "下级是在你下面、听你安排的人。", "primary_collocate": null, "pronunciation": "xià jí", "ipa": "ɕja˥˩ tɕi˧˥", "syllable_count": 2, "sentences": [{"text": "他对下级很好。", "target_word": "下级", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "经理给下级安排了工作。", "target_word": "下级", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "好老板会听下级的意见。", "target_word": "下级", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我有三个下级，他们都很努力。", "target_word": "下级", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他是我的下级，每天向我报告工作。", "target_word": "下级", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "不要对下级大声说话。", "target_word": "下级", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她从不让下级加班。", "target_word": "下级", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "下级做错了事，经理也要负责。", "target_word": "下级", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "王经理常常请下级一起吃饭。", "target_word": "下级", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位下级工作认真，大家都喜欢他。", "target_word": "下级", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "职位比你低、听你安排工作的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ade9d88-d052-4e2e-98ce-73f05ea25cfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88719, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "下级", "is_correct": true, "explanation": "下级：职位比你低、听你安排工作的人。"}, {"text": "夏季", "is_correct": false, "explanation": "xià jí 与 xià jì 第二音节声调不同（jí 第二声，jì 第四声），夏季指一年中的夏天。"}, {"text": "下机", "is_correct": false, "explanation": "xià jí 与 xià jī 第二音节声调不同（jí 第二声，jī 第一声），下机指下飞机。"}, {"text": "下棋", "is_correct": false, "explanation": "xià jí 与 xià qí 声母不同（j 与 q，声调都是第二声），下棋指下象棋或围棋。"}, {"text": "下移", "is_correct": false, "explanation": "xià jí 与 xià yí 声母不同（j 与 y，声调都是第二声），下移指向下移动，不指职务。"}, {"text": "县级", "is_correct": false, "explanation": "xià 与 xiàn 的韵尾不同（xiàn 多一个 n），声调相同；县级指县这一级的行政单位。"}], "explanations": {"下级": "下级：职位比你低、听你安排工作的人。", "夏季": "xià jí 与 xià jì 第二音节声调不同（jí 第二声，jì 第四声），夏季指一年中的夏天。", "下机": "xià jí 与 xià jī 第二音节声调不同（jí 第二声，jī 第一声），下机指下飞机。", "下棋": "xià jí 与 xià qí 声母不同（j 与 q，声调都是第二声），下棋指下象棋或围棋。", "下移": "xià jí 与 xià yí 声母不同（j 与 y，声调都是第二声），下移指向下移动，不指职务。", "县级": "xià 与 xiàn 的韵尾不同（xiàn 多一个 n），声调相同；县级指县这一级的行政单位。"}, "sentence_index": null, "correct_answer": "下级"}, "level_3": {"options": [{"text": "下级", "is_correct": true, "explanation": "正确：“对…很好”的对象是人，下级指听你安排工作的人，符合句意。"}, {"text": "经济", "is_correct": false, "explanation": "语义：“经济”是抽象概念，不能作“对…很好”的对象，句子不通。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“对…很好”常指善待某人，不说“对天气很好”。"}, {"text": "理论", "is_correct": false, "explanation": "语义：“理论”指知识体系，不能被“好”地对待，句子意思不通。"}], "explanations": {"下级": "正确：“对…很好”的对象是人，下级指听你安排工作的人，符合句意。", "经济": "语义：“经济”是抽象概念，不能作“对…很好”的对象，句子不通。", "天气": "搭配：“对…很好”常指善待某人，不说“对天气很好”。", "理论": "语义：“理论”指知识体系，不能被“好”地对待，句子意思不通。"}, "sentence_index": 0, "correct_answer": "下级"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我教的下级都很努力。", "explanation": "这里应该用〈学生〉。“下级”指在工作中听你安排的人，教过的学生不能叫下级。"}, {"text": "我的下级上小学了。", "explanation": "这里应该用〈孩子〉。“下级”只用于职务上的下属，不用来指自己的孩子。"}, {"text": "我每天都要向下级汇报工作。", "explanation": "这里应该用〈上级〉。汇报工作是向上级报告，“下级”的方向说反了。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c0075da-36bd-4801-a6e4-90bf3b8f3399') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88719, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "下级", "is_correct": true, "explanation": "正确：“让…加班”的对象是人，下级是需要听安排、可能加班的人，句意通顺。"}, {"text": "工资", "is_correct": false, "explanation": "语义：“工资”不是人，不能加班，句子意思不通。"}, {"text": "文件", "is_correct": false, "explanation": "语义：“文件”不能执行加班这一动作，句子不通。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：“窗户”不能加班，不能作“让”的对象。"}], "explanations": {"下级": "正确：“让…加班”的对象是人，下级是需要听安排、可能加班的人，句意通顺。", "工资": "语义：“工资”不是人，不能加班，句子意思不通。", "文件": "语义：“文件”不能执行加班这一动作，句子不通。", "窗户": "语义：“窗户”不能加班，不能作“让”的对象。"}, "sentence_index": 6, "correct_answer": "下级"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是我的下级，职位还比我高。", "explanation": "这里应该用〈上级〉。“下级”指职位比你低的人，句中却说职位比我高，前后自相矛盾。"}, {"text": "我的下级在学校教我们数学。", "explanation": "这里应该用〈老师〉。“下级”指在工作中听你安排的人，不指在学校传授知识的老师。"}, {"text": "我的下级是一只小狗，每天陪我散步。", "explanation": "这里应该用〈宠物〉。“下级”指人，不指动物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c0075da-36bd-4801-a6e4-90bf3b8f3399') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88719, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "组长有两只下级，都很努力。", "corrected_sentence": "组长有两名下级，都很努力。", "error_description": "量词错误：“下级”指人，应用“名”或“个”，不用“只”（“只”多用于动物）。正确形式是“两名下级”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c0075da-36bd-4801-a6e4-90bf3b8f3399') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88719, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条下级很努力，经理很喜欢他。", "corrected_sentence": "这位下级很努力，经理很喜欢他。", "error_description": "量词错误：“下级”指人，应用“位”或“个”，不用“条”（“条”多用于长条形的东西或鱼、狗等）。正确形式是“这位下级”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c0075da-36bd-4801-a6e4-90bf3b8f3399') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88720, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "上级", "is_correct": true, "explanation": "上级：组织中职位或级别较高的人或单位，与“下级”意思相反，是反义词。"}, {"text": "同事", "is_correct": false, "explanation": "同事指在同一单位工作的人，与“下级”没有反义关系。"}, {"text": "邻居", "is_correct": false, "explanation": "邻居指住在附近的人，与“下级”没有反义关系。"}, {"text": "亲戚", "is_correct": false, "explanation": "亲戚指有血缘或婚姻关系的人，与“下级”没有反义关系。"}], "correct_answer": "上级", "explanations": {"上级": "上级：组织中职位或级别较高的人或单位，与“下级”意思相反，是反义词。", "同事": "同事指在同一单位工作的人，与“下级”没有反义关系。", "邻居": "邻居指住在附近的人，与“下级”没有反义关系。", "亲戚": "亲戚指有血缘或婚姻关系的人，与“下级”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c0075da-36bd-4801-a6e4-90bf3b8f3399') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88720, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "上级", "is_correct": true, "explanation": "上级：组织中职位或级别较高的人或单位，与“下级”意思相反，是反义词。"}, {"text": "朋友", "is_correct": false, "explanation": "朋友指彼此友好、交往密切的人，与“下级”没有反义关系。"}, {"text": "老乡", "is_correct": false, "explanation": "老乡指同一地方的人，与“下级”没有反义关系。"}, {"text": "客人", "is_correct": false, "explanation": "客人指来访或做客的人，与“下级”没有反义关系。"}], "correct_answer": "上级", "explanations": {"上级": "上级：组织中职位或级别较高的人或单位，与“下级”意思相反，是反义词。", "朋友": "朋友指彼此友好、交往密切的人，与“下级”没有反义关系。", "老乡": "老乡指同一地方的人，与“下级”没有反义关系。", "客人": "客人指来访或做客的人，与“下级”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c0075da-36bd-4801-a6e4-90bf3b8f3399') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88720, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "组织中职位或级别较低的人或单位。", "primary_collocate": null, "pronunciation": "xià jí", "ipa": "ɕja˥˩ tɕi˧˥", "syllable_count": 2, "sentences": [{"text": "总公司把任务交给了各个下级。", "target_word": "下级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上级要关心下级，下级要尊重上级。", "target_word": "下级", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "区政府是市政府的下级。", "target_word": "下级", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "领导开会时，下级要认真记录。", "target_word": "下级", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下级要把工作情况告诉上级。", "target_word": "下级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军队里，下级必须听上级的命令。", "target_word": "下级", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "分公司是总公司的下级。", "target_word": "下级", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他当上了经理，下级也多了。", "target_word": "下级", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件事上级不知道，下级也没有说。", "target_word": "下级", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "各个系是学校的下级，要听学校的安排。", "target_word": "下级", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "个", "label": "量词"}, {"form": "下级单位", "label": "复合"}], "register": "中性", "sense_fingerprint": "组织中级别较低的人或单位，与上级相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ade9d88-d052-4e2e-98ce-73f05ea25cfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88720, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "下级", "is_correct": true, "explanation": "下级：组织中职位或级别较低的人或单位。"}, {"text": "夏季", "is_correct": false, "explanation": "xià jí 与 xià jì 第二音节声调不同（jí 第二声，jì 第四声），夏季指一年中的夏天。"}, {"text": "下机", "is_correct": false, "explanation": "xià jí 与 xià jī 第二音节声调不同（jí 第二声，jī 第一声），下机指下飞机。"}, {"text": "下棋", "is_correct": false, "explanation": "xià jí 与 xià qí 声母不同（j 与 q，声调都是第二声），下棋指下象棋或围棋。"}, {"text": "下移", "is_correct": false, "explanation": "xià jí 与 xià yí 声母不同（j 与 y，声调都是第二声），下移指向下移动，不指组织层级。"}, {"text": "县级", "is_correct": false, "explanation": "xià 与 xiàn 的韵尾不同（xiàn 多一个 n），声调相同；县级指县这一级的行政单位。"}], "explanations": {"下级": "下级：组织中职位或级别较低的人或单位。", "夏季": "xià jí 与 xià jì 第二音节声调不同（jí 第二声，jì 第四声），夏季指一年中的夏天。", "下机": "xià jí 与 xià jī 第二音节声调不同（jí 第二声，jī 第一声），下机指下飞机。", "下棋": "xià jí 与 xià qí 声母不同（j 与 q，声调都是第二声），下棋指下象棋或围棋。", "下移": "xià jí 与 xià yí 声母不同（j 与 y，声调都是第二声），下移指向下移动，不指组织层级。", "县级": "xià 与 xiàn 的韵尾不同（xiàn 多一个 n），声调相同；县级指县这一级的行政单位。"}, "sentence_index": null, "correct_answer": "下级"}, "level_3": {"options": [{"text": "下级", "is_correct": true, "explanation": "正确：“各个下级”指总公司之下的单位，能够接受任务，句意通顺。"}, {"text": "文件", "is_correct": false, "explanation": "语义：“文件”不能接受任务，“交给各个文件”句意不通。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：“窗户”不是能承担工作的单位，不能作接受任务的对象。"}, {"text": "天气", "is_correct": false, "explanation": "配价：“交给”后接的受者须能承担任务，“天气”不能作受者。"}], "explanations": {"下级": "正确：“各个下级”指总公司之下的单位，能够接受任务，句意通顺。", "文件": "语义：“文件”不能接受任务，“交给各个文件”句意不通。", "窗户": "语义：“窗户”不是能承担工作的单位，不能作接受任务的对象。", "天气": "配价：“交给”后接的受者须能承担任务，“天气”不能作受者。"}, "sentence_index": 0, "correct_answer": "下级"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "员工有问题应该先向下级请示。", "explanation": "这里应该用〈上级〉。请示是向上级请求指示，“下级”的方向说反了。"}, {"text": "子公司要向下级汇报工作。", "explanation": "这里应该用〈上级〉。子公司向管理它的单位汇报，应说“向上级汇报”，“下级”方向说反了。"}, {"text": "这笔经费要由下级审批。", "explanation": "这里应该用〈上级〉。审批经费要由更高一级的机关来做，“下级”指低一级的单位，方向说反了。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c0075da-36bd-4801-a6e4-90bf3b8f3399') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88720, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "下级", "is_correct": true, "explanation": "正确：分公司隶属于总公司，是总公司之下的下属单位，“下级”符合这一关系。"}, {"text": "上级", "is_correct": false, "explanation": "语义：分公司隶属于总公司，不能是总公司的上级，与事实相反。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“…的颜色”不能表示隶属关系，“分公司是总公司的颜色”说不通。"}, {"text": "老师", "is_correct": false, "explanation": "语义：“老师”指传授知识的人，不能用来说明分公司与总公司的隶属关系。"}], "explanations": {"下级": "正确：分公司隶属于总公司，是总公司之下的下属单位，“下级”符合这一关系。", "上级": "语义：分公司隶属于总公司，不能是总公司的上级，与事实相反。", "颜色": "搭配：“…的颜色”不能表示隶属关系，“分公司是总公司的颜色”说不通。", "老师": "语义：“老师”指传授知识的人，不能用来说明分公司与总公司的隶属关系。"}, "sentence_index": 6, "correct_answer": "下级"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这张桌子的下级放着一本书。", "explanation": "这里应该用〈下面〉。“下级”指组织中职位或级别较低的人或单位，不表示位置在下方。"}, {"text": "这家公司的下级是一台电脑。", "explanation": "这里应该用〈设备〉。“下级”指组织中的人或单位，不指物品。"}, {"text": "这条河的下级通向大海。", "explanation": "这里应该用〈下游〉。“下级”指组织中的人或单位，不指河流的方向。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c0075da-36bd-4801-a6e4-90bf3b8f3399') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88720, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家公司有三只下级，各自管理一个地区。", "corrected_sentence": "这家公司有三个下级，各自管理一个地区。", "error_description": "量词错误：“下级”指组织中的单位，应用“个”，不用“只”（“只”多用于动物）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c0075da-36bd-4801-a6e4-90bf3b8f3399') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88720, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "总公司有两台下级，分别在北京和上海。", "corrected_sentence": "总公司有两个下级，分别在北京和上海。", "error_description": "量词错误：“下级”指组织中的单位，应用“个”；“台”多用于机器，不能用于单位。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c0075da-36bd-4801-a6e4-90bf3b8f3399') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
