INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88721, 1, 'prompt1_core', '{"pos": "叹词", "semantic_class": "function", "definition": "哈是笑的时候发出的声音。", "primary_collocate": null, "pronunciation": "hā", "ipa": "xa˥", "syllable_count": 1, "sentences": [{"text": "他笑起来，哈哈哈，声音很大。", "target_word": "哈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书上写着“哈哈哈”，那是笑声。", "target_word": "哈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她一边看书一边哈哈笑。", "target_word": "哈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他听完这个笑话，哈哈地笑了起来。", "target_word": "哈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到“哈哈”的声音，我就知道是你。", "target_word": "哈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在门外哈哈地笑，吵得我睡不着。", "target_word": "哈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗的样子很可笑，我哈哈笑了出来。", "target_word": "哈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“哈！”他大笑一声，转身走了。", "target_word": "哈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友讲得太好笑了，我们笑得哈哈响。", "target_word": "哈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家看了电影，在路上哈哈笑个不停。", "target_word": "哈", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "哈哈", "label": "重叠"}], "register": "口语", "sense_fingerprint": "笑时发出的声音", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3de3ff09-fd2d-4605-9abd-d17a76935391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88721, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "哈", "is_correct": true, "explanation": "哈（hā）是笑时发出的声音，即本词。"}, {"text": "发", "is_correct": false, "explanation": "发（fā）与哈（hā）声母不同（f／h），意思是发出，不是笑声。"}, {"text": "喝", "is_correct": false, "explanation": "喝（hē）与哈（hā）韵母不同（e／a），意思是喝水。"}, {"text": "妈", "is_correct": false, "explanation": "妈（mā）与哈（hā）声母不同（m／h），意思是妈妈。"}], "explanations": {"哈": "哈（hā）是笑时发出的声音，即本词。", "发": "发（fā）与哈（hā）声母不同（f／h），意思是发出，不是笑声。", "喝": "喝（hē）与哈（hā）韵母不同（e／a），意思是喝水。", "妈": "妈（mā）与哈（hā）声母不同（m／h），意思是妈妈。"}, "sentence_index": null, "correct_answer": "哈"}, "level_3": {"options": [{"text": "哈", "is_correct": true, "explanation": "正确：第三个“哈”与前两个组成“哈哈哈”，正是笑声的描写。"}, {"text": "呜", "is_correct": false, "explanation": "语义：“呜”模拟哭声，与“笑起来”矛盾。"}, {"text": "嘘", "is_correct": false, "explanation": "语义：“嘘”表示让人安静，不是笑声。"}, {"text": "哟", "is_correct": false, "explanation": "搭配：“哈哈”后不能接“哟”组成笑声的连续描写。"}], "explanations": {"哈": "正确：第三个“哈”与前两个组成“哈哈哈”，正是笑声的描写。", "呜": "语义：“呜”模拟哭声，与“笑起来”矛盾。", "嘘": "语义：“嘘”表示让人安静，不是笑声。", "哟": "搭配：“哈哈”后不能接“哟”组成笑声的连续描写。"}, "sentence_index": 0, "correct_answer": "哈"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他不小心踩到脚，哈哈地叫了起来。", "explanation": "这里应该用〈哎哟〉。“哈哈”模拟笑声，因疼痛发出的叫声要用〈哎哟〉。"}, {"text": "他感冒了，哈哈地咳个不停。", "explanation": "这里应该用〈咳咳〉。“哈哈”模拟笑声，咳嗽的声音要用〈咳咳〉。"}, {"text": "下雨了，雨水哈哈地流下来。", "explanation": "这里应该用〈哗哗〉。“哈哈”模拟笑声，水流的声音要用〈哗哗〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff29ca3d-b11c-4277-8681-bb558e1e29c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88721, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "哈", "is_correct": true, "explanation": "哈（hā）是笑时发出的声音，即本词。"}, {"text": "吧", "is_correct": false, "explanation": "吧（bā）与哈（hā）声母不同（b／h），是语气词，不是笑声。"}, {"text": "他", "is_correct": false, "explanation": "他（tā）与哈（hā）声母不同（t／h），意思是他。"}, {"text": "拉", "is_correct": false, "explanation": "拉（lā）与哈（hā）声母不同（l／h），意思是拉动。"}, {"text": "嘎", "is_correct": false, "explanation": "嘎（gā）与哈（hā）声母不同（g／h），模拟的是鸭叫等声音，不是笑声。"}], "explanations": {"哈": "哈（hā）是笑时发出的声音，即本词。", "吧": "吧（bā）与哈（hā）声母不同（b／h），是语气词，不是笑声。", "他": "他（tā）与哈（hā）声母不同（t／h），意思是他。", "拉": "拉（lā）与哈（hā）声母不同（l／h），意思是拉动。", "嘎": "嘎（gā）与哈（hā）声母不同（g／h），模拟的是鸭叫等声音，不是笑声。"}, "sentence_index": null, "correct_answer": "哈"}, "level_3": {"options": [{"text": "哈", "is_correct": true, "explanation": "正确：“哈哈”正是笑的声音，与后面的“笑了出来”相符。"}, {"text": "嘘", "is_correct": false, "explanation": "语义：“嘘”表示让人安静的声音，与“笑了出来”矛盾。"}, {"text": "咦", "is_correct": false, "explanation": "语义：“咦”表示惊疑，不模拟笑声。"}, {"text": "哦", "is_correct": false, "explanation": "语义：“哦”表示恍然或应答，不模拟笑声。"}], "explanations": {"哈": "正确：“哈哈”正是笑的声音，与后面的“笑了出来”相符。", "嘘": "语义：“嘘”表示让人安静的声音，与“笑了出来”矛盾。", "咦": "语义：“咦”表示惊疑，不模拟笑声。", "哦": "语义：“哦”表示恍然或应答，不模拟笑声。"}, "sentence_index": 6, "correct_answer": "哈"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "小宝宝饿了，哈哈地哭个不停。", "explanation": "这里应该用〈哇哇〉。“哈哈”模拟笑声，婴儿哭的声音要用〈哇哇〉。"}, {"text": "墙上的钟哈哈作响，夜里特别安静。", "explanation": "这里应该用〈滴答〉。“哈哈”模拟笑声，钟表走动的声音要用〈滴答〉。"}, {"text": "有人在门外哈哈地敲了几下。", "explanation": "这里应该用〈咚咚〉。“哈哈”模拟笑声，敲门的声音要用〈咚咚〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff29ca3d-b11c-4277-8681-bb558e1e29c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88721, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他看着小猫的表演，哈哈的笑起来。", "corrected_sentence": "他看着小猫的表演，哈哈地笑起来。", "error_description": "错误在助词。“哈哈”作状语修饰动词“笑”，要用“地”，不能用“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff29ca3d-b11c-4277-8681-bb558e1e29c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88721, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们听完他的笑话，哈哈地笑下来。", "corrected_sentence": "我们听完他的笑话，哈哈地笑起来。", "error_description": "错误在补语。表示开始发笑并持续，应说“笑起来”，不能说“笑下来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff29ca3d-b11c-4277-8681-bb558e1e29c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
