INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88722, 1, 'prompt1_core', '{"pos": "叹词", "semantic_class": "function", "definition": "象声词，模拟笑声。", "primary_collocate": null, "pronunciation": "hā", "ipa": "xa˥", "syllable_count": 1, "sentences": [{"text": "他听了笑话，“哈”的一声笑了出来。", "target_word": "哈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到这个好消息，他哈哈大笑。", "target_word": "哈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们哈哈笑着跑出了教室。", "target_word": "哈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他笑得“哈哈”响，大家也都笑了。", "target_word": "哈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师讲了个笑话，同学们哈哈大笑。", "target_word": "哈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电话里传来哈哈的笑声。", "target_word": "哈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸看着电视，哈哈地笑个不停。", "target_word": "哈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明“哈”了一声，笑得很开心。", "target_word": "哈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们一听就哈哈笑起来了。", "target_word": "哈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她看到我的新帽子，哈哈笑了很久。", "target_word": "哈", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "哈哈", "label": "重叠"}], "register": "口语", "sense_fingerprint": "模拟笑声的象声词", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3de3ff09-fd2d-4605-9abd-d17a76935391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
