INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88722, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他看到小猫滑稽的样子，“哈”的一个笑了出来。", "corrected_sentence": "他看到小猫滑稽的样子，“哈”的一声笑了出来。", "error_description": "错误在量词。“哈”模拟笑声，计量这种声音要用量词“声”，应说““哈”的一声”，不能说““哈”的一个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff29ca3d-b11c-4277-8681-bb558e1e29c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88722, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大家听完他讲的故事，哈哈的大笑起来。", "corrected_sentence": "大家听完他讲的故事，哈哈大笑起来。", "error_description": "错误在助词。“哈哈”作状语修饰“大笑”，不能用“的”；可直接说“哈哈大笑起来”，或用“地”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff29ca3d-b11c-4277-8681-bb558e1e29c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
