INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88723, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54251e93-d74e-4fa7-93dc-f81bfb7fcd91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88723, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "打拍是用手或脚跟着音乐一下一下地敲。", "primary_collocate": null, "pronunciation": "dǎ pāi", "ipa": "ta˨˩˦ pʰaɪ˥˥", "syllable_count": 2, "sentences": [{"text": "孩子们跟着音乐一起打拍。", "target_word": "打拍", "complexity_tier": "T3", "furigana": "hái zi men gēn zhe yīn yuè yì qǐ dǎ pāi。", "sentence_source": "generated"}, {"text": "爸爸喜欢在桌上用手指打拍。", "target_word": "打拍", "complexity_tier": "T3", "furigana": "bà ba xǐ huan zài zhuō shàng yòng shǒu zhǐ dǎ pāi。", "sentence_source": "generated"}, {"text": "她听着歌，轻轻地用脚打拍。", "target_word": "打拍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们一起唱歌，老师在前面打拍。", "target_word": "打拍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明不会跳舞，但是很会打拍。", "target_word": "打拍", "complexity_tier": "T3", "furigana": "xiǎo míng bú huì tiào wǔ，dàn shì hěn huì dǎ pāi。", "sentence_source": "generated"}, {"text": "音乐一响，大家都跟着打拍。", "target_word": "打拍", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我弟弟一边听歌一边在腿上打拍。", "target_word": "打拍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你跟着我的手打拍。", "target_word": "打拍", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他打拍的时候，头也跟着动。", "target_word": "打拍", "complexity_tier": "T3", "furigana": "tā dǎ pāi de shí hou，tóu yě gēn zhe dòng。", "sentence_source": "generated"}, {"text": "音乐太快了，我跟不上，没法打拍。", "target_word": "打拍", "complexity_tier": "T3", "furigana": "yīn yuè tài kuài le，wǒ gēn bu shàng，méi fǎ dǎ pāi。", "sentence_source": "generated"}], "morphological_forms": [{"form": "打拍子", "label": "复合词"}, {"form": "打拍了", "label": "体标"}, {"form": "打着拍", "label": "体标"}, {"form": "打过拍", "label": "体标"}], "register": "中性", "sense_fingerprint": "用手或脚跟着音乐一下一下地敲（日常义）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9f9ac96-b38b-4ebd-b1f9-bb290722a815') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88723, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "打拍", "is_correct": true, "explanation": "正确：“孩子们跟着音乐一起打拍”符合语境，指用手或脚跟着音乐敲节奏。"}, {"text": "下雨", "is_correct": false, "explanation": "语义：“下雨”是天气现象，孩子们不能“跟着音乐一起下雨”。"}, {"text": "罚站", "is_correct": false, "explanation": "语义：“罚站”是一种惩罚，与“跟着音乐一起”的愉快语境矛盾。"}, {"text": "沉思", "is_correct": false, "explanation": "语域：“沉思”是书面化的说法，与口语化、活泼的音乐语境不协调。"}], "explanations": {"打拍": "正确：“孩子们跟着音乐一起打拍”符合语境，指用手或脚跟着音乐敲节奏。", "下雨": "语义：“下雨”是天气现象，孩子们不能“跟着音乐一起下雨”。", "罚站": "语义：“罚站”是一种惩罚，与“跟着音乐一起”的愉快语境矛盾。", "沉思": "语域：“沉思”是书面化的说法，与口语化、活泼的音乐语境不协调。"}, "sentence_index": 0, "correct_answer": "打拍"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "天上突然打拍了，孩子吓哭了。", "explanation": "这里应该用〈打雷〉。打雷是天空中的雷声，打拍是按节拍敲击，二者不能互换。"}, {"text": "他去井边打拍，桶都满了。", "explanation": "这里应该用〈打水〉。打水是从井里取水，打拍是按节拍敲击，二者不能互换。"}, {"text": "妈妈在厨房打拍，香味飘满了屋子。", "explanation": "这里应该用〈烧饭〉。烧饭是做饭，打拍是按节拍敲击，二者不能互换。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54251e93-d74e-4fa7-93dc-f81bfb7fcd91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88723, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "打拍", "is_correct": true, "explanation": "正确：“一边听歌一边在腿上打拍”指用手在腿上跟着节拍敲击，符合句意。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”是加热食物的动作，不能在腿上进行。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”需要食物，不能在腿上进行。"}, {"text": "吟诵", "is_correct": false, "explanation": "语域：“吟诵”是书面化的说法，与口语化的“听歌”语境不协调。"}], "explanations": {"打拍": "正确：“一边听歌一边在腿上打拍”指用手在腿上跟着节拍敲击，符合句意。", "煮": "语义：“煮”是加热食物的动作，不能在腿上进行。", "吃": "语义：“吃”需要食物，不能在腿上进行。", "吟诵": "语域：“吟诵”是书面化的说法，与口语化的“听歌”语境不协调。"}, "sentence_index": 6, "correct_answer": "打拍"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "医生给孩子打拍，孩子哭了。", "explanation": "这里应该用〈打针〉。给人注射要用打针，打拍是按节拍敲击。"}, {"text": "他困得直打拍，眼皮都抬不起来。", "explanation": "这里应该用〈打哈欠〉。打哈欠是张口吸气，打拍是按节拍敲击，二者不能互换。"}, {"text": "他在球场上打拍，投进了三个球。", "explanation": "这里应该用〈打球〉。投篮是打球，打拍是按节拍敲击。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54251e93-d74e-4fa7-93dc-f81bfb7fcd91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88723, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他一下一下得打拍。", "corrected_sentence": "他一下一下地打拍。", "error_description": "错误：“一下一下得打拍”。修饰动词的状语后应用“地”，“得”用于补语，正确为“一下一下地打拍”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54251e93-d74e-4fa7-93dc-f81bfb7fcd91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88723, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈一边做饭，一边桌上打拍。", "corrected_sentence": "妈妈一边做饭，一边在桌上打拍。", "error_description": "错误：“一边桌上打拍”。表示地点的“在”不能省略，应说“在桌上打拍”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54251e93-d74e-4fa7-93dc-f81bfb7fcd91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88724, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54251e93-d74e-4fa7-93dc-f81bfb7fcd91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88724, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54251e93-d74e-4fa7-93dc-f81bfb7fcd91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88724, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "按音乐的节拍用手或脚敲出节奏。", "primary_collocate": null, "pronunciation": "dǎ pāi", "ipa": "ta˨˩˦ pʰaɪ˥˥", "syllable_count": 2, "sentences": [{"text": "他跟着音乐用手打拍。", "target_word": "打拍", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师让我们一边唱歌，一边打拍。", "target_word": "打拍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用脚打拍，节奏很准。", "target_word": "打拍", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学钢琴的时候，我常常打拍。", "target_word": "打拍", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "听到这首歌，大家都不由自主地打拍。", "target_word": "打拍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一直在桌子上打拍，好像很开心。", "target_word": "打拍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他打拍打得很准。", "target_word": "打拍", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "音乐会上，很多人跟着节奏打拍。", "target_word": "打拍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你先听音乐，再用手打拍。", "target_word": "打拍", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "别用脚打拍了，会吵到邻居。", "target_word": "打拍", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "打拍子", "label": "复合词"}, {"form": "打拍了", "label": "体标"}, {"form": "打着拍", "label": "体标"}, {"form": "打过拍", "label": "体标"}], "register": "中性", "sense_fingerprint": "按音乐节拍用手或脚敲出节奏（动作义）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9f9ac96-b38b-4ebd-b1f9-bb290722a815') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88724, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "打拍", "is_correct": true, "explanation": "正确：“用手打拍”即用手跟着音乐的节拍敲出节奏，符合句意。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”不是用手跟着音乐敲节奏的动作，句意不通。"}, {"text": "唱", "is_correct": false, "explanation": "配价：“唱”不能以“手”为工具，不能说“用手唱”。"}, {"text": "咬", "is_correct": false, "explanation": "语义：“咬”不能表示用手跟着音乐敲节奏。"}], "explanations": {"打拍": "正确：“用手打拍”即用手跟着音乐的节拍敲出节奏，符合句意。", "吃": "语义：“吃”不是用手跟着音乐敲节奏的动作，句意不通。", "唱": "配价：“唱”不能以“手”为工具，不能说“用手唱”。", "咬": "语义：“咬”不能表示用手跟着音乐敲节奏。"}, "sentence_index": 0, "correct_answer": "打拍"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他困得直打拍，眼睛都睁不开了。", "explanation": "这里应该用〈打哈欠〉。打哈欠是张口吸气，打拍是按节拍敲出节奏，二者不能互换。"}, {"text": "孩子们在浴室打拍，把身上洗得干干净净。", "explanation": "这里应该用〈洗澡〉。洗澡是用水清洗身体，打拍是按节拍敲出节奏，二者不能互换。"}, {"text": "他看到老师，马上打拍。", "explanation": "这里应该用〈打招呼〉。打招呼是问候，打拍是按节拍敲出节奏，二者不能互换。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54251e93-d74e-4fa7-93dc-f81bfb7fcd91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88724, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "打拍", "is_correct": true, "explanation": "正确：“他打拍打得很准”，“打拍”指用手或脚跟着节拍敲击，符合句意。"}, {"text": "唱歌", "is_correct": false, "explanation": "配价：“唱歌”后面不能直接接“打得很准”，不能构成这样的补语结构。"}, {"text": "跳舞", "is_correct": false, "explanation": "搭配：“跳舞”与“打得很准”不搭配，不能说“跳舞打得很准”。"}, {"text": "吃饭", "is_correct": false, "explanation": "语义：“吃饭”与“打”的动作无关，句子语义不通。"}], "explanations": {"打拍": "正确：“他打拍打得很准”，“打拍”指用手或脚跟着节拍敲击，符合句意。", "唱歌": "配价：“唱歌”后面不能直接接“打得很准”，不能构成这样的补语结构。", "跳舞": "搭配：“跳舞”与“打得很准”不搭配，不能说“跳舞打得很准”。", "吃饭": "语义：“吃饭”与“打”的动作无关，句子语义不通。"}, "sentence_index": 6, "correct_answer": "打拍"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天用电脑打拍，写文章。", "explanation": "这里应该用〈打字〉。用电脑输入文字要用打字，打拍是按节拍敲出节奏。"}, {"text": "医生给孩子打拍，孩子哭了。", "explanation": "这里应该用〈打针〉。给人注射要用打针，打拍是按节拍敲出节奏。"}, {"text": "他在球场上打拍，投进了三个球。", "explanation": "这里应该用〈打球〉。投篮是打球，打拍是按节拍敲出节奏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54251e93-d74e-4fa7-93dc-f81bfb7fcd91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88724, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她打拍得很有节奏。", "corrected_sentence": "她打拍打得很有节奏。", "error_description": "错误：“打拍得很有节奏”。动词带补语时，宾语“拍”之后须重复动词，应说“打拍打得很有节奏”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54251e93-d74e-4fa7-93dc-f81bfb7fcd91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88724, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她跟着音乐打拍着，节奏很准。", "corrected_sentence": "她跟着音乐打着拍，节奏很准。", "error_description": "错误：“打拍着”。“打拍”是动宾式，“着”应紧跟动词“打”，正确为“打着拍”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54251e93-d74e-4fa7-93dc-f81bfb7fcd91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
