INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88725, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "坚决是心里想好了，一点也不改变。", "primary_collocate": null, "pronunciation": "jiān jué", "ipa": "tɕjɛn˥ tɕɥe˧˥", "syllable_count": 2, "sentences": [{"text": "他坚决不改主意，谁说也没用。", "target_word": "坚决", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我坚决要去，你别拦我。", "target_word": "坚决", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她心里很坚决，明天就走。", "target_word": "坚决", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈让他留下，他还是很坚决。", "target_word": "坚决", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我坚决不吃这家的菜了。", "target_word": "坚决", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的样子很坚决，不像在开玩笑。", "target_word": "坚决", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王坚决要自己做这件事。", "target_word": "坚决", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她说话的时候，眼神非常坚决。", "target_word": "坚决", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我坚决戒烟了，一支也不抽。", "target_word": "坚决", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他坚决地摇了摇头，不想再说。", "target_word": "坚决", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "堅決", "label": "繁体"}, {"form": "坚决地", "label": "状语形式"}], "register": "中性", "sense_fingerprint": "心意已定，决定不改变", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dae3ffb7-db8b-4484-bd04-e2dff1dba072') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88725, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "坚决", "is_correct": true, "explanation": "正确。“坚决”表示心意已定、不改变，与“谁说也没用”相符。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示不常发生，与“谁说也没用”所体现的坚持语境矛盾。"}, {"text": "慌忙", "is_correct": false, "explanation": "语义：“慌忙”指匆忙、着急，与“不改主意”的沉稳态度不合。"}, {"text": "热情", "is_correct": false, "explanation": "搭配：“热情”形容待人接物的态度，不能直接修饰“不改主意”这类表示坚定立场的说法。"}], "explanations": {"坚决": "正确。“坚决”表示心意已定、不改变，与“谁说也没用”相符。", "偶尔": "语义：“偶尔”表示不常发生，与“谁说也没用”所体现的坚持语境矛盾。", "慌忙": "语义：“慌忙”指匆忙、着急，与“不改主意”的沉稳态度不合。", "热情": "搭配：“热情”形容待人接物的态度，不能直接修饰“不改主意”这类表示坚定立场的说法。"}, "sentence_index": 0, "correct_answer": "坚决"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座老桥很坚决，经历了几十年的风雨仍然屹立不倒。", "explanation": "这里应该用〈坚固〉。坚决指心意或态度不动摇，形容桥这样的物体要用坚固。"}, {"text": "这块石头很坚决，用锤子也砸不开。", "explanation": "这里应该用〈坚硬〉。坚决说的是意志，形容石头的质地要用坚硬。"}, {"text": "这块布料很坚决，洗了很多次也不起毛。", "explanation": "这里应该用〈坚韧〉。坚决不用来说布料的耐用，布料耐磨要用坚韧。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5e5c281-0c49-4c3e-bf74-0497efde7322') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88725, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "坚决", "is_correct": true, "explanation": "正确。“坚决”表示态度坚定，与“要自己做这件事”的主动意愿相符。"}, {"text": "随意", "is_correct": false, "explanation": "语义：“随意”表示随便、不认真，与“要自己做这件事”的主动态度矛盾。"}, {"text": "犹豫", "is_correct": false, "explanation": "语义：“犹豫”表示拿不定主意，与“要自己做这件事”所体现的坚定意愿相矛盾。"}, {"text": "偶然", "is_correct": false, "explanation": "语义：“偶然”表示碰巧、不经意，与“要”所表达的有意愿相矛盾。"}], "explanations": {"坚决": "正确。“坚决”表示态度坚定，与“要自己做这件事”的主动意愿相符。", "随意": "语义：“随意”表示随便、不认真，与“要自己做这件事”的主动态度矛盾。", "犹豫": "语义：“犹豫”表示拿不定主意，与“要自己做这件事”所体现的坚定意愿相矛盾。", "偶然": "语义：“偶然”表示碰巧、不经意，与“要”所表达的有意愿相矛盾。"}, "sentence_index": 6, "correct_answer": "坚决"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的力气很坚决，一下子就推开了那扇门。", "explanation": "这里应该用〈有力〉。坚决说的是意志，不说力气；形容力气大要用有力。"}, {"text": "这根绳子很坚决，拉了几下就断了。", "explanation": "这里应该用〈结实〉。坚决形容意志，不用来说绳子的牢固程度。"}, {"text": "我坚决地知道明天会下雨。", "explanation": "这里应该用〈确定〉。坚决表示态度不动摇，不修饰“知道”这类认知动作；对明天下雨有把握要说〈确定〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5e5c281-0c49-4c3e-bf74-0497efde7322') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88725, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的态度非常坚决极了。", "corrected_sentence": "他的态度坚决极了。", "error_description": "错误在程度表达：“坚决”前用了“非常”，后面又加“极了”，程度重复。应去掉“非常”，改为“坚决极了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5e5c281-0c49-4c3e-bf74-0497efde7322') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88725, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她坚决的关上了门。", "corrected_sentence": "她坚决地关上了门。", "error_description": "错误在助词：“坚决”作状语修饰动词，后面要用“地”，不能用“的”，应为“坚决地关上了门”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5e5c281-0c49-4c3e-bf74-0497efde7322') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
