INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88726, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "态度或主张明确，不动摇。", "primary_collocate": null, "pronunciation": "jiān jué", "ipa": "tɕjɛn˥ tɕɥe˧˥", "syllable_count": 2, "sentences": [{"text": "我们坚决反对这个做法。", "target_word": "坚决", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师对作弊的态度很坚决。", "target_word": "坚决", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他坚决支持你的想法。", "target_word": "坚决", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司坚决不接受这样的条件。", "target_word": "坚决", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府坚决打击坏人坏事。", "target_word": "坚决", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的回答很坚决，没有一点犹豫。", "target_word": "坚决", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家坚决要求公开这件事。", "target_word": "坚决", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他坚决地说：“我不同意。”", "target_word": "坚决", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对这种错误，我们的态度必须坚决。", "target_word": "坚决", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我坚决站在你这一边。", "target_word": "坚决", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "堅決", "label": "繁体"}, {"form": "坚决地", "label": "状语形式"}], "register": "中性", "sense_fingerprint": "态度或主张明确，不动摇", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dae3ffb7-db8b-4484-bd04-e2dff1dba072') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88726, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "坚决", "is_correct": true, "explanation": "正确。“坚决”表示立场明确、不动摇，与“反对这个做法”相符。"}, {"text": "偶然", "is_correct": false, "explanation": "语义：“偶然”表示碰巧，与“反对”这种明确的立场矛盾。"}, {"text": "随便", "is_correct": false, "explanation": "语义：“随便”表示不认真、无所谓，与“反对这个做法”的立场冲突。"}, {"text": "热情", "is_correct": false, "explanation": "搭配：“热情”多修饰友好的动作，与“反对”这种对立态度不搭配。"}], "explanations": {"坚决": "正确。“坚决”表示立场明确、不动摇，与“反对这个做法”相符。", "偶然": "语义：“偶然”表示碰巧，与“反对”这种明确的立场矛盾。", "随便": "语义：“随便”表示不认真、无所谓，与“反对这个做法”的立场冲突。", "热情": "搭配：“热情”多修饰友好的动作，与“反对”这种对立态度不搭配。"}, "sentence_index": 0, "correct_answer": "坚决"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座大楼很坚决，经历了几十年的风雨仍然屹立不倒。", "explanation": "这里应该用〈坚固〉。坚决指态度不动摇，形容大楼这样的建筑要用坚固。"}, {"text": "这块石头很坚决，用锤子也砸不开。", "explanation": "这里应该用〈坚硬〉。坚决形容态度或主张，石头的质地要用坚硬。"}, {"text": "这把椅子很坚决，坐了很多年也不晃。", "explanation": "这里应该用〈结实〉。坚决说的是心意，椅子的牢固程度要用结实。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5e5c281-0c49-4c3e-bf74-0497efde7322') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88726, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "坚决", "is_correct": true, "explanation": "正确。“坚决”表示态度明确，与“要求公开这件事”的主张相符。"}, {"text": "慢吞吞", "is_correct": false, "explanation": "语义：“慢吞吞”表示没有急切的态度，与“要求公开”的主张矛盾。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示不常发生，与“要求”这种明确的主张不符。"}, {"text": "随意", "is_correct": false, "explanation": "语义：“随意”表示随便，与“要求公开这件事”的郑重主张不合。"}], "explanations": {"坚决": "正确。“坚决”表示态度明确，与“要求公开这件事”的主张相符。", "慢吞吞": "语义：“慢吞吞”表示没有急切的态度，与“要求公开”的主张矛盾。", "偶尔": "语义：“偶尔”表示不常发生，与“要求”这种明确的主张不符。", "随意": "语义：“随意”表示随便，与“要求公开这件事”的郑重主张不合。"}, "sentence_index": 6, "correct_answer": "坚决"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的力气很坚决，一下子就推开了那扇门。", "explanation": "这里应该用〈有力〉。坚决说的是态度，不说力气；形容力气要用有力。"}, {"text": "我坚决地知道明天会下雨。", "explanation": "这里应该用〈确定〉。坚决表示态度不动摇，不修饰“知道”这类认知动作；对明天下雨有把握要说〈确定〉。"}, {"text": "他坚决地睡着了，连闹钟都没听见。", "explanation": "这里应该用〈不知不觉〉。坚决表示有意的态度，睡着是无意发生的，要说〈不知不觉地睡着了〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5e5c281-0c49-4c3e-bf74-0497efde7322') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88726, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他说很坚决，没有一点犹豫。", "corrected_sentence": "他说得很坚决，没有一点犹豫。", "error_description": "错误在补语结构：“很坚决”作补语时，动词和补语之间要加“得”，正确说法是“说得很坚决”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5e5c281-0c49-4c3e-bf74-0497efde7322') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88726, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师的态度非常坚决地。", "corrected_sentence": "老师的态度非常坚决。", "error_description": "错误在“地”的使用：这里“坚决”作谓语，说明“态度”怎么样，后面不能加“地”。“坚决地”只用在动词前面作状语，比如“坚决地说”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5e5c281-0c49-4c3e-bf74-0497efde7322') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
