INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88727, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5e5c281-0c49-4c3e-bf74-0497efde7322') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88727, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "大要是一件事最主要的意思。", "primary_collocate": null, "pronunciation": "dà yào", "ipa": "ta⁵¹ jɑʊ⁵¹", "syllable_count": 2, "sentences": [{"text": "请用一句话说出这篇文章的大要。", "target_word": "大要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他只听了大要，没有听细节。", "target_word": "大要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们先写出故事的大要。", "target_word": "大要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书的大要，我已经记住了。", "target_word": "大要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你能告诉我会议的大要吗？", "target_word": "大要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看完信，我明白了事情的大要。", "target_word": "大要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份报告的大要只有三句话。", "target_word": "大要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很快读完课文，说出了大要。", "target_word": "大要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开会前，请先讲一下计划的大要。", "target_word": "大要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我只知道故事的大要，不知道结尾。", "target_word": "大要", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "一件事最主要的意思", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dae3ffb7-db8b-4484-bd04-e2dff1dba072') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88727, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "大要", "is_correct": true, "explanation": "正确。“大要”指内容的主要意思，可以用一句话说出，与这里的语境相符。"}, {"text": "插图", "is_correct": false, "explanation": "语义：插图是图画，不能用一句话“说出”，与“说出这篇文章的”搭配不成立。"}, {"text": "页码", "is_correct": false, "explanation": "语义：页码只是编号，没有可以说出的内容，与“用一句话说出”的语境不符。"}, {"text": "墨水", "is_correct": false, "explanation": "语义：墨水是书写用的液体，不是能“说出”的内容，与“这篇文章的”语境不符。"}], "explanations": {"大要": "正确。“大要”指内容的主要意思，可以用一句话说出，与这里的语境相符。", "插图": "语义：插图是图画，不能用一句话“说出”，与“说出这篇文章的”搭配不成立。", "页码": "语义：页码只是编号，没有可以说出的内容，与“用一句话说出”的语境不符。", "墨水": "语义：墨水是书写用的液体，不是能“说出”的内容，与“这篇文章的”语境不符。"}, "sentence_index": 0, "correct_answer": "大要"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把这部小说的大要整个背了下来，连每一段对话都能一字不差地复述。", "explanation": "这里应该用〈原文〉。大要只是主要意思，不包括每段对话的字句；一字不差地复述每段对话要用〈原文〉。"}, {"text": "我把这本书的一只大要抄在了笔记本上。", "explanation": "量词用错：〈只〉用于动物，不能用于大要。这里应该用〈份〉或〈段〉。"}, {"text": "他在大要里待了一个下午，谁也没打扰他。", "explanation": "这里把大要当成了地点，应该说“在房间里”。〈房间〉是空间，大要是抽象的内容，不能用“在……里”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5e5c281-0c49-4c3e-bf74-0497efde7322') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88727, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大要", "is_correct": true, "explanation": "正确。大要指报告的主要内容，可以只用三句话概括。"}, {"text": "门票", "is_correct": false, "explanation": "语义：门票是入场凭证，不是报告的内容，与“这份报告的”语境矛盾。"}, {"text": "标题", "is_correct": false, "explanation": "语义：标题通常只是一行字，不能说“只有三句话”。"}, {"text": "饭量", "is_correct": false, "explanation": "搭配：“三句话”计量的是语句，“饭量”是食量，不能用句子数来计量。"}], "explanations": {"大要": "正确。大要指报告的主要内容，可以只用三句话概括。", "门票": "语义：门票是入场凭证，不是报告的内容，与“这份报告的”语境矛盾。", "标题": "语义：标题通常只是一行字，不能说“只有三句话”。", "饭量": "搭配：“三句话”计量的是语句，“饭量”是食量，不能用句子数来计量。"}, "sentence_index": 6, "correct_answer": "大要"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这份报告的大要有三百页，连每个人的座位都标得清清楚楚。", "explanation": "这里应该用〈全文〉。大要只是简要的主要意思，不会有三百页、连座位都写到的细节；这种篇幅的材料是〈全文〉。"}, {"text": "老师给我们讲了一把大要，然后就让大家自己看书。", "explanation": "量词用错：〈把〉用于有柄的器具，大要是文字内容，应该用〈段〉或〈份〉。"}, {"text": "我把书放在大要的旁边，然后关灯睡觉了。", "explanation": "这里把大要当成了地点，应该说“在桌子旁边”。〈桌子〉是实物，大要是文字内容，不能用作方位参照。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5e5c281-0c49-4c3e-bf74-0497efde7322') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88727, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师发给我们一座大要。", "corrected_sentence": "老师发给我们一份大要。", "error_description": "错误在量词：“座”用于山、楼房等大型固定之物，“大要”是文字材料，量词应用“份”，不能用“座”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5e5c281-0c49-4c3e-bf74-0497efde7322') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88727, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我很快就看了完这份大要。", "corrected_sentence": "我很快就看完了这份大要。", "error_description": "错误在补语位置：“看完”是动补结构，“了”应放在补语之后，正确说法是“看完了”；“看了完”语序错误。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5e5c281-0c49-4c3e-bf74-0497efde7322') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
