INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88728, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "大概的内容;主要的意思。", "primary_collocate": null, "pronunciation": "dà yào", "ipa": "ta⁵¹ jɑʊ⁵¹", "syllable_count": 2, "sentences": [{"text": "你先把这件事的大要告诉我。", "target_word": "大要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影的大要是一个男孩寻找回家的路。", "target_word": "大要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "合同太长，我只看了大要。", "target_word": "大要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把旅行的大要写在日记里。", "target_word": "大要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这篇新闻的大要很容易懂。", "target_word": "大要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把比赛的大要告诉大家。", "target_word": "大要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我没时间细读，只看了书的大要。", "target_word": "大要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他讲了一下这个办法的大要。", "target_word": "大要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个故事的大要大家都知道。", "target_word": "大要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请写出你们的活动大要。", "target_word": "大要", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "大概的内容，主要的意思", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dae3ffb7-db8b-4484-bd04-e2dff1dba072') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88728, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "大要", "is_correct": true, "explanation": "正确。大要指事情的主要内容，可以先告诉对方，与这里的语境相符。"}, {"text": "插图", "is_correct": false, "explanation": "搭配：“告诉”的对象是信息，插图是图像，不能被告诉。"}, {"text": "页码", "is_correct": false, "explanation": "语义：页码是编号，不是事情的内容，与“这件事的”不相符。"}, {"text": "字数", "is_correct": false, "explanation": "语义：字数是文字的数量，不能用来说明一件事的情况。"}], "explanations": {"大要": "正确。大要指事情的主要内容，可以先告诉对方，与这里的语境相符。", "插图": "搭配：“告诉”的对象是信息，插图是图像，不能被告诉。", "页码": "语义：页码是编号，不是事情的内容，与“这件事的”不相符。", "字数": "语义：字数是文字的数量，不能用来说明一件事的情况。"}, "sentence_index": 0, "correct_answer": "大要"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这篇课文的大要我背得很熟，连每一句原话都能一字不差地说出来。", "explanation": "这里应该用〈原文〉。大要只是大概的内容，不包括每一句原话；一字不差地说出每句原话要用〈原文〉。"}, {"text": "他给我讲了一把旅行的大要。", "explanation": "量词用错：〈把〉用于有柄的器具，大要是讲述的内容，应该用〈段〉或〈份〉。"}, {"text": "他躲在大要后面哭了一场。", "explanation": "这里把大要当成了实物，应该说“躲在树后面”。〈树〉是实物，大要是抽象的内容，不能用来挡身。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5e5c281-0c49-4c3e-bf74-0497efde7322') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88728, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大要", "is_correct": true, "explanation": "正确。大要是书的主要内容，没时间细读时只看大要是合理的。"}, {"text": "饭菜", "is_correct": false, "explanation": "语义：饭菜是食物，不是书的内容，与“只看了书的”不相符。"}, {"text": "心跳", "is_correct": false, "explanation": "语义：心跳是身体的活动，不是可以“看”的内容，与“只看了书的”语境矛盾。"}, {"text": "音量", "is_correct": false, "explanation": "搭配：“看”的对象是文字或图像，“音量”是声音的大小，不能说“看音量”。"}], "explanations": {"大要": "正确。大要是书的主要内容，没时间细读时只看大要是合理的。", "饭菜": "语义：饭菜是食物，不是书的内容，与“只看了书的”不相符。", "心跳": "语义：心跳是身体的活动，不是可以“看”的内容，与“只看了书的”语境矛盾。", "音量": "搭配：“看”的对象是文字或图像，“音量”是声音的大小，不能说“看音量”。"}, "sentence_index": 6, "correct_answer": "大要"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把活动大要写成了三十页，连每个人的座位都标得清清楚楚。", "explanation": "这里应该用〈详细方案〉。大要是简要的概括；写成三十页、连座位都标出的是〈详细方案〉，不是大要。"}, {"text": "我们为活动准备了一只大要，放在桌子上等大家来取。", "explanation": "量词用错：〈只〉用于动物，大要应该用〈份〉。"}, {"text": "我们把这次会议的大要一字不差地抄进了笔记本，连发言人的停顿和咳嗽都记下来了。", "explanation": "这里应该用〈逐字记录〉。大要只是简要的概括；一字不差、连停顿和咳嗽都记下的是〈逐字记录〉，不是大要。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5e5c281-0c49-4c3e-bf74-0497efde7322') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88728, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他读了完这份计划的大要。", "corrected_sentence": "他读完了这份计划的大要。", "error_description": "错误在补语位置：“读完”是动补结构，“了”应放在补语之后，正确说法是“读完了”；“读了完”语序错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5e5c281-0c49-4c3e-bf74-0497efde7322') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88728, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他给我看了一根活动大要。", "corrected_sentence": "他给我看了一份活动大要。", "error_description": "错误在量词：“根”用于细长条状之物，“大要”是文字材料，量词应用“份”，不能用“根”。正确说法是“一份活动大要”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5e5c281-0c49-4c3e-bf74-0497efde7322') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88729, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c0075da-36bd-4801-a6e4-90bf3b8f3399') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88729, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c0075da-36bd-4801-a6e4-90bf3b8f3399') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88729, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "不可思议是太奇怪了，怎么想也想不通。", "primary_collocate": null, "pronunciation": "bù kě sī yì", "ipa": "pu˥˩ kʰɤ˨˩˦ sɹ̩˥ i˥˩", "syllable_count": 4, "sentences": [{"text": "门明明锁着，他怎么进来的？真不可思议。", "target_word": "不可思议", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他昨天还好好的，今天就走了，太不可思议了。", "target_word": "不可思议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题我想了很久，还是觉得不可思议。", "target_word": "不可思议", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "钥匙放在桌子上，现在不见了，真不可思议。", "target_word": "不可思议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们两个人的想法一样，不可思议。", "target_word": "不可思议", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他没学过画画，却画得这么好，不可思议。", "target_word": "不可思议", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这么大的房子，只住着一个人，不可思议。", "target_word": "不可思议", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个人说的话让我觉得不可思议。", "target_word": "不可思议", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们俩吵了一年，现在又成了好朋友，真不可思议。", "target_word": "不可思议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在沙漠里看到一条河，真不可思议。", "target_word": "不可思议", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "事情太奇怪，怎么想也想不明白", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ade9d88-d052-4e2e-98ce-73f05ea25cfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88729, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "不可思议", "is_correct": true, "explanation": "“不可思议”表示太奇怪、怎么想也想不通，与前文的疑问相符。"}, {"text": "干净", "is_correct": false, "explanation": "语义：“干净”说明整洁，与“门锁着，他怎么进来的”的疑问无关。"}, {"text": "安静", "is_correct": false, "explanation": "语义：“安静”形容环境或声音，不能用来回应门锁着却进来了的疑问。"}, {"text": "胖", "is_correct": false, "explanation": "语义：“胖”形容人或动物的身材，不能用来评价“锁着门却进来了”这件奇怪的事。"}], "explanations": {"不可思议": "“不可思议”表示太奇怪、怎么想也想不通，与前文的疑问相符。", "干净": "语义：“干净”说明整洁，与“门锁着，他怎么进来的”的疑问无关。", "安静": "语义：“安静”形容环境或声音，不能用来回应门锁着却进来了的疑问。", "胖": "语义：“胖”形容人或动物的身材，不能用来评价“锁着门却进来了”这件奇怪的事。"}, "sentence_index": 0, "correct_answer": "不可思议"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天早上七点起床，真不可思议。", "explanation": "这里应该用〈平常〉。每天按时起床是平常的事，“不可思议”指太奇怪、怎么想也想不通的事，不用于此。"}, {"text": "这张桌子高八十厘米，真不可思议。", "explanation": "这里“不可思议”被用来陈述普通的测量数据。桌子的高度可以直接量出来，“不可思议”指太奇怪、怎么想也想不通，不能用于此。"}, {"text": "他刷牙刷得很认真，真不可思议。", "explanation": "这里应该用〈平常〉。刷牙是平常的日常小事，“不可思议”指超出想象、难以理解的事，不用于此。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c0075da-36bd-4801-a6e4-90bf3b8f3399') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88729, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不可思议", "is_correct": true, "explanation": "“不可思议”表示奇怪、想不通，与前文的疑问相符。"}, {"text": "热闹", "is_correct": false, "explanation": "语义：“热闹”形容人多、吵闹，与“只住着一个人”矛盾。"}, {"text": "拥挤", "is_correct": false, "explanation": "语义：“拥挤”形容人或物太多，与“只住着一个人”矛盾。"}, {"text": "年轻", "is_correct": false, "explanation": "搭配：“年轻”多用于人的年龄，不说房子年轻。"}], "explanations": {"不可思议": "“不可思议”表示奇怪、想不通，与前文的疑问相符。", "热闹": "语义：“热闹”形容人多、吵闹，与“只住着一个人”矛盾。", "拥挤": "语义：“拥挤”形容人或物太多，与“只住着一个人”矛盾。", "年轻": "搭配：“年轻”多用于人的年龄，不说房子年轻。"}, "sentence_index": 6, "correct_answer": "不可思议"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天都按时吃饭，真不可思议。", "explanation": "这里应该用〈正常〉。按时吃饭是正常的事，“不可思议”指超出想象的事，这里用错了。"}, {"text": "他下班后回家做饭，真不可思议。", "explanation": "这里应该用〈平常〉。下班做饭是日常生活，“不可思议”指超出想象、难以理解的事，不用于此。"}, {"text": "这杯水是热的，真不可思议。", "explanation": "这里应该用〈寻常〉。热水是寻常的东西，“不可思议”指超出想象的事，不用来描述它。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c0075da-36bd-4801-a6e4-90bf3b8f3399') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88729, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我把钥匙放在抽屉里，现在却找不到，真很不可思议。", "corrected_sentence": "我把钥匙放在抽屉里，现在却找不到，真不可思议。", "error_description": "错误：“真很不可思议”。正确：“真不可思议”。“真”和“很”都表示程度，不能叠加使用。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c0075da-36bd-4801-a6e4-90bf3b8f3399') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88729, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "在沙漠里居然看到一个湖，真不可思议着。", "corrected_sentence": "在沙漠里居然看到一个湖，真不可思议。", "error_description": "错误：“不可思议着”。正确：“不可思议”。“着”表示动作或状态的持续，不能接在形容词“不可思议”后面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c0075da-36bd-4801-a6e4-90bf3b8f3399') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
