INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88730, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c0075da-36bd-4801-a6e4-90bf3b8f3399') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88730, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "无法想象，难以理解。", "primary_collocate": null, "pronunciation": "bù kě sī yì", "ipa": "pu˥˩ kʰɤ˨˩˦ sɹ̩˥ i˥˩", "syllable_count": 4, "sentences": [{"text": "这件事真是不可思议。", "target_word": "不可思议", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他一个人走完了那么远的路，太不可思议了。", "target_word": "不可思议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小孩会说五种语言，真不可思议。", "target_word": "不可思议", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你能一天看完这本书，真不可思议！", "target_word": "不可思议", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大海的美丽让人觉得不可思议。", "target_word": "不可思议", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这么冷的天他只穿一件衣服，不可思议。", "target_word": "不可思议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家发现了一个不可思议的现象。", "target_word": "不可思议", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的记忆力好得不可思议。", "target_word": "不可思议", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一只小鸟飞了几千公里回家，真让人觉得不可思议。", "target_word": "不可思议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个故事听起来不可思议，但是它是真的。", "target_word": "不可思议", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "事情超出想象，让人难以理解", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ade9d88-d052-4e2e-98ce-73f05ea25cfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88730, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "不可思议", "is_correct": true, "explanation": "“不可思议”表示事情超出想象、难以理解，符合句意。"}, {"text": "红", "is_correct": false, "explanation": "语义：“红”是颜色词，不能用来评价一件事。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：“椅子”是家具，不能用来评价一件事，句子不通。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：“桌子”是家具，不能用来评价一件事，句子不通。"}], "explanations": {"不可思议": "“不可思议”表示事情超出想象、难以理解，符合句意。", "红": "语义：“红”是颜色词，不能用来评价一件事。", "椅子": "语义：“椅子”是家具，不能用来评价一件事，句子不通。", "桌子": "语义：“桌子”是家具，不能用来评价一件事，句子不通。"}, "sentence_index": 0, "correct_answer": "不可思议"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我今天中午吃了一碗米饭，真不可思议。", "explanation": "这里应该用〈平常〉。吃一碗米饭是平常的事，“不可思议”指超出想象、难以理解的事，不用于此。"}, {"text": "公共汽车每天早上都从这里经过，真不可思议。", "explanation": "这里应该用〈普通〉。公共汽车按时经过是很普通的事，“不可思议”指无法想象、难以理解，不能用于此。"}, {"text": "这件事我早就知道了，真不可思议。", "explanation": "这里“不可思议”被当作〈出乎意料〉用。“出乎意料”指没想到，“不可思议”指难以想象、难以理解；早就知道的事并不超出想象，二者不能互换。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c0075da-36bd-4801-a6e4-90bf3b8f3399') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88730, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不可思议", "is_correct": true, "explanation": "“不可思议”修饰现象，表示难以想象，与句意相符。"}, {"text": "苦", "is_correct": false, "explanation": "语义：“苦”形容味道，不能用来修饰现象。"}, {"text": "矮", "is_correct": false, "explanation": "体貌：“矮”只描述人或物的高矮，不用于形容现象。"}, {"text": "年轻", "is_correct": false, "explanation": "搭配：“年轻”多用于人的年龄，不说现象年轻。"}], "explanations": {"不可思议": "“不可思议”修饰现象，表示难以想象，与句意相符。", "苦": "语义：“苦”形容味道，不能用来修饰现象。", "矮": "体貌：“矮”只描述人或物的高矮，不用于形容现象。", "年轻": "搭配：“年轻”多用于人的年龄，不说现象年轻。"}, "sentence_index": 6, "correct_answer": "不可思议"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我不确定明天会不会下雨，真不可思议。", "explanation": "这里“不可思议”被当作〈不确定〉用。“不确定”指没有把握，“不可思议”指超出想象、难以理解，说没把握时不能用它。"}, {"text": "我每天早上喝一杯牛奶，真不可思议。", "explanation": "这里“不可思议”被当作〈平常〉用。“平常”指日常习惯，“不可思议”指超出想象的事，喝牛奶这样的日常小事不能用它。"}, {"text": "这个房间有三扇门，真不可思议。", "explanation": "这里“不可思议”被当作〈普通〉用来陈述事实。门的数量可以直接数出来，“不可思议”指难以想象、难以理解，不能用于此。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c0075da-36bd-4801-a6e4-90bf3b8f3399') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88730, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这件事被不可思议，我没想到。", "corrected_sentence": "这件事真是不可思议，我没想到。", "error_description": "错误：“被不可思议”。正确：“真是不可思议”。“被”字句中的谓语需要动词，不能直接接形容词“不可思议”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c0075da-36bd-4801-a6e4-90bf3b8f3399') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88730, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的记忆力好地不可思议，大家都很佩服。", "corrected_sentence": "他的记忆力好得不可思议，大家都很佩服。", "error_description": "错误：“好地不可思议”。正确：“好得不可思议”。“好得……”是程度补语结构，补语前要用“得”，不能用“地”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c0075da-36bd-4801-a6e4-90bf3b8f3399') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
