INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88731, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "打断是别人正在做或说，你让他停下来。", "primary_collocate": null, "pronunciation": "dǎ duàn", "ipa": "tɑ˨˩˦ tuan˥˩", "syllable_count": 2, "sentences": [{"text": "老师在讲课，请不要打断他。", "target_word": "打断", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "别人说话的时候，不要随便打断。", "target_word": "打断", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我正在讲故事，弟弟突然打断了我。", "target_word": "打断", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他说得很快，我不好意思打断他。", "target_word": "打断", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈正在打电话，你别打断她。", "target_word": "打断", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "开会的时候，他一直打断别人的发言。", "target_word": "打断", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请让我说完，不要再打断我了。", "target_word": "打断", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她说到一半，我忍不住打断了她。", "target_word": "打断", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小孩总是打断大人的谈话，这样不太礼貌。", "target_word": "打断", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你还没说完，我就打断了你，对不起。", "target_word": "打断", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "打断了", "label": "体标（了）"}, {"form": "打断过", "label": "体标（过）"}, {"form": "打斷", "label": "繁体"}], "register": "中性", "sense_fingerprint": "打断：别人说话或做事时中途插话，让他停下来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ddf0a86-9417-4ade-a111-6e198f133eb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88731, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "打断", "is_correct": true, "explanation": "打断（dǎ duàn）：中途插话，使正在说话或做事的人停下来。"}, {"text": "打乱", "is_correct": false, "explanation": "luàn 与 duàn 声母不同（l/d），意思是扰乱、弄乱，不是中途插话。"}, {"text": "打算", "is_correct": false, "explanation": "suàn 与 duàn 声母不同（s/d），意思是计划或打算。"}, {"text": "大段", "is_correct": false, "explanation": "dà（第四声）与 dǎ（第三声）声调不同，意思是较长的一段。"}], "explanations": {"打断": "打断（dǎ duàn）：中途插话，使正在说话或做事的人停下来。", "打乱": "luàn 与 duàn 声母不同（l/d），意思是扰乱、弄乱，不是中途插话。", "打算": "suàn 与 duàn 声母不同（s/d），意思是计划或打算。", "大段": "dà（第四声）与 dǎ（第三声）声调不同，意思是较长的一段。"}, "sentence_index": null, "correct_answer": "打断"}, "level_3": {"options": [{"text": "打断", "is_correct": true, "explanation": "打断：中途插话，符合「请不要……他」让老师不被打扰的语境。"}, {"text": "参观", "is_correct": false, "explanation": "搭配：「参观」的对象是场所或展览，不能用于人。"}, {"text": "复印", "is_correct": false, "explanation": "搭配：「复印」的对象是文件或材料，不能用于人。"}, {"text": "欢送", "is_correct": false, "explanation": "语义：「欢送」指送别离开的人，与「老师在讲课」的语境不合。"}], "explanations": {"打断": "打断：中途插话，符合「请不要……他」让老师不被打扰的语境。", "参观": "搭配：「参观」的对象是场所或展览，不能用于人。", "复印": "搭配：「复印」的对象是文件或材料，不能用于人。", "欢送": "语义：「欢送」指送别离开的人，与「老师在讲课」的语境不合。"}, "sentence_index": 0, "correct_answer": "打断"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位运动员终于打断了世界纪录。", "explanation": "这里应该用〈打破〉。打破可用于纪录、沉默，打断只用于中途截住正在进行的讲话或活动。"}, {"text": "双方的谈判终于打断了僵局。", "explanation": "这里应该用〈打破〉。打破可用于僵局、纪录，打断表示中途截住正在进行的讲话或活动，不能用于僵局。"}, {"text": "这份合同终于被打断了。", "explanation": "这里应该用〈终止〉。终止用于合同、协议，打断只表示中途截住讲话或正在进行的活动，不能用于合同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd55f774-744e-4867-8748-d72ae34848bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88731, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "打断", "is_correct": true, "explanation": "打断：中途插话，与「请让我说完」的语境一致。"}, {"text": "原谅", "is_correct": false, "explanation": "语义：「不要再原谅我」与「请让我说完」的语境无关，句子读来不通。"}, {"text": "翻译", "is_correct": false, "explanation": "搭配：「翻译」的对象是语言或文字，不能说「翻译我」。"}, {"text": "叫醒", "is_correct": false, "explanation": "语义：「叫醒」指唤醒睡着的人，与「请让我说完」的语境冲突。"}], "explanations": {"打断": "打断：中途插话，与「请让我说完」的语境一致。", "原谅": "语义：「不要再原谅我」与「请让我说完」的语境无关，句子读来不通。", "翻译": "搭配：「翻译」的对象是语言或文字，不能说「翻译我」。", "叫醒": "语义：「叫醒」指唤醒睡着的人，与「请让我说完」的语境冲突。"}, "sentence_index": 6, "correct_answer": "打断"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位选手在决赛中打断了金牌。", "explanation": "这里应该用〈夺得〉。夺得用于金牌、冠军，打断只表示中途截住讲话或正在进行的活动，不能用于金牌。"}, {"text": "他轻轻打断了房门。", "explanation": "这里应该用〈打开〉。打开用于门窗、箱包，打断表示使正在进行的事中止，不能用于门。"}, {"text": "他向邻居打断了情况。", "explanation": "这里应该用〈打听〉。打听指探问消息，打断不能搭配「情况」表示探问。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd55f774-744e-4867-8748-d72ae34848bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88731, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师讲得很快，我只打断他一个。", "corrected_sentence": "老师讲得很快，我只打断他一次。", "error_description": "错误：动量词用「个」，正确应为「次」。「打断」计次数时用「次」，不能用「个」计量，应说「打断他一次」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd55f774-744e-4867-8748-d72ae34848bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88731, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她正在讲话，我没有打断着她。", "corrected_sentence": "她正在讲话，我没有打断她。", "error_description": "「着」表示动作持续，与否定句「没有打断她」所表示的未发生的动作不相容，应去掉「着」，说「没有打断她」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd55f774-744e-4867-8748-d72ae34848bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88732, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd55f774-744e-4867-8748-d72ae34848bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
