INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88732, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "使正在进行的事情中断。", "primary_collocate": null, "pronunciation": "dǎ duàn", "ipa": "tɑ˨˩˦ tuan˥˩", "syllable_count": 2, "sentences": [{"text": "会议开到一半，突然停电打断了讨论。", "target_word": "打断", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他正在写报告，一个电话打断了他的思路。", "target_word": "打断", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球赛正踢到一半，大雨打断了比赛。", "target_word": "打断", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我正睡得香，门铃声打断了我的午睡。", "target_word": "打断", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈正在看书，孩子的哭声打断了她。", "target_word": "打断", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他每天都练琴，这次生病打断了他的练习。", "target_word": "打断", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老板一进来，就打断了大家的讨论。", "target_word": "打断", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学习时，他把手机关了，免得电话打断自己的学习。", "target_word": "打断", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试时窗外有噪音，打断了大家的思考。", "target_word": "打断", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争打断了这座城市的发展。", "target_word": "打断", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "打断了", "label": "体标（了）"}, {"form": "打断过", "label": "体标（过）"}, {"form": "打斷", "label": "繁体"}], "register": "中性", "sense_fingerprint": "打断：使正在进行的事情（会议、比赛、工作等）中途停止", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ddf0a86-9417-4ade-a111-6e198f133eb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88732, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "打断", "is_correct": true, "explanation": "打断（dǎ duàn）：使正在进行的事情中途停止。"}, {"text": "打乱", "is_correct": false, "explanation": "luàn 与 duàn 声母不同（l/d），意思是扰乱、弄乱。"}, {"text": "打算", "is_correct": false, "explanation": "suàn 与 duàn 声母不同（s/d），意思是计划。"}, {"text": "大段", "is_correct": false, "explanation": "dà（第四声）与 dǎ（第三声）声调不同，意思是较长的一段。"}], "explanations": {"打断": "打断（dǎ duàn）：使正在进行的事情中途停止。", "打乱": "luàn 与 duàn 声母不同（l/d），意思是扰乱、弄乱。", "打算": "suàn 与 duàn 声母不同（s/d），意思是计划。", "大段": "dà（第四声）与 dǎ（第三声）声调不同，意思是较长的一段。"}, "sentence_index": null, "correct_answer": "打断"}, "level_3": {"options": [{"text": "打断", "is_correct": true, "explanation": "打断：使正在进行的讨论中途停止，符合「停电」造成中断的语境。"}, {"text": "组织", "is_correct": false, "explanation": "语义：停电不能「组织」讨论，主语与动作不合。"}, {"text": "参加", "is_correct": false, "explanation": "语义：停电不是讨论的参与者，不能「参加」讨论。"}, {"text": "赞同", "is_correct": false, "explanation": "搭配：「赞同」搭配观点、建议，不能说「赞同讨论」。"}], "explanations": {"打断": "打断：使正在进行的讨论中途停止，符合「停电」造成中断的语境。", "组织": "语义：停电不能「组织」讨论，主语与动作不合。", "参加": "语义：停电不是讨论的参与者，不能「参加」讨论。", "赞同": "搭配：「赞同」搭配观点、建议，不能说「赞同讨论」。"}, "sentence_index": 0, "correct_answer": "打断"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在比赛中打断了奖牌。", "explanation": "这里应该用〈赢得〉。赢得用于奖牌、冠军，打断表示使正在进行的事情中途停止，不能用于奖牌。"}, {"text": "这场地震打断了这座城市的人口。", "explanation": "这里应该用〈减少〉。减少用于人口，打断表示使正在进行的事情中途停止，不能用于人口。"}, {"text": "他终于打断了疾病。", "explanation": "这里应该用〈战胜〉。战胜用于疾病、对手，打断表示使正在进行的事情中途停止，疾病不是进行中的事情，不能用于打断。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd55f774-744e-4867-8748-d72ae34848bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88732, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "打断", "is_correct": true, "explanation": "打断：使正在进行的讨论中途停止，符合「老板一进来」的语境。"}, {"text": "偷走", "is_correct": false, "explanation": "语义：「偷走」指拿走他人的财物，不能用于「讨论」。"}, {"text": "撕毁", "is_correct": false, "explanation": "搭配：「撕毁」的对象是合同、条约等文件，不能说「撕毁讨论」。"}, {"text": "吃掉", "is_correct": false, "explanation": "语义：「吃掉」指把食物咽下，与「讨论」不搭。"}], "explanations": {"打断": "打断：使正在进行的讨论中途停止，符合「老板一进来」的语境。", "偷走": "语义：「偷走」指拿走他人的财物，不能用于「讨论」。", "撕毁": "搭配：「撕毁」的对象是合同、条约等文件，不能说「撕毁讨论」。", "吃掉": "语义：「吃掉」指把食物咽下，与「讨论」不搭。"}, "sentence_index": 6, "correct_answer": "打断"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他向朋友打断了消息。", "explanation": "这里应该用〈打听〉。打听指探问消息，打断表示使正在进行的事中止，不能用于消息。"}, {"text": "工人们正在打断一艘新船。", "explanation": "这里应该用〈打造〉。打造指制作，打断不表示制造船只。"}, {"text": "他用看书打断时间。", "explanation": "这里应该用〈打发〉。打发指消磨时间，打断不能搭配「时间」表示消磨。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd55f774-744e-4867-8748-d72ae34848bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88732, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "突然停电打断着我们的比赛。", "corrected_sentence": "突然停电打断了我们的比赛。", "error_description": "「突然」表示一次性的事件，与表示持续的「着」矛盾，应用「了」表示已经发生的中断：「突然停电打断了我们的比赛」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd55f774-744e-4867-8748-d72ae34848bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88732, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一场大雨被打断了我们的散步。", "corrected_sentence": "一场大雨打断了我们的散步。", "error_description": "被动句语序错误：受事「我们的散步」应放在「被」前，施事「一场大雨」应放在「被」后。应说「一场大雨打断了我们的散步」，或「我们的散步被一场大雨打断了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd55f774-744e-4867-8748-d72ae34848bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
