INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88734, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "有多方面才能。", "primary_collocate": null, "pronunciation": "duō cái", "ipa": "tuo˥ tsʰai˧˥", "syllable_count": 2, "sentences": [{"text": "这位作家多才，写诗、写小说，还能作曲。", "target_word": "多才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是一位多才的艺术家，能画画，也能作曲。", "target_word": "多才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李多才，学校的演出都请他来帮忙。", "target_word": "多才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位多才的医生，也是一位有名的画家。", "target_word": "多才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她多才，成绩好，又会唱歌，又会跳舞。", "target_word": "多才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古代有不少多才的文人，既会写诗，又会画画。", "target_word": "多才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不但聪明，而且多才，大家都很佩服他。", "target_word": "多才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多才的她，既能教书，又能写文章。", "target_word": "多才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "校长多才，常常自己写歌，自己唱。", "target_word": "多才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个多才的年轻人，建筑、音乐、写作都很出色。", "target_word": "多才", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "多才多艺", "label": "复合"}], "register": "书面", "sense_fingerprint": "有多方面才能", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3de3ff09-fd2d-4605-9abd-d17a76935391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88734, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "多才", "is_correct": true, "explanation": "正确：“多才”指有多方面才能，与“写诗、写小说，还能作曲”相符。"}, {"text": "专精", "is_correct": false, "explanation": "语义：“专精”指专攻一门，与“写诗、写小说，还能作曲”的多方面才能矛盾。"}, {"text": "单一", "is_correct": false, "explanation": "语义：“单一”指只有一种，与后面列举的多种创作不符。"}, {"text": "单调", "is_correct": false, "explanation": "搭配：“单调”多形容生活、内容，不用来形容人的才能。"}], "explanations": {"多才": "正确：“多才”指有多方面才能，与“写诗、写小说，还能作曲”相符。", "专精": "语义：“专精”指专攻一门，与“写诗、写小说，还能作曲”的多方面才能矛盾。", "单一": "语义：“单一”指只有一种，与后面列举的多种创作不符。", "单调": "搭配：“单调”多形容生活、内容，不用来形容人的才能。"}, "sentence_index": 0, "correct_answer": "多才"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位老教授的身体很多才，每天都能跑十公里。", "explanation": "这里应该用〈健壮〉。“多才”指会的东西多，不能用来形容身体，形容身体强壮要用〈健壮〉。"}, {"text": "这家饭馆很多才，菜单上有四十多道菜。", "explanation": "这里应该用〈丰富〉。“多才”只形容人的才能，形容饭馆的菜式多要用〈丰富〉。"}, {"text": "这间房子很多才，一共有三个房间。", "explanation": "这里应该用〈宽敞〉。“多才”只形容人会的东西多，形容房间的空间大要用〈宽敞〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff29ca3d-b11c-4277-8681-bb558e1e29c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88734, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "多才", "is_correct": true, "explanation": "正确：“不但……而且”后接褒扬的才能，“多才”与前面的“聪明”并列，语气通顺。"}, {"text": "愚钝", "is_correct": false, "explanation": "语义：“愚钝”是贬义，与“不但聪明”相反，无法并列。"}, {"text": "平凡", "is_correct": false, "explanation": "语义：“平凡”指普通，与“不但聪明，而且”的递进语气不符，大家也不会因此佩服。"}, {"text": "懒散", "is_correct": false, "explanation": "搭配：“懒散”是贬义，与前面的“聪明”不能在“不但……而且”中并列，也不能引出“大家都很佩服他”。"}], "explanations": {"多才": "正确：“不但……而且”后接褒扬的才能，“多才”与前面的“聪明”并列，语气通顺。", "愚钝": "语义：“愚钝”是贬义，与“不但聪明”相反，无法并列。", "平凡": "语义：“平凡”指普通，与“不但聪明，而且”的递进语气不符，大家也不会因此佩服。", "懒散": "搭配：“懒散”是贬义，与前面的“聪明”不能在“不但……而且”中并列，也不能引出“大家都很佩服他”。"}, "sentence_index": 6, "correct_answer": "多才"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个年轻人的性格很多才，见了谁都打招呼。", "explanation": "这里应该用〈热情〉。“多才”指会的东西多，不能用来形容性格，形容待人友好要用〈热情〉。"}, {"text": "这位学者做研究的态度很多才，从不马虎。", "explanation": "这里应该用〈严谨〉。“多才”指会的东西多，不能用来形容态度，形容做研究细致认真要用〈严谨〉。"}, {"text": "他说话的风格很多才，常常讲笑话。", "explanation": "这里应该用〈幽默〉。“多才”指会的东西多，不能用来形容说话风格，形容风趣爱讲笑话要用〈幽默〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff29ca3d-b11c-4277-8681-bb558e1e29c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88734, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位画家很多才着，既会画油画，也会写书法。", "corrected_sentence": "这位画家很多才，既会画油画，也会写书法。", "error_description": "错误在体标。“多才”是表示性质的形容词，后面不能加“着”，应删去“着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff29ca3d-b11c-4277-8681-bb558e1e29c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88734, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位同学很多才很，既会弹琴，又会写诗。", "corrected_sentence": "这位同学很多才，既会弹琴，又会写诗。", "error_description": "错误在程度副词的重复。“很多才”中已有“很”修饰，“才”后面不能再加“很”，应删去多余的“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff29ca3d-b11c-4277-8681-bb558e1e29c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
