INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88735, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "怎么了是问发生了什么事。", "primary_collocate": null, "pronunciation": "zěn me le", "ipa": "ʈʂən˨˩ mə lə", "syllable_count": 3, "sentences": [{"text": "你的脸色不好，怎么了？", "target_word": "怎么了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到哭声，妈妈跑来问：“怎么了？”", "target_word": "怎么了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一进门就问我怎么了。", "target_word": "怎么了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的电脑怎么了？打不开了。", "target_word": "怎么了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明，你怎么了？", "target_word": "怎么了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都在笑，到底怎么了？", "target_word": "怎么了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不说话，我不知道她怎么了。", "target_word": "怎么了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外面这么吵，怎么了？", "target_word": "怎么了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的手怎么了？流血了。", "target_word": "怎么了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师看见我低着头，问我怎么了。", "target_word": "怎么了", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "口语疑问，问发生了什么事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67aa835c-524f-4aad-8e43-c58392166a3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88735, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "怎么了", "is_correct": true, "explanation": "正确：问脸色不好的原因，即“发生了什么事”。"}, {"text": "谁", "is_correct": false, "explanation": "语义：“谁”问的是人，而句子问的是脸色不好的原因，不是问人。"}, {"text": "什么时候", "is_correct": false, "explanation": "语义：“什么时候”问时间，句子问的是状况，与时间无关。"}, {"text": "哪一个", "is_correct": false, "explanation": "搭配：“哪一个”要在可选范围内使用，句中没有可供选择的对象。"}], "explanations": {"怎么了": "正确：问脸色不好的原因，即“发生了什么事”。", "谁": "语义：“谁”问的是人，而句子问的是脸色不好的原因，不是问人。", "什么时候": "语义：“什么时候”问时间，句子问的是状况，与时间无关。", "哪一个": "搭配：“哪一个”要在可选范围内使用，句中没有可供选择的对象。"}, "sentence_index": 0, "correct_answer": "怎么了"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我问他旅行怎么了，他说玩得很开心。", "explanation": "这里应该用〈怎么样〉。问旅行的情况应用怎么样；怎么了预设出了问题，而回答说玩得很开心，前后矛盾。"}, {"text": "我穿这件新衣服怎么了？好看吗？", "explanation": "这里应该用〈怎么样〉。问别人的看法、好不好看要用怎么样；怎么了问出了什么事。"}, {"text": "明天的天气怎么了？会下雨吗？", "explanation": "这里应该用〈怎么样〉。问还没发生的情况要用怎么样；怎么了问已经发生了什么事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8331ff59-ca01-46b3-a95a-7fe76d3603d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88735, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "怎么了", "is_correct": true, "explanation": "正确：间接问她出了什么状况，句中的“怎么了”指“发生了什么事”。"}, {"text": "哪儿", "is_correct": false, "explanation": "语义：“哪儿”问地点，句子问的是她的状况，与地点无关。"}, {"text": "什么", "is_correct": false, "explanation": "配价：“她什么”缺少谓语，宾语位置只放“什么”，句子不成立。"}, {"text": "几点", "is_correct": false, "explanation": "语义：“几点”问时间，句子问的是她的情况，与时间无关。"}], "explanations": {"怎么了": "正确：间接问她出了什么状况，句中的“怎么了”指“发生了什么事”。", "哪儿": "语义：“哪儿”问地点，句子问的是她的状况，与地点无关。", "什么": "配价：“她什么”缺少谓语，宾语位置只放“什么”，句子不成立。", "几点": "语义：“几点”问时间，句子问的是她的情况，与时间无关。"}, "sentence_index": 6, "correct_answer": "怎么了"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们周末去看电影，你觉得怎么了？", "explanation": "这里应该用〈怎么样〉。提建议、问对方意见要用怎么样；怎么了问发生了什么事。"}, {"text": "你觉得这本书怎么了？好看吗？", "explanation": "这里应该用〈怎么样〉。问评价要用怎么样；怎么了问出了什么问题。"}, {"text": "你好！好久不见，最近怎么了？", "explanation": "这里应该用〈怎么样〉。见面问候近况要用“最近怎么样”；怎么了预设出了问题。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8331ff59-ca01-46b3-a95a-7fe76d3603d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88735, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "车突然停了，司机怎么了了？", "corrected_sentence": "车突然停了，司机怎么了？", "error_description": "错误：“怎么了”的“了”重复，写成“怎么了了”。正确应为“怎么了”，句末的“了”已包含在“怎么了”中，不能再加一个“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8331ff59-ca01-46b3-a95a-7fe76d3603d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88735, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老板今天一句话也不说，他很怎么了？", "corrected_sentence": "老板今天一句话也不说，他怎么了？", "error_description": "错误：“很”插在疑问短语“怎么了”前，但“怎么了”是固定的疑问结构，不能被程度副词“很”修饰。删去“很”即恢复正确。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8331ff59-ca01-46b3-a95a-7fe76d3603d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
