INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88737, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "世纪末是一百年快结束的那几年。", "primary_collocate": null, "pronunciation": "shì jì mò", "ipa": "ʂɻ̩˥˩ tɕi˥˩ mɔ˥˩", "syllable_count": 3, "sentences": [{"text": "世纪末的时候，很多人都在谈新世纪。", "target_word": "世纪末", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "二十世纪末，手机还不太多见。", "target_word": "世纪末", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是在上个世纪末出生的。", "target_word": "世纪末", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "世纪末快到了，大家都很期待新的一百年。", "target_word": "世纪末", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那座城市在世纪末变化很大。", "target_word": "世纪末", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我爷爷常说，世纪末的生活比以前好多了。", "target_word": "世纪末", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "世纪末那几年，电脑慢慢走进了家庭。", "target_word": "世纪末", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一九九八年正是二十世纪末。", "target_word": "世纪末", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "到了世纪末，这条街已经很热闹了。", "target_word": "世纪末", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她们家在世纪末搬到了北京。", "target_word": "世纪末", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "世纪末：一百年快结束的那几年", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f2ad337-3c61-49c3-aacc-f67cc219fb9c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88737, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "课桌", "is_correct": false, "explanation": "语义：“课桌”是家具，不能指一段时间。"}, {"text": "世纪末", "is_correct": true, "explanation": "“世纪末”指一百年快结束的那几年，与“很多人都在谈新世纪”的语境一致。"}, {"text": "世纪", "is_correct": false, "explanation": "语义：“世纪”指整整一百年，不是一百年快结束的那几年；且“世纪的时候”搭配不通。"}, {"text": "星期天", "is_correct": false, "explanation": "语义：“星期天”指一周中的某一天，与“世纪”的时间范围不符。"}], "explanations": {"课桌": "语义：“课桌”是家具，不能指一段时间。", "世纪末": "“世纪末”指一百年快结束的那几年，与“很多人都在谈新世纪”的语境一致。", "世纪": "语义：“世纪”指整整一百年，不是一百年快结束的那几年；且“世纪的时候”搭配不通。", "星期天": "语义：“星期天”指一周中的某一天，与“世纪”的时间范围不符。"}, "sentence_index": 0, "correct_answer": "世纪末"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我今年的世纪末要去旅行。", "explanation": "“世纪末”指一百年快结束的那几年，不能指某一年，这里的用法不对。"}, {"text": "我们每天都在世纪末学习。", "explanation": "这里“世纪末”指一百年快结束的那几年，跨度很大，不能像“每天”这样的日常时间那样用。"}, {"text": "我下午三点在世纪末去了超市。", "explanation": "“世纪末”指一百年快结束的那几年，不能指“下午三点”这样的具体时刻。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '471e8873-97e7-49ed-bd8d-dda09d905a89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88737, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "春天", "is_correct": false, "explanation": "语义：“春天”指季节，不能指一百年中的几年。"}, {"text": "世纪末", "is_correct": true, "explanation": "“世纪末”指一百年快结束的那几年，与“电脑慢慢走进了家庭”的语境一致。"}, {"text": "课桌", "is_correct": false, "explanation": "语义：“课桌”是具体的家具，不能指一段时间。"}, {"text": "十二月", "is_correct": false, "explanation": "搭配：“十二月”指具体的一个月，不能与“那几年”搭配。"}], "explanations": {"春天": "语义：“春天”指季节，不能指一百年中的几年。", "世纪末": "“世纪末”指一百年快结束的那几年，与“电脑慢慢走进了家庭”的语境一致。", "课桌": "语义：“课桌”是具体的家具，不能指一段时间。", "十二月": "搭配：“十二月”指具体的一个月，不能与“那几年”搭配。"}, "sentence_index": 6, "correct_answer": "世纪末"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "上个月她们家在世纪末搬到了北京。", "explanation": "“世纪末”指一百年快结束的几年，不能与“上个月”这样的短时间并用。"}, {"text": "那一只世纪末让她们家搬到了北京。", "explanation": "量词“只”用于动物，“世纪末”是一段时间，不能用“只”来数，句子不通。"}, {"text": "她早上七点在世纪末出门上班。", "explanation": "“世纪末”指一百年快结束的那几年，不能指“早上七点”这样的具体时刻。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '471e8873-97e7-49ed-bd8d-dda09d905a89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88737, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "世纪末到快了，我们准备过节。", "corrected_sentence": "世纪末快到了，我们准备过节。", "error_description": "应为“快到了”。“快到”后的“了”须放在句末，“到快了”语序错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '471e8873-97e7-49ed-bd8d-dda09d905a89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88737, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一个上世纪末，我们家搬到了南方。", "corrected_sentence": "上世纪末，我们家搬到了南方。", "error_description": "“上世纪末”前不能加“一个”，“世纪末”作时间词直接修饰即可，应为“上世纪末”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '471e8873-97e7-49ed-bd8d-dda09d905a89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
