INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88738, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一个世纪的最后一段时间。", "primary_collocate": null, "pronunciation": "shì jì mò", "ipa": "ʂɻ̩˥˩ tɕi˥˩ mɔ˥˩", "syllable_count": 3, "sentences": [{"text": "十九世纪末，火车开始在中国出现。", "target_word": "世纪末", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书写的是十八世纪末的故事。", "target_word": "世纪末", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每到世纪末，人们总会回头看看过去。", "target_word": "世纪末", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位老画家生活在上个世纪末。", "target_word": "世纪末", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "世纪末的城市里，高楼越来越多。", "target_word": "世纪末", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影讲了二十世纪末一家人的生活。", "target_word": "世纪末", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "二十一世纪末，世界会是什么样子呢？", "target_word": "世纪末", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在世纪末见过一次面。", "target_word": "世纪末", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "博物馆里有很多世纪末的老照片。", "target_word": "世纪末", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那座老房子是在世纪末建成的。", "target_word": "世纪末", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "世纪末：一个世纪的最后一段时间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f2ad337-3c61-49c3-aacc-f67cc219fb9c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88738, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "春节", "is_correct": false, "explanation": "搭配：“十九春节”不成词，“春节”是节日，不能与世纪数词搭配表示一段时间。"}, {"text": "世纪末", "is_correct": true, "explanation": "“世纪末”指一个世纪的最后一段时间，与“火车开始在中国出现”的时间语境一致。"}, {"text": "星期一", "is_correct": false, "explanation": "搭配：“十九星期一”不成词，“星期一”不能与“十九”搭配作时间。"}, {"text": "课桌", "is_correct": false, "explanation": "语义：“课桌”是家具，不能指时间段。"}], "explanations": {"春节": "搭配：“十九春节”不成词，“春节”是节日，不能与世纪数词搭配表示一段时间。", "世纪末": "“世纪末”指一个世纪的最后一段时间，与“火车开始在中国出现”的时间语境一致。", "星期一": "搭配：“十九星期一”不成词，“星期一”不能与“十九”搭配作时间。", "课桌": "语义：“课桌”是家具，不能指时间段。"}, "sentence_index": 0, "correct_answer": "世纪末"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我昨天在世纪末吃了一顿饭。", "explanation": "“世纪末”指一个世纪的最后一段时间，跨度很长，不能指“昨天”这样的一天。"}, {"text": "我们每天下午都在世纪末散步。", "explanation": "这里“世纪末”指一个世纪最后的一段时间，跨度很长，不能像“每天下午”这样的日常时段那样用。"}, {"text": "他明天早上在世纪末出发去北京。", "explanation": "“世纪末”指一个世纪的最后一段时间，不能指“明天早上”这样的时刻。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '471e8873-97e7-49ed-bd8d-dda09d905a89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88738, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "早晨", "is_correct": false, "explanation": "语义：“早晨”指一天中的时段，不能指一百年中的一段。"}, {"text": "世纪末", "is_correct": true, "explanation": "“世纪末”指一个世纪的最后一段时间，与“世界会是什么样子呢”的未来语境一致。"}, {"text": "周末", "is_correct": false, "explanation": "搭配：“二十一周末”不成词，“周末”不能与世纪数词搭配。"}, {"text": "夏天", "is_correct": false, "explanation": "语义：“夏天”指季节，不能指一百年中的一段。"}], "explanations": {"早晨": "语义：“早晨”指一天中的时段，不能指一百年中的一段。", "世纪末": "“世纪末”指一个世纪的最后一段时间，与“世界会是什么样子呢”的未来语境一致。", "周末": "搭配：“二十一周末”不成词，“周末”不能与世纪数词搭配。", "夏天": "语义：“夏天”指季节，不能指一百年中的一段。"}, "sentence_index": 6, "correct_answer": "世纪末"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那一只世纪末让人难忘。", "explanation": "量词“只”用于动物，“世纪末”是一段时间，不能用“只”来数，句子不通。"}, {"text": "我们今天到了世纪末，就去吃饭。", "explanation": "“世纪末”的跨度是一个世纪的最后一段时间，不能指“今天”这样的一天。"}, {"text": "我周三下午在世纪末开了会。", "explanation": "“世纪末”指一个世纪的最后一段时间，不能指“周三下午”这样的时段。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '471e8873-97e7-49ed-bd8d-dda09d905a89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88738, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "十八个世纪末，欧洲出现了很多新城市。", "corrected_sentence": "十八世纪末，欧洲出现了很多新城市。", "error_description": "数词与“世纪末”之间不用“个”，应说“十八世纪末”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '471e8873-97e7-49ed-bd8d-dda09d905a89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88738, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一个世纪末，我们家买了第一台电视机。", "corrected_sentence": "在世纪末，我们家买了第一台电视机。", "error_description": "“世纪末”前不能加数量词“一个”，应说“在世纪末”，表示时间。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '471e8873-97e7-49ed-bd8d-dda09d905a89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
