INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88739, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "怎么办是遇到难事、一时不知所措时，焦急地发出的求助话语。", "primary_collocate": null, "pronunciation": "zěn me bàn", "ipa": "tsən˨˩ mə pan˥˩", "syllable_count": 3, "sentences": [{"text": "钱包丢了，我可怎么办啊？", "target_word": "怎么办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门打不开，钥匙又不在，怎么办？", "target_word": "怎么办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她急得哭了：“东西都没了，怎么办？”", "target_word": "怎么办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机没电，路又不认识，这下怎么办？", "target_word": "怎么办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "完了，我忘了带护照，怎么办呢？", "target_word": "怎么办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电脑突然坏了，他急得大喊：怎么办？", "target_word": "怎么办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车在半路坏了，天又黑了，怎么办？", "target_word": "怎么办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试马上开始，我还没复习，怎么办？", "target_word": "怎么办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子不见了，他急得直问：怎么办啊？", "target_word": "怎么办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨太大了，我们都没带伞，怎么办啊？", "target_word": "怎么办", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "遇到难事、着急无措时说的话", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28512d04-a44a-481e-98dc-fa698edcda0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88739, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "怎么办", "is_correct": true, "explanation": "语境：“钱包丢了”后的焦急求助，“我可怎么办啊”正好表示无措。"}, {"text": "谁", "is_correct": false, "explanation": "语义：“我可谁啊”是自嘲身份，与丢了钱包后的焦急不符。"}, {"text": "这样", "is_correct": false, "explanation": "搭配：“我可这样啊”不成话，“这样”不能直接接在“我可”后面表达感叹。"}, {"text": "那样", "is_correct": false, "explanation": "语义：“那样”指示方式，不能表达焦急的求助。"}], "explanations": {"怎么办": "语境：“钱包丢了”后的焦急求助，“我可怎么办啊”正好表示无措。", "谁": "语义：“我可谁啊”是自嘲身份，与丢了钱包后的焦急不符。", "这样": "搭配：“我可这样啊”不成话，“这样”不能直接接在“我可”后面表达感叹。", "那样": "语义：“那样”指示方式，不能表达焦急的求助。"}, "sentence_index": 0, "correct_answer": "怎么办"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这道菜的味道很怎么办。", "explanation": "这里应该用〈怎么样〉。「怎么办」是问处理办法的疑问短语，不能用「很」修饰作谓语；问味道好坏要用〈怎么样〉。"}, {"text": "他写得怎么办。", "explanation": "这里应该用〈怎么样〉。「怎么办」不能作「得」字补语；评价写得好坏要用〈怎么样〉。"}, {"text": "你最近身体怎么办？", "explanation": "这里应该用〈怎么样〉。「怎么办」问如何应对，问身体状况要用〈怎么样〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0be81865-5a6b-41b7-b7c7-e3a4302724c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88739, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "怎么办", "is_correct": true, "explanation": "语境：车坏了、天黑了，句末问的是接下来怎么应对，“怎么办”正好表示求助。"}, {"text": "什么", "is_correct": false, "explanation": "语义：“什么”问具体事物，不能表示这种无措的求助。"}, {"text": "哪里", "is_correct": false, "explanation": "配价：“哪里”问地点，“天又黑了，哪里”缺少表示动作的成分。"}, {"text": "为何", "is_correct": false, "explanation": "语域：“为何”是书面语，口语求助中不用；且问的是原因，与车坏后的无措不符。"}], "explanations": {"怎么办": "语境：车坏了、天黑了，句末问的是接下来怎么应对，“怎么办”正好表示求助。", "什么": "语义：“什么”问具体事物，不能表示这种无措的求助。", "哪里": "配价：“哪里”问地点，“天又黑了，哪里”缺少表示动作的成分。", "为何": "语域：“为何”是书面语，口语求助中不用；且问的是原因，与车坏后的无措不符。"}, "sentence_index": 6, "correct_answer": "怎么办"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个软件的用法怎么办？", "explanation": "这里应该用〈怎么用〉。“怎么办”问如何处理，问操作方法要用〈怎么用〉。"}, {"text": "这条路的走法怎么办？", "explanation": "这里应该用〈怎么走〉。“怎么办”问如何处理，问路线要用〈怎么走〉。"}, {"text": "这个字的写法怎么办？", "explanation": "这里应该用〈怎么写〉。“怎么办”问如何处理，问字的写法要用〈怎么写〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0be81865-5a6b-41b7-b7c7-e3a4302724c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88739, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "票没了，我可怎么办吗？", "corrected_sentence": "票没了，我可怎么办啊？", "error_description": "错误形式：“我可怎么办吗”；正确形式：“我可怎么办啊”。表示焦急求助要用语气词“啊”，“吗”是疑问语气，与“我可”的感叹不搭。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0be81865-5a6b-41b7-b7c7-e3a4302724c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88739, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "天又下雨了，我们该把怎么办？", "corrected_sentence": "天又下雨了，我们该怎么办？", "error_description": "错误形式：“把怎么办”；正确形式：“怎么办”。“把”字句需要带受处置的宾语，“怎么办”是一个整体，前面不能加“把”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0be81865-5a6b-41b7-b7c7-e3a4302724c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
