INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88740, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "询问应当如何处理或应对。", "primary_collocate": null, "pronunciation": "zěn me bàn", "ipa": "tsən˨˩ mə pan˥˩", "syllable_count": 3, "sentences": [{"text": "老师，这道题我不会做，应该怎么办？", "target_word": "怎么办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理问大家：客人不满意，我们怎么办？", "target_word": "怎么办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生，孩子发烧了，我该怎么办？", "target_word": "怎么办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题很麻烦，你说我们怎么办？", "target_word": "怎么办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他问警察：车坏在路上，该怎么办？", "target_word": "怎么办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈问我：你想怎么办？", "target_word": "怎么办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛前下大雨，大家都在问怎么办。", "target_word": "怎么办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们，下课后作业没写完怎么办？", "target_word": "怎么办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请告诉我，手机没电了怎么办？", "target_word": "怎么办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们先商量一下，这件事到底怎么办。", "target_word": "怎么办", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "询问处理办法的疑问短语", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28512d04-a44a-481e-98dc-fa698edcda0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88740, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "怎么办", "is_correct": true, "explanation": "语境：“我不会做，应该”之后问的是处理办法，“怎么办”正好表示询问处理方式。"}, {"text": "这样", "is_correct": false, "explanation": "语义：“这样”指示眼前的方式，不表示询问，“应该这样”无法作为求助的问题。"}, {"text": "那样", "is_correct": false, "explanation": "语义：“那样”指已说过或较远的方式，不能用来询问该如何处理。"}, {"text": "怎么回事", "is_correct": false, "explanation": "搭配：“怎么回事”问已发生的情况，不和“应该”搭配。"}], "explanations": {"怎么办": "语境：“我不会做，应该”之后问的是处理办法，“怎么办”正好表示询问处理方式。", "这样": "语义：“这样”指示眼前的方式，不表示询问，“应该这样”无法作为求助的问题。", "那样": "语义：“那样”指已说过或较远的方式，不能用来询问该如何处理。", "怎么回事": "搭配：“怎么回事”问已发生的情况，不和“应该”搭配。"}, "sentence_index": 0, "correct_answer": "怎么办"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这首诗的意思怎么办？", "explanation": "这里应该用〈怎么理解〉。“怎么办”问如何处理，问理解方式要用〈怎么理解〉。"}, {"text": "这个词用英语怎么办？", "explanation": "这里应该用〈怎么说〉。“怎么办”问处理办法，问词语的表达要用〈怎么说〉。"}, {"text": "这个词的发音怎么办？", "explanation": "这里应该用〈怎么读〉。“怎么办”问如何处理，问发音要用〈怎么读〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0be81865-5a6b-41b7-b7c7-e3a4302724c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88740, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "怎么办", "is_correct": true, "explanation": "语境：下大雨后大家在着急，问的是接下来怎么应对，“怎么办”正好表示这种询问。"}, {"text": "这样", "is_correct": false, "explanation": "语法：「问这样」不成话，「这样」不是疑问词，不能作「问」的内容。"}, {"text": "因为", "is_correct": false, "explanation": "语法：「因为」是连词，后面缺少原因，「问因为」不成话。"}, {"text": "非常", "is_correct": false, "explanation": "语法：「非常」是副词，不能作「问」的宾语。"}], "explanations": {"怎么办": "语境：下大雨后大家在着急，问的是接下来怎么应对，“怎么办”正好表示这种询问。", "这样": "语法：「问这样」不成话，「这样」不是疑问词，不能作「问」的内容。", "因为": "语法：「因为」是连词，后面缺少原因，「问因为」不成话。", "非常": "语法：「非常」是副词，不能作「问」的宾语。"}, "sentence_index": 6, "correct_answer": "怎么办"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台机器的用法怎么办？", "explanation": "这里应该用〈怎么用〉。“怎么办”问如何处理，问操作方法要用〈怎么用〉。"}, {"text": "这个软件的打开方式怎么办？", "explanation": "这里应该用〈怎么开〉。“怎么办”问如何处理，问打开方式要用〈怎么开〉。"}, {"text": "这个词的写法怎么办？", "explanation": "这里应该用〈怎么写〉。“怎么办”问如何处理，问字词的写法要用〈怎么写〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0be81865-5a6b-41b7-b7c7-e3a4302724c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88740, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这件事到底该怎么办的？", "corrected_sentence": "这件事到底该怎么办？", "error_description": "错误形式：“怎么办的”；正确形式：“怎么办”。“怎么办”作疑问句时，句末不能再加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0be81865-5a6b-41b7-b7c7-e3a4302724c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88740, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这件事我们该怎么办吗？", "corrected_sentence": "这件事我们该怎么办？", "error_description": "错误形式：“怎么办吗”；正确形式：“怎么办”。“怎么办”本身已是疑问形式，句末不能再加“吗”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0be81865-5a6b-41b7-b7c7-e3a4302724c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
