INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88741, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "打门是用手敲门。", "primary_collocate": null, "pronunciation": "dǎ mén", "ipa": "ta²¹⁴ mən³⁵", "syllable_count": 2, "sentences": [{"text": "半夜有人在外面打门。", "target_word": "打门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用力打门，可是里面没人说话。", "target_word": "打门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子忘了带钥匙，只好打门。", "target_word": "打门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我打门打了很久，妈妈才听见。", "target_word": "打门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你不要用力打门，宝宝在睡觉。", "target_word": "打门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有人打门，你去看看是谁。", "target_word": "打门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他打门的声音很大，邻居都醒了。", "target_word": "打门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在门口打门，学生们马上安静了。", "target_word": "打门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外面下着雨，有个人一直在打门。", "target_word": "打门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我到她家时，先打门，再叫她的名字。", "target_word": "打门", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "打了门", "label": "完成体"}, {"form": "打过门", "label": "经历体"}], "register": "中性", "sense_fingerprint": "打门：用手敲门，让屋里的人知道有人来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df93761e-3099-453a-be8c-fa0da9ef77d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88741, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "打门", "is_correct": true, "explanation": "打门：用手敲门，让屋里的人知道有人来。"}, {"text": "大门", "is_correct": false, "explanation": "dà（第四声）与 dǎ（第三声）声调不同，意思是大门，指房屋或院子的出入口。"}, {"text": "打蒙", "is_correct": false, "explanation": "méng 与 mén 韵母不同（eng 与 en），意思是被打得头脑发懵。"}, {"text": "搭门", "is_correct": false, "explanation": "dā（第一声）与 dǎ（第三声）声调不同，意思是衣服前襟相叠合的部分。"}], "explanations": {"打门": "打门：用手敲门，让屋里的人知道有人来。", "大门": "dà（第四声）与 dǎ（第三声）声调不同，意思是大门，指房屋或院子的出入口。", "打蒙": "méng 与 mén 韵母不同（eng 与 en），意思是被打得头脑发懵。", "搭门": "dā（第一声）与 dǎ（第三声）声调不同，意思是衣服前襟相叠合的部分。"}, "sentence_index": null, "correct_answer": "打门"}, "level_3": {"options": [{"text": "打门", "is_correct": true, "explanation": "正确：“打门”是用手敲门，与“半夜有人在外面”相合。"}, {"text": "毕业", "is_correct": false, "explanation": "语义：「毕业」指完成学业，与半夜在外面发出的动作毫无关系。"}, {"text": "晒", "is_correct": false, "explanation": "语义：“晒”需要阳光，半夜在外面晒东西不合常理。"}, {"text": "扔", "is_correct": false, "explanation": "配价：“扔”后面要带被扔的东西，这里没有宾语。"}], "explanations": {"打门": "正确：“打门”是用手敲门，与“半夜有人在外面”相合。", "毕业": "语义：「毕业」指完成学业，与半夜在外面发出的动作毫无关系。", "晒": "语义：“晒”需要阳光，半夜在外面晒东西不合常理。", "扔": "配价：“扔”后面要带被扔的东西，这里没有宾语。"}, "sentence_index": 0, "correct_answer": "打门"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用键盘打门，写了一封邮件。", "explanation": "在键盘上输入文字要说〈打〉字，“打门”不能指打字。"}, {"text": "饭馆老板在厨房里打门，给客人做了一碗面。", "explanation": "做面要说〈做〉或〈煮〉，“打门”不能指做饭。"}, {"text": "他站在窗户外面打门，想让屋里的人打开窗户。", "explanation": "「打门」只能用于门。想让人开窗，要说〈敲窗户〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '528ae9eb-8f3f-45db-941a-909b86cd0b50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88741, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "打门", "is_correct": true, "explanation": "正确：“他打门的声音很大”，“打门”是用手敲门，能发出声音。"}, {"text": "想", "is_correct": false, "explanation": "语义：“想”是心里的活动，不发出声音，与“声音很大”不合。"}, {"text": "微笑", "is_correct": false, "explanation": "语义：“微笑”不发出声音，句中说“声音很大”，意思矛盾。"}, {"text": "看", "is_correct": false, "explanation": "搭配：“看”后面要带看的对象，“看的声音”不能这样说。"}], "explanations": {"打门": "正确：“他打门的声音很大”，“打门”是用手敲门，能发出声音。", "想": "语义：“想”是心里的活动，不发出声音，与“声音很大”不合。", "微笑": "语义：“微笑”不发出声音，句中说“声音很大”，意思矛盾。", "看": "搭配：“看”后面要带看的对象，“看的声音”不能这样说。"}, "sentence_index": 6, "correct_answer": "打门"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天早上都打门给妈妈，问她好不好。", "explanation": "“打门”不能指打电话；打电话要说〈打〉电话。"}, {"text": "他在纸上用铅笔打门，画了一张地图。", "explanation": "画地图要说〈画〉，“打门”不能指画画。"}, {"text": "他下班后在院子里打门，把衣服洗干净了。", "explanation": "洗衣服要说〈洗〉，“打门”不能指洗涤。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '528ae9eb-8f3f-45db-941a-909b86cd0b50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88741, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我在门口打门得很响，他就听见了。", "corrected_sentence": "我在门口打门打得很响，他就听见了。", "error_description": "补语错误：“打门”后作补语的“得很响”要重复动词“打”，应说“打门打得很响”，不说“打门得很响”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '528ae9eb-8f3f-45db-941a-909b86cd0b50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88741, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在门口把打门，人都醒了。", "corrected_sentence": "他在门口打门，人都醒了。", "error_description": "“把”字句错误：“打门”是动词，“把”后不能直接接动词，句中也没有需要处置的宾语，应去掉“把”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '528ae9eb-8f3f-45db-941a-909b86cd0b50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
