INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88742, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "敲门。", "primary_collocate": null, "pronunciation": "dǎ mén", "ipa": "ta²¹⁴ mən³⁵", "syllable_count": 2, "sentences": [{"text": "进房间以前，要先打门。", "target_word": "打门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他打门三下，里面有人说“请进”。", "target_word": "打门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗不会打门，只会在门口叫。", "target_word": "打门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "快递员在门口打门，没人开。", "target_word": "打门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁在打门？去开一下门。", "target_word": "打门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我打门以后，听到里面有脚步声。", "target_word": "打门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他打门打了半天，也没人来开。", "target_word": "打门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风很大，我以为是有人打门。", "target_word": "打门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别用脚打门，会吓到里面的人。", "target_word": "打门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喝醉了，在别人家门口大声打门。", "target_word": "打门", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "打了门", "label": "完成体"}, {"form": "打过门", "label": "经历体"}], "register": "中性", "sense_fingerprint": "打门：敲门", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df93761e-3099-453a-be8c-fa0da9ef77d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88742, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "打门", "is_correct": true, "explanation": "打门：敲门。"}, {"text": "大门", "is_correct": false, "explanation": "dà（第四声）与 dǎ（第三声）声调不同，意思是大门，指房屋或院子的出入口。"}, {"text": "打蒙", "is_correct": false, "explanation": "méng 与 mén 韵母不同（eng 与 en），意思是被打得头脑发懵。"}, {"text": "搭门", "is_correct": false, "explanation": "dā（第一声）与 dǎ（第三声）声调不同，意思是衣服前襟相叠合的部分。"}], "explanations": {"打门": "打门：敲门。", "大门": "dà（第四声）与 dǎ（第三声）声调不同，意思是大门，指房屋或院子的出入口。", "打蒙": "méng 与 mén 韵母不同（eng 与 en），意思是被打得头脑发懵。", "搭门": "dā（第一声）与 dǎ（第三声）声调不同，意思是衣服前襟相叠合的部分。"}, "sentence_index": null, "correct_answer": "打门"}, "level_3": {"options": [{"text": "打门", "is_correct": true, "explanation": "正确：“进房间以前，要先敲门”，“打门”是敲门的意思。"}, {"text": "买", "is_correct": false, "explanation": "配价：“买”要带宾语，“要先买”不成句。"}, {"text": "晒", "is_correct": false, "explanation": "语义：“晒”是在阳光下做的事，与进房间前的动作不相关。"}, {"text": "扔", "is_correct": false, "explanation": "配价：“扔”后面要带被扔的东西，“要先扔”没有宾语。"}], "explanations": {"打门": "正确：“进房间以前，要先敲门”，“打门”是敲门的意思。", "买": "配价：“买”要带宾语，“要先买”不成句。", "晒": "语义：“晒”是在阳光下做的事，与进房间前的动作不相关。", "扔": "配价：“扔”后面要带被扔的东西，“要先扔”没有宾语。"}, "sentence_index": 0, "correct_answer": "打门"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "孩子打门打了两个小时，终于把作业写完了。", "explanation": "「打门」不能指写作业。写作业要说〈写〉作业。"}, {"text": "司机在路上打门，把车停了下来。", "explanation": "停车要说〈停〉车，“打门”不能指停车。"}, {"text": "他站在窗户外面打门，想让屋里的人打开窗户。", "explanation": "「打门」只能用于门。想让人开窗，要说〈敲窗户〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '528ae9eb-8f3f-45db-941a-909b86cd0b50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88742, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "打门", "is_correct": true, "explanation": "正确：“他打门打了半天”，“打门”是用手敲门，可以持续很久。"}, {"text": "微笑", "is_correct": false, "explanation": "语义：“微笑”不是敲击动作，不能和“打了半天，也没人来开”连用。"}, {"text": "看书", "is_correct": false, "explanation": "搭配：“看书打了半天”不成立，句中的动作不是看书。"}, {"text": "散步", "is_correct": false, "explanation": "搭配：“散步打了半天”不通，“也没人来开”与散步无关。"}], "explanations": {"打门": "正确：“他打门打了半天”，“打门”是用手敲门，可以持续很久。", "微笑": "语义：“微笑”不是敲击动作，不能和“打了半天，也没人来开”连用。", "看书": "搭配：“看书打了半天”不成立，句中的动作不是看书。", "散步": "搭配：“散步打了半天”不通，“也没人来开”与散步无关。"}, "sentence_index": 6, "correct_answer": "打门"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他拿起手机打门给客户，谈好了合同。", "explanation": "打电话要说〈打〉电话，“打门”不能指打电话。"}, {"text": "老师在黑板上打门，写了一道数学题。", "explanation": "写字要说〈写〉，“打门”不能指写字。"}, {"text": "她在车站打门，等了三个小时的火车。", "explanation": "等车要说〈等〉，“打门”不能指等待。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '528ae9eb-8f3f-45db-941a-909b86cd0b50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88742, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我打门过，没人来开。", "corrected_sentence": "我打过门，没人来开。", "error_description": "体标错误：“过”应紧跟动词，说“打过门”，不说“打门过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '528ae9eb-8f3f-45db-941a-909b86cd0b50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88742, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在门口打门得很响，人都醒了。", "corrected_sentence": "他在门口打门打得很响，人都醒了。", "error_description": "补语错误：“打得很响”作补语时要重复动词“打”，应说“打门打得很响”，不说“打门得很响”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '528ae9eb-8f3f-45db-941a-909b86cd0b50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
