INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88744, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用弓弩、枪炮等把箭、子弹等发出去。", "primary_collocate": null, "pronunciation": "shè", "ipa": "ʂɤ˥˩", "syllable_count": 1, "sentences": [{"text": "他拉开弓，一箭射了出去。", "target_word": "射", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "猎人举起枪，对着狼射了一枪。", "target_word": "射", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古代的士兵用弓箭射敌人。", "target_word": "射", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一箭就射中了前面的靶子。", "target_word": "射", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "猎人一枪把那只鸟射下来了。", "target_word": "射", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察朝天空射了一枪。", "target_word": "射", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他站在远处，用弓射那棵树。", "target_word": "射", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在草地上学射箭。", "target_word": "射", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "士兵们一起向城墙上射箭。", "target_word": "射", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他射得很准，十支箭都中了靶。", "target_word": "射", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "射中", "label": "动结式"}, {"form": "射出", "label": "动趋式"}, {"form": "射箭", "label": "动宾搭配"}], "register": "中性", "sense_fingerprint": "动词，用弓、枪等工具把箭或子弹发出去", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '525423d5-7b31-4df5-a976-f002812aab26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88744, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "射", "is_correct": true, "explanation": "正确：听到的是“射”（shè），指用弓弩、枪炮把箭或子弹发出去。"}, {"text": "蛇", "is_correct": false, "explanation": "shé（第二声）与 shè（第四声）声调不同，“蛇”意思是蛇。"}, {"text": "色", "is_correct": false, "explanation": "sè 与 shè 声母不同（s / sh），“色”意思是颜色。"}, {"text": "是", "is_correct": false, "explanation": "shì 与 shè 韵母不同（i / e），“是”意思是对、属于。"}], "explanations": {"射": "正确：听到的是“射”（shè），指用弓弩、枪炮把箭或子弹发出去。", "蛇": "shé（第二声）与 shè（第四声）声调不同，“蛇”意思是蛇。", "色": "sè 与 shè 声母不同（s / sh），“色”意思是颜色。", "是": "shì 与 shè 韵母不同（i / e），“是”意思是对、属于。"}, "sentence_index": null, "correct_answer": "射"}, "level_3": {"options": [{"text": "射", "is_correct": true, "explanation": "正确：“一箭射了出去”指用弓把箭发出去，与拉弓的动作相符。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能用来表示把箭发出去。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”是加热食物，与拉弓射箭的动作无关。"}, {"text": "洗", "is_correct": false, "explanation": "语义：“洗”指用水清除污物，与发射箭矢不符。"}], "explanations": {"射": "正确：“一箭射了出去”指用弓把箭发出去，与拉弓的动作相符。", "吃": "搭配：“吃”不能用来表示把箭发出去。", "煮": "语义：“煮”是加热食物，与拉弓射箭的动作无关。", "洗": "语义：“洗”指用水清除污物，与发射箭矢不符。"}, "sentence_index": 0, "correct_answer": "射"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用力把石头射进了河里。", "explanation": "这里应该用〈投〉。“射”用于弓箭、子弹等发射物，把石头扔进水里要用“投”。"}, {"text": "他把书射到了桌子上。", "explanation": "这里应该用〈扔〉。“射”用于箭、子弹等发射物，把书随手丢到桌上要用“扔”。"}, {"text": "他用相机射了一张照片。", "explanation": "这里应该用〈拍〉。“射”用于弓箭、子弹等发射物，用相机拍照要用“拍”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b01eabee-5f23-40fb-bd13-a6b2189c2450') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88744, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "射", "is_correct": true, "explanation": "正确：听到的是“射”（shè），指用弓弩、枪炮把箭或子弹发出去。"}, {"text": "这", "is_correct": false, "explanation": "zhè 与 shè 声母不同（zh / sh），“这”意思是这个。"}, {"text": "舍", "is_correct": false, "explanation": "shě（第三声）与 shè（第四声）声调不同，“舍”意思是舍弃。"}, {"text": "世", "is_correct": false, "explanation": "shì 与 shè 韵母不同（i / e），“世”意思是世界。"}], "explanations": {"射": "正确：听到的是“射”（shè），指用弓弩、枪炮把箭或子弹发出去。", "这": "zhè 与 shè 声母不同（zh / sh），“这”意思是这个。", "舍": "shě（第三声）与 shè（第四声）声调不同，“舍”意思是舍弃。", "世": "shì 与 shè 韵母不同（i / e），“世”意思是世界。"}, "sentence_index": null, "correct_answer": "射"}, "level_3": {"options": [{"text": "射", "is_correct": true, "explanation": "正确：“用弓射那棵树”指用弓把箭发向目标，与语境相符。"}, {"text": "砍", "is_correct": false, "explanation": "搭配：“砍”需要斧头或刀，不能用弓去砍。"}, {"text": "浇", "is_correct": false, "explanation": "语义：“浇”指把水倒在上面，与用弓攻击树的情境无关。"}, {"text": "擦", "is_correct": false, "explanation": "语义：“擦”指擦拭表面，不符合用弓发箭的情境。"}], "explanations": {"射": "正确：“用弓射那棵树”指用弓把箭发向目标，与语境相符。", "砍": "搭配：“砍”需要斧头或刀，不能用弓去砍。", "浇": "语义：“浇”指把水倒在上面，与用弓攻击树的情境无关。", "擦": "语义：“擦”指擦拭表面，不符合用弓发箭的情境。"}, "sentence_index": 6, "correct_answer": "射"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "农民把种子射在地里。", "explanation": "这里应该用〈撒〉。“射”用于箭、子弹等发射物，把种子撒到地里要用“撒”。"}, {"text": "他把纸团射进了垃圾桶。", "explanation": "这里应该用〈投〉。“射”用于弓箭、子弹等发射物，把纸团投进垃圾桶要用“投”。"}, {"text": "他用力把钥匙射进了锁孔。", "explanation": "这里应该用〈插〉。“射”用于弓箭、子弹等发射物，把钥匙插进锁孔要用“插”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b01eabee-5f23-40fb-bd13-a6b2189c2450') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88744, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "士兵拉开弓，把箭射了向敌人。", "corrected_sentence": "士兵拉开弓，把箭射向敌人。", "error_description": "错误：“了”插在“射”和“向”之间，“射向”是一个整体，不能拆开。正确：“把箭射向敌人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b01eabee-5f23-40fb-bd13-a6b2189c2450') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88744, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他射箭射很准，每次都中靶。", "corrected_sentence": "他射箭射得很准，每次都中靶。", "error_description": "错误：“射很准”缺少“得”。正确：“射得很准”，动词和程度补语之间要用“得”连接。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b01eabee-5f23-40fb-bd13-a6b2189c2450') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
