INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88745, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "水管漏了，师傅正在换了水管。", "corrected_sentence": "水管漏了，师傅正在换水管。", "error_description": "错误：“正在”和“了”不能同时用在一个动作上。正确：表示正在进行时只用“正在”，去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '302840f7-b73e-4a61-bf0e-cb4145bc9216') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
