INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88746, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "拿一样东西去换取另一样;更换;变换。", "primary_collocate": null, "pronunciation": "huàn", "ipa": "xwan˥˩", "syllable_count": 1, "sentences": [{"text": "我想用这本旧书换一本新书。", "target_word": "换", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请问，这里可以换钱吗？", "target_word": "换", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想和你换一下座位，可以吗？", "target_word": "换", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "到人民广场要换二号线。", "target_word": "换", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个话题太难了，我们换一个吧。", "target_word": "换", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妹妹拿苹果跟我换了一块蛋糕。", "target_word": "换", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想把美元换成人民币。", "target_word": "换", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路不通，我们换一条走吧。", "target_word": "换", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我用两张邮票换了他一张明信片。", "target_word": "换", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们俩换着看这本书吧。", "target_word": "换", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "换了", "label": "体标"}, {"form": "换过", "label": "体标"}, {"form": "换着", "label": "体标"}, {"form": "换换", "label": "重叠"}, {"form": "交换", "label": "复合"}, {"form": "換", "label": "繁体"}], "register": "通用", "sense_fingerprint": "用一样东西交换另一样,或把一事物变成另一个", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 8 above tier T1: 3 words above tier T1 (max 2): 两张 (Zipf 3.97), 邮票 (Zipf 3.81), 明信片 (Zipf 3.71)']::text[], '5767602e-4fc3-4fe7-bca0-b5bea1fa5ab2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88746, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "换", "is_correct": true, "explanation": "正确：换 huàn，意思是用一样东西交换另一样，或把一事物变成另一个。"}, {"text": "环", "is_correct": false, "explanation": "环 huán（第二声）与 huàn（第四声）声调不同，意思是圆环。"}, {"text": "欢", "is_correct": false, "explanation": "欢 huān（第一声）与 huàn（第四声）声调不同，意思是高兴。"}, {"text": "晃", "is_correct": false, "explanation": "晃 huàng 与 huàn 韵尾不同（ng／n），意思是晃动。"}], "explanations": {"换": "正确：换 huàn，意思是用一样东西交换另一样，或把一事物变成另一个。", "环": "环 huán（第二声）与 huàn（第四声）声调不同，意思是圆环。", "欢": "欢 huān（第一声）与 huàn（第四声）声调不同，意思是高兴。", "晃": "晃 huàng 与 huàn 韵尾不同（ng／n），意思是晃动。"}, "sentence_index": null, "correct_answer": "换"}, "level_3": {"options": [{"text": "换", "is_correct": true, "explanation": "正确：“用这本旧书换一本新书”表示以旧换新，符合句意。"}, {"text": "寄", "is_correct": false, "explanation": "语义：“寄”指邮寄，“用这本旧书寄一本新书”说不通。"}, {"text": "卖", "is_correct": false, "explanation": "语义：“卖”指把东西卖出换钱，不能表示用旧书换取新书。"}, {"text": "借", "is_correct": false, "explanation": "配价：“借”需要借入方和借出方，句中没有“借”的对象，说不通。"}], "explanations": {"换": "正确：“用这本旧书换一本新书”表示以旧换新，符合句意。", "寄": "语义：“寄”指邮寄，“用这本旧书寄一本新书”说不通。", "卖": "语义：“卖”指把东西卖出换钱，不能表示用旧书换取新书。", "借": "配价：“借”需要借入方和借出方，句中没有“借”的对象，说不通。"}, "sentence_index": 0, "correct_answer": "换"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我想和你换一下年龄，这样我就能早点上大学了。", "explanation": "这里应该用〈长〉。换表示交换，年龄不能交换，要说“长大”。"}, {"text": "我想换一下我的出生日期，让自己早点长大。", "explanation": "出生日期不能更换，“换”在这里说不通，应表达为“想早点长大”。"}, {"text": "他的成绩太差，我们换一下他的身高吧。", "explanation": "这里应该用〈长〉。换表示交换或更换，身高不能交换，要说“长高”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '302840f7-b73e-4a61-bf0e-cb4145bc9216') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88746, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "换", "is_correct": true, "explanation": "正确：换 huàn，意思是交换或更换。"}, {"text": "缓", "is_correct": false, "explanation": "缓 huǎn（第三声）与 huàn（第四声）声调不同，意思是慢或缓解。"}, {"text": "惯", "is_correct": false, "explanation": "惯 guàn 与 huàn 只差声母（g／h），意思是习惯。"}, {"text": "汗", "is_correct": false, "explanation": "汗 hàn 与 huàn 只差介音 u，意思是汗水。"}], "explanations": {"换": "正确：换 huàn，意思是交换或更换。", "缓": "缓 huǎn（第三声）与 huàn（第四声）声调不同，意思是慢或缓解。", "惯": "惯 guàn 与 huàn 只差声母（g／h），意思是习惯。", "汗": "汗 hàn 与 huàn 只差介音 u，意思是汗水。"}, "sentence_index": null, "correct_answer": "换"}, "level_3": {"options": [{"text": "换", "is_correct": true, "explanation": "正确：“把美元换成人民币”表示兑换货币，符合句意。"}, {"text": "存", "is_correct": false, "explanation": "语义：“存”指把钱存入银行，不能表示兑换货币。"}, {"text": "花", "is_correct": false, "explanation": "搭配：“花”指消费，“花成人民币”不成立。"}, {"text": "赚", "is_correct": false, "explanation": "语义：“赚”指获得收益，不表示货币之间的兑换。"}], "explanations": {"换": "正确：“把美元换成人民币”表示兑换货币，符合句意。", "存": "语义：“存”指把钱存入银行，不能表示兑换货币。", "花": "搭配：“花”指消费，“花成人民币”不成立。", "赚": "语义：“赚”指获得收益，不表示货币之间的兑换。"}, "sentence_index": 6, "correct_answer": "换"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我把这本书换给你，我什么也不要。", "explanation": "这里应该用〈送〉。“换”要求对方给出另一样东西，“什么也不要”与之矛盾。"}, {"text": "他借了我的伞，到现在还没换给我。", "explanation": "这里应该用〈还〉。借来的东西要归还，“换”表示用一样东西交换另一样，这里说不通。"}, {"text": "你付了五十块，我应该换你十块钱。", "explanation": "这里应该用〈找〉。找是找回多付的钱；“换”表示用一样换另一样，这里不能说“换你十块钱”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '302840f7-b73e-4a61-bf0e-cb4145bc9216') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88746, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我想被日元换成人民币。", "corrected_sentence": "我想把日元换成人民币。", "error_description": "错误：把“把”写成了“被”。正确：“换成”要用“把”字句，说“我想把日元换成人民币”；“被”表示被动，这里说不通。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '302840f7-b73e-4a61-bf0e-cb4145bc9216') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88746, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们可以把欧元换到人民币。", "corrected_sentence": "我们可以把欧元换成人民币。", "error_description": "错误：补语用错，把“成”写成了“到”。正确：表示把一样变成另一样时要用“成”，“到”表示到达某处。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '302840f7-b73e-4a61-bf0e-cb4145bc9216') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
