INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88747, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "投机是用不太好的办法，想很快得到好处。", "primary_collocate": null, "pronunciation": "tóu jī", "ipa": "tʰou˧˥ tɕi˥", "syllable_count": 2, "sentences": [{"text": "他做事爱投机，总想走捷径。", "target_word": "投机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "想靠投机发财，最后往往会失败。", "target_word": "投机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学习要踏实，不能投机。", "target_word": "投机", "complexity_tier": "T3", "furigana": "xuéxí yào tāshi, bù néng tóujī.", "sentence_source": "generated"}, {"text": "这种投机的办法，老师一眼就看出来了。", "target_word": "投机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他考试前不复习，只想投机混过去。", "target_word": "投机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做生意要老老实实，不能太投机。", "target_word": "投机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他靠投机赚了点钱，却很快花光了。", "target_word": "投机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都不喜欢投机的人。", "target_word": "投机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我觉得他这样做太投机了。", "target_word": "投机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别想着投机，努力才有好结果。", "target_word": "投机", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "投機", "label": "繁体"}, {"form": "投机取巧", "label": "复合"}], "register": "通用", "sense_fingerprint": "用不正当的办法想很快得到好处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '572e04e2-6b86-4c93-ad0e-9ef951c337f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88747, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "投寄", "is_correct": false, "explanation": "投寄（tóujì）与投机（tóujī）只有末字声调不同，意思是把信件等寄出。"}, {"text": "偷鸡", "is_correct": false, "explanation": "偷（tōu，第一声）与投（tóu，第二声）声调不同，意思是偷窃鸡只。"}, {"text": "投机", "is_correct": true, "explanation": "正确答案：投机（tóu jī），指用不正当的办法想很快得到好处。"}, {"text": "游击", "is_correct": false, "explanation": "游（yóu）与投（tóu）声母不同，意思是游动出击，是一种作战方式。"}], "explanations": {"投寄": "投寄（tóujì）与投机（tóujī）只有末字声调不同，意思是把信件等寄出。", "偷鸡": "偷（tōu，第一声）与投（tóu，第二声）声调不同，意思是偷窃鸡只。", "投机": "正确答案：投机（tóu jī），指用不正当的办法想很快得到好处。", "游击": "游（yóu）与投（tóu）声母不同，意思是游动出击，是一种作战方式。"}, "sentence_index": null, "correct_answer": "投机"}, "level_3": {"options": [{"text": "认真", "is_correct": false, "explanation": "语义：“认真”指做事踏实，与“总想走捷径”的意思相反。"}, {"text": "诚实", "is_correct": false, "explanation": "语义：“诚实”的做事风格与“总想走捷径”矛盾。"}, {"text": "投机", "is_correct": true, "explanation": "正确答案：“爱投机”指习惯用不正当的办法图快，与“总想走捷径”的意思一致。"}, {"text": "谨慎", "is_correct": false, "explanation": "语义：“谨慎”的做事风格与“总想走捷径”相矛盾。"}], "explanations": {"认真": "语义：“认真”指做事踏实，与“总想走捷径”的意思相反。", "诚实": "语义：“诚实”的做事风格与“总想走捷径”矛盾。", "投机": "正确答案：“爱投机”指习惯用不正当的办法图快，与“总想走捷径”的意思一致。", "谨慎": "语义：“谨慎”的做事风格与“总想走捷径”相矛盾。"}, "sentence_index": 0, "correct_answer": "投机"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把全部积蓄投机在孩子的教育上。", "explanation": "这里应该用〈投资〉。投机指用不正当办法图快速好处，用于教育这类长期事业应说投资。"}, {"text": "这个实验很投机，需要穿防护服。", "explanation": "这里应该用〈冒险〉。投机指用不正当办法图快速好处，不指有危险的事情。"}, {"text": "他把全部精力投机在新产品开发上。", "explanation": "这里应该用〈投入〉。投机指用不正当办法图快速好处，用于精力、时间应说投入。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc4c3068-c7ea-4d2c-bc87-6e527f09faa2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88747, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "懒惰", "is_correct": false, "explanation": "语义：“懒惰”与“赚了点钱”的意思不相合，懒惰不能用来赚钱。"}, {"text": "愚蠢", "is_correct": false, "explanation": "语义：“愚蠢”不是赚钱的办法，与句意矛盾。"}, {"text": "悠闲", "is_correct": false, "explanation": "搭配：“靠悠闲赚钱”不是常见说法，“悠闲”一般不用来表示赚钱的方式。"}, {"text": "投机", "is_correct": true, "explanation": "正确答案：“靠投机”指用不正当办法图快，与“赚了点钱却很快花光了”的语境相符。"}], "explanations": {"懒惰": "语义：“懒惰”与“赚了点钱”的意思不相合，懒惰不能用来赚钱。", "愚蠢": "语义：“愚蠢”不是赚钱的办法，与句意矛盾。", "悠闲": "搭配：“靠悠闲赚钱”不是常见说法，“悠闲”一般不用来表示赚钱的方式。", "投机": "正确答案：“靠投机”指用不正当办法图快，与“赚了点钱却很快花光了”的语境相符。"}, "sentence_index": 6, "correct_answer": "投机"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "顾客觉得服务不好，就去投机了。", "explanation": "这里应该用〈投诉〉。投机指用不正当办法图快速好处，不能表示向有关方面提出不满。"}, {"text": "面对强敌，他们只好投机了。", "explanation": "这里应该用〈投降〉。投机指用不正当办法图快速好处，不能表示放弃抵抗。"}, {"text": "同学们都来投机，选出了新班长。", "explanation": "这里应该用〈投票〉。投机指用不正当办法图快速好处，不能用于表示选举。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc4c3068-c7ea-4d2c-bc87-6e527f09faa2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88747, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他做事很投机过，总想走捷径。", "corrected_sentence": "他做事很投机，总想走捷径。", "error_description": "错误形式：“很投机过”；正确形式：“很投机”。形容词表示性质，不能用“过”表示经历，应去掉“过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc4c3068-c7ea-4d2c-bc87-6e527f09faa2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88747, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的做法太很投机了。", "corrected_sentence": "他的做法太投机了。", "error_description": "错误形式：“太很投机了”；正确形式：“太投机了”。“太”与“很”都是程度副词，不能同时修饰同一形容词，应去掉“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc4c3068-c7ea-4d2c-bc87-6e527f09faa2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
