INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88749, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "有时就是不是每次,只是有些时候。", "primary_collocate": null, "pronunciation": "yǒu shí", "ipa": "jou˨˩˧ ʂɻ̩˧˥", "syllable_count": 2, "sentences": [{"text": "我上班有时坐地铁，有时骑车。", "target_word": "有时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不是每天都迟到，有时也会准时到。", "target_word": "有时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "周末我有时在家看书，有时出去玩。", "target_word": "有时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的菜有时好吃，有时不太好吃。", "target_word": "有时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气有时很热，有时又很冷。", "target_word": "有时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈有时做面条，有时做米饭。", "target_word": "有时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我不总是喝茶，有时喝咖啡。", "target_word": "有时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们有时听话，有时不听话。", "target_word": "有时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他有时开车去，有时走路去。", "target_word": "有时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "春天的风有时大，有时小。", "target_word": "有时", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "有时候", "label": "复合"}], "register": "中性", "sense_fingerprint": "有时：不是每次，只是某些时候发生，常与「有时……有时……」对举", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6572065d-d0c8-4f83-baf4-ecb8a6676503') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88749, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "有时", "is_correct": true, "explanation": "正确答案：有时（yǒu shí）表示不是每次，只是某些时候。"}, {"text": "有事", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）声调不同，意思是有事情。"}, {"text": "幼时", "is_correct": false, "explanation": "yòu（第四声）与 yǒu（第三声）声调不同，意思是小时候。"}, {"text": "诱使", "is_correct": false, "explanation": "yòu（第四声）与 yǒu（第三声）、shǐ（第三声）与 shí（第二声）声调都不同，意思是引诱、促使。"}], "explanations": {"有时": "正确答案：有时（yǒu shí）表示不是每次，只是某些时候。", "有事": "shí（第二声）与 shì（第四声）声调不同，意思是有事情。", "幼时": "yòu（第四声）与 yǒu（第三声）声调不同，意思是小时候。", "诱使": "yòu（第四声）与 yǒu（第三声）、shǐ（第三声）与 shí（第二声）声调都不同，意思是引诱、促使。"}, "sentence_index": null, "correct_answer": "有时"}, "level_3": {"options": [{"text": "有时", "is_correct": true, "explanation": "正确：“有时”表示有些时候，与后半句“有时骑车”对举，符合语境。"}, {"text": "总是", "is_correct": false, "explanation": "语义：“总是”表示每次都如此，与后半句“有时骑车”的交替意思矛盾。"}, {"text": "一直", "is_correct": false, "explanation": "语义：“一直”表示持续不变，与“有时骑车”的间歇意思矛盾。"}, {"text": "从来", "is_correct": false, "explanation": "搭配：“从来”通常与“不”“没”连用，不能直接修饰肯定句中的“坐地铁”。"}], "explanations": {"有时": "正确：“有时”表示有些时候，与后半句“有时骑车”对举，符合语境。", "总是": "语义：“总是”表示每次都如此，与后半句“有时骑车”的交替意思矛盾。", "一直": "语义：“一直”表示持续不变，与“有时骑车”的间歇意思矛盾。", "从来": "搭配：“从来”通常与“不”“没”连用，不能直接修饰肯定句中的“坐地铁”。"}, "sentence_index": 0, "correct_answer": "有时"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家店的菜每次都有时好吃。", "explanation": "这里“每次都”与“有时”矛盾：“有时”指不是每次，“每次都”指每次如此，两者不能同时修饰“好吃”。"}, {"text": "上周我有时去了一次超市，东西很便宜。", "explanation": "这里应该用〈有一次〉。“有时”指多次中的某些时候，说单次发生的事要用“有一次”，这里的“有时”与“一次”矛盾。"}, {"text": "这个月我一直有时加班。", "explanation": "这里应该用〈经常〉。“一直”表示持续不断，与“有时”表示的间歇性冲突。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5832db7a-7430-4448-94f4-64c816ee246e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88749, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "有时", "is_correct": true, "explanation": "正确：“有时”表示某些时候，与“不总是喝茶”形成对比，符合语境。"}, {"text": "马上", "is_correct": false, "explanation": "语义：“马上”表示时间紧接，与“不总是喝茶”描述的习惯性对比不搭。"}, {"text": "已经", "is_correct": false, "explanation": "语义：“已经”表示动作已经完成，与此处泛指的习惯不合。"}, {"text": "十分", "is_correct": false, "explanation": "搭配：“十分”修饰形容词或心理动词，不能修饰动词“喝”。"}], "explanations": {"有时": "正确：“有时”表示某些时候，与“不总是喝茶”形成对比，符合语境。", "马上": "语义：“马上”表示时间紧接，与“不总是喝茶”描述的习惯性对比不搭。", "已经": "语义：“已经”表示动作已经完成，与此处泛指的习惯不合。", "十分": "搭配：“十分”修饰形容词或心理动词，不能修饰动词“喝”。"}, "sentence_index": 6, "correct_answer": "有时"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "春天的风总是有时大。", "explanation": "这里“总是”与“有时”矛盾：“有时”指不是每次，“总是”指每次都如此，两者不能同时使用。"}, {"text": "春天的风每次都有时大。", "explanation": "这里“每次都”与“有时”矛盾：“有时”指不是每次，只是某些时候，而“每次都”指每次如此，两者不能同时修饰“大”。"}, {"text": "春天的风天天都有时大。", "explanation": "这里把“有时”用成了〈每天〉的意思。“有时”指不是每次，只是某些时候，而“天天都”表示每天都这样，两者矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5832db7a-7430-4448-94f4-64c816ee246e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88749, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "周末我有时睡懒觉有时。", "corrected_sentence": "周末我有时睡懒觉。", "error_description": "错误：句末多出一个“有时”，“有时”是副词，应放在动词前作状语，不能放在动词短语“睡懒觉”之后。正确：写作“周末我有时睡懒觉”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5832db7a-7430-4448-94f4-64c816ee246e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88749, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我有时的会迟到。", "corrected_sentence": "我有时会迟到。", "error_description": "错误：“有时”后面多加了“的”，使副词变成了定语结构，句子不通。正确：“有时”作状语，直接修饰“会迟到”，应写作“我有时会迟到”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5832db7a-7430-4448-94f4-64c816ee246e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88750, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "过去", "is_correct": true, "explanation": "正确答案。过去指已经过去的时间，与“将来”是时间上的一对反义词。"}, {"text": "桌子", "is_correct": false, "explanation": "桌子是具体的家具，与时间概念的“将来”没有反义关系。"}, {"text": "河流", "is_correct": false, "explanation": "河流是地理事物，与“将来”没有反义关系。"}, {"text": "草原", "is_correct": false, "explanation": "草原是地理环境，与“将来”没有反义关系。"}], "correct_answer": "过去", "explanations": {"过去": "正确答案。过去指已经过去的时间，与“将来”是时间上的一对反义词。", "桌子": "桌子是具体的家具，与时间概念的“将来”没有反义关系。", "河流": "河流是地理事物，与“将来”没有反义关系。", "草原": "草原是地理环境，与“将来”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44bc7b03-ab11-44e9-88d9-59ad108632a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88750, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "过去", "is_correct": true, "explanation": "正确答案。过去与将来是时间上相对的一对反义词。"}, {"text": "窗户", "is_correct": false, "explanation": "窗户是房屋的构件，与时间概念的“将来”没有反义关系。"}, {"text": "石头", "is_correct": false, "explanation": "石头是具体的物体，与“将来”没有反义关系。"}, {"text": "牛奶", "is_correct": false, "explanation": "牛奶是饮品，与“将来”没有反义关系。"}], "correct_answer": "过去", "explanations": {"过去": "正确答案。过去与将来是时间上相对的一对反义词。", "窗户": "窗户是房屋的构件，与时间概念的“将来”没有反义关系。", "石头": "石头是具体的物体，与“将来”没有反义关系。", "牛奶": "牛奶是饮品，与“将来”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44bc7b03-ab11-44e9-88d9-59ad108632a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88750, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "将来是还没有到的以后的日子。", "primary_collocate": null, "pronunciation": "jiāng lái", "ipa": "tɕjɑŋ˥ lai˧˥", "syllable_count": 2, "sentences": [{"text": "我将来想当医生。", "target_word": "将来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "将来的日子还很长。", "target_word": "将来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你将来想住在哪里？", "target_word": "将来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了将来，他现在努力学习。", "target_word": "将来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "将来有一天，我要去看海。", "target_word": "将来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁也不知道将来会怎么样。", "target_word": "将来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在为将来的生活存钱。", "target_word": "将来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们的将来很重要。", "target_word": "将来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要想一想将来。", "target_word": "将来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "将来我有了钱，就买大房子。", "target_word": "将来", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "还没到的以后的日子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6ed2684-d9cf-47cd-bea6-80ea625cf249') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88750, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "将来", "is_correct": true, "explanation": "正确答案。“我___想当医生”需要表示以后时间的词，“将来”与“想当医生”的志向相合。"}, {"text": "医院", "is_correct": false, "explanation": "语法：“医院”是处所名词，不能直接放在主语后修饰“想当医生”。"}, {"text": "苹果", "is_correct": false, "explanation": "语义：“苹果”是水果，不是时间词，放在这里句子不通。"}, {"text": "终于", "is_correct": false, "explanation": "副词“终于”表示经过一段过程后才出现的结果，与“我___想当医生”这种长远志向搭配不当。"}], "explanations": {"将来": "正确答案。“我___想当医生”需要表示以后时间的词，“将来”与“想当医生”的志向相合。", "医院": "语法：“医院”是处所名词，不能直接放在主语后修饰“想当医生”。", "苹果": "语义：“苹果”是水果，不是时间词，放在这里句子不通。", "终于": "副词“终于”表示经过一段过程后才出现的结果，与“我___想当医生”这种长远志向搭配不当。"}, "sentence_index": 0, "correct_answer": "将来"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "吃完饭将来，我们去散步。", "explanation": "这里应该用〈以后〉。将来指较远的未来，紧接着吃完饭的先后顺序要用以后。"}, {"text": "我们以前是同学，将来他去了上海。", "explanation": "这里应该用〈后来〉。将来只指还没到的时间，这句说的是已经发生的事，要用后来。"}, {"text": "我将来明天要去医院。", "explanation": "这里不能用〈将来〉。〈将来〉指较远、尚未确定的时间，与“明天”矛盾；应直接去掉〈将来〉，说“我明天要去医院。”"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44bc7b03-ab11-44e9-88d9-59ad108632a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88750, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "将来", "is_correct": true, "explanation": "正确答案。将来 jiāng lái 指还没到的以后的日子。"}, {"text": "江南", "is_correct": false, "explanation": "jiāng nán 与 jiāng lái 的第二个音节声母不同（n/l），意思是长江以南的地区。"}, {"text": "刚来", "is_correct": false, "explanation": "gāng lái（第一声）与 jiāng lái 声母不同（g/j），意思是刚到。"}, {"text": "强来", "is_correct": false, "explanation": "qiáng lái 与 jiāng lái 的第一个音节声母、韵母和声调都不同（q/j，iang 第二声/第一声），意思是硬来、不讲道理地做。"}], "explanations": {"将来": "正确答案。将来 jiāng lái 指还没到的以后的日子。", "江南": "jiāng nán 与 jiāng lái 的第二个音节声母不同（n/l），意思是长江以南的地区。", "刚来": "gāng lái（第一声）与 jiāng lái 声母不同（g/j），意思是刚到。", "强来": "qiáng lái 与 jiāng lái 的第一个音节声母、韵母和声调都不同（q/j，iang 第二声/第一声），意思是硬来、不讲道理地做。"}, "sentence_index": null, "correct_answer": "将来"}, "level_3": {"options": [{"text": "将来", "is_correct": true, "explanation": "正确答案。“为___的生活存钱”需要指向以后的时间，“将来”符合存钱为未来准备的语义。"}, {"text": "童年", "is_correct": false, "explanation": "语义：“童年”是已经过去的人生阶段，不能作为存钱要为之准备的时间。"}, {"text": "当年", "is_correct": false, "explanation": "语义：“当年”指过去的某一年，与为以后的生活存钱的目的相矛盾。"}, {"text": "往年", "is_correct": false, "explanation": "搭配：“往年”指以前的年份，与“为……的生活存钱”搭配不当。"}], "explanations": {"将来": "正确答案。“为___的生活存钱”需要指向以后的时间，“将来”符合存钱为未来准备的语义。", "童年": "语义：“童年”是已经过去的人生阶段，不能作为存钱要为之准备的时间。", "当年": "语义：“当年”指过去的某一年，与为以后的生活存钱的目的相矛盾。", "往年": "搭配：“往年”指以前的年份，与“为……的生活存钱”搭配不当。"}, "sentence_index": 6, "correct_answer": "将来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我将来上个星期去过北京。", "explanation": "这里不能用〈将来〉。“上个星期”是已经过去的时间，应该用〈以前〉。"}, {"text": "他的将来已经过去了。", "explanation": "这里不能用〈将来〉指已经过去的时间。〈将来〉指还没有到的时间，已经过去的时间应该用〈以前〉。"}, {"text": "他很擅长回忆将来。", "explanation": "这里应该用〈展望〉。“回忆”针对已经发生的事，将来指还没有到的时间，不能回忆；谈论还没到的时间要用〈展望〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44bc7b03-ab11-44e9-88d9-59ad108632a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88750, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我将来了想去北京工作。", "corrected_sentence": "我将来想去北京工作。", "error_description": "“将来”是表示未来的时间名词，后面不能加“了”。正确的说法是“我将来想去北京工作”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44bc7b03-ab11-44e9-88d9-59ad108632a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88750, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他为了将来地生活努力工作。", "corrected_sentence": "他为了将来的生活努力工作。", "error_description": "“将来”修饰名词“生活”应用“的”，不能用“地”（“地”用于修饰动词）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44bc7b03-ab11-44e9-88d9-59ad108632a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88751, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "过去", "is_correct": true, "explanation": "正确答案。过去指已经过去的时间，与“将来”是时间上相对的一对反义词。"}, {"text": "书包", "is_correct": false, "explanation": "书包是具体的物品，与“将来”没有反义关系。"}, {"text": "茶杯", "is_correct": false, "explanation": "茶杯是具体的器物，与“将来”没有反义关系。"}, {"text": "山峰", "is_correct": false, "explanation": "山峰是地理事物，与“将来”没有反义关系。"}], "correct_answer": "过去", "explanations": {"过去": "正确答案。过去指已经过去的时间，与“将来”是时间上相对的一对反义词。", "书包": "书包是具体的物品，与“将来”没有反义关系。", "茶杯": "茶杯是具体的器物，与“将来”没有反义关系。", "山峰": "山峰是地理事物，与“将来”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44bc7b03-ab11-44e9-88d9-59ad108632a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88751, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "过去", "is_correct": true, "explanation": "正确答案。过去与将来是时间上相对的一对反义词。"}, {"text": "窗帘", "is_correct": false, "explanation": "窗帘是具体的家居物品，与“将来”没有反义关系。"}, {"text": "钢笔", "is_correct": false, "explanation": "钢笔是具体的文具，与“将来”没有反义关系。"}, {"text": "牛奶", "is_correct": false, "explanation": "牛奶是饮品，与“将来”没有反义关系。"}], "correct_answer": "过去", "explanations": {"过去": "正确答案。过去与将来是时间上相对的一对反义词。", "窗帘": "窗帘是具体的家居物品，与“将来”没有反义关系。", "钢笔": "钢笔是具体的文具，与“将来”没有反义关系。", "牛奶": "牛奶是饮品，与“将来”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44bc7b03-ab11-44e9-88d9-59ad108632a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88751, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "现在以后的时间；未来。", "primary_collocate": null, "pronunciation": "jiāng lái", "ipa": "tɕjɑŋ˥ lai˧˥", "syllable_count": 2, "sentences": [{"text": "将来的世界会更方便。", "target_word": "将来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对将来很有信心。", "target_word": "将来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "将来天气会越来越热。", "target_word": "将来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不远的将来，人们会坐飞船旅行。", "target_word": "将来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题将来还要再谈。", "target_word": "将来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们该为将来做好准备。", "target_word": "将来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "将来她一定会成功。", "target_word": "将来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别总想过去，多想想将来。", "target_word": "将来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司将来会越做越大。", "target_word": "将来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把将来的计划写在了本子上。", "target_word": "将来", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "现在以后的时间，未来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6ed2684-d9cf-47cd-bea6-80ea625cf249') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88751, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "将来", "is_correct": true, "explanation": "正确答案。“___的世界会更方便”是对未来的预测，“将来”符合这一语义。"}, {"text": "过去", "is_correct": false, "explanation": "语义：“会”表示对未来的预测，与指已经过去的“过去”相矛盾。"}, {"text": "当年", "is_correct": false, "explanation": "语义：“当年”指过去的某一年，不能与表示未来预测的“会更方便”搭配。"}, {"text": "童年", "is_correct": false, "explanation": "语义：“童年”是过去的人生阶段，不能作为会变得更方便的世界的时间。"}], "explanations": {"将来": "正确答案。“___的世界会更方便”是对未来的预测，“将来”符合这一语义。", "过去": "语义：“会”表示对未来的预测，与指已经过去的“过去”相矛盾。", "当年": "语义：“当年”指过去的某一年，不能与表示未来预测的“会更方便”搭配。", "童年": "语义：“童年”是过去的人生阶段，不能作为会变得更方便的世界的时间。"}, "sentence_index": 0, "correct_answer": "将来"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他去年买了房子，将来又搬走了。", "explanation": "这里应该用〈后来〉。将来只指还没到的时间，这句说的是去年已经发生的事，要用后来。"}, {"text": "我们吃完饭将来就去上课。", "explanation": "这里应该用〈以后〉。将来指较远的未来，紧接着吃完饭的先后顺序要用以后。"}, {"text": "我小时候将来很想当医生。", "explanation": "这里应该用〈那时候〉。将来只指还没到的时间，小时候是过去，不能用将来。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44bc7b03-ab11-44e9-88d9-59ad108632a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88751, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "将来", "is_correct": true, "explanation": "正确答案。将来 jiāng lái 指现在以后的时间，即未来。"}, {"text": "强来", "is_correct": false, "explanation": "qiáng lái 与 jiāng lái 声母不同（q/j），意思是硬要去做。"}, {"text": "江南", "is_correct": false, "explanation": "jiāng nán 与 jiāng lái 的第二个音节声母不同（n/l），意思是长江以南的地区。"}, {"text": "刚来", "is_correct": false, "explanation": "gāng lái（第一声）与 jiāng lái 声母不同（g/j），意思是刚到。"}], "explanations": {"将来": "正确答案。将来 jiāng lái 指现在以后的时间，即未来。", "强来": "qiáng lái 与 jiāng lái 声母不同（q/j），意思是硬要去做。", "江南": "jiāng nán 与 jiāng lái 的第二个音节声母不同（n/l），意思是长江以南的地区。", "刚来": "gāng lái（第一声）与 jiāng lái 声母不同（g/j），意思是刚到。"}, "sentence_index": null, "correct_answer": "将来"}, "level_3": {"options": [{"text": "将来", "is_correct": true, "explanation": "正确答案。“___她一定会成功”是对未来的判断，“将来”符合这一语义。"}, {"text": "刚才", "is_correct": false, "explanation": "语义：“刚才”指刚刚过去的时间，与“一定会成功”的未来判断相矛盾。"}, {"text": "去年", "is_correct": false, "explanation": "语义：“去年”指已经过去的一年，不能与表示未来判断的“一定会成功”搭配。"}, {"text": "眼前", "is_correct": false, "explanation": "搭配：“眼前”指当前的时刻，与“一定会成功”这种对长远结果的判断搭配不当。"}], "explanations": {"将来": "正确答案。“___她一定会成功”是对未来的判断，“将来”符合这一语义。", "刚才": "语义：“刚才”指刚刚过去的时间，与“一定会成功”的未来判断相矛盾。", "去年": "语义：“去年”指已经过去的一年，不能与表示未来判断的“一定会成功”搭配。", "眼前": "搭配：“眼前”指当前的时刻，与“一定会成功”这种对长远结果的判断搭配不当。"}, "sentence_index": 6, "correct_answer": "将来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她把已经发生的将来写在了本子上。", "explanation": "这里不能用〈将来〉指已经发生的事。〈将来〉只指还没有到的时间，应改为“她把已经发生的事写在了本子上”。"}, {"text": "她把昨天的将来写在了本子上。", "explanation": "这里不能用〈将来〉指昨天这样已经过去的时间。〈将来〉只指还没有到的时间，应改为“她把昨天的计划写在了本子上”。"}, {"text": "她把上个月的将来写在了本子上。", "explanation": "这里不能用〈将来〉。上个月已经过去，〈将来〉只指还没到的时间，应改为“上个月的事”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44bc7b03-ab11-44e9-88d9-59ad108632a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88751, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "将来了我们会有更多机会。", "corrected_sentence": "将来我们会有更多机会。", "error_description": "“将来”是表示未来的时间词，后面不能加“了”。正确的说法是“将来我们会有更多机会”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44bc7b03-ab11-44e9-88d9-59ad108632a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88751, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们将来以后会在北京工作。", "corrected_sentence": "我们将来会在北京工作。", "error_description": "“将来”与“以后”都表示时间，不能叠加使用。正确的说法是“我们将来会在北京工作”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44bc7b03-ab11-44e9-88d9-59ad108632a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
