INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88752, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词,表示某些时候;偶尔。", "primary_collocate": null, "pronunciation": "yǒu shí", "ipa": "jou˨˩˧ ʂɻ̩˧˥", "syllable_count": 2, "sentences": [{"text": "我平时很忙，有时周末也要上班。", "target_word": "有时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他很少喝酒，有时和朋友喝一点。", "target_word": "有时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我一般坐公交车上学，有时走路去。", "target_word": "有时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "奶奶一般早睡，有时看电视看到很晚。", "target_word": "有时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他平时不说话，有时会讲个笑话。", "target_word": "有时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我很少吃甜的，有时想吃蛋糕。", "target_word": "有时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那家店人不多，有时会排队。", "target_word": "有时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师很严格，有时也会请我们吃糖。", "target_word": "有时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一个人住，有时会觉得很孤单。", "target_word": "有时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小王很少迟到，有时因为下雨才晚到。", "target_word": "有时", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "有时候", "label": "复合"}], "register": "中性", "sense_fingerprint": "有时：偶尔，在平时、一般情况之外偶然发生", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6572065d-d0c8-4f83-baf4-ecb8a6676503') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88752, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "有时", "is_correct": true, "explanation": "正确答案：有时（yǒu shí）表示偶尔、在一般情况之外偶然发生。"}, {"text": "有事", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）声调不同，意思是有事情。"}, {"text": "幼时", "is_correct": false, "explanation": "yòu（第四声）与 yǒu（第三声）声调不同，意思是小时候。"}, {"text": "诱使", "is_correct": false, "explanation": "yòu（第四声）与 yǒu（第三声）、shǐ（第三声）与 shí（第二声）声调都不同，意思是引诱、促使。"}], "explanations": {"有时": "正确答案：有时（yǒu shí）表示偶尔、在一般情况之外偶然发生。", "有事": "shí（第二声）与 shì（第四声）声调不同，意思是有事情。", "幼时": "yòu（第四声）与 yǒu（第三声）声调不同，意思是小时候。", "诱使": "yòu（第四声）与 yǒu（第三声）、shǐ（第三声）与 shí（第二声）声调都不同，意思是引诱、促使。"}, "sentence_index": null, "correct_answer": "有时"}, "level_3": {"options": [{"text": "有时", "is_correct": true, "explanation": "正确：“有时”表示偶尔，与“平时很忙”形成对比，符合语境。"}, {"text": "已经", "is_correct": false, "explanation": "语义：“已经”表示动作已经发生，与“平时很忙”的一般情况描述不协调。"}, {"text": "从来", "is_correct": false, "explanation": "搭配：“从来”通常与“不”“没”连用，不能直接用于肯定句。"}, {"text": "马上", "is_correct": false, "explanation": "语义：“马上”表示时间紧接，与“平时”的一般情况不协调。"}], "explanations": {"有时": "正确：“有时”表示偶尔，与“平时很忙”形成对比，符合语境。", "已经": "语义：“已经”表示动作已经发生，与“平时很忙”的一般情况描述不协调。", "从来": "搭配：“从来”通常与“不”“没”连用，不能直接用于肯定句。", "马上": "语义：“马上”表示时间紧接，与“平时”的一般情况不协调。"}, "sentence_index": 0, "correct_answer": "有时"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "奶奶一般早睡，有时每次看电视都看到很晚。", "explanation": "这里把“有时”用成了〈总是〉的意思。“有时”表示偶尔，而“每次……都”表示每次如此，两者矛盾。"}, {"text": "奶奶的母语有时是英语。", "explanation": "这里把“有时”用成了〈始终〉的意思。母语是固定的，“有时”只表示某些时候，不能用来说明固定事实。"}, {"text": "奶奶的生日有时是五月十号。", "explanation": "这里把“有时”用成了〈总是〉的意思。生日是固定的，“有时”表示偶尔、某些时候，不能用来说明固定的日期。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5832db7a-7430-4448-94f4-64c816ee246e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88752, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "有时", "is_correct": true, "explanation": "正确：“有时”表示偶尔，与“人不多”形成对比，表示只是某些时候排队。"}, {"text": "立刻", "is_correct": false, "explanation": "语义：“立刻”表示马上发生，与“那家店人不多”的描述不搭。"}, {"text": "一直", "is_correct": false, "explanation": "语义：“一直”表示持续，与“人不多”的情况矛盾。"}, {"text": "十分", "is_correct": false, "explanation": "搭配：“十分”修饰形容词，不能修饰“会排队”。"}], "explanations": {"有时": "正确：“有时”表示偶尔，与“人不多”形成对比，表示只是某些时候排队。", "立刻": "语义：“立刻”表示马上发生，与“那家店人不多”的描述不搭。", "一直": "语义：“一直”表示持续，与“人不多”的情况矛盾。", "十分": "搭配：“十分”修饰形容词，不能修饰“会排队”。"}, "sentence_index": 6, "correct_answer": "有时"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "小王每次都准时，有时也会迟到。", "explanation": "这里“每次都”与“有时”矛盾：“每次都准时”说明每次如此，“有时也会迟到”又说明不是每次，两者冲突。"}, {"text": "小王的个子有时很高。", "explanation": "这里把“有时”用成了〈始终〉的意思。身高是固定的，“有时”表示某些时候，不能用来说明固定特点。"}, {"text": "小王一直有时很早起床。", "explanation": "这里“一直”与“有时”矛盾：“一直”指持续不断，“有时”指间歇发生，两者不能同时修饰“很早起床”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5832db7a-7430-4448-94f4-64c816ee246e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88752, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我很少睡午觉，有时的会睡一会儿。", "corrected_sentence": "我很少睡午觉，有时会睡一会儿。", "error_description": "错误：“有时”后面多加了“的”，使副词变成了定语结构，句子不通。正确：“有时”作状语，直接修饰“会睡一会儿”，应写作“有时会睡一会儿”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5832db7a-7430-4448-94f4-64c816ee246e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88752, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他很少生病，有时有时会感冒。", "corrected_sentence": "他很少生病，有时会感冒。", "error_description": "错误：“有时”重复出现。正确：只需用一次“有时”，写作“有时会感冒”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5832db7a-7430-4448-94f4-64c816ee246e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
