INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88754, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "主要的与次要的；主导的与从属的。", "primary_collocate": null, "pronunciation": "zhǔ cóng", "ipa": "ʈʂu˨˩˦ tsʰʊŋ˧˥", "syllable_count": 2, "sentences": [{"text": "写文章要分清主从。", "target_word": "主从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两件事要分清主从，先做主要的。", "target_word": "主从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们分清主从，再做计划。", "target_word": "主从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些问题没有主从，都很重要。", "target_word": "主从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "画画的时候，要注意颜色的主从。", "target_word": "主从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他做事分不清主从。", "target_word": "主从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开会前，先把事情的主从理顺，再说小事。", "target_word": "主从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这篇文章的内容主从很清楚。", "target_word": "主从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做事先理清主从，效率会高很多。", "target_word": "主从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "复习考试要分主从，别什么都看。", "target_word": "主从", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "通用", "sense_fingerprint": "主要与次要、主导与从属", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90443c19-7a61-476e-90a3-d5c5a7345015') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88754, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "主从", "is_correct": true, "explanation": "正确。“分清主从”指分清主要与次要，符合“写文章”的语境。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：写文章时要分清的是观点和结构，“颜色”与“写文章”的语境不符。"}, {"text": "门窗", "is_correct": false, "explanation": "语义：“门窗”与写作无关，“分清门窗”在这个语境中不成立。"}, {"text": "脚步", "is_correct": false, "explanation": "语义：“脚步”不是可以在写作中分清的对象，与“写文章”不搭。"}], "explanations": {"主从": "正确。“分清主从”指分清主要与次要，符合“写文章”的语境。", "颜色": "语义：写文章时要分清的是观点和结构，“颜色”与“写文章”的语境不符。", "门窗": "语义：“门窗”与写作无关，“分清门窗”在这个语境中不成立。", "脚步": "语义：“脚步”不是可以在写作中分清的对象，与“写文章”不搭。"}, "sentence_index": 0, "correct_answer": "主从"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台服务器采用主从架构，数据同步很快。", "explanation": "这里的“主从”是计算机术语，指主机与从机，不是“主要与次要”的意思，不能用来说安排的主次。"}, {"text": "他在团队里的主从很高。", "explanation": "这里应该用〈地位〉。“主从”不表示等级高低，不能说“主从很高”。"}, {"text": "这个孩子的主从很活泼。", "explanation": "这里应该用〈性格〉。“主从”指主要与次要的关系，不能用来描述人的性格，不能说“主从很活泼”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2a2bbbe-96ec-42e7-b346-2c51b8318667') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88754, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "主从", "is_correct": true, "explanation": "正确。“事情的主从”指事情的主要与次要，可以“理顺”。"}, {"text": "鞋子", "is_correct": false, "explanation": "语义：“鞋子”不是可以理顺的事情，“事情的鞋子”不成立。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：“桌子”不属于事情的内容，无法被理顺。"}, {"text": "花草", "is_correct": false, "explanation": "搭配：“理顺”不能搭配“花草”，与“事情”也不相关。"}], "explanations": {"主从": "正确。“事情的主从”指事情的主要与次要，可以“理顺”。", "鞋子": "语义：“鞋子”不是可以理顺的事情，“事情的鞋子”不成立。", "桌子": "语义：“桌子”不属于事情的内容，无法被理顺。", "花草": "搭配：“理顺”不能搭配“花草”，与“事情”也不相关。"}, "sentence_index": 6, "correct_answer": "主从"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "复习考试要抓主从，别什么都看。", "explanation": "这里应该用〈重点〉。“主从”是关系，不能“抓”，要说“抓重点”。"}, {"text": "他的主从很灵活。", "explanation": "这里应该用〈思维〉。“主从”指主要与次要的关系，不能用来形容思维是否灵活。"}, {"text": "他很有主从。", "explanation": "这里应该用〈主见〉。“主从”不表示个人的见解，不能说“有主从”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2a2bbbe-96ec-42e7-b346-2c51b8318667') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88754, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "写文章时要先分清主从们。", "corrected_sentence": "写文章时要先分清主从。", "error_description": "错误：抽象名词“主从”后不能加复数后缀“们”，应去掉“们”，说“分清主从”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2a2bbbe-96ec-42e7-b346-2c51b8318667') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88754, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这份报告把主从分很清楚。", "corrected_sentence": "这份报告把主从分得很清楚。", "error_description": "错误：“分得”少了“得”。“分”后面的结果要用“分得很清楚”，不能说“分很清楚”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2a2bbbe-96ec-42e7-b346-2c51b8318667') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
