INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88756, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "电器等设备上用手按动以控制开关的部件。", "primary_collocate": null, "pronunciation": "àn niǔ", "ipa": "an˥˩ niou˨˩˦", "syllable_count": 2, "sentences": [{"text": "遥控器上红色的按钮是用来开关电视的。", "target_word": "按钮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "微波炉的按钮不灵了，需要修理。", "target_word": "按钮", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这台机器有三个按钮，分别控制开关、速度和时间。", "target_word": "按钮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机侧面的按钮可以调节音量。", "target_word": "按钮", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他按下了机器上的按钮，风扇就转起来了。", "target_word": "按钮", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "洗衣机的按钮上有字，一看就知道怎么用。", "target_word": "按钮", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个按钮是用来打开电源的，不是用来关机的。", "target_word": "按钮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "空调上的按钮很多，老人常常不会用。", "target_word": "按钮", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请按一下机器上绿色的按钮，再等一分钟。", "target_word": "按钮", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电梯外面的按钮亮着，说明电梯快来了。", "target_word": "按钮", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个按钮", "label": "量词（个）"}, {"form": "电源按钮", "label": "复合"}, {"form": "按鈕", "label": "繁体"}], "register": "中性", "sense_fingerprint": "按钮：电器等设备上用手按动、控制开关的部件", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ddf0a86-9417-4ade-a111-6e198f133eb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88756, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "按钮", "is_correct": true, "explanation": "正确。遥控器上的“按钮”用来开关电视，符合句意。"}, {"text": "频道", "is_correct": false, "explanation": "搭配：“用来开关”一般指按钮、开关之类的部件，不说频道。"}, {"text": "电池", "is_correct": false, "explanation": "语义：电池是供电的部件，不能用来开关电视。"}, {"text": "屏幕", "is_correct": false, "explanation": "语义：屏幕用来显示画面，不是按动来开关电视的部件。"}], "explanations": {"按钮": "正确。遥控器上的“按钮”用来开关电视，符合句意。", "频道": "搭配：“用来开关”一般指按钮、开关之类的部件，不说频道。", "电池": "语义：电池是供电的部件，不能用来开关电视。", "屏幕": "语义：屏幕用来显示画面，不是按动来开关电视的部件。"}, "sentence_index": 0, "correct_answer": "按钮"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件外套的按钮掉了，我得缝一下。", "explanation": "这里应该用〈纽扣〉。按钮指电器等设备上用手按动的部件，衣服上扣合的小东西要说〈纽扣〉。"}, {"text": "妈妈在锅里放了几个按钮，煮了一碗汤。", "explanation": "此句把“按钮”当作食物，但按钮只指电器等设备上用手按动的部件，不能放进锅里煮汤。"}, {"text": "这块蛋糕上的按钮很甜。", "explanation": "此句的“按钮”指食物，但按钮只指电器等设备上用手按动的部件，不能用来吃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd55f774-744e-4867-8748-d72ae34848bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88756, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "按钮", "is_correct": true, "explanation": "正确。“按钮”用来打开电源，符合“不是用来关机的”的对比。"}, {"text": "抽屉", "is_correct": false, "explanation": "语义：抽屉是家具部件，不是控制电源的部件。"}, {"text": "键盘", "is_correct": false, "explanation": "语义：键盘用来输入文字，与开关电源无关。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包不是电器部件，无法用来打开电源。"}], "explanations": {"按钮": "正确。“按钮”用来打开电源，符合“不是用来关机的”的对比。", "抽屉": "语义：抽屉是家具部件，不是控制电源的部件。", "键盘": "语义：键盘用来输入文字，与开关电源无关。", "书包": "语义：书包不是电器部件，无法用来打开电源。"}, "sentence_index": 6, "correct_answer": "按钮"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "书桌上放着一根按钮。", "explanation": "这里量词应该用〈个〉。「根」用于细长的东西，按钮不用「根」。"}, {"text": "树上的按钮开得很漂亮。", "explanation": "此句的“按钮”指花苞，但按钮只指电器等设备上用手按动的部件，不指植物的部分。"}, {"text": "墙上贴着一张按钮。", "explanation": "这里量词应该用〈个〉。「张」用于平面的东西，按钮不用「张」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd55f774-744e-4867-8748-d72ae34848bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88756, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "电视机上有一只按钮，可以调节音量。", "corrected_sentence": "电视机上有一个按钮，可以调节音量。", "error_description": "错误：量词用“只”，正确应为“个”。“按钮”不是动物或成对物品，应说“一个按钮”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd55f774-744e-4867-8748-d72ae34848bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88756, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "请把机器上的一只绿色按钮按一下。", "corrected_sentence": "请把机器上的一个绿色按钮按一下。", "error_description": "错误：量词用“只”，正确应为“个”。“只”用于动物或成对物品中的一件，“按钮”应说“一个绿色按钮”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd55f774-744e-4867-8748-d72ae34848bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
