INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88759, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '302840f7-b73e-4a61-bf0e-cb4145bc9216') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88759, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "本来是说一开始就是这样的。", "primary_collocate": null, "pronunciation": "běn lái", "ipa": "pən˨˩˦ lai˧˥", "syllable_count": 2, "sentences": [{"text": "这本来是一家小饭店，现在很大了。", "target_word": "本来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我本来住在上海，后来搬到了北京。", "target_word": "本来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他本来不喜欢吃辣的，现在天天吃。", "target_word": "本来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条河本来很干净，现在有点脏了。", "target_word": "本来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我本来想去，可是下雨了。", "target_word": "本来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她本来是老师，后来开了一家店。", "target_word": "本来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明本来很害羞，现在爱说话了。", "target_word": "本来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里本来没有路，是大家走出来的。", "target_word": "本来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我本来打算坐火车去，但是票卖完了。", "target_word": "本来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个杯子本来是白色的，用久了变黄了。", "target_word": "本来", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "本来就", "label": "搭配"}, {"form": "本來", "label": "繁体"}], "register": "通用", "sense_fingerprint": "副词,指一开始的情况,后来有了变化", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5767602e-4fc3-4fe7-bca0-b5bea1fa5ab2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88759, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "一直", "is_correct": false, "explanation": "语义：“一直”表示始终如此，与后半句“现在很大了”的变化相矛盾。"}, {"text": "本来", "is_correct": true, "explanation": "本来表示一开始的情况，与“现在很大了”形成前后变化，句意正确。"}, {"text": "刚", "is_correct": false, "explanation": "体貌：“刚”表示刚刚发生的情况，不能说明一开始就是这样，与后文的变化不搭。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示不时发生，不能说明这家店一开始的性质。"}], "explanations": {"一直": "语义：“一直”表示始终如此，与后半句“现在很大了”的变化相矛盾。", "本来": "本来表示一开始的情况，与“现在很大了”形成前后变化，句意正确。", "刚": "体貌：“刚”表示刚刚发生的情况，不能说明一开始就是这样，与后文的变化不搭。", "偶尔": "语义：“偶尔”表示不时发生，不能说明这家店一开始的性质。"}, "sentence_index": 0, "correct_answer": "本来"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "本来这条河这么脏啊！", "explanation": "这里应该用〈原来〉。原来用于说话人忽然发现真相时的感叹，本来只说明原先的状态，不能表示“才发现”。"}, {"text": "这条河本来变脏了。", "explanation": "这里应该用〈突然〉。突然表示事情忽然发生，本来只说明一开始的情况，不能表示变脏这一突然的变化。"}, {"text": "他上学本来迟到，老师很生气。", "explanation": "这里应该用〈总是〉。总是表示经常如此，本来只说明一开始的情况，不能表示经常发生。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '302840f7-b73e-4a61-bf0e-cb4145bc9216') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88759, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "从来", "is_correct": false, "explanation": "语义：“从来”指从未如此，多与否定连用，与“很害羞，现在爱说话了”的前后变化不符。"}, {"text": "本来", "is_correct": true, "explanation": "本来表示一开始的性格，与“现在爱说话了”形成变化，句意正确。"}, {"text": "竟然", "is_correct": false, "explanation": "语义：“竟然”表示出乎意料，句中没有意外的语境，不能用来说明性格原先如何。"}, {"text": "赶快", "is_correct": false, "explanation": "搭配：“赶快”多修饰要立即进行的动作，不能修饰“很害羞”这样的状态。"}], "explanations": {"从来": "语义：“从来”指从未如此，多与否定连用，与“很害羞，现在爱说话了”的前后变化不符。", "本来": "本来表示一开始的性格，与“现在爱说话了”形成变化，句意正确。", "竟然": "语义：“竟然”表示出乎意料，句中没有意外的语境，不能用来说明性格原先如何。", "赶快": "搭配：“赶快”多修饰要立即进行的动作，不能修饰“很害羞”这样的状态。"}, "sentence_index": 6, "correct_answer": "本来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座城市本来热闹起来了。", "explanation": "这里应该用〈渐渐〉。渐渐描述逐步变化的过程，本来只说明一开始的情况，不能和“起来了”描述变化过程。"}, {"text": "经过三年努力，他本来学会了游泳。", "explanation": "这里应该用〈终于〉。终于表示经过努力最终实现，本来表示原先的情况，与“经过三年努力”的过程相矛盾。"}, {"text": "我本来在路上遇见了他，真巧。", "explanation": "这里应该用〈恰好〉。恰好表示碰巧遇上，本来只说明原先的情况，不能表达“碰巧”的意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '302840f7-b73e-4a61-bf0e-cb4145bc9216') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88759, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个公园本来了一片荒地，现在变成了花园。", "corrected_sentence": "这个公园本来是一片荒地，现在变成了花园。", "error_description": "“本来”后面不能接动态助词“了”，应改为判断动词“是”，写作“这个公园本来是一片荒地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '302840f7-b73e-4a61-bf0e-cb4145bc9216') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88759, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我本来不就爱喝咖啡，最近却天天喝。", "corrected_sentence": "我本来就不爱喝咖啡，最近却天天喝。", "error_description": "“就”应放在“本来”之后，写作“本来就”。“不就”与“本来”的组合中“就”位置错误。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '302840f7-b73e-4a61-bf0e-cb4145bc9216') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
