INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88761, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "主日是基督教徒去教堂做礼拜的那一天，每周一次。", "primary_collocate": null, "pronunciation": "zhǔ rì", "ipa": "ʈʂu˨˩˦ ɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "每个主日，她都去教堂做礼拜。", "target_word": "主日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个主日，我们教会有聚会。", "target_word": "主日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "主日早上，教堂里坐满了人。", "target_word": "主日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每个主日都带孩子去教堂。", "target_word": "主日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "主日的礼拜九点开始。", "target_word": "主日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天是主日，他们全家去了教堂。", "target_word": "主日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "主日那天，教堂外面很安静。", "target_word": "主日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下个主日，牧师会讲一个故事。", "target_word": "主日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她主日不工作，要去做礼拜。", "target_word": "主日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "主日过后，大家又开始上班了。", "target_word": "主日", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "主日学", "label": "复合"}, {"form": "主日崇拜", "label": "复合"}], "register": "书面", "sense_fingerprint": "基督徒每周去教堂做礼拜的日子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18a42da8-9800-487c-a0cc-6369a01a14d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88761, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "主日", "is_correct": true, "explanation": "主日（zhǔ rì）：基督徒每周去教堂做礼拜的那一天，本题答案。"}, {"text": "主任", "is_correct": false, "explanation": "rèn（第四声）与 rì（第四声）韵母不同，意思是主任，指负责人。"}, {"text": "主力", "is_correct": false, "explanation": "lì 与 rì 声母不同，意思是主力，指主要力量。"}, {"text": "逐日", "is_correct": false, "explanation": "zhú（第二声）与 zhǔ（第三声）声调不同，意思是一天天地。"}, {"text": "数日", "is_correct": false, "explanation": "shù（第四声）与 zhǔ（第三声）声调不同，声母也不同（sh 与 zh），意思是几天。"}, {"text": "主义", "is_correct": false, "explanation": "yì 与 rì 声母不同，意思是主义，指思想体系。"}], "explanations": {"主日": "主日（zhǔ rì）：基督徒每周去教堂做礼拜的那一天，本题答案。", "主任": "rèn（第四声）与 rì（第四声）韵母不同，意思是主任，指负责人。", "主力": "lì 与 rì 声母不同，意思是主力，指主要力量。", "逐日": "zhú（第二声）与 zhǔ（第三声）声调不同，意思是一天天地。", "数日": "shù（第四声）与 zhǔ（第三声）声调不同，声母也不同（sh 与 zh），意思是几天。", "主义": "yì 与 rì 声母不同，意思是主义，指思想体系。"}, "sentence_index": null, "correct_answer": "主日"}, "level_3": {"options": [{"text": "主日", "is_correct": true, "explanation": "主日：基督徒每周做礼拜的日子，与“每个”和“做礼拜”相符。"}, {"text": "饺子", "is_correct": false, "explanation": "语义：饺子不是时间，“每个饺子”去教堂做礼拜不合常理。"}, {"text": "小时", "is_correct": false, "explanation": "语义：每小时去教堂做礼拜不合常理，礼拜是每周一次。"}, {"text": "老爷", "is_correct": false, "explanation": "语域：“老爷”是旧时口语中的尊称，与基督徒礼拜的语境不合。"}], "explanations": {"主日": "主日：基督徒每周做礼拜的日子，与“每个”和“做礼拜”相符。", "饺子": "语义：饺子不是时间，“每个饺子”去教堂做礼拜不合常理。", "小时": "语义：每小时去教堂做礼拜不合常理，礼拜是每周一次。", "老爷": "语域：“老爷”是旧时口语中的尊称，与基督徒礼拜的语境不合。"}, "sentence_index": 0, "correct_answer": "主日"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一个月里有一只主日没去教堂。", "explanation": "这里应该用〈个〉。主日是时间单位，计数用“个”，不用“只”。"}, {"text": "这个主日有三十天，大家都很忙。", "explanation": "这里应该用〈月〉。主日指星期日这一天，不能表示三十天的时间段，计量一段时间要用月。"}, {"text": "我把钥匙放在主日的抽屉里。", "explanation": "这里应该用〈桌子〉。主日是时间，不是处所，不能用来指“抽屉”所在的地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d153eb1-9e1a-4cc7-8cf1-1e337122b545') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88761, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "主日", "is_correct": true, "explanation": "主日：基督教称星期日的说法，指基督徒做礼拜的那一天，与句意相符。"}, {"text": "铅笔", "is_correct": false, "explanation": "语义：铅笔是文具，不是某一天，不能说“铅笔那天”。"}, {"text": "鞭炮", "is_correct": false, "explanation": "语义：放鞭炮声音很大，与“很安静”矛盾。"}, {"text": "老外", "is_correct": false, "explanation": "语域：“老外”是口语，指外国人，不能用作表示时间的词。"}], "explanations": {"主日": "主日：基督教称星期日的说法，指基督徒做礼拜的那一天，与句意相符。", "铅笔": "语义：铅笔是文具，不是某一天，不能说“铅笔那天”。", "鞭炮": "语义：放鞭炮声音很大，与“很安静”矛盾。", "老外": "语域：“老外”是口语，指外国人，不能用作表示时间的词。"}, "sentence_index": 6, "correct_answer": "主日"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家店的主日很热情。", "explanation": "这里应该用〈主人〉。主日指星期日，不能指人；称呼店的主人要说主人。"}, {"text": "学校的主日运动会在下个月举行。", "explanation": "这里应该用〈周末〉。主日是基督教用语，专指星期日，不能用来称呼学校的运动会。"}, {"text": "犹太人每周五晚上都庆祝主日。", "explanation": "这里应该用〈安息日〉。主日指基督教的星期日，犹太人庆祝的是安息日，不能用主日称呼。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d153eb1-9e1a-4cc7-8cf1-1e337122b545') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88761, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们全家每只主日都去教堂做礼拜。", "corrected_sentence": "我们全家每个主日都去教堂做礼拜。", "error_description": "错误：每只主日。正确：每个主日。主日是时间名词，量词用“个”，不用“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d153eb1-9e1a-4cc7-8cf1-1e337122b545') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88761, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "教会的一主日礼拜九点开始。", "corrected_sentence": "教会的主日礼拜九点开始。", "error_description": "错误：一主日礼拜。正确：主日礼拜。“主日”作定语时前面不能直接加数词“一”，去掉“一”即可。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d153eb1-9e1a-4cc7-8cf1-1e337122b545') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
