INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88762, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "基督教称星期日为主日。", "primary_collocate": null, "pronunciation": "zhǔ rì", "ipa": "ʈʂu˨˩˦ ɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "基督教把星期日叫作主日。", "target_word": "主日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "主日就是基督教的星期日。", "target_word": "主日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在基督教里，星期日又叫主日。", "target_word": "主日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他告诉我，主日是星期日的另一个说法。", "target_word": "主日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "基督徒说的主日，就是我们说的星期日。", "target_word": "主日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书上写着，基督教称星期日为主日。", "target_word": "主日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "主日是星期日，不是星期六。", "target_word": "主日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为什么基督教的星期日叫主日？", "target_word": "主日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，主日是基督教的叫法。", "target_word": "主日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "圣经课上，我学到了主日这个词。", "target_word": "主日", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "主日学", "label": "复合"}, {"form": "主日崇拜", "label": "复合"}], "register": "书面", "sense_fingerprint": "基督教对星期日的称呼", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18a42da8-9800-487c-a0cc-6369a01a14d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88762, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "主日", "is_correct": true, "explanation": "主日（zhǔ rì）：基督教称星期日为主日，本题答案。"}, {"text": "主任", "is_correct": false, "explanation": "rèn（第四声）与 rì（第四声）韵母不同，意思是主任，指负责人。"}, {"text": "主力", "is_correct": false, "explanation": "lì 与 rì 声母不同，意思是主力，指主要力量。"}, {"text": "逐日", "is_correct": false, "explanation": "zhú（第二声）与 zhǔ（第三声）声调不同，意思是一天天地。"}, {"text": "数日", "is_correct": false, "explanation": "shù（第四声）与 zhǔ（第三声）声调不同，声母也不同（sh 与 zh），意思是几天。"}, {"text": "主义", "is_correct": false, "explanation": "yì 与 rì 声母不同，意思是主义，指思想体系。"}], "explanations": {"主日": "主日（zhǔ rì）：基督教称星期日为主日，本题答案。", "主任": "rèn（第四声）与 rì（第四声）韵母不同，意思是主任，指负责人。", "主力": "lì 与 rì 声母不同，意思是主力，指主要力量。", "逐日": "zhú（第二声）与 zhǔ（第三声）声调不同，意思是一天天地。", "数日": "shù（第四声）与 zhǔ（第三声）声调不同，声母也不同（sh 与 zh），意思是几天。", "主义": "yì 与 rì 声母不同，意思是主义，指思想体系。"}, "sentence_index": null, "correct_answer": "主日"}, "level_3": {"options": [{"text": "主日", "is_correct": true, "explanation": "主日：基督教称星期日的说法，与“基督教”“星期日”相符。"}, {"text": "圣诞节", "is_correct": false, "explanation": "语义：圣诞节是纪念耶稣诞生的节日，不是星期日的别称。"}, {"text": "元旦", "is_correct": false, "explanation": "语义：元旦是公历新年的第一天，与星期日无关。"}, {"text": "老天爷", "is_correct": false, "explanation": "语域：“老天爷”是口语，指民间的神，不能作为基督教指称星期日的用语。"}], "explanations": {"主日": "主日：基督教称星期日的说法，与“基督教”“星期日”相符。", "圣诞节": "语义：圣诞节是纪念耶稣诞生的节日，不是星期日的别称。", "元旦": "语义：元旦是公历新年的第一天，与星期日无关。", "老天爷": "语域：“老天爷”是口语，指民间的神，不能作为基督教指称星期日的用语。"}, "sentence_index": 0, "correct_answer": "主日"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们每周日都去教堂做主日。", "explanation": "这里应该用〈礼拜〉。“做礼拜”是固定说法，主日指一个日子，不能与“做”搭配。"}, {"text": "犹太人把星期六定为主日。", "explanation": "这里应该用〈安息日〉。主日指基督教的星期日，犹太教的安息日是星期六。"}, {"text": "他一年里一只主日都没有缺席过教堂的礼拜。", "explanation": "这里应该用〈个〉。主日是时间单位，计数用“个”，不用“只”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d153eb1-9e1a-4cc7-8cf1-1e337122b545') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88762, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "主日", "is_correct": true, "explanation": "主日：基督教称星期日的说法，与“是星期日”相符。"}, {"text": "黑板", "is_correct": false, "explanation": "语义：黑板是教具，不能是某一天，与“是星期日”矛盾。"}, {"text": "老外", "is_correct": false, "explanation": "语域：“老外”是口语，指外国人，与“星期日”的说法不相容。"}, {"text": "春天", "is_correct": false, "explanation": "语义：春天是季节，不是一天，与句意矛盾。"}], "explanations": {"主日": "主日：基督教称星期日的说法，与“是星期日”相符。", "黑板": "语义：黑板是教具，不能是某一天，与“是星期日”矛盾。", "老外": "语域：“老外”是口语，指外国人，与“星期日”的说法不相容。", "春天": "语义：春天是季节，不是一天，与句意矛盾。"}, "sentence_index": 6, "correct_answer": "主日"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把书放在主日里。", "explanation": "这里应该用〈书架〉。主日是时间，不是存放东西的处所，不能用“放在……里”引出存放的地方。"}, {"text": "我们班的主日辩论赛在下个月举行。", "explanation": "这里应该用〈周末〉。主日是基督教用语，指星期日，不能用来称呼班级组织的辩论赛。"}, {"text": "这个主日的时长是三十天。", "explanation": "这里应该用〈月〉。主日指星期日这一天，不能当作三十天的时间段来计量，计算一段时间要用月。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d153eb1-9e1a-4cc7-8cf1-1e337122b545') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88762, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只主日，我们去教堂做礼拜。", "corrected_sentence": "这个主日，我们去教堂做礼拜。", "error_description": "错误：这只主日。正确：这个主日。主日是时间名词，量词用“个”，不用“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d153eb1-9e1a-4cc7-8cf1-1e337122b545') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88762, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们很主日都去教堂做礼拜。", "corrected_sentence": "我们每个主日都去教堂做礼拜。", "error_description": "错误：很主日。正确：每个主日。“很”是程度副词，不能修饰名词“主日”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d153eb1-9e1a-4cc7-8cf1-1e337122b545') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
