INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88763, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "捕鱼是用网把水里的鱼抓上来。", "primary_collocate": null, "pronunciation": "bǔ yú", "ipa": "pu˨˩˦ y˧˥", "syllable_count": 2, "sentences": [{"text": "渔民每天早上用网捕鱼。", "target_word": "捕鱼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们把大网放进河里，开始捕鱼。", "target_word": "捕鱼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷年轻时在海边用网捕鱼。", "target_word": "捕鱼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天亮以前，船就出海捕鱼了。", "target_word": "捕鱼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "湖上有几条小船，人们正在撒网捕鱼。", "target_word": "捕鱼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "捕鱼要先把网整理好。", "target_word": "捕鱼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在河边撒开大网捕鱼，晚上才回家。", "target_word": "捕鱼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张旧网太小，不能用来捕鱼。", "target_word": "捕鱼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风太大了，渔民今天没有出海捕鱼。", "target_word": "捕鱼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我小时候看过爸爸用网捕鱼。", "target_word": "捕鱼", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "捕了鱼", "label": "体标"}, {"form": "捕过鱼", "label": "体标"}, {"form": "捕鱼船", "label": "复合"}], "register": "中性", "sense_fingerprint": "用网把水里的鱼抓上来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40c6bb68-9edb-4a24-ad31-cf0cde640a3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88763, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "捕鱼", "is_correct": true, "explanation": "正确答案。捕鱼（bǔ yú）指用网把水里的鱼抓上来。"}, {"text": "哺育", "is_correct": false, "explanation": "哺育（bǔ yù）与捕鱼（bǔ yú）第二个音节声调不同（第四声），意思是喂养幼小的动物或婴儿。"}, {"text": "补语", "is_correct": false, "explanation": "补语（bǔ yǔ）与捕鱼（bǔ yú）第二个音节声调不同（第三声），是语法术语，指动词后面补充说明结果或程度的成分。"}, {"text": "不予", "is_correct": false, "explanation": "不予（bù yǔ）与捕鱼两个音节的声调都不同，意思是不给予、不加以。"}], "explanations": {"捕鱼": "正确答案。捕鱼（bǔ yú）指用网把水里的鱼抓上来。", "哺育": "哺育（bǔ yù）与捕鱼（bǔ yú）第二个音节声调不同（第四声），意思是喂养幼小的动物或婴儿。", "补语": "补语（bǔ yǔ）与捕鱼（bǔ yú）第二个音节声调不同（第三声），是语法术语，指动词后面补充说明结果或程度的成分。", "不予": "不予（bù yǔ）与捕鱼两个音节的声调都不同，意思是不给予、不加以。"}, "sentence_index": null, "correct_answer": "捕鱼"}, "level_3": {"options": [{"text": "捕鱼", "is_correct": true, "explanation": "正确。捕鱼指用网把水里的鱼抓上来，与句中的“用网”一致。"}, {"text": "钓鱼", "is_correct": false, "explanation": "语义：钓鱼用鱼竿和鱼钩，与句中的“用网”冲突。"}, {"text": "种花", "is_correct": false, "explanation": "语义：种花在土里进行，不用网，与“渔民”“用网”都不符。"}, {"text": "吃鱼", "is_correct": false, "explanation": "语义：吃鱼是食用，不是抓鱼，与“渔民每天早上用网”的动作不符。"}], "explanations": {"捕鱼": "正确。捕鱼指用网把水里的鱼抓上来，与句中的“用网”一致。", "钓鱼": "语义：钓鱼用鱼竿和鱼钩，与句中的“用网”冲突。", "种花": "语义：种花在土里进行，不用网，与“渔民”“用网”都不符。", "吃鱼": "语义：吃鱼是食用，不是抓鱼，与“渔民每天早上用网”的动作不符。"}, "sentence_index": 0, "correct_answer": "捕鱼"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "救援队在海底捕鱼，发现了一艘沉船。", "explanation": "这里应该用〈打捞〉。捕鱼是抓鱼，从水底把沉物捞上来要说打捞。"}, {"text": "猎人在森林里捕鱼，打到了一只野兔。", "explanation": "这里应该用〈捕猎〉。捕鱼只指抓鱼，在森林里抓野生动物要说捕猎。"}, {"text": "警察在河边捕鱼，抓住了一个小偷。", "explanation": "这里应该用〈抓捕〉。捕鱼是抓鱼，抓捕罪犯要说抓捕。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4eacca5e-114b-458c-b73b-212c17bea824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88763, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "捕鱼", "is_correct": true, "explanation": "正确。“撒开大网”指的就是用网抓鱼的动作。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：撒开大网时人不能同时游泳，句中的“大网”与“游泳”的动作冲突。"}, {"text": "砍柴", "is_correct": false, "explanation": "搭配：“砍”的对象是树木或柴火，不能和“撒开大网”搭配。"}, {"text": "放牧", "is_correct": false, "explanation": "语义：放牧指照看牲畜，与“撒开大网”的动作不符。"}], "explanations": {"捕鱼": "正确。“撒开大网”指的就是用网抓鱼的动作。", "游泳": "语义：撒开大网时人不能同时游泳，句中的“大网”与“游泳”的动作冲突。", "砍柴": "搭配：“砍”的对象是树木或柴火，不能和“撒开大网”搭配。", "放牧": "语义：放牧指照看牲畜，与“撒开大网”的动作不符。"}, "sentence_index": 6, "correct_answer": "捕鱼"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我小时候看过爸爸在厨房里捕鱼。", "explanation": "这里应该用〈烧鱼〉。捕鱼是在水里用网抓鱼，在厨房里做鱼要说烧鱼。"}, {"text": "我小时候常去市场捕鱼，再买回家吃。", "explanation": "这里应该用〈购买〉。捕鱼是抓鱼的活动，到市场拿钱购买鱼类要说购买。"}, {"text": "我小时候常去游泳池捕鱼。", "explanation": "这里应该用〈游泳〉。捕鱼是用网抓鱼，在泳池里游要说游泳。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4eacca5e-114b-458c-b73b-212c17bea824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88763, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他昨天早上把捕鱼了。", "corrected_sentence": "他昨天早上捕了鱼。", "error_description": "错误：“把捕鱼了”；“把”后面不能接动宾结构“捕鱼”。正确是“捕了鱼”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4eacca5e-114b-458c-b73b-212c17bea824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88763, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他昨天在河边捕鱼一条鱼。", "corrected_sentence": "他昨天在河边捕了一条鱼。", "error_description": "错误：「捕鱼」是动宾式，本身已含宾语「鱼」，后面不能再接「一条鱼」。正确是「捕了一条鱼」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4eacca5e-114b-458c-b73b-212c17bea824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
